-- ✅ CORRECTION 2026-01-30: DROP la vue avant de la recréer pour éviter l'erreur "cannot change data type"
DROP VIEW IF EXISTS product_comments_view CASCADE;

CREATE VIEW product_comments_view AS
SELECT
    pc.id,
    pc.service_id,
    pc.user_id,
    pc.parent_comment_id,
    pc.rating,
    pc.content,
    pc.mentions,
    pc.reaction_counts,
    pc.created_at,
    pc.updated_at,
    pc.edited_at,
    pc.is_deleted,
    COALESCE(u.nom_complet::TEXT, u.email) AS user_name,  -- ✅ Corrigé: utiliser TEXT explicitement
    u.avatar_url AS user_avatar,
    (
        SELECT jsonb_object_agg(reaction_type, reaction_count)
        FROM (
            SELECT reaction_type, CAST(COUNT(*) AS INT) AS reaction_count
            FROM product_comment_reactions
            WHERE comment_id = pc.id
            GROUP BY reaction_type
        ) sub
    ) AS aggregated_reactions,
    (
        SELECT CAST(COUNT(*) AS INT)
        FROM product_comments replies
        WHERE replies.parent_comment_id = pc.id
          AND replies.is_deleted = FALSE
    ) AS reply_count
FROM product_comments pc
JOIN users u ON u.id = pc.user_id;

COMMENT ON VIEW product_comments_view IS 'Commentaires produits enrichis avec auteur, réactions agrégées et nombre de réponses';

