END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_premium_audio_jobs_updated_at ON premium_audio_jobs;
CREATE TRIGGER trg_premium_audio_jobs_updated_at
    BEFORE UPDATE ON premium_audio_jobs
    FOR EACH ROW
