-- Infrastructure de matching temps réel
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_type WHERE typname = 'delivery_matching_status'
    ) THEN
        CREATE TYPE delivery_matching_status AS ENUM (
            'queued',
            'searching',
            'assigned',
            'rejected',
            'failed',
            'timeout',
            'cancelled',
            'fallback',
            'no_courier'
        );
    END IF;
END
$$;

