    periode_fin DATE NOT NULL,
    
    -- Métadonnées
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Contraintes
    CONSTRAINT unique_analytics UNIQUE (user_id, livre_id, periode_debut, periode_fin)
);

