-- 3. Table pour le partage de fichiers
CREATE TABLE IF NOT EXISTS shared_files (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    chat_id TEXT NOT NULL,
    original_filename TEXT NOT NULL,
    stored_filename TEXT NOT NULL,
    file_path TEXT NOT NULL,
    file_size_bytes BIGINT NOT NULL,
    mime_type TEXT NOT NULL,
    is_public BOOLEAN DEFAULT FALSE,
    download_count INTEGER DEFAULT 0,
    max_downloads INTEGER,
    expires_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Index pour améliorer les performances
CREATE INDEX IF NOT EXISTS idx_shared_files_user_id ON shared_files(user_id);
CREATE INDEX IF NOT EXISTS idx_shared_files_chat_id ON shared_files(chat_id);
CREATE INDEX IF NOT EXISTS idx_shared_files_expires_at ON shared_files(expires_at);
CREATE INDEX IF NOT EXISTS idx_shared_files_created_at ON shared_files(created_at);

-- 4. Table pour le suivi des téléchargements
CREATE TABLE IF NOT EXISTS file_downloads (
    id TEXT PRIMARY KEY,
    file_id TEXT NOT NULL REFERENCES shared_files(id) ON DELETE CASCADE,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    downloaded_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    ip_address TEXT,
    user_agent TEXT
);

-- Index pour améliorer les performances
CREATE INDEX IF NOT EXISTS idx_file_downloads_file_id ON file_downloads(file_id);
CREATE INDEX IF NOT EXISTS idx_file_downloads_user_id ON file_downloads(user_id);
CREATE INDEX IF NOT EXISTS idx_file_downloads_downloaded_at ON file_downloads(downloaded_at);

-- 5. Table pour le statut de frappe (optionnel, peut être géré en mémoire)
CREATE TABLE IF NOT EXISTS typing_status (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    chat_id TEXT NOT NULL,
    is_typing BOOLEAN DEFAULT FALSE,
    last_activity TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Index pour améliorer les performances
CREATE INDEX IF NOT EXISTS idx_typing_status_user_id ON typing_status(user_id);
CREATE INDEX IF NOT EXISTS idx_typing_status_chat_id ON typing_status(chat_id);
CREATE INDEX IF NOT EXISTS idx_typing_status_last_activity ON typing_status(last_activity);

-- Contraintes d'unicité
ALTER TABLE push_subscriptions ADD CONSTRAINT unique_user_endpoint UNIQUE(user_id, endpoint);
ALTER TABLE typing_status ADD CONSTRAINT unique_user_chat UNIQUE(user_id, chat_id);

-- Commentaires pour la documentation
COMMENT ON TABLE push_subscriptions IS 'Subscriptions pour les notifications push du navigateur';
COMMENT ON TABLE voice_messages IS 'Messages vocaux enregistrés par les utilisateurs';
COMMENT ON TABLE shared_files IS 'Fichiers partagés entre utilisateurs';
COMMENT ON TABLE file_downloads IS 'Suivi des téléchargements de fichiers';
COMMENT ON TABLE typing_status IS 'Statut de frappe des utilisateurs dans les chats'; 

-- ============================================
-- Migration: 20250101_ALIGN_SEARCH_GPS_FINAL_WITH_KEYWORD_SEARCH.sql
-- ============================================
-- Migration: Aligner search_services_gps_final avec la logique de keyword_search_with_gps
-- Date: 2025-01-01
-- Description: 
--  1. Utiliser la même logique de recherche que keyword_search_with_gps (autocomplete, produits, unaccent, similarity)
--  2. Inclure recherche dans produits et sous-caractéristiques
--  3. Gérer accents, erreurs de saisie, troncature comme la requête optimisée

DROP FUNCTION IF EXISTS search_services_gps_final(text, text, integer, integer);

CREATE OR REPLACE FUNCTION search_services_gps_final(
    search_query text,
    user_gps_zone text DEFAULT NULL,
    search_radius_km integer DEFAULT 50,
    max_results integer DEFAULT 20
)
RETURNS TABLE(
    service_id integer,
    titre_service text,
    category text,
    gps_coords text,
    distance_km double precision,
    relevance_score double precision,
    gps_source text
) 
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    gps_parts text[];
    lat double precision;
    lng double precision;
    radius_adjusted double precision;
BEGIN
    -- Ajuster le rayon
    BEGIN
        radius_adjusted := COALESCE(calculate_intelligent_radius(search_radius_km::double precision), search_radius_km::double precision);
    EXCEPTION WHEN OTHERS THEN
        radius_adjusted := search_radius_km::double precision;
    END;

    -- CAS 1: Recherche AVEC zone GPS
    IF user_gps_zone IS NOT NULL AND user_gps_zone != '' AND user_gps_zone != 'null' THEN
        gps_parts := string_to_array(user_gps_zone, '|');
        
        IF array_length(gps_parts, 1) > 0 THEN
            BEGIN
                lat := split_part(gps_parts[1], ',', 1)::double precision;
                lng := split_part(gps_parts[1], ',', 2)::double precision;
            EXCEPTION WHEN OTHERS THEN
                lat := NULL;
                lng := NULL;
            END;

            IF lat IS NOT NULL AND lng IS NOT NULL THEN
                -- ✅ ALIGNÉ 2025-01-01: Utiliser la même logique que keyword_search_with_gps
                RETURN QUERY
                WITH autocomplete_matches AS (
                    -- ✅ ÉTAPE 1: Matches depuis autocomplete_characteristics (rapide, indexé)
                    SELECT 
                        ac.service_id,
                        ac.valeur,
                        ac.usage_count,
                        (
                            CASE WHEN LOWER(unaccent(ac.valeur)) = LOWER(unaccent(search_query)) THEN 100.0 ELSE 0.0 END +
                            CASE WHEN unaccent(ac.valeur) ILIKE unaccent(search_query) || '%' THEN 80.0 ELSE 0.0 END +
                            CASE WHEN unaccent(ac.valeur) ILIKE '%' || unaccent(search_query) || '%' THEN 60.0 ELSE 0.0 END +
                            ts_rank(to_tsvector('french', unaccent(ac.valeur)), plainto_tsquery('french', unaccent(search_query))) * 20.0 +
                            CASE WHEN similarity(unaccent(LOWER(ac.valeur)), unaccent(LOWER(search_query))) > 0.3 THEN 
                                similarity(unaccent(LOWER(ac.valeur)), unaccent(LOWER(search_query))) * 15.0 
                            ELSE 0.0 END +
                            (ac.usage_count::REAL * 0.5)
                        )::REAL as ac_score
                    FROM autocomplete_characteristics ac
                    INNER JOIN services s ON s.id = ac.service_id
                    WHERE s.is_active = true
                    AND ac.identifiant_base = 'produits'
                    AND ac.is_real_product = TRUE
                    AND (
                        LOWER(unaccent(ac.valeur)) = LOWER(unaccent(search_query))
                        OR unaccent(ac.valeur) ILIKE unaccent(search_query) || '%'
                        OR unaccent(ac.valeur) ILIKE '%' || unaccent(search_query) || '%'
                        OR to_tsvector('french', unaccent(ac.valeur)) @@ plainto_tsquery('french', unaccent(search_query))
                        OR similarity(unaccent(LOWER(ac.valeur)), unaccent(LOWER(search_query))) > 0.3
                    )
                    LIMIT 200
                ),
                best_autocomplete_per_service AS (
                    SELECT DISTINCT ON (service_id)
                        service_id,
                        ac_score
                    FROM autocomplete_matches
                    ORDER BY service_id, ac_score DESC, usage_count DESC NULLS LAST
                    LIMIT 100
                ),
                prefiltered_services_for_products AS (
                    -- ✅ CORRIGÉ 2026-01-06: Pré-filtrer services AVANT de décomposer produits
                    -- Inclut services avec produits dans service_products OU dans s.data->produits
                    SELECT DISTINCT s.id
                    FROM services s
                    WHERE s.is_active = true
                    AND (
                        to_tsvector('french', COALESCE(s.data->'titre_service'->>'valeur', '')) @@ plainto_tsquery('french', search_query)
                        OR to_tsvector('french', COALESCE(s.data->'description'->>'valeur', '')) @@ plainto_tsquery('french', search_query)
                        OR (COALESCE(s.data->'titre_service'->>'valeur', '')) % search_query
                        OR (COALESCE(s.data->'category'->>'valeur', s.category, '')) % search_query
                        -- ✅ NOUVEAU: Inclure services avec produits dans service_products qui matchent
                        OR EXISTS (
                            SELECT 1
                            FROM service_products p
                            WHERE p.service_id = s.id
                            AND p.is_active = true
                            AND (
                                unaccent(p.product_name) ILIKE '%' || unaccent(search_query) || '%'
                                OR to_tsvector('french', p.product_name) @@ plainto_tsquery('french', search_query)
                            )
                        )
                    )
                    LIMIT 200
                ),
                product_scores AS (
                    -- ✅ CORRIGÉ 2026-01-06: Recherche UNIQUEMENT dans service_products (plus de recherche dans s.data->produits)
                    SELECT 
                        p.service_id,
                        GREATEST(
                            CASE WHEN LOWER(unaccent(p.product_name)) = LOWER(unaccent(search_query)) THEN 100.0 ELSE 0.0 END,
                            CASE WHEN unaccent(p.product_name) ILIKE unaccent(search_query) || '%' THEN 80.0 ELSE 0.0 END,
                            CASE WHEN unaccent(p.product_name) ILIKE '%' || unaccent(search_query) || '%' THEN 40.0 ELSE 0.0 END,
                            CASE WHEN LOWER(unaccent(COALESCE(p.product_data->>'description_produit', p.product_data->>'description', ''))) = LOWER(unaccent(search_query)) THEN 55.0 ELSE 0.0 END,
                            CASE WHEN unaccent(COALESCE(p.product_data->>'description_produit', p.product_data->>'description', '')) ILIKE unaccent(search_query) || '%' THEN 45.0 ELSE 0.0 END,
                            CASE WHEN unaccent(COALESCE(p.product_data->>'description_produit', p.product_data->>'description', '')) ILIKE '%' || unaccent(search_query) || '%' THEN 35.0 ELSE 0.0 END,
                            CASE WHEN unaccent(extract_all_product_text(p.product_data)) ILIKE '%' || unaccent(search_query) || '%' THEN 30.0 ELSE 0.0 END,
                            CASE WHEN to_tsvector('french', p.product_name) @@ plainto_tsquery('french', search_query) THEN 25.0 ELSE 0.0 END,
                            CASE WHEN to_tsvector('french', COALESCE(p.product_data->>'description_produit', p.product_data->>'description', '')) @@ plainto_tsquery('french', search_query) THEN 20.0 ELSE 0.0 END,
                            CASE WHEN to_tsvector('french', extract_all_product_text(p.product_data)) @@ plainto_tsquery('french', search_query) THEN 15.0 ELSE 0.0 END,
                            CASE WHEN similarity(unaccent(LOWER(p.product_name)), unaccent(LOWER(search_query))) > 0.3 THEN 
                                similarity(unaccent(LOWER(p.product_name)), unaccent(LOWER(search_query))) * 12.0 
                            ELSE 0.0 END
                        )::REAL as product_score
                    FROM prefiltered_services_for_products pf
                    INNER JOIN service_products p ON p.service_id = pf.id
                    WHERE p.is_active = true
                    AND (
                        unaccent(p.product_name) ILIKE '%' || unaccent(search_query) || '%'
                        OR unaccent(COALESCE(p.product_data->>'description_produit', p.product_data->>'description', '')) ILIKE '%' || unaccent(search_query) || '%'
                        OR unaccent(extract_all_product_text(p.product_data)) ILIKE '%' || unaccent(search_query) || '%'
                        OR to_tsvector('french', p.product_name) @@ plainto_tsquery('french', search_query)
                        OR to_tsvector('french', COALESCE(p.product_data->>'description_produit', p.product_data->>'description', '')) @@ plainto_tsquery('french', search_query)
                        OR to_tsvector('french', extract_all_product_text(p.product_data)) @@ plainto_tsquery('french', search_query)
                        OR similarity(unaccent(LOWER(p.product_name)), unaccent(LOWER(search_query))) > 0.3
                        OR similarity(unaccent(LOWER(COALESCE(p.product_data->>'description_produit', p.product_data->>'description', ''))), unaccent(LOWER(search_query))) > 0.3
                    )
                    LIMIT 500
                ),
                best_product_per_service AS (
                    SELECT DISTINCT ON (service_id)
                        service_id,
                        MAX(product_score) as max_product_score
                    FROM product_scores
                    GROUP BY service_id
                    ORDER BY service_id, max_product_score DESC
                    LIMIT 100
                ),
                services_with_distance AS (
                    SELECT 
                        s.id,
                        COALESCE(s.data->'titre_service'->>'valeur', s.data->>'titre_service', '')::text AS titre_service,
                        COALESCE(s.category, s.data->'category'->>'valeur', '')::text AS category,
                        COALESCE(s.gps, '')::text AS gps_coords,
                        CASE 
                            WHEN s.gps IS NOT NULL AND s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$' THEN
                                (
                                    6371 * acos(
                                        GREATEST(-1.0, LEAST(1.0,
                                            cos(radians(lat)) * 
                                            cos(radians(split_part(s.gps, ',', 1)::double precision)) *
                                            cos(radians(split_part(s.gps, ',', 2)::double precision) - radians(lng)) +
                                            sin(radians(lat)) *
                                            sin(radians(split_part(s.gps, ',', 1)::double precision))
                                        ))
                                    )
                                )
                            ELSE NULL
                        END AS distance_km,
                        GREATEST(
                            COALESCE(ac.ac_score, 0.0),
                            COALESCE(bp.max_product_score, 0.0),
                            CASE 
                                WHEN LOWER(unaccent(COALESCE(s.data->'titre_service'->>'valeur', ''))) = LOWER(unaccent(search_query)) THEN 70.0
                                WHEN unaccent(COALESCE(s.data->'titre_service'->>'valeur', '')) ILIKE unaccent(search_query) || '%' THEN 60.0
                                WHEN unaccent(COALESCE(s.data->'titre_service'->>'valeur', '')) ILIKE '%' || unaccent(search_query) || '%' THEN 30.0
                                WHEN similarity(unaccent(LOWER(COALESCE(s.data->'titre_service'->>'valeur', ''))), unaccent(LOWER(search_query))) > 0.3 THEN 
                                    similarity(unaccent(LOWER(COALESCE(s.data->'titre_service'->>'valeur', ''))), unaccent(LOWER(search_query))) * 30.0
                                ELSE 0.0
                            END,
                            CASE 
                                WHEN unaccent(COALESCE(s.data->'category'->>'valeur', s.category, '')) ILIKE '%' || unaccent(search_query) || '%' THEN 50.0
                                WHEN unaccent(COALESCE(s.data->'description'->>'valeur', '')) ILIKE '%' || unaccent(search_query) || '%' THEN 5.0
                                ELSE 0.0
                            END
                        )::REAL as relevance_score,
                        (CASE 
                            WHEN s.gps IS NOT NULL AND s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$' THEN 'service_gps'
                            ELSE 'no_gps'
                        END)::text AS gps_source
                    FROM services s
                    LEFT JOIN best_autocomplete_per_service ac ON ac.service_id = s.id
                    LEFT JOIN best_product_per_service bp ON bp.service_id = s.id
                    WHERE s.is_active = true
                    AND (
                        ac.service_id IS NOT NULL
                        OR bp.service_id IS NOT NULL
                        OR to_tsvector('french', COALESCE(s.data->'titre_service'->>'valeur', '')) @@ plainto_tsquery('french', search_query)
                        OR (COALESCE(s.data->'titre_service'->>'valeur', '')) % search_query
                        OR (COALESCE(s.data->'category'->>'valeur', s.category, '')) % search_query
                        OR unaccent(COALESCE(s.data->'titre_service'->>'valeur', '')) ILIKE '%' || unaccent(search_query) || '%'
                        OR unaccent(COALESCE(s.data->'category'->>'valeur', s.category, '')) ILIKE '%' || unaccent(search_query) || '%'
                    )
                )
                SELECT DISTINCT ON (id)
                    id::integer AS service_id,
                    titre_service,
                    category,
                    gps_coords,
                    distance_km,
                    relevance_score,
                    gps_source
                FROM services_with_distance
                WHERE distance_km IS NULL OR distance_km <= radius_adjusted
                ORDER BY id, relevance_score DESC
                LIMIT max_results;
                
                RETURN;
            END IF;
        END IF;
    END IF;

    -- CAS 2: Recherche SANS GPS (même logique mais sans calcul distance)
    -- ✅ ALIGNÉ 2025-01-01: Utiliser la même logique que keyword_search_with_gps
    RETURN QUERY
    WITH autocomplete_matches AS (
        SELECT 
            ac.service_id,
            ac.valeur,
            ac.usage_count,
            (
                CASE WHEN LOWER(unaccent(ac.valeur)) = LOWER(unaccent(search_query)) THEN 100.0 ELSE 0.0 END +
                CASE WHEN unaccent(ac.valeur) ILIKE unaccent(search_query) || '%' THEN 80.0 ELSE 0.0 END +
                CASE WHEN unaccent(ac.valeur) ILIKE '%' || unaccent(search_query) || '%' THEN 60.0 ELSE 0.0 END +
                ts_rank(to_tsvector('french', unaccent(ac.valeur)), plainto_tsquery('french', unaccent(search_query))) * 20.0 +
                CASE WHEN similarity(unaccent(LOWER(ac.valeur)), unaccent(LOWER(search_query))) > 0.3 THEN 
                    similarity(unaccent(LOWER(ac.valeur)), unaccent(LOWER(search_query))) * 15.0 
                ELSE 0.0 END +
                (ac.usage_count::REAL * 0.5)
            )::REAL as ac_score
        FROM autocomplete_characteristics ac
        INNER JOIN services s ON s.id = ac.service_id
        WHERE s.is_active = true
        AND ac.identifiant_base = 'produits'
        AND ac.is_real_product = TRUE
        AND (
            LOWER(unaccent(ac.valeur)) = LOWER(unaccent(search_query))
            OR unaccent(ac.valeur) ILIKE unaccent(search_query) || '%'
            OR unaccent(ac.valeur) ILIKE '%' || unaccent(search_query) || '%'
            OR to_tsvector('french', unaccent(ac.valeur)) @@ plainto_tsquery('french', unaccent(search_query))
            OR similarity(unaccent(LOWER(ac.valeur)), unaccent(LOWER(search_query))) > 0.3
        )
        LIMIT 200
    ),
    best_autocomplete_per_service AS (
        SELECT DISTINCT ON (service_id)
            service_id,
            ac_score
        FROM autocomplete_matches
        ORDER BY service_id, ac_score DESC, usage_count DESC NULLS LAST
        LIMIT 100
    ),
    prefiltered_services_for_products AS (
        -- ✅ CORRIGÉ 2026-01-06: Pré-filtrer services AVANT de décomposer produits
        -- Inclut services avec produits dans service_products OU dans s.data->produits
        SELECT DISTINCT s.id
        FROM services s
        WHERE s.is_active = true
        AND (
            to_tsvector('french', COALESCE(s.data->'titre_service'->>'valeur', '')) @@ plainto_tsquery('french', search_query)
            OR to_tsvector('french', COALESCE(s.data->'description'->>'valeur', '')) @@ plainto_tsquery('french', search_query)
            OR (COALESCE(s.data->'titre_service'->>'valeur', '')) % search_query
            OR (COALESCE(s.data->'category'->>'valeur', s.category, '')) % search_query
            -- ✅ NOUVEAU: Inclure services avec produits dans service_products qui matchent
            OR EXISTS (
                SELECT 1
                FROM service_products p
                WHERE p.service_id = s.id
                AND p.is_active = true
                AND (
                    unaccent(p.product_name) ILIKE '%' || unaccent(search_query) || '%'
                    OR to_tsvector('french', p.product_name) @@ plainto_tsquery('french', search_query)
                )
            )
        )
        LIMIT 200
    ),
    product_scores AS (
        -- ✅ CORRIGÉ 2026-01-06: Recherche UNIQUEMENT dans service_products (plus de recherche dans s.data->produits)
        SELECT 
            p.service_id,
            GREATEST(
                CASE WHEN LOWER(unaccent(p.product_name)) = LOWER(unaccent(search_query)) THEN 100.0 ELSE 0.0 END,
                CASE WHEN unaccent(p.product_name) ILIKE unaccent(search_query) || '%' THEN 80.0 ELSE 0.0 END,
                CASE WHEN unaccent(p.product_name) ILIKE '%' || unaccent(search_query) || '%' THEN 40.0 ELSE 0.0 END,
                CASE WHEN LOWER(unaccent(COALESCE(p.product_data->>'description_produit', p.product_data->>'description', ''))) = LOWER(unaccent(search_query)) THEN 55.0 ELSE 0.0 END,
                CASE WHEN unaccent(COALESCE(p.product_data->>'description_produit', p.product_data->>'description', '')) ILIKE unaccent(search_query) || '%' THEN 45.0 ELSE 0.0 END,
                CASE WHEN unaccent(COALESCE(p.product_data->>'description_produit', p.product_data->>'description', '')) ILIKE '%' || unaccent(search_query) || '%' THEN 35.0 ELSE 0.0 END,
                CASE WHEN unaccent(extract_all_product_text(p.product_data)) ILIKE '%' || unaccent(search_query) || '%' THEN 30.0 ELSE 0.0 END,
                CASE WHEN to_tsvector('french', p.product_name) @@ plainto_tsquery('french', search_query) THEN 25.0 ELSE 0.0 END,
                CASE WHEN to_tsvector('french', COALESCE(p.product_data->>'description_produit', p.product_data->>'description', '')) @@ plainto_tsquery('french', search_query) THEN 20.0 ELSE 0.0 END,
                CASE WHEN to_tsvector('french', extract_all_product_text(p.product_data)) @@ plainto_tsquery('french', search_query) THEN 15.0 ELSE 0.0 END,
                CASE WHEN similarity(unaccent(LOWER(p.product_name)), unaccent(LOWER(search_query))) > 0.3 THEN 
                    similarity(unaccent(LOWER(p.product_name)), unaccent(LOWER(search_query))) * 12.0 
                ELSE 0.0 END
            )::REAL as product_score
        FROM prefiltered_services_for_products pf
        INNER JOIN service_products p ON p.service_id = pf.id
        WHERE p.is_active = true
        AND (
            unaccent(p.product_name) ILIKE '%' || unaccent(search_query) || '%'
            OR unaccent(COALESCE(p.product_data->>'description_produit', p.product_data->>'description', '')) ILIKE '%' || unaccent(search_query) || '%'
            OR unaccent(extract_all_product_text(p.product_data)) ILIKE '%' || unaccent(search_query) || '%'
            OR to_tsvector('french', p.product_name) @@ plainto_tsquery('french', search_query)
            OR to_tsvector('french', COALESCE(p.product_data->>'description_produit', p.product_data->>'description', '')) @@ plainto_tsquery('french', search_query)
            OR to_tsvector('french', extract_all_product_text(p.product_data)) @@ plainto_tsquery('french', search_query)
            OR similarity(unaccent(LOWER(p.product_name)), unaccent(LOWER(search_query))) > 0.3
            OR similarity(unaccent(LOWER(COALESCE(p.product_data->>'description_produit', p.product_data->>'description', ''))), unaccent(LOWER(search_query))) > 0.3
        )
        LIMIT 500
    ),
    best_product_per_service AS (
        SELECT DISTINCT ON (service_id)
            service_id,
            MAX(product_score) as max_product_score
        FROM product_scores
        GROUP BY service_id
        ORDER BY service_id, max_product_score DESC
        LIMIT 100
    )
    SELECT DISTINCT ON (s.id)
        s.id::integer AS service_id,
        COALESCE(s.data->'titre_service'->>'valeur', s.data->>'titre_service', '')::text AS titre_service,
        COALESCE(s.category, s.data->'category'->>'valeur', '')::text AS category,
        COALESCE(s.gps, '')::text AS gps_coords,
        NULL::double precision AS distance_km,
        GREATEST(
            COALESCE(ac.ac_score, 0.0),
            COALESCE(bp.max_product_score, 0.0),
            CASE 
                WHEN LOWER(unaccent(COALESCE(s.data->'titre_service'->>'valeur', ''))) = LOWER(unaccent(search_query)) THEN 70.0
                WHEN unaccent(COALESCE(s.data->'titre_service'->>'valeur', '')) ILIKE unaccent(search_query) || '%' THEN 60.0
                WHEN unaccent(COALESCE(s.data->'titre_service'->>'valeur', '')) ILIKE '%' || unaccent(search_query) || '%' THEN 30.0
                WHEN similarity(unaccent(LOWER(COALESCE(s.data->'titre_service'->>'valeur', ''))), unaccent(LOWER(search_query))) > 0.3 THEN 
                    similarity(unaccent(LOWER(COALESCE(s.data->'titre_service'->>'valeur', ''))), unaccent(LOWER(search_query))) * 30.0
                ELSE 0.0
            END,
            CASE 
                WHEN unaccent(COALESCE(s.data->'category'->>'valeur', s.category, '')) ILIKE '%' || unaccent(search_query) || '%' THEN 50.0
                WHEN unaccent(COALESCE(s.data->'description'->>'valeur', '')) ILIKE '%' || unaccent(search_query) || '%' THEN 5.0
                ELSE 0.0
            END
        )::REAL as relevance_score,
        ('text_search')::text AS gps_source
    FROM services s
    LEFT JOIN best_autocomplete_per_service ac ON ac.service_id = s.id
    LEFT JOIN best_product_per_service bp ON bp.service_id = s.id
    WHERE s.is_active = true
    AND (
        ac.service_id IS NOT NULL
        OR bp.service_id IS NOT NULL
        OR to_tsvector('french', COALESCE(s.data->'titre_service'->>'valeur', '')) @@ plainto_tsquery('french', search_query)
        OR (COALESCE(s.data->'titre_service'->>'valeur', '')) % search_query
        OR (COALESCE(s.data->'category'->>'valeur', s.category, '')) % search_query
        OR unaccent(COALESCE(s.data->'titre_service'->>'valeur', '')) ILIKE '%' || unaccent(search_query) || '%'
        OR unaccent(COALESCE(s.data->'category'->>'valeur', s.category, '')) ILIKE '%' || unaccent(search_query) || '%'
    )
    ORDER BY s.id, relevance_score DESC
    LIMIT max_results;
END;
$$;

COMMENT ON FUNCTION search_services_gps_final IS 
'✅ ALIGNÉ 2025-01-01: Utilise la même logique que keyword_search_with_gps (autocomplete, produits, unaccent, similarity).
✅ CORRIGÉ 2026-01-06: Recherche UNIQUEMENT dans service_products (plus de recherche dans s.data->produits JSONB).
Inclut recherche dans produits et sous-caractéristiques. Gère accents, erreurs de saisie, troncature.';




-- ============================================
-- Migration: 20250101_OPTIMIZE_HYBRID_IMAGE_SEARCH_WITH_UNACCENT_SIMILARITY.sql
-- ============================================
-- Migration: Optimiser hybrid_image_search avec unaccent() et similarity()
-- Date: 2025-01-01
-- Description: 
--  1. Ajouter unaccent() pour gérer les accents (comme keyword_search_with_gps)
--  2. Ajouter similarity() pour gérer les erreurs de saisie (comme keyword_search_with_gps)
--  3. Aligner la logique avec la nouvelle approche optimisée

-- ✅ Corrigé: Spécifier la signature complète pour éviter "function name is not unique"
DROP FUNCTION IF EXISTS hybrid_image_search(TEXT[], TEXT, TEXT, TEXT, TEXT, FLOAT, FLOAT, INTEGER, INTEGER, TEXT) CASCADE;

CREATE FUNCTION hybrid_image_search(
    search_tags TEXT[],
    search_category TEXT DEFAULT NULL,
    search_marque TEXT DEFAULT NULL,
    search_couleur TEXT DEFAULT NULL,
    search_query_semantic TEXT DEFAULT NULL,
    gps_lat FLOAT DEFAULT NULL,
    gps_lng FLOAT DEFAULT NULL,
    search_radius_km INTEGER DEFAULT 50,
    max_results INTEGER DEFAULT 20,
    pg_lang TEXT DEFAULT 'french'
)
RETURNS TABLE (
    service_id INTEGER,
    analysis_id INTEGER,
    media_id INTEGER,
    product_description TEXT,
    product_tags TEXT[],
    product_marque TEXT,
    product_couleurs TEXT[],
    match_score FLOAT,
    distance_km FLOAT,
    service_data JSONB
) AS $$
BEGIN
    RETURN QUERY
    WITH combined_results AS (
        -- ✅ SOURCE 1 (PRIORITÉ HAUTE): Recherche dans autocomplete_characteristics
        -- ✅ OPTIMISÉ 2025-01-01: Ajout unaccent() et similarity() comme keyword_search_with_gps
        SELECT DISTINCT ON (ac.service_id)
            ac.service_id,
            NULL::INTEGER as analysis_id,
            NULL::INTEGER as media_id,
            ac.valeur as product_description,
            ARRAY(
                SELECT DISTINCT unnest(string_to_array(ac.valeur, ','))
            )::TEXT[] as product_tags,
            COALESCE(
                (ac.product_labels->>'marque')::TEXT,
                (SELECT unnest(string_to_array(ac.valeur, ',')) LIMIT 1)
            ) as product_marque,
            ARRAY(
                SELECT jsonb_array_elements_text(ac.product_labels->'couleurs')
                WHERE jsonb_typeof(ac.product_labels->'couleurs') = 'array'
            )::TEXT[] as product_couleurs,
            (
                -- ✅ OPTIMISÉ 2025-01-01: Utiliser unaccent() et similarity() comme keyword_search_with_gps
                -- Score exact avec unaccent (priorité maximale)
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND LOWER(unaccent(ac.valeur)) = LOWER(unaccent(search_query_semantic)) THEN 600.0
                    WHEN search_query_semantic IS NOT NULL AND unaccent(ac.valeur) ILIKE unaccent(search_query_semantic) || '%' THEN 400.0
                    WHEN search_query_semantic IS NOT NULL AND unaccent(ac.valeur) ILIKE '%' || unaccent(search_query_semantic) || '%' THEN 200.0
                    ELSE 0.0
                END +
                -- ✅ NOUVEAU: Score similarity pour erreurs de saisie
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND similarity(unaccent(LOWER(ac.valeur)), unaccent(LOWER(search_query_semantic))) > 0.3 THEN 
                        similarity(unaccent(LOWER(ac.valeur)), unaccent(LOWER(search_query_semantic))) * 150.0
                    ELSE 0.0
                END +
                -- ✅ Score full-text sur valeur (index GIN tsvector) - avec langue dynamique et unaccent
                COALESCE(
                    ts_rank(to_tsvector(pg_lang, unaccent(ac.valeur)), plainto_tsquery(pg_lang, unaccent(COALESCE(search_query_semantic, '')))) * 400.0,
                    0.0
                ) +
                -- ✅ Score full-text sur characteristic_vector avec unaccent
                COALESCE(
                    ts_rank(characteristic_vector_to_tsvector(ac.characteristic_vector), plainto_tsquery(pg_lang, unaccent(COALESCE(search_query_semantic, '')))) * 300.0,
                    0.0
                ) +
                -- ✅ Score full-text sur full_vector avec unaccent
                COALESCE(
                    ts_rank(full_vector_to_tsvector(ac.full_vector), plainto_tsquery(pg_lang, unaccent(COALESCE(search_query_semantic, '')))) * 250.0,
                    0.0
                ) +
                -- ✅ AMÉLIORÉ 2025-01-01: Score tags communs avec unaccent et similarity
                CASE 
                    WHEN search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 THEN
                        (SELECT 
                            CASE 
                                WHEN COUNT(*) >= 2 THEN COUNT(*) * 120.0
                                WHEN COUNT(*) = 1 THEN 60.0
                                ELSE 0.0
                            END
                         FROM unnest(search_tags) tag 
                         WHERE unaccent(ac.valeur) ILIKE '%' || unaccent(tag) || '%'
                         OR similarity(unaccent(LOWER(ac.valeur)), unaccent(LOWER(tag))) > 0.3
                         OR characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery(pg_lang, unaccent(tag))
                         OR full_vector_to_tsvector(ac.full_vector) @@ plainto_tsquery(pg_lang, unaccent(tag)))
                    ELSE 0.0
                END +
                -- ✅ Score marque exacte avec unaccent
                CASE 
                    WHEN search_marque IS NOT NULL 
                         AND (
                             unaccent(ac.valeur) ILIKE unaccent(search_marque) || '%'
                             OR unaccent(ac.product_labels->>'marque') ILIKE unaccent(search_marque) || '%'
                             OR similarity(unaccent(LOWER(ac.valeur)), unaccent(LOWER(search_marque))) > 0.3
                         )
                    THEN 300.0
                    ELSE 0.0
                END +
                -- ✅ Score couleur avec unaccent
                CASE 
                    WHEN search_couleur IS NOT NULL 
                         AND (
                             unaccent(ac.valeur) ILIKE '%' || unaccent(search_couleur) || '%'
                             OR (jsonb_typeof(ac.product_labels->'couleurs') = 'array' 
                                 AND unaccent(ac.product_labels->'couleurs'::text) ILIKE '%' || unaccent(search_couleur) || '%')
                         )
                    THEN 100.0
                    ELSE 0.0
                END +
                -- ✅ Score catégorie - bonus seulement
                CASE 
                    WHEN search_category IS NOT NULL 
                         AND (
                             s.category = search_category
                             OR s.data->'category'->>'valeur' = search_category
                         )
                    THEN 50.0
                    ELSE 0.0
                END +
                -- ✅ Bonus usage_count
                (COALESCE(ac.usage_count, 0)::REAL * 0.5)
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM autocomplete_characteristics ac
        INNER JOIN services s ON s.id = ac.service_id
        WHERE s.is_active = true
        AND ac.identifiant_base = 'produits'
        AND ac.is_real_product = TRUE
        AND (
            -- ✅ OPTIMISÉ 2025-01-01: Utiliser unaccent() et similarity() comme keyword_search_with_gps
            (
                -- Option 1: Correspondance sur query semantic avec unaccent
                (search_query_semantic IS NOT NULL AND search_query_semantic != '' AND (
                    unaccent(ac.valeur) ILIKE unaccent(search_query_semantic) || '%'
                    OR to_tsvector(pg_lang, unaccent(ac.valeur)) @@ plainto_tsquery(pg_lang, unaccent(search_query_semantic))
                    OR characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery(pg_lang, unaccent(search_query_semantic))
                    OR full_vector_to_tsvector(ac.full_vector) @@ plainto_tsquery(pg_lang, unaccent(search_query_semantic))
                    OR similarity(unaccent(LOWER(ac.valeur)), unaccent(LOWER(search_query_semantic))) > 0.3
                ))
                -- Option 2: Correspondance sur au moins 1 tag avec unaccent et similarity
                OR (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND (
                    (SELECT COUNT(*) FROM unnest(search_tags) tag 
                     WHERE unaccent(ac.valeur) ILIKE '%' || unaccent(tag) || '%'
                     OR similarity(unaccent(LOWER(ac.valeur)), unaccent(LOWER(tag))) > 0.3
                     OR characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery(pg_lang, unaccent(tag))
                     OR full_vector_to_tsvector(ac.full_vector) @@ plainto_tsquery(pg_lang, unaccent(tag))) >= 1
                ))
                -- Option 3: Correspondance marque avec unaccent et similarity
                OR (search_marque IS NOT NULL AND search_marque != '' AND (
                    unaccent(ac.valeur) ILIKE unaccent(search_marque) || '%'
                    OR unaccent(ac.product_labels->>'marque') ILIKE unaccent(search_marque) || '%'
                    OR similarity(unaccent(LOWER(ac.valeur)), unaccent(LOWER(search_marque))) > 0.3
                ))
            )
            AND (search_couleur IS NULL OR search_couleur = '' OR (
                unaccent(ac.valeur) ILIKE '%' || unaccent(search_couleur) || '%'
                OR (jsonb_typeof(ac.product_labels->'couleurs') = 'array' 
                    AND unaccent(ac.product_labels->'couleurs'::text) ILIKE '%' || unaccent(search_couleur) || '%')
            ))
            AND (search_category IS NULL OR search_category = '' OR (
                s.category = search_category
                OR s.data->'category'->>'valeur' = search_category
            ))
        )
        
        UNION ALL
        
        -- ✅ SOURCE 2: Recherche dans image_analyses (produits catalogués - fallback)
        -- ✅ OPTIMISÉ 2025-01-01: Ajout unaccent() et similarity()
        SELECT 
            ia.service_id,
            ia.id as analysis_id,
            ia.media_id,
            ia.description as product_description,
            ia.tags as product_tags,
            ia.marque as product_marque,
            ia.couleurs as product_couleurs,
            (
                -- ✅ OPTIMISÉ: Scoring avec unaccent() et similarity()
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND LOWER(unaccent(ia.description)) = LOWER(unaccent(search_query_semantic)) THEN 550.0
                    WHEN search_query_semantic IS NOT NULL AND unaccent(ia.description) ILIKE unaccent(search_query_semantic) || '%' THEN 400.0
                    WHEN search_query_semantic IS NOT NULL AND unaccent(ia.description) ILIKE '%' || unaccent(search_query_semantic) || '%' THEN 200.0
                    ELSE 0.0
                END +
                -- ✅ NOUVEAU: Score similarity pour erreurs de saisie
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND similarity(unaccent(LOWER(ia.description)), unaccent(LOWER(search_query_semantic))) > 0.3 THEN 
                        similarity(unaccent(LOWER(ia.description)), unaccent(LOWER(search_query_semantic))) * 150.0
                    ELSE 0.0
                END +
                -- ✅ Score tags communs avec unaccent
                (SELECT 
                    CASE 
                        WHEN COUNT(*) >= 2 THEN COUNT(*) * 100.0
                        WHEN COUNT(*) = 1 THEN 30.0
                        ELSE 0.0
                    END
                 FROM unnest(ia.tags) tag 
                 WHERE tag = ANY(search_tags)
                 OR (search_query_semantic IS NOT NULL AND unaccent(tag) ILIKE '%' || unaccent(search_query_semantic) || '%')
                 OR (search_query_semantic IS NOT NULL AND similarity(unaccent(LOWER(tag)), unaccent(LOWER(search_query_semantic))) > 0.3)) +
                -- ✅ Score marque avec unaccent et similarity
                CASE 
                    WHEN search_marque IS NOT NULL AND (
                        unaccent(ia.marque) ILIKE unaccent(search_marque) || '%'
                        OR similarity(unaccent(LOWER(ia.marque)), unaccent(LOWER(search_marque))) > 0.3
                    ) THEN 300.0 
                    ELSE 0.0 
                END +
                -- ✅ Score couleur avec unaccent
                CASE 
                    WHEN search_couleur IS NOT NULL AND search_couleur = ANY(ia.couleurs) THEN 100.0 
                    ELSE 0.0 
                END +
                -- ✅ Score catégorie - bonus seulement
                CASE 
                    WHEN search_category IS NOT NULL AND ia.category_detected = search_category THEN 50.0 
                    ELSE 0.0 
                END +
                -- ✅ Score full-text sur description avec unaccent (langue dynamique)
                COALESCE(
                    ts_rank(to_tsvector(pg_lang, unaccent(COALESCE(ia.description, ''))), plainto_tsquery(pg_lang, unaccent(COALESCE(search_query_semantic, '')))) * 500.0,
                    0.0
                ) +
                -- Bonus confiance
                (ia.confiance * 20.0)
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM image_analyses ia
        INNER JOIN services s ON s.id = ia.service_id
        WHERE s.is_active = true
        AND NOT EXISTS (
            SELECT 1 FROM autocomplete_characteristics ac2 
            WHERE ac2.service_id = ia.service_id 
            AND ac2.identifiant_base = 'produits' 
            AND ac2.is_real_product = TRUE
        )
        AND (
            -- ✅ OPTIMISÉ 2025-01-01: Utiliser unaccent() et similarity()
            (
                (search_query_semantic IS NOT NULL AND search_query_semantic != '' AND (
                    unaccent(ia.description) ILIKE unaccent(search_query_semantic) || '%'
                    OR to_tsvector(pg_lang, unaccent(COALESCE(ia.description, ''))) @@ plainto_tsquery(pg_lang, unaccent(search_query_semantic))
                    OR similarity(unaccent(LOWER(ia.description)), unaccent(LOWER(search_query_semantic))) > 0.3
                ))
                OR (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND (
                    (SELECT COUNT(*) FROM unnest(ia.tags) tag 
                     WHERE tag = ANY(search_tags)
                     OR (search_query_semantic IS NOT NULL AND unaccent(tag) ILIKE '%' || unaccent(search_query_semantic) || '%')
                     OR (search_query_semantic IS NOT NULL AND similarity(unaccent(LOWER(tag)), unaccent(LOWER(search_query_semantic))) > 0.3)) >= 1
                ))
                OR (search_marque IS NOT NULL AND search_marque != '' AND (
                    unaccent(ia.marque) ILIKE unaccent(search_marque) || '%'
                    OR similarity(unaccent(LOWER(ia.marque)), unaccent(LOWER(search_marque))) > 0.3
                ))
            )
            AND (search_couleur IS NULL OR search_couleur = '' OR search_couleur = ANY(ia.couleurs))
            AND (search_category IS NULL OR search_category = '' OR ia.category_detected = search_category)
        )
        
        UNION ALL
        
        -- ✅ SOURCE 3: Recherche dans media.ai_* (images avec IA - fallback)
        -- ✅ OPTIMISÉ 2025-01-01: Ajout unaccent() et similarity()
        SELECT 
            m.service_id,
            NULL::INTEGER as analysis_id,
            m.id as media_id,
            COALESCE(m.ai_description, '') as product_description,
            COALESCE(m.ai_tags, ARRAY[]::TEXT[]) as product_tags,
            m.ai_metadata->>'marque' as product_marque,
            ARRAY(SELECT jsonb_array_elements_text(m.ai_metadata->'couleurs'))::TEXT[] as product_couleurs,
            (
                -- ✅ OPTIMISÉ: Scoring avec unaccent() et similarity()
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND LOWER(unaccent(COALESCE(m.ai_description, ''))) = LOWER(unaccent(search_query_semantic)) THEN 550.0
                    WHEN search_query_semantic IS NOT NULL AND unaccent(m.ai_description) ILIKE unaccent(search_query_semantic) || '%' THEN 400.0
                    WHEN search_query_semantic IS NOT NULL AND unaccent(m.ai_description) ILIKE '%' || unaccent(search_query_semantic) || '%' THEN 200.0
                    ELSE 0.0
                END +
                -- ✅ NOUVEAU: Score similarity pour erreurs de saisie
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND similarity(unaccent(LOWER(COALESCE(m.ai_description, ''))), unaccent(LOWER(search_query_semantic))) > 0.3 THEN 
                        similarity(unaccent(LOWER(COALESCE(m.ai_description, ''))), unaccent(LOWER(search_query_semantic))) * 150.0
                    ELSE 0.0
                END +
                -- ✅ Score tags communs avec unaccent
                (SELECT 
                    CASE 
                        WHEN COUNT(*) >= 2 THEN COUNT(*) * 100.0
                        WHEN COUNT(*) = 1 THEN 50.0
                        ELSE 0.0
                    END
                 FROM unnest(COALESCE(m.ai_tags, ARRAY[]::TEXT[])) tag 
                 WHERE tag = ANY(search_tags)
                 OR (search_query_semantic IS NOT NULL AND unaccent(tag) ILIKE '%' || unaccent(search_query_semantic) || '%')
                 OR (search_query_semantic IS NOT NULL AND similarity(unaccent(LOWER(tag)), unaccent(LOWER(search_query_semantic))) > 0.3)) +
                -- ✅ Score marque avec unaccent et similarity
                CASE 
                    WHEN search_marque IS NOT NULL AND (
                        unaccent(m.ai_metadata->>'marque') ILIKE unaccent(search_marque) || '%'
                        OR similarity(unaccent(LOWER(COALESCE(m.ai_metadata->>'marque', ''))), unaccent(LOWER(search_marque))) > 0.3
                    ) THEN 300.0 
                    ELSE 0.0 
                END +
                -- ✅ Score couleur avec unaccent
                CASE 
                    WHEN search_couleur IS NOT NULL AND m.ai_metadata->'couleurs' ? search_couleur THEN 100.0 
                    ELSE 0.0 
                END +
                -- ✅ Score catégorie - bonus seulement
                CASE 
                    WHEN search_category IS NOT NULL AND m.ai_category = search_category THEN 50.0 
                    ELSE 0.0 
                END +
                -- ✅ Score full-text sur description avec unaccent (langue dynamique)
                COALESCE(
                    ts_rank(to_tsvector(pg_lang, unaccent(COALESCE(m.ai_description, ''))), plainto_tsquery(pg_lang, unaccent(COALESCE(search_query_semantic, '')))) * 500.0,
                    0.0
                ) +
                -- Bonus confiance
                (COALESCE(m.ai_confidence, 0.5) * 20.0)
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM media m
        INNER JOIN services s ON s.id = m.service_id
        WHERE s.is_active = true
        AND m.type = 'image'
        AND m.ai_description IS NOT NULL
        AND NOT EXISTS (
            SELECT 1 FROM autocomplete_characteristics ac3 
            WHERE ac3.service_id = m.service_id 
            AND ac3.identifiant_base = 'produits' 
            AND ac3.is_real_product = TRUE
        )
        AND NOT EXISTS (
            SELECT 1 FROM image_analyses ia2 
            WHERE ia2.media_id = m.id AND ia2.service_id = m.service_id
        )
        AND (
            -- ✅ OPTIMISÉ 2025-01-01: Utiliser unaccent() et similarity()
            (
                (search_query_semantic IS NOT NULL AND search_query_semantic != '' AND (
                    unaccent(m.ai_description) ILIKE unaccent(search_query_semantic) || '%'
                    OR to_tsvector(pg_lang, unaccent(COALESCE(m.ai_description, ''))) @@ plainto_tsquery(pg_lang, unaccent(search_query_semantic))
                    OR similarity(unaccent(LOWER(COALESCE(m.ai_description, ''))), unaccent(LOWER(search_query_semantic))) > 0.3
                ))
                OR (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND (
                    (SELECT COUNT(*) FROM unnest(COALESCE(m.ai_tags, ARRAY[]::TEXT[])) tag 
                     WHERE tag = ANY(search_tags)
                     OR (search_query_semantic IS NOT NULL AND unaccent(tag) ILIKE '%' || unaccent(search_query_semantic) || '%')
                     OR (search_query_semantic IS NOT NULL AND similarity(unaccent(LOWER(tag)), unaccent(LOWER(search_query_semantic))) > 0.3)) >= 1
                ))
                OR (search_marque IS NOT NULL AND search_marque != '' AND (
                    unaccent(m.ai_metadata->>'marque') ILIKE unaccent(search_marque) || '%'
                    OR similarity(unaccent(LOWER(COALESCE(m.ai_metadata->>'marque', ''))), unaccent(LOWER(search_marque))) > 0.3
                ))
            )
            AND (search_couleur IS NULL OR search_couleur = '' OR m.ai_metadata->'couleurs' ? search_couleur)
            AND (search_category IS NULL OR search_category = '' OR m.ai_category = search_category)
        )
    )
    SELECT 
        cr.service_id,
        cr.analysis_id,
        cr.media_id,
        cr.product_description,
        cr.product_tags,
        cr.product_marque,
        cr.product_couleurs,
        cr.match_score,
        cr.service_data,
        -- Calculer distance GPS si coordonnées fournies
        CASE 
            WHEN gps_lat IS NOT NULL AND gps_lng IS NOT NULL THEN
                (SELECT 
                    CASE 
                        WHEN s.gps IS NOT NULL AND s.gps != '' AND s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$' THEN
                            calculate_gps_distance_km_simple(
                                gps_lat,
                                gps_lng,
                                split_part(s.gps, ',', 1)::double precision,
                                split_part(s.gps, ',', 2)::double precision
                            )
                        ELSE NULL
                    END
                FROM services s WHERE s.id = cr.service_id)
            ELSE NULL
        END::FLOAT as distance_km
    FROM combined_results cr
    WHERE cr.match_score >= 200.0  -- Seuil strict maintenu
    ORDER BY 
        cr.match_score DESC,
        distance_km ASC NULLS LAST
    LIMIT max_results;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION hybrid_image_search IS 
'✅ OPTIMISÉ 2025-01-01: Utilise unaccent() et similarity() comme keyword_search_with_gps.
Gère accents, erreurs de saisie, troncature. Aligné avec la nouvelle approche optimisée.';




-- ============================================
-- Migration: 20250101_scalability_improvements.sql
-- ============================================
-- ✅ Migrations pour la scalabilité (millions de créations vidéo simultanées)

-- ✅ Index optimisés pour les requêtes fréquentes
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_video_jobs_status_created 
    ON video_generation_jobs(status, created_at) 
    WHERE status IN ('queued', 'processing');

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_video_jobs_user_status 
    ON video_generation_jobs(user_id, status, created_at DESC);

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_studio_sessions_user_updated 
    ON studio_sessions(user_id, updated_at DESC);

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_studio_sessions_status 
    ON studio_sessions(status, created_at DESC) 
    WHERE status != 'draft';

-- ✅ Index partiel pour les jobs actifs uniquement (sans condition NOW() car non IMMUTABLE)
-- Note: Cet index couvre tous les jobs queued/processing, la condition de date sera gérée dans la requête
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_video_jobs_active 
    ON video_generation_jobs(created_at DESC) 
    WHERE status IN ('queued', 'processing');

-- ✅ Table pour le tracking des métriques en temps réel (partitionnée)
CREATE TABLE IF NOT EXISTS video_generation_metrics (
    id BIGSERIAL,
    job_id UUID NOT NULL,
    user_id INTEGER NOT NULL,
    status TEXT NOT NULL,
    duration_ms BIGINT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);

-- ✅ Partitions mensuelles pour les métriques
CREATE TABLE IF NOT EXISTS video_generation_metrics_2025_01 
    PARTITION OF video_generation_metrics
    FOR VALUES FROM ('2025-01-01') TO ('2025-02-01');

CREATE TABLE IF NOT EXISTS video_generation_metrics_2025_02 
    PARTITION OF video_generation_metrics
    FOR VALUES FROM ('2025-02-01') TO ('2025-03-01');

-- ✅ Index sur les métriques
CREATE INDEX IF NOT EXISTS idx_video_metrics_job 
    ON video_generation_metrics(job_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_video_metrics_user 
    ON video_generation_metrics(user_id, created_at DESC);

-- ✅ Table pour le rate limiting (si pas de Redis)
CREATE TABLE IF NOT EXISTS rate_limit_tracking (
    id BIGSERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL,
    endpoint TEXT NOT NULL,
    request_count INTEGER NOT NULL DEFAULT 1,
    window_start TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(user_id, endpoint, window_start)
);

CREATE INDEX IF NOT EXISTS idx_rate_limit_user_endpoint 
    ON rate_limit_tracking(user_id, endpoint, window_start DESC);

-- ✅ Nettoyage automatique des anciennes entrées de rate limiting
CREATE OR REPLACE FUNCTION cleanup_old_rate_limits()
RETURNS void AS $$
BEGIN
    DELETE FROM rate_limit_tracking 
    WHERE window_start < NOW() - INTERVAL '1 hour';
END;
$$ LANGUAGE plpgsql;

-- ✅ Optimisation des requêtes avec matérielisation pour les stats
CREATE MATERIALIZED VIEW IF NOT EXISTS video_generation_stats_hourly AS
SELECT 
    DATE_TRUNC('hour', created_at) AS hour,
    status,
    COUNT(*) AS job_count,
    AVG(EXTRACT(EPOCH FROM (updated_at - created_at))) AS avg_duration_seconds,
    PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY EXTRACT(EPOCH FROM (updated_at - created_at))) AS median_duration_seconds,
    PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY EXTRACT(EPOCH FROM (updated_at - created_at))) AS p95_duration_seconds
FROM video_generation_jobs
WHERE created_at > NOW() - INTERVAL '7 days'
GROUP BY DATE_TRUNC('hour', created_at), status;

CREATE UNIQUE INDEX IF NOT EXISTS idx_video_stats_hourly 
    ON video_generation_stats_hourly(hour, status);

-- ✅ Rafraîchissement automatique de la vue matérialisée
CREATE OR REPLACE FUNCTION refresh_video_stats()
RETURNS void AS $$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY video_generation_stats_hourly;
END;
$$ LANGUAGE plpgsql;

-- ✅ Optimisation de la table studio_preview_events
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_preview_events_session_created 
    ON studio_preview_events(session_id, created_at DESC);

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_preview_events_status 
    ON studio_preview_events(status, created_at DESC) 
    WHERE status IN ('processing', 'completed');

-- ✅ Table pour le cache des sessions (fallback si Redis indisponible)
CREATE TABLE IF NOT EXISTS studio_session_cache (
    session_id UUID PRIMARY KEY,
    cached_data JSONB NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ✅ Index sur expires_at (sans condition NOW() car non IMMUTABLE)
-- La condition de date sera gérée dans les requêtes
CREATE INDEX IF NOT EXISTS idx_session_cache_expires 
    ON studio_session_cache(expires_at);

-- ✅ Nettoyage automatique du cache expiré
CREATE OR REPLACE FUNCTION cleanup_expired_cache()
RETURNS void AS $$
BEGIN
    DELETE FROM studio_session_cache 
    WHERE expires_at < NOW();
END;
$$ LANGUAGE plpgsql;

-- ✅ Optimisation des connexions avec connection pooling hints
COMMENT ON TABLE video_generation_jobs IS 
    'Jobs de génération vidéo - Optimisé pour millions de requêtes simultanées. Utiliser FOR UPDATE SKIP LOCKED pour le processing.';

COMMENT ON TABLE studio_sessions IS 
    'Sessions de création vidéo - Index optimisés pour les requêtes par user_id et status.';

-- ✅ Statistiques mises à jour automatiquement
ANALYZE video_generation_jobs;
ANALYZE studio_sessions;
ANALYZE studio_timeline_clips;
ANALYZE studio_preview_events;



