-- ============================================
-- Migration: 20250125_create_bus_reservations.sql
-- ============================================
-- Migration: Système de réservation de places de bus
-- Date: 2025-01-25
-- Description: Gestion des réservations de places de bus pour les tickets de voyage (ticket_voyage)
-- Note: Compatible avec SQLx offline mode

-- 1. Créer la table des réservations de bus
CREATE TABLE IF NOT EXISTS bus_reservations (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    product_id TEXT NOT NULL,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    seat_id VARCHAR(50) NOT NULL,
    seat_number INTEGER NOT NULL,
    passenger_name VARCHAR(255),
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'confirmed', 'cancelled', 'expired')),
    caution_amount INTEGER DEFAULT 500,
    total_price INTEGER,
    payment_status VARCHAR(20) DEFAULT 'caution_paid' CHECK (payment_status IN ('caution_paid', 'fully_paid', 'refunded')),
    ticket_pdf_url TEXT,
    expires_at TIMESTAMP WITH TIME ZONE DEFAULT (NOW() + INTERVAL '30 minutes'),
    confirmed_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    CONSTRAINT unique_product_seat UNIQUE (product_id, seat_id)
);

-- 2. Index pour optimiser les requêtes
CREATE INDEX IF NOT EXISTS idx_bus_reservations_user ON bus_reservations(user_id);
CREATE INDEX IF NOT EXISTS idx_bus_reservations_product ON bus_reservations(product_id);
CREATE INDEX IF NOT EXISTS idx_bus_reservations_status ON bus_reservations(status);
CREATE INDEX IF NOT EXISTS idx_bus_reservations_created_at ON bus_reservations(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_bus_reservations_expires_at ON bus_reservations(expires_at) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS idx_bus_reservations_payment_status ON bus_reservations(payment_status);

-- Index composite pour requêtes courantes
CREATE INDEX IF NOT EXISTS idx_bus_reservations_product_status 
ON bus_reservations(product_id, status) WHERE status IN ('pending', 'confirmed');

-- 3. Ajouter les colonnes nécessaires dans la table products si elles n'existent pas
DO $$ 
BEGIN
    -- Colonne pour stocker la configuration du bus
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
                   WHERE table_name='products' AND column_name='bus_configuration') THEN
        ALTER TABLE products ADD COLUMN bus_configuration JSONB;
        RAISE NOTICE 'Colonne bus_configuration ajoutée à products';
    END IF;

    -- Colonne pour stocker le plan des sièges
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
                   WHERE table_name='products' AND column_name='seat_map') THEN
        ALTER TABLE products ADD COLUMN seat_map JSONB;
        RAISE NOTICE 'Colonne seat_map ajoutée à products';
    END IF;

    -- Colonne pour le nombre total de places
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
                   WHERE table_name='products' AND column_name='total_seats') THEN
        ALTER TABLE products ADD COLUMN total_seats INTEGER;
        RAISE NOTICE 'Colonne total_seats ajoutée à products';
    END IF;

    -- Colonnes pour informations ticket PDF
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
                   WHERE table_name='products' AND column_name='numero_bus') THEN
        ALTER TABLE products ADD COLUMN numero_bus VARCHAR(50);
        RAISE NOTICE 'Colonne numero_bus ajoutée à products';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
                   WHERE table_name='products' AND column_name='logo_agence') THEN
        ALTER TABLE products ADD COLUMN logo_agence TEXT;
        RAISE NOTICE 'Colonne logo_agence ajoutée à products';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
                   WHERE table_name='products' AND column_name='conditions_voyage') THEN
        ALTER TABLE products ADD COLUMN conditions_voyage TEXT;
        RAISE NOTICE 'Colonne conditions_voyage ajoutée à products';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
                   WHERE table_name='products' AND column_name='caution_reservation') THEN
        ALTER TABLE products ADD COLUMN caution_reservation INTEGER DEFAULT 500;
        RAISE NOTICE 'Colonne caution_reservation ajoutée à products';
    END IF;
END $$;

-- 4. Index sur les nouvelles colonnes de products
CREATE INDEX IF NOT EXISTS idx_products_total_seats ON products(total_seats) WHERE total_seats IS NOT NULL;

-- 5. Fonction pour valider le format du seat_id
CREATE OR REPLACE FUNCTION validate_seat_id()
RETURNS TRIGGER AS $$
BEGIN
    -- Vérifier que seat_id est au format "row-col"
    IF NEW.seat_id !~ '^\d+-\d+$' THEN
        RAISE EXCEPTION 'Format seat_id invalide: % (attendu: row-col)', NEW.seat_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger pour valider seat_id avant insertion
DROP TRIGGER IF EXISTS trigger_validate_seat_id ON bus_reservations;
CREATE TRIGGER trigger_validate_seat_id
    BEFORE INSERT OR UPDATE ON bus_reservations
    FOR EACH ROW
    EXECUTE FUNCTION validate_seat_id();

-- 6. Fonction pour mettre à jour updated_at automatiquement
CREATE OR REPLACE FUNCTION update_bus_reservation_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger pour mettre à jour automatiquement updated_at
DROP TRIGGER IF EXISTS trigger_update_bus_reservation_timestamp ON bus_reservations;
CREATE TRIGGER trigger_update_bus_reservation_timestamp
    BEFORE UPDATE ON bus_reservations
    FOR EACH ROW
    EXECUTE FUNCTION update_bus_reservation_timestamp();

-- 7. Vue pour les réservations actives avec informations du produit
CREATE OR REPLACE VIEW active_bus_reservations AS
SELECT 
    br.id,
    br.product_id,
    br.user_id,
    br.seat_id,
    br.seat_number,
    br.status,
    br.created_at,
    br.updated_at,
    COALESCE(
        u.nom_complet,
        NULLIF(TRIM(CONCAT(u.prenom, ' ', u.nom)), ''),
        u.email
    ) AS user_name,
    u.email AS user_email,
    p.name AS product_name,
    p.type AS product_type
FROM bus_reservations br
JOIN users u ON u.id = br.user_id
LEFT JOIN products p ON p.id::text = br.product_id
WHERE br.status = 'reserved';

-- 8. Commentaires pour la documentation
COMMENT ON TABLE bus_reservations IS 'Réservations de places de bus pour les tickets de voyage (ticket_voyage)';
COMMENT ON COLUMN bus_reservations.id IS 'Identifiant unique de la réservation (UUID au format text)';
COMMENT ON COLUMN bus_reservations.product_id IS 'Identifiant du produit (ticket de voyage) au format text';
COMMENT ON COLUMN bus_reservations.seat_id IS 'Identifiant de la place au format row-col (ex: 1-2, 3-4)';
COMMENT ON COLUMN bus_reservations.seat_number IS 'Numéro de la place affiché aux utilisateurs (1, 2, 3...)';
COMMENT ON COLUMN bus_reservations.status IS 'Statut: reserved (réservée), confirmed (confirmée), cancelled (annulée)';

COMMENT ON COLUMN products.bus_configuration IS 'Configuration du bus: {rows, seatsPerRow, firstRowSeats, allSeatsAvailable}';
COMMENT ON COLUMN products.seat_map IS 'Plan complet des sièges avec statuts et types (array JSONB)';
COMMENT ON COLUMN products.total_seats IS 'Nombre total de places passagers (excluant le chauffeur)';

-- 9. Fonction pour expirer automatiquement les réservations non confirmées
CREATE OR REPLACE FUNCTION expire_unconfirmed_reservations()
RETURNS TABLE(
    reservation_id TEXT,
    product_id TEXT,
    seat_id VARCHAR(50),
    user_id INTEGER
) AS $$
BEGIN
    -- Marquer comme expirées et libérer les places
    RETURN QUERY
    UPDATE bus_reservations
    SET 
        status = 'expired',
        payment_status = 'refunded',
        updated_at = NOW()
    WHERE status = 'pending'
        AND expires_at <= NOW()
    RETURNING 
        id as reservation_id,
        bus_reservations.product_id,
        bus_reservations.seat_id,
        bus_reservations.user_id;
END;
$$ LANGUAGE plpgsql;

-- 10. Fonction pour confirmer une réservation après paiement complet
CREATE OR REPLACE FUNCTION confirm_bus_reservation(
    p_reservation_id TEXT,
    p_total_price INTEGER,
    p_ticket_pdf_url TEXT
) RETURNS JSONB AS $$
DECLARE
    v_reservation RECORD;
    v_user_balance BIGINT;
    v_remaining_amount INTEGER;
BEGIN
    -- Récupérer la réservation
    SELECT * INTO v_reservation
    FROM bus_reservations
    WHERE id = p_reservation_id AND status = 'pending';
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Réservation non trouvée ou déjà traitée'
        );
    END IF;
    
    -- Vérifier si pas expirée
    IF v_reservation.expires_at < NOW() THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Réservation expirée'
        );
    END IF;
    
    -- Calculer le montant restant à payer
    v_remaining_amount := p_total_price - v_reservation.caution_amount;
    
    -- Vérifier le solde de l'utilisateur
    SELECT tokens_balance INTO v_user_balance
    FROM users
    WHERE id = v_reservation.user_id;
    
    IF v_user_balance < v_remaining_amount THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Solde insuffisant',
            'required', v_remaining_amount,
            'balance', v_user_balance
        );
    END IF;
    
    -- Débiter le solde
    UPDATE users
    SET tokens_balance = tokens_balance - v_remaining_amount
    WHERE id = v_reservation.user_id;
    
    -- Confirmer la réservation
    UPDATE bus_reservations
    SET 
        status = 'confirmed',
        payment_status = 'fully_paid',
        total_price = p_total_price,
        ticket_pdf_url = p_ticket_pdf_url,
        confirmed_at = NOW(),
        updated_at = NOW()
    WHERE id = p_reservation_id;
    
    RETURN jsonb_build_object(
        'success', TRUE,
        'message', 'Réservation confirmée avec succès',
        'total_paid', p_total_price,
        'caution', v_reservation.caution_amount,
        'remaining_paid', v_remaining_amount,
        'new_balance', v_user_balance - v_remaining_amount,
        'ticket_url', p_ticket_pdf_url
    );
END;
$$ LANGUAGE plpgsql;

-- 11. Commentaires sur les nouvelles colonnes
COMMENT ON COLUMN bus_reservations.passenger_name IS 'Nom du passager (pour le ticket PDF)';
COMMENT ON COLUMN bus_reservations.caution_amount IS 'Montant de la caution payée pour bloquer la place (FCFA)';
COMMENT ON COLUMN bus_reservations.total_price IS 'Prix total du ticket (FCFA)';
COMMENT ON COLUMN bus_reservations.payment_status IS 'caution_paid: caution seulement, fully_paid: ticket payé, refunded: remboursé';
COMMENT ON COLUMN bus_reservations.ticket_pdf_url IS 'URL du ticket PDF généré après confirmation';
COMMENT ON COLUMN bus_reservations.expires_at IS 'Date d''expiration de la réservation (30 min par défaut)';

-- 12. Statistiques initiales
SELECT 
    COUNT(*) as total_reservations,
    COUNT(CASE WHEN status = 'pending' THEN 1 END) as pending,
    COUNT(CASE WHEN status = 'confirmed' THEN 1 END) as confirmed,
    COUNT(CASE WHEN status = 'cancelled' THEN 1 END) as cancelled,
    COUNT(CASE WHEN status = 'expired' THEN 1 END) as expired
FROM bus_reservations;



-- ============================================
-- Migration: 20250126001_bus_return_trips_system.sql
-- ============================================
-- Migration: Système complet aller-retour pour tickets de bus
-- Date: 2025-01-26
-- Description: Gestion des trajets retour, notifications, et paiements de tickets

-- 1. Table pour les paiements de tickets de bus (tracabilité complète)
CREATE TABLE IF NOT EXISTS bus_ticket_payments (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    agency_user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, -- Propriétaire agence
    product_id TEXT NOT NULL, -- Le ticket de voyage
    reservation_ids TEXT[] NOT NULL, -- IDs des réservations de ce paiement
    
    -- Montants détaillés
    ticket_price INTEGER NOT NULL, -- Prix unitaire du ticket
    number_of_tickets INTEGER NOT NULL DEFAULT 1, -- Nombre de tickets
    subtotal INTEGER NOT NULL, -- ticket_price × number_of_tickets
    booking_fee INTEGER NOT NULL DEFAULT 500, -- Frais de réservation (500 FCFA fixe)
    total_amount INTEGER NOT NULL, -- subtotal + booking_fee
    currency VARCHAR(10) NOT NULL DEFAULT 'XAF',
    
    -- Informations voyage
    bus_number VARCHAR(50),
    departure_city TEXT NOT NULL,
    arrival_city TEXT NOT NULL,
    departure_date VARCHAR(20) NOT NULL,
    departure_time VARCHAR(10) NOT NULL,
    company_name TEXT,
    
    -- Statut paiement
    payment_status VARCHAR(20) NOT NULL DEFAULT 'completed' CHECK (payment_status IN ('completed', 'refunded', 'partial_refund')),
    payment_method JSONB,
    
    -- Tracabilité
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    refunded_at TIMESTAMP WITH TIME ZONE,
    refund_amount INTEGER DEFAULT 0,
    refund_reason TEXT,
    
    CONSTRAINT positive_amounts CHECK (ticket_price > 0 AND subtotal > 0 AND total_amount > 0)
);

-- 2. Table pour les demandes de retour
CREATE TABLE IF NOT EXISTS return_trip_requests (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    outbound_ticket_id TEXT NOT NULL, -- ID du ticket aller
    outbound_payment_id TEXT REFERENCES bus_ticket_payments(id),
    
    -- Informations trajet retour souhaité
    return_from TEXT NOT NULL, -- Destination du voyage aller
    return_to TEXT NOT NULL, -- Départ du voyage aller (inverse)
    preferred_return_date VARCHAR(20) NOT NULL, -- DD/MM/YYYY
    preferred_return_time VARCHAR(10), -- HH:MM (optionnel, flexible)
    date_flexibility_days INTEGER DEFAULT 1, -- ±1 jour acceptable
    
    -- Passagers et places
    passenger_names TEXT[] NOT NULL, -- Noms des passagers
    number_of_seats INTEGER NOT NULL,
    
    -- Informations paiement
    already_paid BOOLEAN DEFAULT TRUE, -- Payé avec le ticket aller
    paid_amount INTEGER, -- Montant déjà payé pour le retour
    
    -- Matching avec bus retour
    matched_product_id TEXT, -- ID du bus retour trouvé
    matched_at TIMESTAMP WITH TIME ZONE,
    notification_sent BOOLEAN DEFAULT FALSE,
    notification_sent_at TIMESTAMP WITH TIME ZONE,
    
    -- Réservation effectuée
    reservation_completed BOOLEAN DEFAULT FALSE,
    reservation_ids TEXT[], -- IDs des réservations confirmées
    completed_at TIMESTAMP WITH TIME ZONE,
    
    -- Statut
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'matched', 'completed', 'cancelled', 'expired')),
    expires_at TIMESTAMP WITH TIME ZONE DEFAULT (NOW() + INTERVAL '90 days'), -- Expire après 3 mois
    
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 3. Table pour les places pré-réservées (retour)
CREATE TABLE IF NOT EXISTS prebooked_return_seats (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    return_request_id TEXT NOT NULL REFERENCES return_trip_requests(id) ON DELETE CASCADE,
    product_id TEXT NOT NULL, -- Bus retour
    seat_ids TEXT[] NOT NULL, -- Places pré-réservées
    passenger_names TEXT[] NOT NULL,
    
    status VARCHAR(20) DEFAULT 'reserved' CHECK (status IN ('reserved', 'confirmed', 'released')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    confirmed_at TIMESTAMP WITH TIME ZONE
);

-- 4. Index pour performances
CREATE INDEX IF NOT EXISTS idx_bus_ticket_payments_user ON bus_ticket_payments(user_id);
CREATE INDEX IF NOT EXISTS idx_bus_ticket_payments_agency ON bus_ticket_payments(agency_user_id);
CREATE INDEX IF NOT EXISTS idx_bus_ticket_payments_date ON bus_ticket_payments(departure_date, departure_time);
CREATE INDEX IF NOT EXISTS idx_bus_ticket_payments_route ON bus_ticket_payments(departure_city, arrival_city);
CREATE INDEX IF NOT EXISTS idx_bus_ticket_payments_created ON bus_ticket_payments(created_at DESC);

CREATE INDEX IF NOT EXISTS idx_return_requests_user ON return_trip_requests(user_id);
CREATE INDEX IF NOT EXISTS idx_return_requests_status ON return_trip_requests(status);
CREATE INDEX IF NOT EXISTS idx_return_requests_route ON return_trip_requests(return_from, return_to);
CREATE INDEX IF NOT EXISTS idx_return_requests_date ON return_trip_requests(preferred_return_date);
CREATE INDEX IF NOT EXISTS idx_return_requests_pending ON return_trip_requests(status, preferred_return_date) 
WHERE status = 'pending';

CREATE INDEX IF NOT EXISTS idx_prebooked_seats_product ON prebooked_return_seats(product_id);
CREATE INDEX IF NOT EXISTS idx_prebooked_seats_request ON prebooked_return_seats(return_request_id);

-- 5. Fonction pour matcher automatiquement les demandes de retour
CREATE OR REPLACE FUNCTION match_return_trip_requests(p_product_id TEXT)
RETURNS TABLE(
    request_id TEXT,
    user_id INTEGER,
    passenger_names TEXT[],
    number_of_seats INTEGER
) AS $$
BEGIN
    -- Trouver les demandes de retour correspondantes
    -- Quand un nouveau bus est créé, on check s'il match des demandes
    RETURN QUERY
    SELECT 
        rtr.id as request_id,
        rtr.user_id,
        rtr.passenger_names,
        rtr.number_of_seats
    FROM return_trip_requests rtr
    JOIN products p ON p.id::text = p_product_id
    WHERE rtr.status = 'pending'
        -- Match route (inverse du voyage)
        AND rtr.return_from = p.depart
        AND rtr.return_to = p.destination
        -- Match date (avec flexibilité)
        AND p.date_depart BETWEEN 
            (rtr.preferred_return_date::date - INTERVAL '1 day' * rtr.date_flexibility_days)
            AND (rtr.preferred_return_date::date + INTERVAL '1 day' * rtr.date_flexibility_days)
        -- Vérifier qu'il y a assez de places
        AND p.total_seats >= rtr.number_of_seats;
END;
$$ LANGUAGE plpgsql;

-- 6. Fonction pour pré-réserver les places du retour
CREATE OR REPLACE FUNCTION prebook_return_seats(
    p_request_id TEXT,
    p_product_id TEXT,
    p_seat_ids TEXT[],
    p_passenger_names TEXT[]
) RETURNS JSONB AS $$
DECLARE
    v_request RECORD;
BEGIN
    -- Vérifier que la demande existe
    SELECT * INTO v_request
    FROM return_trip_requests
    WHERE id = p_request_id AND status = 'pending';
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Demande de retour non trouvée'
        );
    END IF;
    
    -- Créer la pré-réservation
    INSERT INTO prebooked_return_seats (
        return_request_id,
        product_id,
        seat_ids,
        passenger_names,
        status
    ) VALUES (
        p_request_id,
        p_product_id,
        p_seat_ids,
        p_passenger_names,
        'reserved'
    );
    
    -- Marquer comme matched
    UPDATE return_trip_requests
    SET 
        matched_product_id = p_product_id,
        matched_at = NOW(),
        status = 'matched'
    WHERE id = p_request_id;
    
    RETURN jsonb_build_object(
        'success', TRUE,
        'message', 'Places pré-réservées avec succès'
    );
END;
$$ LANGUAGE plpgsql;

-- 7. Fonction pour calculer frais de réservation selon devise
CREATE OR REPLACE FUNCTION calculate_booking_fee(p_currency VARCHAR(10))
RETURNS INTEGER AS $$
BEGIN
    -- 500 FCFA de base
    CASE p_currency
        WHEN 'XAF' THEN RETURN 500;
        WHEN 'EUR' THEN RETURN 1; -- ~1€
        WHEN 'USD' THEN RETURN 1; -- ~1$
        WHEN 'XOF' THEN RETURN 500; -- Même zone
        ELSE RETURN 500; -- Par défaut
    END CASE;
END;
$$ LANGUAGE plpgsql;

-- 8. Vue pour les statistiques des paiements par agence
DROP VIEW IF EXISTS bus_payment_stats_by_agency;
CREATE OR REPLACE VIEW bus_payment_stats_by_agency AS
SELECT 
    btp.agency_user_id,
    COALESCE(
        u.nom_complet,
        NULLIF(TRIM(CONCAT(u.prenom, ' ', u.nom)), ''),
        u.email
    ) AS agency_name,
    COUNT(*) as total_payments,
    SUM(btp.number_of_tickets) as total_tickets_sold,
    SUM(btp.subtotal) as total_ticket_revenue,
    SUM(btp.booking_fee) as total_booking_fees,
    SUM(btp.total_amount) as total_revenue,
    DATE_TRUNC('month', btp.created_at) as month
FROM bus_ticket_payments btp
JOIN users u ON u.id = btp.agency_user_id
WHERE btp.payment_status = 'completed'
GROUP BY 
    btp.agency_user_id,
    COALESCE(
        u.nom_complet,
        NULLIF(TRIM(CONCAT(u.prenom, ' ', u.nom)), ''),
        u.email
    ),
    DATE_TRUNC('month', btp.created_at)
ORDER BY month DESC, total_revenue DESC;

-- 9. Commentaires
COMMENT ON TABLE bus_ticket_payments IS 'Paiements de tickets de bus avec tracabilité complète (user, agence, voyage, montants séparés)';
COMMENT ON COLUMN bus_ticket_payments.booking_fee IS 'Frais de réservation en ligne fixe de 500 FCFA (par réservation, pas par ticket)';
COMMENT ON COLUMN bus_ticket_payments.subtotal IS 'Montant tickets uniquement (ticket_price × number_of_tickets)';
COMMENT ON COLUMN bus_ticket_payments.total_amount IS 'Montant total (subtotal + booking_fee)';

COMMENT ON TABLE return_trip_requests IS 'Demandes de trajet retour avec matching automatique quand bus créé';
COMMENT ON COLUMN return_trip_requests.already_paid IS 'TRUE si payé avec aller, FALSE si à payer séparément';
COMMENT ON COLUMN return_trip_requests.date_flexibility_days IS 'Flexibilité en jours (±X jours acceptable)';

COMMENT ON TABLE prebooked_return_seats IS 'Places pré-réservées pour trajets retour (déjà payées)';

-- 10. Statistiques initiales
SELECT 
    COUNT(*) as total_payments,
    SUM(number_of_tickets) as total_tickets,
    SUM(subtotal) as revenue_tickets,
    SUM(booking_fee) as revenue_fees,
    SUM(total_amount) as revenue_total
FROM bus_ticket_payments;



-- ============================================
-- Migration: 20250126002_user_push_tokens.sql
-- ============================================
-- Migration pour les tokens de notification push des utilisateurs
-- Permet de stocker les tokens Expo Push et d'envoyer des notifications

-- Table des tokens de notification push
CREATE TABLE IF NOT EXISTS user_push_tokens (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::TEXT,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    push_token TEXT NOT NULL,
    platform TEXT NOT NULL, -- 'ios', 'android'
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    -- Index pour recherche rapide par utilisateur
    CONSTRAINT unique_user_push_token UNIQUE (user_id, push_token)
);

-- Index pour recherche par utilisateur
CREATE INDEX IF NOT EXISTS idx_user_push_tokens_user_id ON user_push_tokens(user_id);
CREATE INDEX IF NOT EXISTS idx_user_push_tokens_active ON user_push_tokens(is_active) WHERE is_active = TRUE;

-- Trigger pour mettre à jour updated_at
CREATE OR REPLACE FUNCTION update_user_push_tokens_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_update_user_push_tokens_timestamp
    BEFORE UPDATE ON user_push_tokens
    FOR EACH ROW
    EXECUTE FUNCTION update_user_push_tokens_timestamp();

-- Commentaires
COMMENT ON TABLE user_push_tokens IS 'Stocke les tokens Expo Push des utilisateurs pour les notifications';
COMMENT ON COLUMN user_push_tokens.push_token IS 'Token Expo Push (format: ExponentPushToken[...])';
COMMENT ON COLUMN user_push_tokens.platform IS 'Plateforme: ios ou android';
COMMENT ON COLUMN user_push_tokens.is_active IS 'Indique si le token est encore valide';



-- ============================================
-- Migration: 20250127_000001_create_user_saved_addresses.sql
-- ============================================
-- Migration: Création de la table user_saved_addresses pour mémoriser les adresses de livraison
-- Date: 2025-01-27
-- Description: Permet aux utilisateurs de sauvegarder leurs adresses de pickup et dropoff pour les réutiliser facilement

CREATE TABLE IF NOT EXISTS user_saved_addresses (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    
    -- Identification de l'adresse
    label VARCHAR(100) NOT NULL, -- Ex: "Domicile", "Bureau", "Maison", "Adresse 1"
    address_type VARCHAR(20) NOT NULL CHECK (address_type IN ('pickup', 'dropoff', 'both')),
    
    -- Données géographiques
    address TEXT NOT NULL,
    latitude DOUBLE PRECISION NOT NULL,
    longitude DOUBLE PRECISION NOT NULL,
    
    -- Enrichissement (composants LocationObject)
    location_data JSONB DEFAULT '{}'::jsonb, -- Pour stocker quartier, ville, pays, etc.
    
    -- Informations complémentaires
    contact_name VARCHAR(255),
    contact_phone VARCHAR(50),
    instructions TEXT, -- Instructions de livraison spécifiques
    building_number VARCHAR(50),
    floor VARCHAR(50),
    apartment VARCHAR(50),
    
    -- Métadonnées
    is_default_pickup BOOLEAN DEFAULT FALSE,
    is_default_dropoff BOOLEAN DEFAULT FALSE,
    usage_count INTEGER DEFAULT 0, -- Nombre de fois utilisée
    last_used_at TIMESTAMPTZ,
    is_active BOOLEAN DEFAULT TRUE,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Un seul label par utilisateur (éviter les doublons)
    UNIQUE(user_id, label)
);

-- Index pour recherche rapide
CREATE INDEX IF NOT EXISTS idx_user_saved_addresses_user_id ON user_saved_addresses(user_id);
CREATE INDEX IF NOT EXISTS idx_user_saved_addresses_user_type ON user_saved_addresses(user_id, address_type);
CREATE INDEX IF NOT EXISTS idx_user_saved_addresses_default ON user_saved_addresses(user_id, is_default_pickup, is_default_dropoff);
CREATE INDEX IF NOT EXISTS idx_user_saved_addresses_active ON user_saved_addresses(user_id, is_active);
CREATE INDEX IF NOT EXISTS idx_user_saved_addresses_last_used ON user_saved_addresses(user_id, last_used_at DESC NULLS LAST);

-- Index spatial pour recherche géographique (nécessite PostGIS)
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'postgis') THEN
        CREATE INDEX IF NOT EXISTS idx_user_saved_addresses_location 
        ON user_saved_addresses USING GIST(ST_MakePoint(longitude, latitude));
    END IF;
END $$;

-- Trigger pour mettre à jour updated_at automatiquement
CREATE OR REPLACE FUNCTION update_user_saved_addresses_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_update_user_saved_addresses_updated_at
    BEFORE UPDATE ON user_saved_addresses
    FOR EACH ROW
    EXECUTE FUNCTION update_user_saved_addresses_updated_at();

-- Fonction pour incrémenter usage_count et mettre à jour last_used_at
CREATE OR REPLACE FUNCTION increment_user_saved_address_usage(address_id INTEGER)
RETURNS VOID AS $$
BEGIN
    UPDATE user_saved_addresses
    SET usage_count = usage_count + 1,
        last_used_at = NOW(),
        updated_at = NOW()
    WHERE id = address_id;
END;
$$ LANGUAGE plpgsql;

-- Contraintes pour s'assurer qu'il n'y a qu'une seule adresse par défaut de chaque type par utilisateur
-- Note: Cette contrainte sera gérée au niveau application, mais on peut aussi créer des triggers si nécessaire

-- Commentaires pour documentation
COMMENT ON TABLE user_saved_addresses IS 'Adresses sauvegardées par les utilisateurs pour pickup et dropoff de livraisons';
COMMENT ON COLUMN user_saved_addresses.label IS 'Nom donné par l''utilisateur à cette adresse (ex: "Domicile", "Bureau")';
COMMENT ON COLUMN user_saved_addresses.address_type IS 'Type d''adresse: pickup (récupération), dropoff (livraison), both (les deux)';
COMMENT ON COLUMN user_saved_addresses.location_data IS 'Données enrichies LocationObject (quartier, ville, pays, etc.) au format JSONB';
COMMENT ON COLUMN user_saved_addresses.usage_count IS 'Nombre de fois que cette adresse a été utilisée dans une livraison';
COMMENT ON COLUMN user_saved_addresses.last_used_at IS 'Date de dernière utilisation de cette adresse';







