-- ============================================
-- Migration: 20250127_012_create_plugin_marketplace.sql
-- ============================================
-- ✅ Migration pour créer la table plugin_marketplace
-- Date: 2025-01-27
-- Phase 2: Système Plugins - Marketplace

CREATE TABLE IF NOT EXISTS plugin_marketplace (
    id SERIAL PRIMARY KEY,
    plugin_id VARCHAR(255) NOT NULL UNIQUE,
    name VARCHAR(255) NOT NULL,
    version VARCHAR(50) NOT NULL,
    author VARCHAR(255) NOT NULL,
    description TEXT,
    category VARCHAR(50) NOT NULL CHECK (category IN ('effect', 'transition', 'filter', 'export', 'integration', 'other')),
    tags TEXT[] DEFAULT ARRAY[]::TEXT[],
    icon_url TEXT,
    homepage_url TEXT,
    license VARCHAR(100) NOT NULL DEFAULT 'MIT',
    min_yukpo_version VARCHAR(50),
    download_url TEXT NOT NULL,
    download_count INTEGER DEFAULT 0,
    rating DECIMAL(3,2) DEFAULT 0.0 CHECK (rating >= 0.0 AND rating <= 5.0),
    rating_count INTEGER DEFAULT 0,
    price DECIMAL(10,2) DEFAULT 0.0,
    is_premium BOOLEAN DEFAULT false,
    is_featured BOOLEAN DEFAULT false,
    is_verified BOOLEAN DEFAULT false,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Index pour recherche rapide
CREATE INDEX IF NOT EXISTS idx_plugin_marketplace_category ON plugin_marketplace(category);
CREATE INDEX IF NOT EXISTS idx_plugin_marketplace_tags ON plugin_marketplace USING GIN(tags);
CREATE INDEX IF NOT EXISTS idx_plugin_marketplace_featured ON plugin_marketplace(is_featured) WHERE is_featured = true;
CREATE INDEX IF NOT EXISTS idx_plugin_marketplace_rating ON plugin_marketplace(rating DESC);
CREATE INDEX IF NOT EXISTS idx_plugin_marketplace_downloads ON plugin_marketplace(download_count DESC);

-- Fonction pour mettre à jour updated_at
CREATE OR REPLACE FUNCTION update_plugin_marketplace_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ✅ CORRECTION 2026-02-01: DROP le trigger avant de le recréer pour éviter "already exists"
DROP TRIGGER IF EXISTS trigger_update_plugin_marketplace_updated_at ON plugin_marketplace;
-- Trigger pour updated_at
CREATE TRIGGER trigger_update_plugin_marketplace_updated_at
    BEFORE UPDATE ON plugin_marketplace
    FOR EACH ROW
    EXECUTE FUNCTION update_plugin_marketplace_updated_at();

-- Table pour les dépendances de plugins
CREATE TABLE IF NOT EXISTS plugin_dependencies (
    id SERIAL PRIMARY KEY,
    plugin_id VARCHAR(255) NOT NULL REFERENCES plugin_marketplace(plugin_id) ON DELETE CASCADE,
    dependency_id VARCHAR(255) NOT NULL,
    dependency_version VARCHAR(50),
    is_required BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_plugin_dependencies_plugin ON plugin_dependencies(plugin_id);
CREATE INDEX IF NOT EXISTS idx_plugin_dependencies_dep ON plugin_dependencies(dependency_id);

-- Table pour les permissions de plugins
CREATE TABLE IF NOT EXISTS plugin_permissions (
    id SERIAL PRIMARY KEY,
    plugin_id VARCHAR(255) NOT NULL REFERENCES plugin_marketplace(plugin_id) ON DELETE CASCADE,
    permission_name VARCHAR(100) NOT NULL,
    permission_description TEXT,
    is_required BOOLEAN DEFAULT false,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_plugin_permissions_plugin ON plugin_permissions(plugin_id);

-- Table pour les avis/ratings de plugins
CREATE TABLE IF NOT EXISTS plugin_reviews (
    id SERIAL PRIMARY KEY,
    plugin_id VARCHAR(255) NOT NULL REFERENCES plugin_marketplace(plugin_id) ON DELETE CASCADE,
    user_id INTEGER NOT NULL,
    rating INTEGER NOT NULL CHECK (rating >= 1 AND rating <= 5),
    review_text TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(plugin_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_plugin_reviews_plugin ON plugin_reviews(plugin_id);
CREATE INDEX IF NOT EXISTS idx_plugin_reviews_user ON plugin_reviews(user_id);
CREATE INDEX IF NOT EXISTS idx_plugin_reviews_rating ON plugin_reviews(rating);

-- Fonction pour mettre à jour le rating moyen d'un plugin
CREATE OR REPLACE FUNCTION update_plugin_rating()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE plugin_marketplace
    SET 
        rating = (
            SELECT COALESCE(AVG(rating), 0.0)
            FROM plugin_reviews
            WHERE plugin_id = NEW.plugin_id
        ),
        rating_count = (
            SELECT COUNT(*)
            FROM plugin_reviews
            WHERE plugin_id = NEW.plugin_id
        )
    WHERE plugin_id = NEW.plugin_id;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger pour mettre à jour le rating
CREATE TRIGGER trigger_update_plugin_rating
    AFTER INSERT OR UPDATE OR DELETE ON plugin_reviews
    FOR EACH ROW
    EXECUTE FUNCTION update_plugin_rating();



-- ============================================
-- Migration: 20250127_013_create_version_control_tables.sql
-- ============================================
-- ✅ NOUVEAU Phase 4: Tables pour version control vidéos
-- Date: 2025-01-27

CREATE TABLE IF NOT EXISTS video_versions (
    id SERIAL PRIMARY KEY,
    timeline_id VARCHAR(255) NOT NULL,
    version_number INTEGER NOT NULL,
    version_name VARCHAR(255),
    created_by INTEGER NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    snapshot_data JSONB NOT NULL,
    description TEXT,
    UNIQUE(timeline_id, version_number)
);

CREATE INDEX IF NOT EXISTS idx_video_versions_timeline ON video_versions(timeline_id);
CREATE INDEX IF NOT EXISTS idx_video_versions_created_by ON video_versions(created_by);
CREATE INDEX IF NOT EXISTS idx_video_versions_created_at ON video_versions(created_at DESC);

-- Table pour commentaires sur timeline
CREATE TABLE IF NOT EXISTS timeline_comments (
    id SERIAL PRIMARY KEY,
    timeline_id VARCHAR(255) NOT NULL,
    user_id INTEGER NOT NULL,
    comment_text TEXT NOT NULL,
    timestamp_seconds FLOAT,
    clip_id VARCHAR(255),
    parent_comment_id INTEGER REFERENCES timeline_comments(id) ON DELETE CASCADE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    resolved_at TIMESTAMP WITH TIME ZONE,
    resolved_by INTEGER
);

CREATE INDEX IF NOT EXISTS idx_timeline_comments_timeline ON timeline_comments(timeline_id);
CREATE INDEX IF NOT EXISTS idx_timeline_comments_user ON timeline_comments(user_id);
CREATE INDEX IF NOT EXISTS idx_timeline_comments_parent ON timeline_comments(parent_comment_id);

-- Table pour cursors partagés (position utilisateurs)
CREATE TABLE IF NOT EXISTS shared_cursors (
    id SERIAL PRIMARY KEY,
    timeline_id VARCHAR(255) NOT NULL,
    user_id INTEGER NOT NULL,
    position_seconds FLOAT NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(timeline_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_shared_cursors_timeline ON shared_cursors(timeline_id);
CREATE INDEX IF NOT EXISTS idx_shared_cursors_user ON shared_cursors(user_id);
CREATE INDEX IF NOT EXISTS idx_shared_cursors_updated ON shared_cursors(updated_at DESC);

-- Fonction pour mettre à jour updated_at
CREATE OR REPLACE FUNCTION update_timeline_comments_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_update_timeline_comments_updated_at
    BEFORE UPDATE ON timeline_comments
    FOR EACH ROW
    EXECUTE FUNCTION update_timeline_comments_updated_at();



