-- ============================================================================

COMMENT ON INDEX idx_hospital_consultations_user_status_date IS 
    'Optimise la recherche des consultations d''un utilisateur par statut et date';
COMMENT ON INDEX idx_pharmacy_orders_user_status_created IS 
    'Optimise la recherche des commandes d''un utilisateur par statut et date';
COMMENT ON INDEX idx_lab_examinations_user_status_date IS 
    'Optimise la recherche des examens d''un utilisateur par statut et date';



-- ============================================
-- Migration: 20250127_create_bourse_livre_advanced_tables.sql
-- ============================================
-- Migration: Tables avancées pour Bourse du Livre avec IA et analytics
-- Date: 2025-01-27
-- Description: Tables pour échanges, recommandations IA, historique prix et analytics
-- Compatible SQLx offline mode

-- Extension PostGIS pour géolocalisation (déjà créée normalement)
CREATE EXTENSION IF NOT EXISTS postgis;

-- ============================================================================
-- 1. TABLE : Échanges de livres (historique et tracking)
-- ============================================================================
CREATE TABLE IF NOT EXISTS book_exchanges (
    id SERIAL PRIMARY KEY,
    livre_offert_id INTEGER NOT NULL REFERENCES livres_scolaires(id) ON DELETE CASCADE,
    livre_souhaite_id INTEGER NOT NULL REFERENCES livres_scolaires(id) ON DELETE CASCADE,
    initiateur_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    participant_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    troc_id INTEGER REFERENCES troc_livres_scolaires(id) ON DELETE SET NULL,
    
    -- Type d'échange
    exchange_type VARCHAR(50) NOT NULL CHECK (exchange_type IN ('troc', 'achat', 'vente', 'don')),
    prix_negocie DECIMAL(10, 2), -- Prix négocié si achat/vente
    
    -- Statut
    statut VARCHAR(50) NOT NULL DEFAULT 'en_attente' CHECK (statut IN ('en_attente', 'accepte', 'refuse', 'complete', 'annule')),
    
    -- Évaluation
    rating_initiateur INTEGER CHECK (rating_initiateur >= 1 AND rating_initiateur <= 5),
    rating_participant INTEGER CHECK (rating_participant >= 1 AND rating_participant <= 5),
    comment_initiateur TEXT,
    comment_participant TEXT,
    
    -- Dates
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    date_echange TIMESTAMPTZ, -- Date prévue pour l'échange
    date_complete TIMESTAMPTZ -- Date de finalisation
    
    -- Contraintes
    -- CONSTRAINT unique_exchange UNIQUE (livre_offert_id, livre_souhaite_id, initiateur_id, participant_id)
);

CREATE INDEX IF NOT EXISTS idx_book_exchanges_livre_offert ON book_exchanges(livre_offert_id);
CREATE INDEX IF NOT EXISTS idx_book_exchanges_livre_souhaite ON book_exchanges(livre_souhaite_id);
CREATE INDEX IF NOT EXISTS idx_book_exchanges_initiateur ON book_exchanges(initiateur_id, statut);
CREATE INDEX IF NOT EXISTS idx_book_exchanges_participant ON book_exchanges(participant_id, statut);
CREATE INDEX IF NOT EXISTS idx_book_exchanges_statut ON book_exchanges(statut, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_book_exchanges_troc ON book_exchanges(troc_id) WHERE troc_id IS NOT NULL;

-- ============================================================================
-- 2. TABLE : Recommandations IA de livres
-- ============================================================================
CREATE TABLE IF NOT EXISTS book_recommendations (
    id SERIAL PRIMARY KEY,
    user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
    livre_id INTEGER REFERENCES livres_scolaires(id) ON DELETE CASCADE,
    
    -- Critères de recommandation
    classe_actuelle TEXT,
    classe_souhaitee TEXT,
    matiere TEXT,
    niveau TEXT,
    
    -- Résultats IA
    score_recommendation DECIMAL(5, 2) NOT NULL, -- Score 0-100
    reasoning TEXT, -- Explication de la recommandation
    alternative_books INTEGER[], -- IDs de livres alternatifs
    
    -- Métadonnées
    model_used VARCHAR(100), -- Modèle IA utilisé
    tokens_consumed INTEGER,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL -- Expiration du cache
    
    -- Contraintes
    -- CONSTRAINT unique_recommendation UNIQUE (user_id, livre_id, classe_actuelle, classe_souhaitee, matiere)
);

CREATE INDEX IF NOT EXISTS idx_book_recommendations_user ON book_recommendations(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_book_recommendations_livre ON book_recommendations(livre_id);
CREATE INDEX IF NOT EXISTS idx_book_recommendations_score ON book_recommendations(score_recommendation DESC);
-- Index sur expires_at pour les requêtes de filtrage
-- Note: Les index partiels avec NOW() ne sont pas supportés (fonction non-IMMUTABLE)
-- Le filtrage WHERE expires_at > NOW() sera fait dans les requêtes SQL
CREATE INDEX IF NOT EXISTS idx_book_recommendations_expires ON book_recommendations(expires_at);

-- ============================================================================
-- 3. TABLE : Historique des prix (pour suggestions prix IA)
-- ============================================================================
CREATE TABLE IF NOT EXISTS book_price_history (
    id SERIAL PRIMARY KEY,
    livre_id INTEGER REFERENCES livres_scolaires(id) ON DELETE CASCADE,
    
    -- Informations livre
    titre TEXT NOT NULL,
    auteur TEXT,
    editeur TEXT,
    isbn TEXT,
    classe TEXT,
    matiere TEXT,
    etat_livre TEXT,
    
    -- Prix
    prix_vente DECIMAL(10, 2) NOT NULL,
    prix_achat DECIMAL(10, 2), -- Prix d'achat si disponible
    devise VARCHAR(10) DEFAULT 'XAF',
    
    -- Source
    source_type VARCHAR(50) NOT NULL CHECK (source_type IN ('echange', 'achat', 'vente', 'estimation_ia', 'marche')),
    source_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    
    -- Localisation
    ville TEXT,
    quartier TEXT,
    gps TEXT,
    
    -- Métadonnées
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    is_verified BOOLEAN DEFAULT false -- Prix vérifié par admin
);

CREATE INDEX IF NOT EXISTS idx_book_price_history_livre ON book_price_history(livre_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_book_price_history_isbn ON book_price_history(isbn) WHERE isbn IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_book_price_history_classe_matiere ON book_price_history(classe, matiere);
CREATE INDEX IF NOT EXISTS idx_book_price_history_ville ON book_price_history(ville, quartier);
CREATE INDEX IF NOT EXISTS idx_book_price_history_date ON book_price_history(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_book_price_history_verified ON book_price_history(is_verified, created_at DESC) WHERE is_verified = true;

-- ============================================================================
-- 4. TABLE : Analytics Bourse du Livre
-- ============================================================================
CREATE TABLE IF NOT EXISTS book_analytics (
    id SERIAL PRIMARY KEY,
    user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
    livre_id INTEGER REFERENCES livres_scolaires(id) ON DELETE CASCADE,
    
    -- Métriques
    nombre_vues INTEGER DEFAULT 0,
    nombre_contacts INTEGER DEFAULT 0,
    nombre_echanges_completes INTEGER DEFAULT 0,
    nombre_echanges_annules INTEGER DEFAULT 0,
    
    -- Scores
    score_popularite DECIMAL(5, 2) DEFAULT 0, -- Score de popularité (0-100)
    score_satisfaction DECIMAL(5, 2), -- Score moyen de satisfaction (1-5)
    
    -- Démographie
    repartition_classes JSONB, -- {"6ème": 10, "5ème": 25, ...}
    repartition_villes JSONB, -- {"Douala": 15, "Yaoundé": 20, ...}
    
    -- Période
    periode_debut DATE NOT NULL,
    periode_fin DATE NOT NULL,
    
    -- Métadonnées
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Contraintes
    CONSTRAINT unique_analytics UNIQUE (user_id, livre_id, periode_debut, periode_fin)
);

CREATE INDEX IF NOT EXISTS idx_book_analytics_user ON book_analytics(user_id, periode_debut DESC);
CREATE INDEX IF NOT EXISTS idx_book_analytics_livre ON book_analytics(livre_id, periode_debut DESC);
CREATE INDEX IF NOT EXISTS idx_book_analytics_periode ON book_analytics(periode_debut, periode_fin);

-- ============================================================================
-- TRIGGERS POUR UPDATED_AT
-- ============================================================================

CREATE OR REPLACE FUNCTION update_book_exchanges_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_update_book_exchanges_updated_at ON book_exchanges;
CREATE TRIGGER trigger_update_book_exchanges_updated_at
    BEFORE UPDATE ON book_exchanges
    FOR EACH ROW
    EXECUTE FUNCTION update_book_exchanges_updated_at();

CREATE OR REPLACE FUNCTION update_book_analytics_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_update_book_analytics_updated_at ON book_analytics;
CREATE TRIGGER trigger_update_book_analytics_updated_at
    BEFORE UPDATE ON book_analytics
    FOR EACH ROW
    EXECUTE FUNCTION update_book_analytics_updated_at();

-- ============================================================================
-- FONCTIONS UTILITAIRES
-- ============================================================================

-- Fonction pour calculer le prix moyen suggéré pour un livre
CREATE OR REPLACE FUNCTION calculate_suggested_price(
    p_livre_id INTEGER,
    p_ville TEXT DEFAULT NULL,
    p_etat_livre TEXT DEFAULT NULL
) RETURNS DECIMAL(10, 2) AS $$
DECLARE
    v_avg_price DECIMAL(10, 2);
BEGIN
    SELECT AVG(prix_vente) INTO v_avg_price
    FROM book_price_history
    WHERE livre_id = p_livre_id
        AND is_verified = true
        AND created_at >= NOW() - INTERVAL '6 months'
        AND (p_ville IS NULL OR ville = p_ville)
        AND (p_etat_livre IS NULL OR etat_livre = p_etat_livre);
    
    RETURN COALESCE(v_avg_price, 0);
END;
$$ LANGUAGE plpgsql;

-- Fonction pour nettoyer les recommandations expirées
CREATE OR REPLACE FUNCTION cleanup_expired_recommendations()
RETURNS INTEGER AS $$
DECLARE
    v_deleted_count INTEGER;
BEGIN
    DELETE FROM book_recommendations
    WHERE expires_at < NOW();
    
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RETURN v_deleted_count;
END;
$$ LANGUAGE plpgsql;

-- ============================================================================
-- COMMENTAIRES
-- ============================================================================

COMMENT ON TABLE book_exchanges IS 'Historique et tracking des échanges de livres (troc, achat, vente, don)';
COMMENT ON TABLE book_recommendations IS 'Recommandations IA de livres avec scores et reasoning';
COMMENT ON TABLE book_price_history IS 'Historique des prix pour suggestions prix IA basées sur marché';
COMMENT ON TABLE book_analytics IS 'Analytics pour prestataires : vues, contacts, échanges, popularité';

COMMENT ON COLUMN book_exchanges.exchange_type IS 'Type d''échange: troc, achat, vente, don';
COMMENT ON COLUMN book_recommendations.score_recommendation IS 'Score de recommandation IA (0-100)';
COMMENT ON COLUMN book_price_history.source_type IS 'Source du prix: echange, achat, vente, estimation_ia, marche';
COMMENT ON COLUMN book_analytics.score_popularite IS 'Score de popularité calculé (0-100)';



-- ============================================
-- Migration: 20250127_create_hospital_advanced_tables.sql
-- ============================================
-- Migration: Tables avancées pour Hôpitaux/Cliniques
-- Date: 2025-01-27
-- Description: Tables pour consultations, urgences, créneaux horaires et analytics
-- Compatible SQLx offline mode

-- ============================================================================
-- 1. TABLE : Consultations médicales
-- ============================================================================
CREATE TABLE IF NOT EXISTS hospital_consultations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    hospital_id INTEGER NOT NULL REFERENCES hopitaux_cliniques(id) ON DELETE CASCADE,
    service_id INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    doctor_id INTEGER, -- ID du médecin (peut être NULL si non spécifié)
    doctor_name VARCHAR(255), -- Nom du médecin
    specialty VARCHAR(100), -- Spécialité
    appointment_date TIMESTAMPTZ NOT NULL,
    appointment_duration_minutes INTEGER DEFAULT 30,
    status VARCHAR(20) NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled', 'confirmed', 'in_progress', 'completed', 'cancelled', 'no_show')),
    symptoms TEXT, -- Symptômes décrits par le patient
    diagnosis TEXT, -- Diagnostic (rempli après consultation)
    prescription JSONB, -- Prescription médicale (médicaments, posologie, etc.)
    notes TEXT, -- Notes additionnelles
    consultation_fee DECIMAL(10,2), -- Frais de consultation
    payment_status VARCHAR(20) DEFAULT 'pending' CHECK (payment_status IN ('pending', 'paid', 'refunded')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at TIMESTAMPTZ -- Date de fin de consultation
);

CREATE INDEX IF NOT EXISTS idx_hospital_consultations_hospital ON hospital_consultations(hospital_id);
CREATE INDEX IF NOT EXISTS idx_hospital_consultations_user ON hospital_consultations(user_id);
CREATE INDEX IF NOT EXISTS idx_hospital_consultations_service ON hospital_consultations(service_id);
CREATE INDEX IF NOT EXISTS idx_hospital_consultations_date ON hospital_consultations(appointment_date);
CREATE INDEX IF NOT EXISTS idx_hospital_consultations_status ON hospital_consultations(status);
CREATE INDEX IF NOT EXISTS idx_hospital_consultations_specialty ON hospital_consultations(specialty) WHERE specialty IS NOT NULL;

-- ============================================================================
-- 2. TABLE : Urgences médicales
-- ============================================================================
CREATE TABLE IF NOT EXISTS hospital_emergencies (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    hospital_id INTEGER NOT NULL REFERENCES hopitaux_cliniques(id) ON DELETE CASCADE,
    service_id INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    severity_level INTEGER NOT NULL CHECK (severity_level >= 1 AND severity_level <= 5), -- 1=Critique, 5=Non urgent
    symptoms TEXT NOT NULL, -- Symptômes décrits
    arrival_time TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    triage_time TIMESTAMPTZ, -- Heure du triage
    treatment_start_time TIMESTAMPTZ, -- Heure de début de traitement
    treatment_end_time TIMESTAMPTZ, -- Heure de fin de traitement
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'triaged', 'in_treatment', 'discharged', 'transferred', 'cancelled')),
    diagnosis TEXT, -- Diagnostic
    treatment_description TEXT, -- Description du traitement
    wait_time_minutes INTEGER, -- Temps d'attente calculé
    treatment_duration_minutes INTEGER, -- Durée du traitement
    transferred_to_hospital_id INTEGER, -- Si transféré vers un autre hôpital
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_hospital_emergencies_hospital ON hospital_emergencies(hospital_id);
CREATE INDEX IF NOT EXISTS idx_hospital_emergencies_user ON hospital_emergencies(user_id);
CREATE INDEX IF NOT EXISTS idx_hospital_emergencies_status ON hospital_emergencies(status);
CREATE INDEX IF NOT EXISTS idx_hospital_emergencies_severity ON hospital_emergencies(severity_level);
CREATE INDEX IF NOT EXISTS idx_hospital_emergencies_arrival ON hospital_emergencies(arrival_time);
CREATE INDEX IF NOT EXISTS idx_hospital_emergencies_pending ON hospital_emergencies(hospital_id, status) WHERE status IN ('pending', 'triaged', 'in_treatment');

-- ============================================================================
-- 3. TABLE : Créneaux horaires de consultation
-- ============================================================================
CREATE TABLE IF NOT EXISTS hospital_slots (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    hospital_id INTEGER NOT NULL REFERENCES hopitaux_cliniques(id) ON DELETE CASCADE,
    service_id INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE,
    doctor_id INTEGER, -- ID du médecin (optionnel)
    doctor_name VARCHAR(255), -- Nom du médecin
    specialty VARCHAR(100), -- Spécialité
    slot_date DATE NOT NULL,
    slot_time TIME NOT NULL,
    duration_minutes INTEGER NOT NULL DEFAULT 30,
    status VARCHAR(20) NOT NULL DEFAULT 'available' CHECK (status IN ('available', 'booked', 'cancelled', 'blocked')),
    consultation_id UUID REFERENCES hospital_consultations(id) ON DELETE SET NULL, -- Si réservé, lien vers consultation
    notes TEXT, -- Notes additionnelles (ex: "Bloqué pour réunion")
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(hospital_id, slot_date, slot_time, doctor_id) -- Éviter les doublons
);

CREATE INDEX IF NOT EXISTS idx_hospital_slots_hospital ON hospital_slots(hospital_id);
CREATE INDEX IF NOT EXISTS idx_hospital_slots_service ON hospital_slots(service_id);
CREATE INDEX IF NOT EXISTS idx_hospital_slots_date ON hospital_slots(slot_date, slot_time);
CREATE INDEX IF NOT EXISTS idx_hospital_slots_status ON hospital_slots(status);
CREATE INDEX IF NOT EXISTS idx_hospital_slots_specialty ON hospital_slots(specialty) WHERE specialty IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_hospital_slots_available ON hospital_slots(hospital_id, slot_date, status) WHERE status = 'available';

-- ============================================================================
-- 4. TABLE : Statistiques et analytics des hôpitaux
-- ============================================================================
CREATE TABLE IF NOT EXISTS hospital_analytics (
    id SERIAL PRIMARY KEY,
    hospital_id INTEGER NOT NULL REFERENCES hopitaux_cliniques(id) ON DELETE CASCADE,
    service_id INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE,
    date DATE NOT NULL,
    -- Métriques consultations
    total_consultations INTEGER DEFAULT 0,
    completed_consultations INTEGER DEFAULT 0,
    cancelled_consultations INTEGER DEFAULT 0,
    no_show_consultations INTEGER DEFAULT 0,
    -- Métriques urgences
    total_emergencies INTEGER DEFAULT 0,
    avg_wait_time_minutes DECIMAL(10,2),
    avg_treatment_duration_minutes DECIMAL(10,2),
    -- Revenus
    total_revenue DECIMAL(10,2) DEFAULT 0,
    consultation_revenue DECIMAL(10,2) DEFAULT 0,
    emergency_revenue DECIMAL(10,2) DEFAULT 0,
    -- Satisfaction
    avg_rating DECIMAL(3,2), -- Note moyenne sur 5
    total_ratings INTEGER DEFAULT 0,
    -- Taux d'occupation
    occupation_rate DECIMAL(5,2), -- Pourcentage
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(hospital_id, date)
);

CREATE INDEX IF NOT EXISTS idx_hospital_analytics_hospital ON hospital_analytics(hospital_id);
CREATE INDEX IF NOT EXISTS idx_hospital_analytics_date ON hospital_analytics(date);
CREATE INDEX IF NOT EXISTS idx_hospital_analytics_service ON hospital_analytics(service_id);

-- ============================================================================
-- 5. FONCTIONS : Calcul automatique des statistiques
-- ============================================================================

-- Fonction pour calculer le temps d'attente moyen des urgences
CREATE OR REPLACE FUNCTION calculate_hospital_avg_wait_time(hospital_id_param INTEGER, date_param DATE DEFAULT CURRENT_DATE)
RETURNS DECIMAL(10,2) AS $$
DECLARE
    avg_wait DECIMAL(10,2);
BEGIN
    SELECT COALESCE(AVG(EXTRACT(EPOCH FROM (treatment_start_time - arrival_time)) / 60), 0)
    INTO avg_wait
    FROM hospital_emergencies
    WHERE hospital_id = hospital_id_param
        AND DATE(arrival_time) = date_param
        AND treatment_start_time IS NOT NULL
        AND status IN ('in_treatment', 'discharged', 'transferred');
    
    RETURN ROUND(avg_wait, 2);
END;
$$ LANGUAGE plpgsql;

-- Fonction pour calculer le taux d'occupation des créneaux
CREATE OR REPLACE FUNCTION calculate_hospital_occupation_rate(hospital_id_param INTEGER, date_param DATE DEFAULT CURRENT_DATE)
RETURNS DECIMAL(5,2) AS $$
DECLARE
    total_slots INTEGER;
    booked_slots INTEGER;
    occupation_rate DECIMAL(5,2);
BEGIN
    SELECT COUNT(*)
    INTO total_slots
    FROM hospital_slots
    WHERE hospital_id = hospital_id_param
        AND slot_date = date_param
        AND status IN ('available', 'booked');
    
    SELECT COUNT(*)
    INTO booked_slots
    FROM hospital_slots
    WHERE hospital_id = hospital_id_param
        AND slot_date = date_param
        AND status = 'booked';
    
    IF total_slots > 0 THEN
        occupation_rate := (booked_slots::DECIMAL / total_slots::DECIMAL) * 100;
    ELSE
        occupation_rate := 0;
    END IF;
    
    RETURN ROUND(occupation_rate, 2);
END;
$$ LANGUAGE plpgsql;

-- ============================================================================
-- 6. TRIGGERS : Mise à jour automatique des analytics
-- ============================================================================

-- Trigger pour mettre à jour les analytics quand une consultation change de statut
CREATE OR REPLACE FUNCTION update_hospital_analytics_on_consultation()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO hospital_analytics (hospital_id, service_id, date, total_consultations, completed_consultations, cancelled_consultations, no_show_consultations)
    VALUES (
        NEW.hospital_id,
        NEW.service_id,
        DATE(NEW.appointment_date),
        CASE WHEN NEW.status IN ('scheduled', 'confirmed', 'in_progress', 'completed') THEN 1 ELSE 0 END,
        CASE WHEN NEW.status = 'completed' THEN 1 ELSE 0 END,
        CASE WHEN NEW.status = 'cancelled' THEN 1 ELSE 0 END,
        CASE WHEN NEW.status = 'no_show' THEN 1 ELSE 0 END
    )
    ON CONFLICT (hospital_id, date)
    DO UPDATE SET
        total_consultations = hospital_analytics.total_consultations + 
            CASE WHEN NEW.status IN ('scheduled', 'confirmed', 'in_progress', 'completed') THEN 1 ELSE 0 END,
        completed_consultations = hospital_analytics.completed_consultations + 
            CASE WHEN NEW.status = 'completed' THEN 1 ELSE 0 END,
        cancelled_consultations = hospital_analytics.cancelled_consultations + 
            CASE WHEN NEW.status = 'cancelled' THEN 1 ELSE 0 END,
        no_show_consultations = hospital_analytics.no_show_consultations + 
            CASE WHEN NEW.status = 'no_show' THEN 1 ELSE 0 END,
        updated_at = NOW();
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Pas de trigger automatique pour éviter la surcharge, on utilisera des jobs programmés

