    offre_id INTEGER NOT NULL REFERENCES offres_emploi(id) ON DELETE CASCADE,
    candidat_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    
    -- Score de matching
    score_total DECIMAL(5, 2) NOT NULL, -- Score global (0-100)
