-- ============================================
-- Migration: 20250128_improve_return_trip_matching.sql
-- ============================================
-- Migration: Amélioration du système de matching pour retours
-- Date: 2025-01-28
-- Description: Fonction améliorée pour matcher les demandes de retour avec les buses créés

-- 1. Fonction améliorée pour matcher une demande de retour avec un produit
CREATE OR REPLACE FUNCTION match_return_trip_request_with_product(
    p_request_id TEXT,
    p_product_id TEXT
) RETURNS JSONB AS $$
DECLARE
    v_request RECORD;
    v_product RECORD;
    v_matches BOOLEAN := FALSE;
    v_available_seats INTEGER;
BEGIN
    -- Récupérer la demande
    SELECT * INTO v_request
    FROM return_trip_requests
    WHERE id = p_request_id AND status = 'pending';
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Demande non trouvée ou déjà traitée');
    END IF;
    
    -- Récupérer le produit
    SELECT 
        p.*,
        (p.metadata->>'departure_city')::text as departure_city,
        (p.metadata->>'arrival_city')::text as arrival_city,
        (p.metadata->>'departure_date')::date as departure_date,
        (p.metadata->>'departure_time')::time as departure_time
    INTO v_product
    FROM products p
    WHERE p.id::text = p_product_id AND p.type = 'ticket_voyage';
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Produit non trouvé');
    END IF;
    
    -- Vérifier le matching
    -- 1. Route inverse (return_from = arrival_city, return_to = departure_city)
    IF v_request.return_from = v_product.arrival_city 
       AND v_request.return_to = v_product.departure_city THEN
        -- 2. Date avec flexibilité
        IF v_product.departure_date BETWEEN 
            (v_request.preferred_return_date::date - INTERVAL '1 day' * v_request.date_flexibility_days)
            AND (v_request.preferred_return_date::date + INTERVAL '1 day' * v_request.date_flexibility_days) THEN
            -- 3. Places disponibles
            SELECT COUNT(*) INTO v_available_seats
            FROM bus_seats
            WHERE product_id = p_product_id AND is_available = TRUE;
            
            IF v_available_seats >= v_request.number_of_seats THEN
                v_matches := TRUE;
                
                -- Mettre à jour la demande
                UPDATE return_trip_requests
                SET 
                    matched_product_id = p_product_id,
                    matched_at = NOW(),
                    status = 'matched',
                    updated_at = NOW()
                WHERE id = p_request_id;
            END IF;
        END IF;
    END IF;
    
    RETURN jsonb_build_object(
        'success', TRUE,
        'matches', v_matches,
        'available_seats', v_available_seats,
        'required_seats', v_request.number_of_seats
    );
END;
$$ LANGUAGE plpgsql;

-- 2. Fonction pour matcher automatiquement toutes les demandes en attente avec un nouveau produit
CREATE OR REPLACE FUNCTION auto_match_return_requests_for_product(p_product_id TEXT)
RETURNS INTEGER AS $$
DECLARE
    v_product RECORD;
    v_request RECORD;
    v_matched_count INTEGER := 0;
BEGIN
    -- Récupérer les infos du produit
    SELECT 
        (metadata->>'departure_city')::text as departure_city,
        (metadata->>'arrival_city')::text as arrival_city,
        (metadata->>'departure_date')::date as departure_date
    INTO v_product
    FROM products
    WHERE id::text = p_product_id AND type = 'ticket_voyage';
    
    IF NOT FOUND THEN
        RETURN 0;
    END IF;
    
    -- Parcourir les demandes en attente et essayer de les matcher
    FOR v_request IN 
        SELECT * FROM return_trip_requests
        WHERE status = 'pending'
            AND return_from = v_product.arrival_city
            AND return_to = v_product.departure_city
            AND v_product.departure_date BETWEEN 
                (preferred_return_date::date - INTERVAL '1 day' * date_flexibility_days)
                AND (preferred_return_date::date + INTERVAL '1 day' * date_flexibility_days)
    LOOP
        -- Vérifier les places disponibles
        IF EXISTS (
            SELECT 1 FROM bus_seats
            WHERE product_id = p_product_id 
                AND is_available = TRUE
            HAVING COUNT(*) >= v_request.number_of_seats
        ) THEN
            -- Matcher la demande
            UPDATE return_trip_requests
            SET 
                matched_product_id = p_product_id,
                matched_at = NOW(),
                status = 'matched',
                notification_sent = FALSE, -- Sera envoyée par le système
                updated_at = NOW()
            WHERE id = v_request.id;
            
            v_matched_count := v_matched_count + 1;
            
            -- TODO: Déclencher notification push (fait ailleurs dans le code)
        END IF;
    END LOOP;
    
    RETURN v_matched_count;
END;
$$ LANGUAGE plpgsql;

-- 3. Commentaires
COMMENT ON FUNCTION match_return_trip_request_with_product IS 'Match une demande de retour spécifique avec un produit bus';
COMMENT ON FUNCTION auto_match_return_requests_for_product IS 'Match automatiquement toutes les demandes en attente avec un nouveau produit créé';



-- ============================================
-- Migration: 20250128_improve_stock_management.sql
-- ============================================
-- ✅ Migration : Amélioration de la gestion du stock
-- Date : 2025-01-28
-- Description : 
--   1. Modifie deactivate_expired_products() pour inclure vérification stock = 0
--   2. Ajoute index pour optimiser les vérifications de stock
--   3. Uniquement pour les produits (is_tarissable = TRUE)

-- ✅ 0. DROP la fonction existante pour changer le type de retour
DROP FUNCTION IF EXISTS deactivate_expired_products();

-- ✅ 1. Modifier la fonction deactivate_expired_products() pour inclure vérification stock
CREATE OR REPLACE FUNCTION deactivate_expired_products()
RETURNS TABLE(
    service_id INTEGER,
    product_index INTEGER,
    product_nom TEXT,
    user_id INTEGER,
    deactivation_reason TEXT
) AS $$
BEGIN
    RETURN QUERY
    UPDATE products_lifecycle pl
    SET 
        is_active = FALSE,
        updated_at = NOW(),
        deactivation_count = deactivation_count + 1
    FROM services s
    WHERE pl.service_id = s.id
        AND pl.is_active = TRUE
        AND (
            -- Critère 1: Délai expiré (existant)
            pl.auto_deactivate_at <= NOW()
            OR
            -- ✅ NOUVEAU Critère 2: Stock = 0 (uniquement pour les produits)
            (
                s.is_tarissable = TRUE  -- Uniquement pour les produits
                AND EXISTS (
                    SELECT 1 
                    FROM autocomplete_combinations ac
                    WHERE ac.service_id = s.id
                        AND ac.stock IS NOT NULL
                        AND ac.stock <= 0
                )
            )
        )
    RETURNING 
        pl.service_id,
        pl.product_index,
        pl.product_nom,
        s.user_id,
        CASE 
            WHEN pl.auto_deactivate_at <= NOW() THEN 'expired_time'
            ELSE 'stock_zero'
        END::TEXT;
END;
$$ LANGUAGE plpgsql;

-- ✅ 2. Créer index pour optimiser les vérifications de stock
CREATE INDEX IF NOT EXISTS idx_autocomplete_combinations_stock_check 
ON autocomplete_combinations(service_id, stock) 
WHERE stock IS NOT NULL AND stock <= 0;

CREATE INDEX IF NOT EXISTS idx_services_is_tarissable 
ON services(is_tarissable) 
WHERE is_tarissable = TRUE;

-- ✅ 3. Commentaires
COMMENT ON FUNCTION deactivate_expired_products() IS 
'Désactive automatiquement les produits expirés (30 jours) OU en rupture de stock (stock <= 0). Uniquement pour les produits (is_tarissable = TRUE).';



-- ============================================
-- Migration: 20250128_optimize_flash_blackfriday_scalability.sql
-- ============================================
-- ✅ Migration: Optimisations scalabilité Flash Sales et Black Friday
-- Date: 2025-01-28
-- Objectif: Index et vues matérialisées pour gérer des millions d'interactions simultanées

-- Index pour flash sales
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_flash_sales_status_start 
ON live_flash_sales(status, start_at) 
WHERE status IN ('scheduled', 'live');

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_flash_reservations_sale_user 
ON live_flash_sale_reservations(flash_sale_id, user_id);

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_flash_reservations_sale_quantity 
ON live_flash_sale_reservations(flash_sale_id, quantity);

-- Index pour Black Friday / Global Promo
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_global_promo_entries_event_status 
ON global_promo_entries(event_id, status) 
WHERE status IN ('approved', 'published');

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_global_promo_entries_service 
ON global_promo_entries(service_id) 
WHERE status IN ('approved', 'published');

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_global_promo_products_highlighted_priority 
ON global_promo_products(highlighted DESC, priority_score DESC);

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_global_promo_events_status_dates 
ON global_promo_events(status, starts_at, ends_at) 
WHERE status IN ('scheduled', 'live');

-- Index full-text pour recherche (si PostgreSQL >= 12)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_global_promo_events_search 
ON global_promo_events USING gin(to_tsvector('french', display_name || ' ' || COALESCE(theme, '')));

-- Vue matérialisée pour le catalogue (refresh toutes les 30 secondes)
CREATE MATERIALIZED VIEW IF NOT EXISTS global_promo_catalog_cache AS
SELECT
    e.id AS entry_id,
    e.event_id,
    e.service_id,
    e.discount_percentage,
    e.promo_price_cfa,
    e.stock_cap,
    e.availability,
    e.status AS entry_status,
    ev.id AS event_id_alias,
    ev.slug AS event_slug,
    ev.theme AS event_theme,
    ev.display_name AS event_display_name,
    ev.starts_at AS event_starts_at,
    ev.ends_at AS event_ends_at,
    ev.status AS event_status,
    gp.id AS product_id,
    gp.priority_score AS product_priority_score,
    gp.highlighted AS product_highlighted,
    gp.snapshot AS product_snapshot
FROM global_promo_entries e
JOIN global_promo_events ev ON ev.id = e.event_id
LEFT JOIN global_promo_products gp ON gp.promo_entry_id = e.id
WHERE ev.status IN ('scheduled', 'live')
  AND e.status IN ('approved', 'published')
  AND ev.ends_at >= NOW();

CREATE UNIQUE INDEX IF NOT EXISTS idx_global_promo_catalog_cache_entry_id ON global_promo_catalog_cache(entry_id);
CREATE INDEX IF NOT EXISTS idx_global_promo_catalog_cache_highlighted_priority ON global_promo_catalog_cache(product_highlighted DESC, product_priority_score DESC);
CREATE INDEX IF NOT EXISTS idx_global_promo_catalog_cache_starts_at ON global_promo_catalog_cache(event_starts_at);
CREATE INDEX IF NOT EXISTS idx_global_promo_catalog_cache_ends_at ON global_promo_catalog_cache(event_ends_at);

-- Commentaires pour documentation
COMMENT ON INDEX idx_flash_sales_status_start IS 'Optimise les requêtes de flash sales actives';
COMMENT ON INDEX idx_flash_reservations_sale_user IS 'Optimise les vérifications de réservations utilisateur';
COMMENT ON INDEX idx_global_promo_entries_event_status IS 'Optimise les requêtes de catalogue par événement';
COMMENT ON INDEX idx_global_promo_products_highlighted_priority IS 'Optimise le tri par priorité et mise en avant';
COMMENT ON MATERIALIZED VIEW global_promo_catalog_cache IS 'Cache matérialisé pour le catalogue Black Friday (refresh toutes les 30s)';



