-- ============================================
-- Migration: 20251020006_improve_product_search_all_fields.sql
-- ============================================
-- Migration pour améliorer la recherche dans TOUS les champs des produits
-- Date: 2025-10-20
-- Description: Indexe dynamiquement tous les champs JSONB des produits, peu importe le type

-- 1. Fonction pour extraire récursivement tous les textes d'un produit JSONB
CREATE OR REPLACE FUNCTION extract_all_product_text(product JSONB)
RETURNS TEXT AS $$
DECLARE
    result TEXT := '';
    key TEXT;
    value JSONB;
BEGIN
    -- Parcourir toutes les clés du produit
    FOR key, value IN SELECT * FROM jsonb_each(product)
    LOOP
        -- Si c'est une chaîne, l'ajouter
        IF jsonb_typeof(value) = 'string' THEN
            result := result || ' ' || (value #>> '{}');
        
        -- Si c'est un tableau, extraire tous les éléments
        ELSIF jsonb_typeof(value) = 'array' THEN
            result := result || ' ' || (
                SELECT string_agg(elem #>> '{}', ' ')
                FROM jsonb_array_elements_text(value) AS elem
            );
        
        -- Si c'est un objet, extraire récursivement
        ELSIF jsonb_typeof(value) = 'object' THEN
            -- Pour les objets simples, extraire les valeurs
            result := result || ' ' || (
                SELECT string_agg(v #>> '{}', ' ')
                FROM jsonb_each(value) AS kv(k, v)
                WHERE jsonb_typeof(kv.v) = 'string'
            );
        
        -- Si c'est un booléen ou nombre, le convertir en texte
        ELSIF jsonb_typeof(value) IN ('boolean', 'number') THEN
            result := result || ' ' || (value #>> '{}');
        END IF;
    END LOOP;
    
    RETURN trim(result);
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- 2. Fonction utilitaire pour agréger le texte de tous les produits d'un service
CREATE OR REPLACE FUNCTION extract_service_products_text(service_data JSONB)
RETURNS TEXT AS $$
DECLARE
    aggregated TEXT := '';
    products JSONB;
    product_record JSONB;
BEGIN
    products := CASE 
        WHEN jsonb_typeof(service_data->'produits') = 'array' 
        THEN service_data->'produits'
        ELSE '[]'::jsonb
    END;

    FOR product_record IN SELECT * FROM jsonb_array_elements(products)
    LOOP
        aggregated := aggregated || ' ' || extract_all_product_text(product_record);
    END LOOP;

    RETURN trim(aggregated);
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- 3. Index GIN sur le texte extrait de tous les produits
CREATE INDEX IF NOT EXISTS idx_services_products_fulltext_all 
ON services USING GIN (
    to_tsvector('french', extract_service_products_text(data))
);

-- 4. Fonction améliorée de scoring produits qui cherche dans TOUS les champs
CREATE OR REPLACE FUNCTION calculate_product_relevance_score_v2(
    service_data JSONB,
    search_query TEXT
)
RETURNS FLOAT AS $$
DECLARE
    products JSONB;
    total_score FLOAT := 0.0;
    product_record JSONB;
    product_text TEXT;
BEGIN
    -- Extraire les produits
    products := CASE 
        WHEN jsonb_typeof(service_data->'produits') = 'array' 
        THEN service_data->'produits'
        ELSE '[]'::jsonb
    END;
    
    -- Parcourir chaque produit
    FOR product_record IN SELECT * FROM jsonb_array_elements(products)
    LOOP
        -- Extraire tout le texte du produit (tous champs confondus)
        product_text := extract_all_product_text(product_record);
        
        -- Calculer le score full-text
        total_score := total_score + ts_rank(
            to_tsvector('french', product_text),
            plainto_tsquery('french', search_query)
        ) * 3.0;
        
        -- Bonus pour correspondances exactes dans les champs clés
        IF product_record->>'nom' ILIKE '%' || search_query || '%' THEN
            total_score := total_score + 5.0;
        END IF;
        
        IF product_record->>'description' ILIKE '%' || search_query || '%' THEN
            total_score := total_score + 3.0;
        END IF;
        
        -- Bonus pour champs spécifiques métier (nouveaux champs)
        -- Clinique/Hôpital
        IF product_record->>'typeEtablissement' ILIKE '%' || search_query || '%' THEN
            total_score := total_score + 4.0;
        END IF;
        
        IF product_record->'prestationsMedicales' IS NOT NULL THEN
            IF EXISTS (
                SELECT 1 FROM jsonb_array_elements_text(product_record->'prestationsMedicales') AS prestation
                WHERE prestation ILIKE '%' || search_query || '%'
            ) THEN
                total_score := total_score + 4.0;
            END IF;
        END IF;
        
        -- Déménagement
        IF product_record->>'typeDemenagement' ILIKE '%' || search_query || '%' THEN
            total_score := total_score + 4.0;
        END IF;
        
        IF product_record->>'typeVehicule' ILIKE '%' || search_query || '%' THEN
            total_score := total_score + 3.0;
        END IF;
        
        -- Autres champs fréquents
        IF product_record->>'marque' ILIKE '%' || search_query || '%' OR
           product_record->>'modele' ILIKE '%' || search_query || '%' OR
           product_record->>'ville' ILIKE '%' || search_query || '%' OR
           product_record->>'quartier' ILIKE '%' || search_query || '%' OR
           product_record->>'couleur' ILIKE '%' || search_query || '%' OR
           product_record->>'taille' ILIKE '%' || search_query || '%' THEN
            total_score := total_score + 2.5;
        END IF;
    END LOOP;
    
    RETURN total_score;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- 5. Vue matérialisée pour cache de recherche produits (optionnel, pour performance)
CREATE MATERIALIZED VIEW IF NOT EXISTS products_search_cache AS
SELECT 
    s.id as service_id,
    s.user_id,
    s.data->'titre_service'->>'valeur' as titre,
    s.data->'category'->>'valeur' as category,
    jsonb_array_elements(
        CASE 
            WHEN jsonb_typeof(s.data->'produits') = 'array' 
            THEN s.data->'produits'
            ELSE '[]'::jsonb
        END
    ) as product,
    to_tsvector('french', extract_all_product_text(
        jsonb_array_elements(
            CASE 
                WHEN jsonb_typeof(s.data->'produits') = 'array' 
                THEN s.data->'produits'
                ELSE '[]'::jsonb
            END
        )
    )) as product_tsvector
FROM services s
WHERE s.is_active = TRUE;

-- Index sur la vue matérialisée
CREATE INDEX IF NOT EXISTS idx_products_search_cache_tsvector 
ON products_search_cache USING GIN(product_tsvector);

CREATE INDEX IF NOT EXISTS idx_products_search_cache_service 
ON products_search_cache(service_id);

-- 5. Fonction de rafraîchissement automatique (à appeler périodiquement)
CREATE OR REPLACE FUNCTION refresh_products_search_cache()
RETURNS void AS $$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY products_search_cache;
END;
$$ LANGUAGE plpgsql;

-- 6. Amélioration de la fonction de recherche existante
-- Remplacer l'ancien scoring produits par le nouveau
COMMENT ON FUNCTION calculate_product_relevance_score_v2 IS 'Calcule le score en recherchant dans TOUS les champs JSONB des produits (clinique, déménagement, etc.)';
COMMENT ON FUNCTION extract_all_product_text IS 'Extrait récursivement tout le texte d''un produit JSONB pour indexation full-text';
COMMENT ON MATERIALIZED VIEW products_search_cache IS 'Cache de recherche produits avec tsvector pré-calculé pour performance';

-- 7. Trigger pour rafraîchir le cache quand un service est modifié (optionnel)
-- Note: REFRESH MATERIALIZED VIEW CONCURRENTLY nécessite un UNIQUE INDEX
CREATE UNIQUE INDEX IF NOT EXISTS idx_products_search_cache_unique 
ON products_search_cache(service_id, (product->>'id'));

-- 8. Fonction de recherche optimisée utilisant le cache
CREATE OR REPLACE FUNCTION search_products_optimized(
    search_query TEXT,
    category_filter TEXT DEFAULT NULL,
    max_results INTEGER DEFAULT 100
)
RETURNS TABLE(
    service_id INTEGER,
    product JSONB,
    score FLOAT
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        psc.service_id,
        psc.product,
        ts_rank(psc.product_tsvector, plainto_tsquery('french', search_query)) as score
    FROM products_search_cache psc
    WHERE 
        (category_filter IS NULL OR psc.category ILIKE '%' || category_filter || '%')
        AND psc.product_tsvector @@ plainto_tsquery('french', search_query)
    ORDER BY score DESC
    LIMIT max_results;
END;
$$ LANGUAGE plpgsql STABLE;

-- Commentaires
COMMENT ON FUNCTION search_products_optimized IS 'Recherche optimisée dans les produits utilisant le cache matérialisé';

-- Note pour l'utilisation :
-- Pour mettre à jour le cache : SELECT refresh_products_search_cache();
-- Créer un cron job ou trigger selon les besoins de fraîcheur des données



-- ============================================
-- Migration: 20251021001_add_ai_image_analysis.sql
-- ============================================
-- Migration pour ajouter l'analyse IA des images dans la table media
-- Permet la recherche intelligente par image sans pgvector
-- Date: 2025-10-21
-- Compatible avec sqlx offline

-- Ajouter les colonnes d'analyse IA
ALTER TABLE media
ADD COLUMN IF NOT EXISTS ai_description TEXT,
ADD COLUMN IF NOT EXISTS ai_tags TEXT[],
ADD COLUMN IF NOT EXISTS ai_category VARCHAR(100),
ADD COLUMN IF NOT EXISTS ai_metadata JSONB,
ADD COLUMN IF NOT EXISTS ai_analyzed_at TIMESTAMP WITH TIME ZONE,
ADD COLUMN IF NOT EXISTS ai_model_used VARCHAR(100),
ADD COLUMN IF NOT EXISTS ai_confidence FLOAT;

-- Ajouter des commentaires
COMMENT ON COLUMN media.ai_description IS 'Description générée par IA pour recherche full-text';
COMMENT ON COLUMN media.ai_tags IS 'Tags/mots-clés extraits par IA pour matching';
COMMENT ON COLUMN media.ai_category IS 'Catégorie de produit détectée par IA';
COMMENT ON COLUMN media.ai_metadata IS 'Métadonnées extraites par IA (marque, couleurs, caractéristiques)';
COMMENT ON COLUMN media.ai_analyzed_at IS 'Date de l''analyse IA';
COMMENT ON COLUMN media.ai_model_used IS 'Modèle IA utilisé pour l''analyse';
COMMENT ON COLUMN media.ai_confidence IS 'Score de confiance de l''analyse (0.0-1.0)';

-- Créer des index pour optimiser les recherches
CREATE INDEX IF NOT EXISTS idx_media_ai_description_fulltext 
ON media USING GIN (to_tsvector('french', COALESCE(ai_description, '')));

CREATE INDEX IF NOT EXISTS idx_media_ai_tags_gin 
ON media USING GIN (ai_tags);

CREATE INDEX IF NOT EXISTS idx_media_ai_category 
ON media(ai_category) WHERE ai_category IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_media_ai_metadata_gin 
ON media USING GIN (ai_metadata);

-- Fonction pour rechercher des images par analyse IA (compatible sqlx offline)
CREATE OR REPLACE FUNCTION search_images_by_ai_analysis(
    search_query TEXT,
    search_tags TEXT[],
    search_category TEXT DEFAULT NULL,
    search_marque TEXT DEFAULT NULL,
    search_couleur TEXT DEFAULT NULL,
    gps_lat FLOAT DEFAULT NULL,
    gps_lng FLOAT DEFAULT NULL,
    search_radius_km INTEGER DEFAULT 50,
    max_results INTEGER DEFAULT 20
)
RETURNS TABLE (
    service_id INTEGER,
    media_id INTEGER,
    media_path TEXT,
    product_name TEXT,
    ai_description TEXT,
    ai_tags TEXT[],
    match_score FLOAT,
    distance_km FLOAT,
    service_data JSONB
) AS $$
BEGIN
    RETURN QUERY
    WITH ranked_results AS (
        SELECT 
            s.id as service_id,
            m.id as media_id,
            m.path as media_path,
            COALESCE(
                product->>'nom',
                product->>'name',
                product->>'titre',
                'Produit'
            ) as product_name,
            m.ai_description,
            m.ai_tags,
            (
                -- Score Full-Text sur description
                COALESCE(
                    ts_rank(
                        to_tsvector('french', COALESCE(m.ai_description, '')),
                        plainto_tsquery('french', search_query)
                    ) * 50.0,
                    0.0
                ) +
                
                -- Bonus tags communs
                (SELECT COUNT(*) * 20.0 FROM unnest(COALESCE(m.ai_tags, ARRAY[]::TEXT[])) tag 
                 WHERE tag = ANY(search_tags)) +
                
                -- Bonus marque exacte
                CASE 
                    WHEN search_marque IS NOT NULL 
                         AND m.ai_metadata->>'marque' ILIKE search_marque 
                    THEN 100.0 
                    ELSE 0.0 
                END +
                
                -- Bonus couleur exacte
                CASE 
                    WHEN search_couleur IS NOT NULL 
                         AND m.ai_metadata->'couleurs' ? search_couleur 
                    THEN 30.0 
                    ELSE 0.0 
                END +
                
                -- Bonus catégorie identique
                CASE 
                    WHEN search_category IS NOT NULL 
                         AND m.ai_category = search_category 
                    THEN 40.0 
                    ELSE 0.0 
                END +
                
                -- Bonus confidence élevée
                (COALESCE(m.ai_confidence, 0.5) * 20.0)
                
            )::FLOAT as match_score,
            
            -- Calcul distance GPS si coordonnées fournies
            CASE 
                WHEN gps_lat IS NOT NULL AND gps_lng IS NOT NULL 
                     AND s.gps IS NOT NULL AND s.gps != '' 
                     AND s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$'
                THEN
                    ST_Distance(
                        ST_Point(gps_lng, gps_lat)::geography,
                        ST_Point(
                            COALESCE(CAST(SPLIT_PART(s.gps, ',', 2) AS FLOAT), 0.0),
                            COALESCE(CAST(SPLIT_PART(s.gps, ',', 1) AS FLOAT), 0.0)
                        )::geography
                    ) / 1000.0  -- Convertir en km
                ELSE NULL
            END as distance_km,
            
            s.data as service_data,
            product
        FROM services s
        INNER JOIN media m ON m.service_id = s.id
        CROSS JOIN LATERAL jsonb_array_elements(
            CASE 
                WHEN jsonb_typeof(s.data->'produits') = 'array' 
                THEN s.data->'produits'
                ELSE '[]'::jsonb
            END
        ) AS product
        WHERE s.is_active = true
        AND m.type = 'image'
        AND m.ai_description IS NOT NULL
        AND (
            to_tsvector('french', COALESCE(m.ai_description, '')) @@ plainto_tsquery('french', search_query)
            OR m.ai_tags && search_tags
            OR (search_category IS NOT NULL AND m.ai_category = search_category)
        )
        -- Filtre GPS si coordonnées fournies
        AND (
            gps_lat IS NULL 
            OR gps_lng IS NULL
            OR search_radius_km IS NULL
            OR s.gps IS NULL
            OR s.gps = ''
            OR s.gps !~ '^-?\d+\.?\d*,-?\d+\.?\d*$'
            OR ST_Distance(
                ST_Point(gps_lng, gps_lat)::geography,
                ST_Point(
                    COALESCE(CAST(SPLIT_PART(s.gps, ',', 2) AS FLOAT), 0.0),
                    COALESCE(CAST(SPLIT_PART(s.gps, ',', 1) AS FLOAT), 0.0)
                )::geography
            ) / 1000.0 <= search_radius_km
        )
    )
    SELECT 
        ranked_results.service_id,
        ranked_results.media_id,
        ranked_results.media_path,
        ranked_results.product_name,
        ranked_results.ai_description,
        ranked_results.ai_tags,
        ranked_results.match_score,
        ranked_results.distance_km,
        ranked_results.service_data
    FROM ranked_results
    ORDER BY 
        ranked_results.match_score DESC,
        ranked_results.distance_km ASC NULLS LAST
    LIMIT max_results;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION search_images_by_ai_analysis IS 'Recherche intelligente d''images par analyse IA avec support GPS et scoring multi-critères';


-- ============================================
-- Migration: 20251021002_add_message_replies.sql
-- ============================================
-- Migration pour ajouter le support des réponses/citations dans les messages du chat
-- Permet aux utilisateurs de répondre à un message spécifique pour un contexte clair

-- Ajouter la colonne reply_to_message_id à la table chat_messages
ALTER TABLE chat_messages
ADD COLUMN IF NOT EXISTS reply_to_message_id TEXT REFERENCES chat_messages(id) ON DELETE SET NULL;

-- Ajouter un commentaire explicatif
COMMENT ON COLUMN chat_messages.reply_to_message_id IS 'ID du message auquel on répond (système de citation/réponse)';

-- Créer un index pour améliorer les performances de recherche des réponses
CREATE INDEX IF NOT EXISTS idx_chat_messages_reply_to ON chat_messages(reply_to_message_id) WHERE reply_to_message_id IS NOT NULL;

-- Créer une vue pour faciliter la récupération des messages avec leurs citations
DROP VIEW IF EXISTS chat_messages_with_replies;
CREATE OR REPLACE VIEW chat_messages_with_replies AS
SELECT 
    m.*,
    r.id as reply_to_id,
    r.from_user_id as reply_to_sender_id,
    r.content as reply_to_content,
    r.message_type as reply_to_content_type,
    r.created_at as reply_to_created_at,
    COALESCE(
        reply_user.nom_complet,
        NULLIF(TRIM(CONCAT(reply_user.prenom, ' ', reply_user.nom)), ''),
        reply_user.email
    ) as reply_to_sender_name
FROM chat_messages m
LEFT JOIN chat_messages r ON m.reply_to_message_id = r.id
LEFT JOIN users reply_user ON r.from_user_id = reply_user.id;

COMMENT ON VIEW chat_messages_with_replies IS 'Vue combinant les messages avec leurs citations pour faciliter les requêtes';

-- Fonction pour obtenir les messages d'une conversation avec leurs citations
CREATE OR REPLACE FUNCTION get_conversation_messages_with_replies(
    p_conversation_id TEXT,
    p_limit INTEGER DEFAULT 50,
    p_offset INTEGER DEFAULT 0
)
RETURNS TABLE (
    message_id TEXT,
    conversation_id TEXT,
    sender_id INTEGER,
    sender_name TEXT,
    content TEXT,
    content_type VARCHAR(50),
    created_at TIMESTAMP,
    updated_at TIMESTAMP,
    is_edited BOOLEAN,
    reply_to_id TEXT,
    reply_to_sender_id INTEGER,
    reply_to_sender_name TEXT,
    reply_to_content TEXT,
    reply_to_content_type VARCHAR(50)
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        m.id as message_id,
        m.conversation_id,
        m.from_user_id as sender_id,
        COALESCE(
            sender_user.nom_complet,
            NULLIF(TRIM(CONCAT(sender_user.prenom, ' ', sender_user.nom)), ''),
            sender_user.email
        ) as sender_name,
        m.content,
        m.message_type as content_type,
        m.created_at,
        m.updated_at,
        m.is_edited,
        r.id as reply_to_id,
        r.from_user_id as reply_to_sender_id,
        COALESCE(
            reply_user.nom_complet,
            NULLIF(TRIM(CONCAT(reply_user.prenom, ' ', reply_user.nom)), ''),
            reply_user.email
        ) as reply_to_sender_name,
        r.content as reply_to_content,
        r.message_type as reply_to_content_type
    FROM chat_messages m
    INNER JOIN users sender_user ON m.from_user_id = sender_user.id
    LEFT JOIN chat_messages r ON m.reply_to_message_id = r.id
    LEFT JOIN users reply_user ON r.from_user_id = reply_user.id
    WHERE m.conversation_id = p_conversation_id
    ORDER BY m.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION get_conversation_messages_with_replies IS 'Récupère les messages d''une conversation avec leurs citations';



-- ============================================
-- Migration: 20251021003_add_promotion_to_products.sql
-- ============================================
-- Migration: Ajout du flag en_promotion aux produits
-- Date: 2025-10-21
-- Description: Permet d'identifier rapidement les produits en publicité active

-- ✅ Ajouter colonne en_promotion dans table services (JSONB data)
-- Note: Les produits sont stockés dans services.data->produits[]
-- On ajoute un flag computed pour faciliter les requêtes

-- Créer une fonction pour vérifier si un produit est en promotion
CREATE OR REPLACE FUNCTION is_product_in_active_publicite(p_service_id INTEGER, p_product_index INTEGER)
RETURNS BOOLEAN AS $$
DECLARE
    product_key TEXT;
BEGIN
    product_key := p_service_id || '_' || p_product_index;
    
    RETURN EXISTS (
        SELECT 1
        FROM publicites
        WHERE product_key = ANY(produits_indexes)
        AND status = 'active'
        AND date_fin > NOW()
    );
END;
$$ LANGUAGE plpgsql STABLE;

-- ✅ Créer une vue pour faciliter l'accès aux produits avec leur status de promotion
CREATE OR REPLACE VIEW products_with_promotion AS
SELECT 
    s.id as service_id,
    s.user_id,
    s.data,
    idx as product_index,
    product as product_data,
    CASE 
        WHEN EXISTS (
            SELECT 1 FROM publicites pub
            WHERE s.id || '_' || idx = ANY(pub.produits_indexes)
            AND pub.status = 'active'
            AND pub.date_fin > NOW()
        ) THEN true
        ELSE false
    END as en_promotion,
    (
        SELECT pub.id
        FROM publicites pub
        WHERE s.id || '_' || idx = ANY(pub.produits_indexes)
        AND pub.status = 'active'
        AND pub.date_fin > NOW()
        LIMIT 1
    ) as publicite_id,
    (
        SELECT pub.zone_geographique
        FROM publicites pub
        WHERE s.id || '_' || idx = ANY(pub.produits_indexes)
        AND pub.status = 'active'
        AND pub.date_fin > NOW()
        LIMIT 1
    ) as publicite_zone,
    (
        SELECT pub.geo_publicitaire
        FROM publicites pub
        WHERE s.id || '_' || idx = ANY(pub.produits_indexes)
        AND pub.status = 'active'
        AND pub.date_fin > NOW()
        LIMIT 1
    ) as publicite_geo
FROM 
    services s,
    jsonb_array_elements((s.data->'produits')::jsonb) WITH ORDINALITY AS t(product, idx)
WHERE 
    jsonb_typeof((s.data->'produits')::jsonb) = 'array'
    AND jsonb_array_length((s.data->'produits')::jsonb) > 0;

-- ✅ Index sur la vue matérialisée (optionnel, pour meilleures performances)
-- CREATE MATERIALIZED VIEW products_with_promotion_mat AS
-- SELECT * FROM products_with_promotion;
-- CREATE INDEX idx_products_promo_service ON products_with_promotion_mat(service_id);
-- CREATE INDEX idx_products_promo_flag ON products_with_promotion_mat(en_promotion);

-- ✅ Fonction pour rafraîchir automatiquement le statut de promotion
-- Peut être appelée périodiquement ou après chaque création/modification de publicité
CREATE OR REPLACE FUNCTION refresh_products_promotion_status()
RETURNS TABLE(service_id INTEGER, product_index BIGINT, en_promotion BOOLEAN) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        s.id::INTEGER as service_id,
        idx as product_index,
        EXISTS (
            SELECT 1 FROM publicites pub
            WHERE s.id || '_' || idx = ANY(pub.produits_indexes)
            AND pub.status = 'active'
            AND pub.date_fin > NOW()
        ) as en_promotion
    FROM 
        services s,
        jsonb_array_elements((s.data->'produits')::jsonb) WITH ORDINALITY AS t(product, idx)
    WHERE 
        jsonb_typeof((s.data->'produits')::jsonb) = 'array';
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION is_product_in_active_publicite IS 'Vérifie si un produit spécifique est dans une publicité active';
COMMENT ON VIEW products_with_promotion IS 'Vue permettant d''accéder rapidement aux produits avec leur statut de promotion';
COMMENT ON FUNCTION refresh_products_promotion_status IS 'Rafraîchit le statut de promotion de tous les produits';






-- ============================================
-- Migration: 20251021004_create_publicites_table.sql
-- ============================================
-- Migration: Création de la table publicites pour le système de publicité payante
-- Date: 2025-10-21
-- Description: Table pour gérer les publicités des prestataires avec tracking analytics

-- ✅ Vérifier que PostGIS est disponible (doit être créé par migration 20250830_002)
-- CREATE EXTENSION IF NOT EXISTS postgis;

-- ✅ Créer la table publicites
CREATE TABLE IF NOT EXISTS publicites (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    
    -- Informations de base
    titre VARCHAR(255) NOT NULL,
    description TEXT,
    
    -- Produits indexés (format: 'serviceId_productIndex')
    produits_indexes TEXT[] NOT NULL DEFAULT '{}',
    
    -- Médias publicitaires (stockés en base64)
    videos TEXT[] DEFAULT '{}', -- Array de vidéos en base64
    thumbnails TEXT[] DEFAULT '{}', -- Array de miniatures en base64
    
    -- Tarification et durée
    duree_jours INTEGER NOT NULL CHECK (duree_jours > 0),
    cout INTEGER NOT NULL CHECK (cout >= 0), -- En FCFA (centimes)
    devise_utilisateur VARCHAR(10) DEFAULT 'FCFA',
    
    -- Zone géographique d'impact
    zone_geographique VARCHAR(50) NOT NULL DEFAULT 'local' CHECK (zone_geographique IN ('local', 'regional', 'international')),
    geo_publicitaire GEOMETRY(POINT, 4326), -- Coordonnées GPS PostGIS (SRID 4326 = WGS84)
    rayon_km INTEGER DEFAULT 50, -- Rayon en km (pour zone locale)
    
    -- Status et lifecycle
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'expired', 'pending', 'paused')),
    date_debut TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    date_fin TIMESTAMPTZ NOT NULL,
    
    -- Analytics et tracking
    vues INTEGER NOT NULL DEFAULT 0,
    clics INTEGER NOT NULL DEFAULT 0,
    impressions INTEGER NOT NULL DEFAULT 0, -- Nombre d'affichages dans le carousel
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Contraintes
    CONSTRAINT check_date_fin_after_debut CHECK (date_fin > date_debut),
    CONSTRAINT check_produits_not_empty CHECK (array_length(produits_indexes, 1) > 0)
);

-- ✅ Index pour performances
CREATE INDEX IF NOT EXISTS idx_publicites_user_id ON publicites(user_id);
CREATE INDEX IF NOT EXISTS idx_publicites_status ON publicites(status);
CREATE INDEX IF NOT EXISTS idx_publicites_zone ON publicites(zone_geographique);
CREATE INDEX IF NOT EXISTS idx_publicites_date_fin ON publicites(date_fin);
CREATE INDEX IF NOT EXISTS idx_publicites_active ON publicites(status, date_fin) WHERE status = 'active';

-- ✅ Index spatial pour geo_publicitaire (nécessite PostGIS)
CREATE INDEX IF NOT EXISTS idx_publicites_geo ON publicites USING GIST(geo_publicitaire) WHERE geo_publicitaire IS NOT NULL;

-- ✅ Index GIN pour recherche dans produits_indexes
CREATE INDEX IF NOT EXISTS idx_publicites_produits_gin ON publicites USING GIN(produits_indexes);

-- ✅ Fonction pour mettre à jour updated_at automatiquement
CREATE OR REPLACE FUNCTION update_publicites_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_update_publicites_updated_at ON publicites;
CREATE TRIGGER trigger_update_publicites_updated_at
    BEFORE UPDATE ON publicites
    FOR EACH ROW
    EXECUTE FUNCTION update_publicites_updated_at();

-- ✅ Fonction pour calculer automatiquement date_fin
CREATE OR REPLACE FUNCTION set_publicite_date_fin()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.date_fin IS NULL OR NEW.date_fin = NEW.date_debut THEN
        NEW.date_fin = NEW.date_debut + (NEW.duree_jours || ' days')::interval;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_set_publicite_date_fin ON publicites;
CREATE TRIGGER trigger_set_publicite_date_fin
    BEFORE INSERT OR UPDATE ON publicites
    FOR EACH ROW
    EXECUTE FUNCTION set_publicite_date_fin();

-- ✅ Fonction pour désactiver automatiquement les publicités expirées
CREATE OR REPLACE FUNCTION deactivate_expired_publicites()
RETURNS INTEGER AS $$
DECLARE
    affected_count INTEGER;
BEGIN
    UPDATE publicites
    SET status = 'expired'
    WHERE status = 'active'
    AND date_fin < NOW();
    
    GET DIAGNOSTICS affected_count = ROW_COUNT;
    RETURN affected_count;
END;
$$ LANGUAGE plpgsql;

-- ✅ Commentaires pour documentation
COMMENT ON TABLE publicites IS 'Table pour gérer les publicités payantes des prestataires';
COMMENT ON COLUMN publicites.produits_indexes IS 'Array des produits indexés (format: serviceId_productIndex)';
COMMENT ON COLUMN publicites.videos IS 'Array des vidéos promotionnelles en base64';
COMMENT ON COLUMN publicites.thumbnails IS 'Array des miniatures des vidéos en base64';
COMMENT ON COLUMN publicites.zone_geographique IS 'Portée géographique: local (ville), regional (pays), international';
COMMENT ON COLUMN publicites.geo_publicitaire IS 'Coordonnées GPS du centre de la zone publicitaire';
COMMENT ON COLUMN publicites.rayon_km IS 'Rayon de diffusion en km (pour zone locale)';
COMMENT ON COLUMN publicites.vues IS 'Nombre de fois où la publicité a été vue';
COMMENT ON COLUMN publicites.clics IS 'Nombre de clics sur la publicité';
COMMENT ON COLUMN publicites.impressions IS 'Nombre d''affichages dans le carousel';

