-- ============================================
-- Migration: 20251031001_002_create_search_history.sql
-- ============================================
-- Migration: Créer table search_history pour historiser les recherches utilisateurs
-- Date: 2025-10-31
-- Description: Table pour historiser les recherches effectuées par les utilisateurs
--              Permet les suggestions intelligentes et l'amélioration de la recherche
-- Note: Compatible avec SQLx offline mode

-- Vérifier et créer la table search_history
DO $$
BEGIN
    IF NOT EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'search_history') THEN
        CREATE TABLE search_history (
            id SERIAL PRIMARY KEY,
            user_id INTEGER,
            -- NULL si recherche anonyme, sinon ID de l'utilisateur
            query_text TEXT NOT NULL,
            -- Texte de la recherche
            query_type VARCHAR(50) DEFAULT 'text',
            -- 'text', 'image', 'voice', 'autocomplete'
            category VARCHAR(255),
            -- Catégorie filtrée (optionnel)
            filters JSONB,
            -- Filtres appliqués (ex: {"prix_min": 10000, "prix_max": 50000, "ville": "Yaoundé"})
            location_lat DOUBLE PRECISION,
            location_lon DOUBLE PRECISION,
            -- Coordonnées GPS si recherche géolocalisée
            results_count INTEGER DEFAULT 0,
            -- Nombre de résultats trouvés
            clicked_result_id INTEGER,
            -- ID du résultat sur lequel l'utilisateur a cliqué (optionnel)
            clicked_at TIMESTAMP WITH TIME ZONE,
            -- Timestamp du clic sur un résultat
            session_id VARCHAR(255),
            -- ID de session pour regrouper les recherches d'une même session
            device_type VARCHAR(50),
            -- 'mobile', 'web', 'tablet'
            created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
        );
        
        RAISE NOTICE 'Table search_history créée avec succès';
    ELSE
        RAISE NOTICE 'Table search_history existe déjà';
    END IF;
END $$;

-- Index pour recherche par user_id
CREATE INDEX IF NOT EXISTS idx_search_history_user_id 
    ON search_history(user_id) WHERE user_id IS NOT NULL;

-- Index pour recherche par query_text (trigram pour recherche floue)
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_trgm') THEN
        -- Utiliser pg_trgm si disponible
        EXECUTE 'CREATE INDEX IF NOT EXISTS idx_search_history_query_text_gin 
                 ON search_history USING gin(query_text gin_trgm_ops)';
        RAISE NOTICE 'Index pg_trgm créé pour search_history.query_text';
    ELSE
        -- Index B-tree simple si pg_trgm non disponible
        CREATE INDEX IF NOT EXISTS idx_search_history_query_text_btree 
            ON search_history(query_text);
        RAISE NOTICE 'Index B-tree créé pour search_history.query_text';
    END IF;
END $$;

-- Index pour recherche par query_type
CREATE INDEX IF NOT EXISTS idx_search_history_query_type 
    ON search_history(query_type);

-- Index pour recherche par category
CREATE INDEX IF NOT EXISTS idx_search_history_category 
    ON search_history(category) WHERE category IS NOT NULL;

-- Index pour recherche géolocalisée (si extension PostGIS disponible)
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'postgis') THEN
        -- Utiliser PostGIS si disponible
        EXECUTE 'CREATE INDEX IF NOT EXISTS idx_search_history_location_gist 
                 ON search_history USING gist(ST_MakePoint(location_lon, location_lat)) 
                 WHERE location_lat IS NOT NULL AND location_lon IS NOT NULL';
        RAISE NOTICE 'Index PostGIS créé pour search_history.location';
    ELSE
        -- Index B-tree simple si PostGIS non disponible
        CREATE INDEX IF NOT EXISTS idx_search_history_location_btree 
            ON search_history(location_lat, location_lon) 
            WHERE location_lat IS NOT NULL AND location_lon IS NOT NULL;
        RAISE NOTICE 'Index B-tree créé pour search_history.location';
    END IF;
END $$;

-- Index pour recherche par session_id
CREATE INDEX IF NOT EXISTS idx_search_history_session_id 
    ON search_history(session_id) WHERE session_id IS NOT NULL;

-- Index pour recherche par created_at (pour statistiques temporelles)
CREATE INDEX IF NOT EXISTS idx_search_history_created_at 
    ON search_history(created_at DESC);

-- Index composite pour recherche utilisateur récente
CREATE INDEX IF NOT EXISTS idx_search_history_user_created 
    ON search_history(user_id, created_at DESC) WHERE user_id IS NOT NULL;

-- Index pour recherche par clicked_result_id (pour analytics)
CREATE INDEX IF NOT EXISTS idx_search_history_clicked_result 
    ON search_history(clicked_result_id) WHERE clicked_result_id IS NOT NULL;

-- Index GIN pour recherche dans les filtres JSONB
CREATE INDEX IF NOT EXISTS idx_search_history_filters_gin 
    ON search_history USING gin(filters) WHERE filters IS NOT NULL;

-- Fonction pour obtenir les recherches populaires
CREATE OR REPLACE FUNCTION get_popular_searches(
    p_limit INTEGER DEFAULT 10,
    p_category VARCHAR(255) DEFAULT NULL,
    p_days INTEGER DEFAULT 30
)
RETURNS TABLE (
    query_text TEXT,
    search_count BIGINT,
    last_searched TIMESTAMP WITH TIME ZONE
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        sh.query_text,
        COUNT(*) as search_count,
        MAX(sh.created_at) as last_searched
    FROM search_history sh
    WHERE sh.created_at >= NOW() - (p_days || ' days')::INTERVAL
    AND (p_category IS NULL OR sh.category = p_category)
    GROUP BY sh.query_text
    ORDER BY search_count DESC, last_searched DESC
    LIMIT p_limit;
END;
$$ LANGUAGE plpgsql;

-- Fonction pour obtenir les suggestions de recherche pour un utilisateur
CREATE OR REPLACE FUNCTION get_search_suggestions(
    p_user_id INTEGER DEFAULT NULL,
    p_prefix TEXT DEFAULT NULL,
    p_limit INTEGER DEFAULT 5
)
RETURNS TABLE (
    query_text TEXT,
    search_count BIGINT
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        sh.query_text,
        COUNT(*) as search_count
    FROM search_history sh
    WHERE (p_user_id IS NULL OR sh.user_id = p_user_id)
    AND (p_prefix IS NULL OR LOWER(sh.query_text) LIKE LOWER(p_prefix || '%'))
    AND sh.created_at >= NOW() - INTERVAL '90 days'
    GROUP BY sh.query_text
    ORDER BY 
        CASE WHEN p_user_id IS NOT NULL AND sh.user_id = p_user_id THEN 1 ELSE 2 END,
        search_count DESC,
        MAX(sh.created_at) DESC
    LIMIT p_limit;
END;
$$ LANGUAGE plpgsql;

-- Fonction pour nettoyer les anciennes recherches (à exécuter périodiquement)
CREATE OR REPLACE FUNCTION cleanup_old_search_history(
    p_days_to_keep INTEGER DEFAULT 365
)
RETURNS INTEGER AS $$
DECLARE
    v_deleted_count INTEGER;
BEGIN
    DELETE FROM search_history
    WHERE created_at < NOW() - (p_days_to_keep || ' days')::INTERVAL
    AND clicked_result_id IS NULL; -- Garder les recherches avec clics plus longtemps
    
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RETURN v_deleted_count;
END;
$$ LANGUAGE plpgsql;

COMMENT ON TABLE search_history IS 'Historique des recherches utilisateurs pour suggestions intelligentes';
COMMENT ON COLUMN search_history.query_text IS 'Texte de la recherche effectuée';
COMMENT ON COLUMN search_history.query_type IS 'Type de recherche: text, image, voice, autocomplete';
COMMENT ON COLUMN search_history.filters IS 'Filtres appliqués au format JSONB';
COMMENT ON COLUMN search_history.results_count IS 'Nombre de résultats trouvés';
COMMENT ON COLUMN search_history.clicked_result_id IS 'ID du résultat sur lequel l''utilisateur a cliqué';
COMMENT ON FUNCTION get_popular_searches IS 'Retourne les recherches les plus populaires';
COMMENT ON FUNCTION get_search_suggestions IS 'Retourne des suggestions de recherche basées sur l''historique';
COMMENT ON FUNCTION cleanup_old_search_history IS 'Nettoie les anciennes recherches (garde celles avec clics)';



-- ============================================
-- Migration: 20251031002_add_product_id_to_media.sql
-- ============================================
-- Migration: Ajouter product_id et product_index à la table media
-- Date: 2025-10-31
-- Description: Permet de rattacher les médias à des produits spécifiques, pas juste au service
-- Note: Compatible avec SQLx offline mode

-- Ajouter les colonnes pour lier les médias aux produits spécifiques
DO $$ 
BEGIN
    -- Colonne product_id (ID du produit)
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name='media' AND column_name='product_id'
    ) THEN
        ALTER TABLE media ADD COLUMN product_id TEXT;
        RAISE NOTICE 'Colonne product_id ajoutée à media';
    END IF;

    -- Colonne product_index (index dans service.data.produits[])
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name='media' AND column_name='product_index'
    ) THEN
        ALTER TABLE media ADD COLUMN product_index INTEGER;
        RAISE NOTICE 'Colonne product_index ajoutée à media';
    END IF;

    -- Colonne is_main_image (image principale du produit)
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name='media' AND column_name='is_main_image'
    ) THEN
        ALTER TABLE media ADD COLUMN is_main_image BOOLEAN DEFAULT FALSE;
        RAISE NOTICE 'Colonne is_main_image ajoutée à media';
    END IF;

    -- Colonne display_order (ordre d'affichage)
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name='media' AND column_name='display_order'
    ) THEN
        ALTER TABLE media ADD COLUMN display_order INTEGER DEFAULT 0;
        RAISE NOTICE 'Colonne display_order ajoutée à media';
    END IF;
END $$;

-- Commentaires pour documentation
COMMENT ON COLUMN media.product_id IS 'ID du produit spécifique auquel ce média appartient';
COMMENT ON COLUMN media.product_index IS 'Index du produit dans service.data.produits[] (0-based)';
COMMENT ON COLUMN media.is_main_image IS 'Indique si c''est l''image principale du produit';
COMMENT ON COLUMN media.display_order IS 'Ordre d''affichage des médias (0 = premier, 1 = deuxième, etc.)';

-- Créer des index pour améliorer les performances
DO $$
BEGIN
    -- Index sur product_id
    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE c.relname = 'idx_media_product_id' AND n.nspname = 'public'
    ) THEN
        CREATE INDEX idx_media_product_id ON media(product_id) WHERE product_id IS NOT NULL;
        RAISE NOTICE 'Index idx_media_product_id créé';
    END IF;

    -- Index sur product_index
    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE c.relname = 'idx_media_product_index' AND n.nspname = 'public'
    ) THEN
        CREATE INDEX idx_media_product_index ON media(product_index) WHERE product_index IS NOT NULL;
        RAISE NOTICE 'Index idx_media_product_index créé';
    END IF;

    -- Index composite service_id + product_index
    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE c.relname = 'idx_media_service_product' AND n.nspname = 'public'
    ) THEN
        CREATE INDEX idx_media_service_product ON media(service_id, product_index);
        RAISE NOTICE 'Index idx_media_service_product créé';
    END IF;

    -- Index pour images principales
    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE c.relname = 'idx_media_main_image' AND n.nspname = 'public'
    ) THEN
        CREATE INDEX idx_media_main_image ON media(product_id, is_main_image) WHERE is_main_image = TRUE;
        RAISE NOTICE 'Index idx_media_main_image créé';
    END IF;

    -- Index composite pour ordre d'affichage
    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE c.relname = 'idx_media_product_display' AND n.nspname = 'public'
    ) THEN
        CREATE INDEX idx_media_product_display ON media(product_id, display_order) WHERE product_id IS NOT NULL;
        RAISE NOTICE 'Index idx_media_product_display créé';
    END IF;
END $$;

-- Fonction pour récupérer les médias d'un produit (compatible sqlx offline)
CREATE OR REPLACE FUNCTION get_product_media(
    p_service_id INTEGER,
    p_product_index INTEGER,
    p_media_type TEXT DEFAULT NULL
)
RETURNS TABLE (
    media_id INTEGER,
    type TEXT,
    path TEXT,
    is_main BOOLEAN,
    display_order INTEGER,
    ai_description TEXT
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        m.id,
        m.type,
        m.path,
        COALESCE(m.is_main_image, FALSE),
        COALESCE(m.display_order, 0),
        m.ai_description
    FROM media m
    WHERE m.service_id = p_service_id
    AND m.product_index = p_product_index
    AND (p_media_type IS NULL OR m.type = p_media_type)
    ORDER BY 
        COALESCE(m.is_main_image, FALSE) DESC,
        COALESCE(m.display_order, 0) ASC,
        m.id ASC;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION get_product_media IS 'Récupère tous les médias d''un produit spécifique dans un ordre logique';

-- Fonction pour définir l'image principale d'un produit (compatible sqlx offline)
CREATE OR REPLACE FUNCTION set_main_product_image(
    p_media_id INTEGER
) RETURNS BOOLEAN AS $$
DECLARE
    v_service_id INTEGER;
    v_product_index INTEGER;
BEGIN
    -- Récupérer les infos du média
    SELECT service_id, product_index 
    INTO v_service_id, v_product_index
    FROM media 
    WHERE id = p_media_id;
    
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;
    
    -- Désactiver toutes les images principales de ce produit
    UPDATE media
    SET is_main_image = FALSE
    WHERE service_id = v_service_id
    AND product_index = v_product_index
    AND type = 'image';
    
    -- Définir cette image comme principale
    UPDATE media
    SET is_main_image = TRUE
    WHERE id = p_media_id;
    
    RETURN TRUE;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION set_main_product_image IS 'Définit une image comme image principale d''un produit (désactive les autres)';


-- ============================================
-- Migration: 20251031003_fix_index_size_limit.sql
-- ============================================
-- Migration pour corriger l'erreur "index row requires 416920 bytes, maximum size is 8191"
-- Date: 2025-10-31
-- Description: Supprime l'index GIN problématique sur data->'produits' qui essaie d'indexer 
--              des données volumineuses (images base64, etc.) et le remplace par un index optimisé

-- 1. Supprimer l'index problématique qui indexe directement tout le champ produits
DROP INDEX IF EXISTS idx_services_products_gin;

-- 2. Supprimer aussi l'index sur le type (pas très utile pour un champ JSONB)
DROP INDEX IF EXISTS idx_services_products_type;

-- 3. L'index idx_services_products_fulltext_all est déjà présent et utilise une fonction
--    qui extrait seulement le texte (pas les images), donc il n'y a pas de problème de taille.
--    Cet index sera utilisé pour les recherches full-text dans les produits.

-- 4. Fonction utilitaire pour extraire un champ spécifique des produits en tableau TEXT[]
CREATE OR REPLACE FUNCTION extract_service_products_field(service_data JSONB, field_name TEXT)
RETURNS TEXT[] AS $$
DECLARE
    products JSONB;
    product_record JSONB;
    result TEXT[];
    field_value TEXT;
BEGIN
    products := CASE 
        WHEN jsonb_typeof(service_data->'produits') = 'array' 
        THEN service_data->'produits'
        ELSE '[]'::jsonb
    END;

    result := ARRAY[]::TEXT[];

    FOR product_record IN SELECT * FROM jsonb_array_elements(products)
    LOOP
        field_value := product_record->>field_name;
        IF field_value IS NOT NULL AND field_value <> '' THEN
            result := array_append(result, field_value);
        END IF;
    END LOOP;

    RETURN result;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- 5. Créer un index optimisé pour les recherches par type de produit (plus léger)
CREATE INDEX IF NOT EXISTS idx_services_products_type_optimized 
ON services USING GIN (extract_service_products_field(data, 'type'))
WHERE data->'produits' IS NOT NULL;

-- 6. Créer un index optimisé pour les recherches par nom de produit (plus léger)
CREATE INDEX IF NOT EXISTS idx_services_products_nom_optimized 
ON services USING GIN (extract_service_products_field(data, 'nom'))
WHERE data->'produits' IS NOT NULL;

-- Commentaires
COMMENT ON INDEX idx_services_products_type_optimized IS 'Index optimisé pour recherche par type de produit (évite d''indexer les images base64)';
COMMENT ON INDEX idx_services_products_nom_optimized IS 'Index optimisé pour recherche par nom de produit (évite d''indexer les images base64)';



-- ============================================
-- Migration: 20251101_002_create_token_usage_logs.sql
-- ============================================
-- Migration : Créer la table token_usage_logs pour l'historique des consommations de tokens
-- Date : 2025-11-01
-- Compatible avec SQLx offline mode (fichier SQL standard)

-- Créer la table pour stocker l'historique des consommations de tokens
CREATE TABLE IF NOT EXISTS token_usage_logs (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    intention VARCHAR(100) NOT NULL, -- 'creation_service', 'recherche_besoin', 'assistance_generale', etc.
    tokens_ia_consumed INTEGER NOT NULL, -- Nombre de tokens IA réellement consommés
    tokens_cost_xaf INTEGER NOT NULL, -- Coût en XAF
    tokens_deducted INTEGER NOT NULL, -- Tokens déduits du solde (équivalent XAF)
    balance_before BIGINT NOT NULL, -- Solde avant déduction
    balance_after BIGINT NOT NULL, -- Solde après déduction
    processing_time_ms INTEGER, -- Temps de traitement en millisecondes
    response_source VARCHAR(50), -- 'cache', 'optimized', 'external'
    endpoint VARCHAR(255), -- Endpoint appelé
    request_metadata JSONB, -- Métadonnées de la requête (optionnel)
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Index pour améliorer les performances des requêtes
CREATE INDEX IF NOT EXISTS idx_token_logs_user_id ON token_usage_logs(user_id);
CREATE INDEX IF NOT EXISTS idx_token_logs_created_at ON token_usage_logs(created_at);
CREATE INDEX IF NOT EXISTS idx_token_logs_intention ON token_usage_logs(intention);
CREATE INDEX IF NOT EXISTS idx_token_logs_user_date ON token_usage_logs(user_id, created_at DESC);

-- Commentaires pour documentation
COMMENT ON TABLE token_usage_logs IS 'Historique détaillé de toutes les consommations de tokens IA par utilisateur';
COMMENT ON COLUMN token_usage_logs.intention IS 'Type d''opération effectuée (creation_service, recherche_besoin, etc.)';
COMMENT ON COLUMN token_usage_logs.tokens_ia_consumed IS 'Nombre réel de tokens IA consommés lors de l''appel';
COMMENT ON COLUMN token_usage_logs.tokens_cost_xaf IS 'Coût calculé en XAF basé sur l''intention';
COMMENT ON COLUMN token_usage_logs.tokens_deducted IS 'Nombre de tokens déduits du solde utilisateur (1 token = 1 XAF)';
COMMENT ON COLUMN token_usage_logs.response_source IS 'Source de la réponse : cache (gratuit), optimized (réduit), external (complet)';

-- Fonction pour obtenir les stats de consommation d'un utilisateur
CREATE OR REPLACE FUNCTION get_user_token_stats(p_user_id INTEGER, p_days INTEGER DEFAULT 30)
RETURNS TABLE (
    total_requests BIGINT,
    total_tokens_consumed BIGINT,
    total_cost_xaf BIGINT,
    avg_tokens_per_request NUMERIC,
    by_intention JSONB,
    by_source JSONB,
    daily_consumption JSONB
) AS $$
BEGIN
    RETURN QUERY
    WITH stats AS (
        SELECT
            COUNT(*) as request_count,
            SUM(tokens_ia_consumed) as total_tokens,
            SUM(tokens_cost_xaf) as total_xaf,
            AVG(tokens_ia_consumed) as avg_tokens,
            intention,
            response_source,
            DATE(created_at) as consumption_date
        FROM token_usage_logs
        WHERE user_id = p_user_id
          AND created_at >= CURRENT_TIMESTAMP - (p_days || ' days')::INTERVAL
        GROUP BY intention, response_source, DATE(created_at)
    )
    SELECT
        SUM(request_count)::BIGINT as total_requests,
        SUM(total_tokens)::BIGINT as total_tokens_consumed,
        SUM(total_xaf)::BIGINT as total_cost_xaf,
        AVG(avg_tokens)::NUMERIC as avg_tokens_per_request,
        
        -- Stats par intention
        (SELECT jsonb_object_agg(intention, json_build_object(
            'count', SUM(request_count),
            'tokens', SUM(total_tokens),
            'cost_xaf', SUM(total_xaf)
        ))
        FROM stats
        GROUP BY intention) as by_intention,
        
        -- Stats par source
        (SELECT jsonb_object_agg(response_source, json_build_object(
            'count', SUM(request_count),
            'tokens', SUM(total_tokens)
        ))
        FROM stats
        WHERE response_source IS NOT NULL
        GROUP BY response_source) as by_source,
        
        -- Consommation journalière
        (SELECT jsonb_object_agg(consumption_date::TEXT, json_build_object(
            'count', SUM(request_count),
            'tokens', SUM(total_tokens),
            'cost_xaf', SUM(total_xaf)
        ))
        FROM stats
        GROUP BY consumption_date
        ORDER BY consumption_date DESC) as daily_consumption
    FROM stats;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION get_user_token_stats IS 'Retourne les statistiques de consommation de tokens pour un utilisateur sur N jours';

-- Vue pour les 10 dernières consommations par utilisateur (utile pour l'historique)
CREATE OR REPLACE VIEW recent_token_usage AS
SELECT 
    tul.id,
    tul.user_id,
    u.nom_complet as user_name,
    tul.intention,
    tul.tokens_ia_consumed,
    tul.tokens_cost_xaf,
    tul.tokens_deducted,
    tul.balance_before,
    tul.balance_after,
    tul.processing_time_ms,
    tul.response_source,
    tul.endpoint,
    tul.created_at,
    ROW_NUMBER() OVER (PARTITION BY tul.user_id ORDER BY tul.created_at DESC) as row_num
FROM token_usage_logs tul
JOIN users u ON tul.user_id = u.id
ORDER BY tul.created_at DESC;

COMMENT ON VIEW recent_token_usage IS 'Vue avec les consommations récentes enrichies des infos utilisateur';

