-- ============================================
-- Migration: 20251101003_004_improve_search_with_autocomplete.sql
-- ============================================
-- Migration : Améliorer la recherche en intégrant autocomplete_characteristics
-- Date : 2025-11-01
-- Description : Ajouter des index et une fonction pour booster la recherche via les caractéristiques autocomplete structurées
-- Compatible avec SQLx offline mode

-- Index composite optimisé pour recherche rapide
CREATE INDEX IF NOT EXISTS idx_autocomplete_search_optimized
ON autocomplete_characteristics(service_id, identifiant_base, sous_caracteristique, LOWER(valeur));

-- Index GIN pour full-text search sur valeur
CREATE INDEX IF NOT EXISTS idx_autocomplete_valeur_gin
ON autocomplete_characteristics USING GIN (to_tsvector('french', valeur));

-- Index pour recherche insensible à la casse
CREATE INDEX IF NOT EXISTS idx_autocomplete_valeur_trgm
ON autocomplete_characteristics USING GIN (valeur gin_trgm_ops);

-- Fonction pour calculer le score autocomplete d'un service
CREATE OR REPLACE FUNCTION calculate_autocomplete_score(
    p_service_id INTEGER,
    p_search_query TEXT
)
RETURNS FLOAT AS $$
DECLARE
    total_score FLOAT := 0.0;
    characteristic_record RECORD;
    query_words TEXT[];
    word TEXT;
BEGIN
    -- Découper la requête en mots
    query_words := string_to_array(LOWER(p_search_query), ' ');
    
    -- Parcourir toutes les caractéristiques du service
    FOR characteristic_record IN
        SELECT 
            sous_caracteristique,
            valeur,
            usage_count
        FROM autocomplete_characteristics
        WHERE service_id = p_service_id
        AND identifiant_base LIKE 'produit%'  -- Seulement les produits
    LOOP
        -- Vérifier chaque mot de la requête
        FOREACH word IN ARRAY query_words
        LOOP
            IF word = '' OR LENGTH(word) < 2 THEN
                CONTINUE;
            END IF;
            
            -- Match sur la valeur (insensible casse)
            IF LOWER(characteristic_record.valeur) LIKE '%' || word || '%' THEN
                -- Score de base selon la sous-caractéristique
                CASE 
                    -- ✅ Caractéristiques CRITIQUES (20.0)
                    WHEN characteristic_record.sous_caracteristique IN ('marque', 'brand') THEN 
                        total_score := total_score + 20.0;
                    WHEN characteristic_record.sous_caracteristique IN ('modele', 'model') THEN 
                        total_score := total_score + 18.0;
                    
                    -- ✅ Caractéristiques TRÈS IMPORTANTES (15.0)
                    WHEN characteristic_record.sous_caracteristique IN ('type', 'categorie', 'category') THEN 
                        total_score := total_score + 15.0;
                    
                    -- ✅ Caractéristiques IMPORTANTES (12.0)
                    WHEN characteristic_record.sous_caracteristique IN ('couleur', 'color') THEN 
                        total_score := total_score + 12.0;
                    WHEN characteristic_record.sous_caracteristique IN ('taille', 'size', 'pointure') THEN 
                        total_score := total_score + 12.0;
                    
                    -- ✅ Caractéristiques UTILES pour AUTO (12.0)
                    WHEN characteristic_record.sous_caracteristique IN ('carburant', 'transmission', 'annee', 'kilometrage') THEN 
                        total_score := total_score + 12.0;
                    
                    -- ✅ Caractéristiques UTILES pour IMMOBILIER (10.0)
                    WHEN characteristic_record.sous_caracteristique IN ('typeBatiment', 'nombre_chambres', 'surface') THEN 
                        total_score := total_score + 10.0;
                    
                    -- ✅ Autres caractéristiques (8.0)
                    ELSE 
                        total_score := total_score + 8.0;
                END CASE;
                
                -- ✅ BOOST selon popularité (usage_count)
                -- Une caractéristique utilisée 10 fois vaut 2x plus qu'une utilisée 1 fois
                total_score := total_score * (1.0 + (characteristic_record.usage_count::FLOAT / 10.0));
            END IF;
        END LOOP;
    END LOOP;
    
    RETURN total_score;
END;
$$ LANGUAGE plpgsql STABLE;

-- Fonction alternative utilisant full-text search (plus rapide pour grandes bases)
CREATE OR REPLACE FUNCTION calculate_autocomplete_score_fast(
    p_service_id INTEGER,
    p_search_query TEXT
)
RETURNS FLOAT AS $$
SELECT COALESCE(SUM(
    CASE 
        WHEN ac.sous_caracteristique IN ('marque', 'brand') THEN 20.0
        WHEN ac.sous_caracteristique IN ('modele', 'model') THEN 18.0
        WHEN ac.sous_caracteristique IN ('type', 'categorie', 'category') THEN 15.0
        WHEN ac.sous_caracteristique IN ('couleur', 'color') THEN 12.0
        WHEN ac.sous_caracteristique IN ('taille', 'pointure', 'size') THEN 12.0
        WHEN ac.sous_caracteristique IN ('carburant', 'transmission', 'annee', 'kilometrage') THEN 12.0
        WHEN ac.sous_caracteristique IN ('typeBatiment', 'nombre_chambres', 'surface') THEN 10.0
        ELSE 8.0
    END *
    ts_rank(to_tsvector('french', ac.valeur), plainto_tsquery('french', p_search_query)) *
    (1.0 + (ac.usage_count::FLOAT / 10.0))
), 0.0)
FROM autocomplete_characteristics ac
WHERE ac.service_id = p_service_id
AND ac.identifiant_base LIKE 'produit%'
AND to_tsvector('french', ac.valeur) @@ plainto_tsquery('french', p_search_query);
$$ LANGUAGE SQL STABLE;

-- Commentaires
COMMENT ON FUNCTION calculate_autocomplete_score IS 
'Calcule le score de pertinence en parcourant les caractéristiques autocomplete mot par mot';

COMMENT ON FUNCTION calculate_autocomplete_score_fast IS 
'Version optimisée utilisant full-text search PostgreSQL pour grandes bases de données';

COMMENT ON INDEX idx_autocomplete_search_optimized IS 
'Index composite pour recherche rapide par service + caractéristique + valeur';

COMMENT ON INDEX idx_autocomplete_valeur_gin IS 
'Index GIN pour full-text search performant sur les valeurs';

COMMENT ON INDEX idx_autocomplete_valeur_trgm IS 
'Index trigram pour recherche floue et fautes de frappe';



-- ============================================
-- Migration: 20251101004_create_autocomplete_characteristics.sql
-- ============================================
-- Migration: Créer table autocomplete_characteristics pour historiser les caractéristiques autocomplete
-- Date: 2025-11-01
-- Description: Table pour historiser les caractéristiques autocomplete créées par l'IA ou les utilisateurs
--              Permet la réutilisation intelligente dans recherche et filtrage
-- Note: Compatible avec SQLx offline mode (fichier SQL standard)

-- Créer la table autocomplete_characteristics
CREATE TABLE IF NOT EXISTS autocomplete_characteristics (
    id SERIAL PRIMARY KEY,
    identifiant_base VARCHAR(255) NOT NULL,
    -- Exemple: "produits", "services", "prestations"
    sous_caracteristique VARCHAR(255) NOT NULL,
    -- Exemple: "marque", "modele", "annee", "pointure", "couleur"
    valeur VARCHAR(500) NOT NULL,
    -- Exemple: "Toyota", "RAV4", "2018", "42", "Noir"
    origine_champs VARCHAR(50) NOT NULL DEFAULT 'ia',
    -- 'ia' pour généré par IA, 'utilisateur' pour créé manuellement
    user_id INTEGER,
    -- NULL si créé par IA, sinon ID de l'utilisateur qui l'a créé
    service_id INTEGER,
    -- ID du service où cette caractéristique a été utilisée (optionnel)
    usage_count INTEGER DEFAULT 1,
    -- Nombre de fois que cette valeur a été utilisée
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    -- Contrainte unique : même identifiant_base + sous_caracteristique + valeur = même entrée
    CONSTRAINT unique_autocomplete_characteristic 
        UNIQUE (identifiant_base, sous_caracteristique, valeur)
);

-- Index pour recherche rapide par identifiant_base
CREATE INDEX IF NOT EXISTS idx_autocomplete_identifiant_base 
    ON autocomplete_characteristics(identifiant_base);

-- Index pour recherche par sous_caracteristique
CREATE INDEX IF NOT EXISTS idx_autocomplete_sous_caracteristique 
    ON autocomplete_characteristics(sous_caracteristique);

-- Index composite pour recherche combinée
CREATE INDEX IF NOT EXISTS idx_autocomplete_base_sous 
    ON autocomplete_characteristics(identifiant_base, sous_caracteristique);

-- Index pour recherche par valeur (insensible à la casse)
CREATE INDEX IF NOT EXISTS idx_autocomplete_valeur_lower 
    ON autocomplete_characteristics(LOWER(valeur));

-- Index pour recherche par origine_champs
CREATE INDEX IF NOT EXISTS idx_autocomplete_origine 
    ON autocomplete_characteristics(origine_champs);

-- Index pour recherche par user_id (si créé par utilisateur)
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE c.relname = 'idx_autocomplete_user_id' AND n.nspname = 'public'
    ) THEN
        CREATE INDEX idx_autocomplete_user_id ON autocomplete_characteristics(user_id) WHERE user_id IS NOT NULL;
    END IF;
END $$;

-- Index pour recherche par service_id
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE c.relname = 'idx_autocomplete_service_id' AND n.nspname = 'public'
    ) THEN
        CREATE INDEX idx_autocomplete_service_id ON autocomplete_characteristics(service_id) WHERE service_id IS NOT NULL;
    END IF;
END $$;

-- Index pour tri par usage_count (valeurs les plus utilisées en premier)
CREATE INDEX IF NOT EXISTS idx_autocomplete_usage_count 
    ON autocomplete_characteristics(identifiant_base, sous_caracteristique, usage_count DESC);

-- Fonction pour mettre à jour updated_at
CREATE OR REPLACE FUNCTION update_autocomplete_characteristics_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger pour updated_at
DROP TRIGGER IF EXISTS trigger_autocomplete_characteristics_updated_at ON autocomplete_characteristics;
CREATE TRIGGER trigger_autocomplete_characteristics_updated_at
    BEFORE UPDATE ON autocomplete_characteristics
    FOR EACH ROW
    EXECUTE FUNCTION update_autocomplete_characteristics_updated_at();

-- Fonction pour incrémenter usage_count lors de l'insertion d'une valeur existante
CREATE OR REPLACE FUNCTION upsert_autocomplete_characteristic(
    p_identifiant_base VARCHAR(255),
    p_sous_caracteristique VARCHAR(255),
    p_valeur VARCHAR(500),
    p_origine_champs VARCHAR(50) DEFAULT 'ia',
    p_user_id INTEGER DEFAULT NULL,
    p_service_id INTEGER DEFAULT NULL
)
RETURNS INTEGER AS $$
DECLARE
    v_id INTEGER;
BEGIN
    -- Essayer d'insérer
    INSERT INTO autocomplete_characteristics (
        identifiant_base,
        sous_caracteristique,
        valeur,
        origine_champs,
        user_id,
        service_id,
        usage_count
    )
    VALUES (
        p_identifiant_base,
        p_sous_caracteristique,
        p_valeur,
        p_origine_champs,
        p_user_id,
        p_service_id,
        1
    )
    ON CONFLICT (identifiant_base, sous_caracteristique, valeur)
    DO UPDATE SET
        usage_count = autocomplete_characteristics.usage_count + 1,
        updated_at = NOW();
    
    -- Récupérer l'ID
    SELECT id INTO v_id
    FROM autocomplete_characteristics
    WHERE identifiant_base = p_identifiant_base
    AND sous_caracteristique = p_sous_caracteristique
    AND valeur = p_valeur;
    
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

-- Commentaires pour documentation
COMMENT ON TABLE autocomplete_characteristics IS 'Historique des caractéristiques autocomplete pour réutilisation intelligente';
COMMENT ON COLUMN autocomplete_characteristics.identifiant_base IS 'Identifiant du type de caractéristique (ex: produits, services, prestations)';
COMMENT ON COLUMN autocomplete_characteristics.sous_caracteristique IS 'Nom de la dimension (ex: marque, modele, annee)';
COMMENT ON COLUMN autocomplete_characteristics.valeur IS 'Valeur de la caractéristique (ex: Toyota, RAV4, 2018)';
COMMENT ON COLUMN autocomplete_characteristics.origine_champs IS 'Origine: ia ou utilisateur';
COMMENT ON COLUMN autocomplete_characteristics.usage_count IS 'Nombre de fois que cette valeur a été utilisée';
COMMENT ON FUNCTION upsert_autocomplete_characteristic IS 'Insère ou met à jour une caractéristique autocomplete avec incrément du compteur d''usage';



-- ============================================
-- Migration: 20251102000000_create_autocomplete_combinations.sql
-- ============================================
-- Migration: Créer table autocomplete_combinations pour stocker les vecteurs complets de produits
-- Date: 2025-11-02
-- Description: Table pour stocker toutes les combinaisons vectorielles possibles générées par l'IA
--              Permet la recherche intelligente et la sélection dans le formulaire de création produit
-- Compatible SQLx offline mode

-- Créer la table autocomplete_combinations
CREATE TABLE IF NOT EXISTS autocomplete_combinations (
    id SERIAL PRIMARY KEY,
    
    -- Service associé (peut être NULL si combinaison générée avant création du service)
    service_id INTEGER,
    
    -- Vecteur produit (caractéristiques hors localisation)
    -- Ex: ["Nike", "Air Max", "Noir", "Neuf", "42"]
    product_vector TEXT[] NOT NULL,
    
    -- Vecteur localisation (hiérarchie géographique)
    -- Ex: ["Douala", "Akwa", "Littoral", "Cameroun"]
    location_vector TEXT[] DEFAULT '{}',
    
    -- Vecteur complet (product_vector + location_vector)
    -- Ex: ["Nike", "Air Max", "Noir", "Neuf", "42", "Douala", "Akwa", "Littoral", "Cameroun"]
    full_vector TEXT[] NOT NULL,
    
    -- Localisation choisie (dernier élément clé du location_vector)
    -- Ex: "Douala" ou "Akwa"
    chosen_location TEXT,
    
    -- Compteur d'utilisation (popularité)
    usage_count INTEGER DEFAULT 1,
    
    -- Indicateur de choix AI (TRUE si c'est la combinaison préférée par l'IA)
    is_ai_preferred BOOLEAN DEFAULT FALSE,
    
    -- Confiance IA (0.0 à 1.0)
    ai_confidence FLOAT DEFAULT 0.0,
    
    -- Session ID pour traçabilité (lien avec la génération IA)
    session_id TEXT,
    
    -- Variabilité de prix (si applicable)
    has_variant BOOLEAN DEFAULT FALSE,
    variant_dimension TEXT, -- Ex: "pointure", "taille", "capacité"
    variant_value TEXT, -- Ex: "42", "M", "128GB"
    
    -- Prix et stock (si disponibles)
    prix DECIMAL(12, 2),
    devise TEXT DEFAULT 'XAF',
    stock INTEGER,
    
    -- Métadonnées
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    -- Contrainte d'unicité : même vecteur complet = même entrée
    CONSTRAINT unique_full_vector UNIQUE (full_vector)
);

-- Index pour recherche par service_id (avec filtre partiel)
CREATE INDEX IF NOT EXISTS idx_combinations_service_id 
    ON autocomplete_combinations(service_id) 
    WHERE service_id IS NOT NULL;

-- Index pour recherche par session (toutes les combinaisons d'une session AI)
CREATE INDEX IF NOT EXISTS idx_combinations_session 
    ON autocomplete_combinations(session_id);

-- Index pour recherche par choix AI préféré (avec filtre partiel)
CREATE INDEX IF NOT EXISTS idx_combinations_ai_preferred 
    ON autocomplete_combinations(is_ai_preferred) 
    WHERE is_ai_preferred = TRUE;

-- Index GIN pour recherche vectorielle rapide dans product_vector
CREATE INDEX IF NOT EXISTS idx_combinations_product_vector_gin 
    ON autocomplete_combinations USING GIN(product_vector);

-- Index GIN pour recherche vectorielle rapide dans location_vector
CREATE INDEX IF NOT EXISTS idx_combinations_location_vector_gin 
    ON autocomplete_combinations USING GIN(location_vector);

-- Index GIN pour recherche vectorielle rapide dans full_vector
CREATE INDEX IF NOT EXISTS idx_combinations_full_vector_gin 
    ON autocomplete_combinations USING GIN(full_vector);

-- Index pour tri par popularité (DESC pour ORDER BY optimization)
CREATE INDEX IF NOT EXISTS idx_combinations_usage_count 
    ON autocomplete_combinations(usage_count DESC);

-- Index composite pour recherche avec filtres de localisation
CREATE INDEX IF NOT EXISTS idx_combinations_location_usage 
    ON autocomplete_combinations(chosen_location, usage_count DESC);

-- Index pour recherche avec variabilité
CREATE INDEX IF NOT EXISTS idx_combinations_variant 
    ON autocomplete_combinations(has_variant, variant_dimension, variant_value);

-- Fonction pour mettre à jour updated_at
CREATE OR REPLACE FUNCTION update_combinations_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger pour updated_at
DROP TRIGGER IF EXISTS trigger_combinations_updated_at ON autocomplete_combinations;
CREATE TRIGGER trigger_combinations_updated_at
    BEFORE UPDATE ON autocomplete_combinations
    FOR EACH ROW
    EXECUTE FUNCTION update_combinations_updated_at();

DO $$
DECLARE
    rec RECORD;
BEGIN
    FOR rec IN 
        SELECT oid::regprocedure AS func_signature
        FROM pg_proc 
        WHERE proname = 'upsert_autocomplete_combination'
    LOOP
        EXECUTE format('DROP FUNCTION IF EXISTS %s CASCADE', rec.func_signature);
    END LOOP;
END $$;

-- Fonction pour upsert une combinaison (incrémenter usage_count si existe)
CREATE OR REPLACE FUNCTION upsert_autocomplete_combination(
    p_product_vector TEXT[],
    p_location_vector TEXT[] DEFAULT ARRAY[]::TEXT[],
    p_full_vector TEXT[] DEFAULT ARRAY[]::TEXT[],
    p_chosen_location TEXT DEFAULT NULL,
    p_is_ai_preferred BOOLEAN DEFAULT FALSE,
    p_ai_confidence FLOAT DEFAULT 0.0,
    p_session_id TEXT DEFAULT NULL,
    p_has_variant BOOLEAN DEFAULT FALSE,
    p_variant_dimension TEXT DEFAULT NULL,
    p_variant_value TEXT DEFAULT NULL,
    p_prix DECIMAL(12, 2) DEFAULT NULL,
    p_devise TEXT DEFAULT 'XAF',
    p_stock INTEGER DEFAULT NULL,
    p_service_id INTEGER DEFAULT NULL
)
RETURNS INTEGER AS $$
DECLARE
    v_id INTEGER;
    v_existing_count INTEGER;
BEGIN
    -- Vérifier si la combinaison existe déjà
    SELECT id, usage_count INTO v_id, v_existing_count
    FROM autocomplete_combinations
    WHERE full_vector = p_full_vector;
    
    IF FOUND THEN
        -- Mise à jour : incrémenter usage_count
        UPDATE autocomplete_combinations
        SET 
            usage_count = usage_count + 1,
            is_ai_preferred = CASE 
                WHEN p_is_ai_preferred THEN TRUE 
                ELSE is_ai_preferred 
            END,
            ai_confidence = GREATEST(ai_confidence, p_ai_confidence),
            service_id = COALESCE(p_service_id, service_id),
            updated_at = NOW()
        WHERE id = v_id;
        
        RETURN v_id;
    ELSE
        -- Insertion nouvelle combinaison
        INSERT INTO autocomplete_combinations (
            service_id,
            product_vector,
            location_vector,
            full_vector,
            chosen_location,
            usage_count,
            is_ai_preferred,
            ai_confidence,
            session_id,
            has_variant,
            variant_dimension,
            variant_value,
            prix,
            devise,
            stock
        )
        VALUES (
            p_service_id,
            p_product_vector,
            p_location_vector,
            p_full_vector,
            p_chosen_location,
            1,
            p_is_ai_preferred,
            p_ai_confidence,
            p_session_id,
            p_has_variant,
            p_variant_dimension,
            p_variant_value,
            p_prix,
            p_devise,
            p_stock
        )
        RETURNING id INTO v_id;
        
        RETURN v_id;
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Fonction pour calculer le score de localisation (proximité géographique)
-- Utilisée pour trier les résultats par pertinence géographique
CREATE OR REPLACE FUNCTION calculate_location_score(
    search_location TEXT,
    location_vector TEXT[],
    chosen_location TEXT
)
RETURNS FLOAT AS $$
DECLARE
    score FLOAT := 0.0;
    search_lower TEXT;
    i INTEGER;
    vec_length INTEGER;
BEGIN
    IF search_location IS NULL OR location_vector IS NULL THEN
        RETURN 0.0;
    END IF;
    
    search_lower := LOWER(search_location);
    vec_length := array_length(location_vector, 1);

    IF vec_length IS NULL OR vec_length < 1 THEN
        RETURN 0.0;
    END IF;
    
    -- Correspondance exacte avec chosen_location (score max)
    IF chosen_location IS NOT NULL AND LOWER(chosen_location) = search_lower THEN
        RETURN 1.0;
    END IF;
    
    -- Recherche dans le vecteur de localisation
    FOR i IN 1..vec_length LOOP
        IF LOWER(location_vector[i]) = search_lower THEN
            -- Score dépend de la position dans la hiérarchie
            -- Position 1 (ville) = 1.0, Position 2 (quartier) = 0.9, etc.
            score := 1.0 - (i - 1) * 0.1;
            EXIT;
        ELSIF LOWER(location_vector[i]) LIKE '%' || search_lower || '%' THEN
            -- Correspondance partielle (score réduit)
            score := 0.5 - (i - 1) * 0.1;
        END IF;
    END LOOP;
    
    RETURN GREATEST(score, 0.0);
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- Commentaires pour documentation
COMMENT ON TABLE autocomplete_combinations IS 'Stockage des combinaisons vectorielles complètes de produits pour recherche intelligente';
COMMENT ON COLUMN autocomplete_combinations.product_vector IS 'Vecteur caractéristiques produit sans localisation';
COMMENT ON COLUMN autocomplete_combinations.location_vector IS 'Vecteur hiérarchie géographique';
COMMENT ON COLUMN autocomplete_combinations.full_vector IS 'Vecteur complet (product + location)';
COMMENT ON COLUMN autocomplete_combinations.is_ai_preferred IS 'TRUE si combinaison préférée par IA (affichée en premier)';
COMMENT ON COLUMN autocomplete_combinations.session_id IS 'ID de session IA pour regrouper les combinaisons générées ensemble';
COMMENT ON COLUMN autocomplete_combinations.usage_count IS 'Nombre d''utilisations (popularité)';
COMMENT ON FUNCTION upsert_autocomplete_combination IS 'Insère ou met à jour une combinaison autocomplete avec incrément du compteur d''usage';
COMMENT ON FUNCTION calculate_location_score IS 'Calcule le score de pertinence géographique pour le tri des résultats';



