-- Migration: 20251104002_003_add_review_replies_system.sql
-- ============================================
-- Migration pour ajouter le support des réponses aux avis/commentaires sur les produits
-- Permet aux utilisateurs de répondre à un avis spécifique avec indexation claire

-- Ajouter la colonne reply_to_review_id à la table service_reviews
ALTER TABLE service_reviews
ADD COLUMN IF NOT EXISTS reply_to_review_id INTEGER REFERENCES service_reviews(id) ON DELETE CASCADE;

-- Ajouter un commentaire explicatif
COMMENT ON COLUMN service_reviews.reply_to_review_id IS 'ID de l''avis auquel on répond (système de réponses aux commentaires)';

-- ✅ SQLx OFFLINE MODE: Créer l'index de manière conditionnelle
DO $$ 
BEGIN 
    IF NOT EXISTS (
        SELECT 1 FROM pg_indexes 
        WHERE indexname = 'idx_service_reviews_reply_to'
    ) THEN
        CREATE INDEX idx_service_reviews_reply_to ON service_reviews(reply_to_review_id) WHERE reply_to_review_id IS NOT NULL;
    END IF;
END $$;

-- Créer une vue pour faciliter la récupération des avis avec leurs réponses
CREATE OR REPLACE VIEW service_reviews_with_replies AS
SELECT 
    r.*,
    COALESCE(u.nom_complet, u.email) as user_name,
    u.email as user_email,
    u.avatar_url as user_avatar,
    rr.id as reply_to_id,
    rr.user_id as reply_to_user_id,
    rr.rating as reply_to_rating,
    rr.comment as reply_to_text,
    rr.created_at as reply_to_created_at,
    COALESCE(ru.nom_complet, ru.email) as reply_to_user_name,
    ru.avatar_url as reply_to_user_avatar
FROM service_reviews r
LEFT JOIN users u ON r.user_id = u.id
LEFT JOIN service_reviews rr ON r.reply_to_review_id = rr.id
LEFT JOIN users ru ON rr.user_id = ru.id;

COMMENT ON VIEW service_reviews_with_replies IS 'Vue combinant les avis avec leurs réponses pour faciliter les requêtes';

-- Fonction pour obtenir les avis d'un service avec leurs réponses
CREATE OR REPLACE FUNCTION get_service_reviews_with_replies(
    p_service_id INTEGER,
    p_limit INTEGER DEFAULT 50,
    p_offset INTEGER DEFAULT 0
)
RETURNS TABLE (
    review_id INTEGER,
    user_id INTEGER,
    user_name TEXT,
    user_avatar TEXT,
    rating INTEGER,
    comment TEXT,
    created_at TIMESTAMP WITH TIME ZONE,
    updated_at TIMESTAMP WITH TIME ZONE,
    reply_to_review_id INTEGER,
    reply_to_user_name TEXT,
    reply_to_text TEXT,
    reply_to_created_at TIMESTAMP WITH TIME ZONE,
    reply_count BIGINT
)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.id::INTEGER as review_id,
        r.user_id::INTEGER,
        COALESCE(u.nom_complet, u.email)::TEXT as user_name,
        u.avatar_url::TEXT as user_avatar,
        r.rating::INTEGER,
        r.comment::TEXT,
        r.created_at,
        r.updated_at,
        r.reply_to_review_id::INTEGER,
        COALESCE(ru.nom_complet, ru.email)::TEXT as reply_to_user_name,
        rr.comment::TEXT as reply_to_text,
        rr.created_at as reply_to_created_at,
        (SELECT COUNT(*) FROM service_reviews WHERE reply_to_review_id = r.id)::BIGINT as reply_count
    FROM service_reviews r
    LEFT JOIN users u ON r.user_id = u.id
    LEFT JOIN service_reviews rr ON r.reply_to_review_id = rr.id
    LEFT JOIN users ru ON rr.user_id = ru.id
    WHERE r.service_id = p_service_id
    ORDER BY r.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$;

COMMENT ON FUNCTION get_service_reviews_with_replies IS 'Récupère les avis d''un service avec leurs réponses et le nombre de réponses par avis';

-- Fonction pour obtenir les réponses d'un avis spécifique
CREATE OR REPLACE FUNCTION get_review_replies(
    p_review_id INTEGER,
    p_limit INTEGER DEFAULT 20
)
RETURNS TABLE (
    reply_id INTEGER,
    user_id INTEGER,
    user_name TEXT,
    user_avatar TEXT,
    rating INTEGER,
    reply_text TEXT,
    created_at TIMESTAMP WITH TIME ZONE
)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.id::INTEGER as reply_id,
        r.user_id::INTEGER,
        COALESCE(u.nom_complet, u.email)::TEXT as user_name,
        u.avatar_url::TEXT as user_avatar,
        r.rating::INTEGER,
        r.comment::TEXT as reply_text,
        r.created_at
    FROM service_reviews r
    LEFT JOIN users u ON r.user_id = u.id
    WHERE r.reply_to_review_id = p_review_id
    ORDER BY r.created_at ASC
    LIMIT p_limit;
END;
$$;

COMMENT ON FUNCTION get_review_replies IS 'Récupère toutes les réponses à un avis spécifique';



-- ============================================
-- Migration: 20251104003_004_add_product_reactions.sql
-- ============================================
-- Migration pour le système de réactions/émotions sur les produits
-- Date: 2025-11-04
-- Description: Permet aux utilisateurs de réagir avec des émotions sur les produits

-- Table pour les réactions sur les produits
CREATE TABLE IF NOT EXISTS product_reactions (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    service_id INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE,
    product_id TEXT NOT NULL,  -- Format: "serviceId_productIndex"
    reaction_type VARCHAR(20) NOT NULL CHECK (reaction_type IN (
        'love',        -- ❤️ J'adore
        'like',        -- 👍 J'aime
        'wow',         -- 😮 Impressionnant
        'interested',  -- 🎯 Intéressant
        'thinking',    -- 🤔 À réfléchir
        'disappointed' -- 😕 Déçu
    )),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    UNIQUE(user_id, service_id, product_id, reaction_type)
);

-- ✅ SQLx OFFLINE MODE: Créer les index de manière conditionnelle
DO $$ 
BEGIN 
    IF NOT EXISTS (
        SELECT 1 FROM pg_indexes 
        WHERE indexname = 'idx_product_reactions_product'
    ) THEN
        CREATE INDEX idx_product_reactions_product ON product_reactions(service_id, product_id);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_indexes 
        WHERE indexname = 'idx_product_reactions_user'
    ) THEN
        CREATE INDEX idx_product_reactions_user ON product_reactions(user_id);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_indexes 
        WHERE indexname = 'idx_product_reactions_type'
    ) THEN
        CREATE INDEX idx_product_reactions_type ON product_reactions(reaction_type);
    END IF;
END $$;

-- Fonction pour obtenir le décompte des réactions par produit
CREATE OR REPLACE FUNCTION get_product_reactions_count(
    p_service_id INTEGER,
    p_product_id TEXT
)
RETURNS TABLE (
    reaction_type VARCHAR(20),
    count BIGINT,
    users_sample TEXT[]
)
LANGUAGE SQL
AS $$
    SELECT 
        pr.reaction_type,
        COUNT(*)::BIGINT as count,
        array_agg(COALESCE(u.nom_complet, u.email) ORDER BY pr.created_at DESC)::TEXT[] as users_sample
    FROM product_reactions pr
    LEFT JOIN users u ON pr.user_id = u.id
    WHERE pr.service_id = p_service_id
      AND pr.product_id = p_product_id
    GROUP BY pr.reaction_type
    ORDER BY count DESC;
$$;

COMMENT ON TABLE product_reactions IS 'Réactions/émotions des utilisateurs sur les produits';
COMMENT ON FUNCTION get_product_reactions_count IS 'Récupère le décompte des réactions par produit avec échantillon d''utilisateurs';


-- ============================================
-- Migration: 20251104004_005_add_private_conversations.sql
-- ============================================
-- Migration pour conversations privées 1-to-1
-- Date: 2025-11-04
-- Description: Permet aux utilisateurs de discuter en privé entre eux

-- Table pour conversations privées
CREATE TABLE IF NOT EXISTS private_conversations (
    id SERIAL PRIMARY KEY,
    user_1_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    user_2_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    context TEXT,  -- 'product_review', 'direct_contact', 'mention', etc.
    created_at TIMESTAMPTZ DEFAULT NOW(),
    last_message_at TIMESTAMPTZ,
    
    -- Contrainte pour éviter doublons (user_1_id toujours < user_2_id)
    CHECK (user_1_id < user_2_id),
    UNIQUE(user_1_id, user_2_id)
);

-- ✅ SQLx OFFLINE MODE: Créer les index de manière conditionnelle
DO $$ 
BEGIN 
    IF NOT EXISTS (
        SELECT 1 FROM pg_indexes 
        WHERE indexname = 'idx_private_conversations_user_1'
    ) THEN
        CREATE INDEX idx_private_conversations_user_1 ON private_conversations(user_1_id);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_indexes 
        WHERE indexname = 'idx_private_conversations_user_2'
    ) THEN
        CREATE INDEX idx_private_conversations_user_2 ON private_conversations(user_2_id);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_indexes 
        WHERE indexname = 'idx_private_conversations_last_message'
    ) THEN
        CREATE INDEX idx_private_conversations_last_message ON private_conversations(last_message_at DESC);
    END IF;
END $$;

-- Fonction pour normaliser l'ordre des IDs (user_1_id toujours < user_2_id)
CREATE OR REPLACE FUNCTION normalize_conversation_users()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.user_1_id > NEW.user_2_id THEN
        -- Inverser si user_1 > user_2
        DECLARE
            temp INTEGER;
        BEGIN
            temp := NEW.user_1_id;
            NEW.user_1_id := NEW.user_2_id;
            NEW.user_2_id := temp;
        END;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger pour appliquer la normalisation automatiquement
DROP TRIGGER IF EXISTS trigger_normalize_conversation_users ON private_conversations;
CREATE TRIGGER trigger_normalize_conversation_users
    BEFORE INSERT OR UPDATE ON private_conversations
    FOR EACH ROW
    EXECUTE FUNCTION normalize_conversation_users();

COMMENT ON TABLE private_conversations IS 'Conversations privées 1-to-1 entre utilisateurs (pas liées à un service)';
COMMENT ON FUNCTION normalize_conversation_users IS 'Garantit que user_1_id < user_2_id pour éviter doublons';



