-- ============================================
-- Migration: 20251123_filter_active_products_in_search_gps_final.sql
-- ============================================
-- Migration: Filtrer les produits désactivés dans search_services_gps_final
-- Date: 2025-11-23
-- Description: Modifier search_services_gps_final pour rechercher dans les PRODUITS actifs (table products_lifecycle) et non dans les services

-- 1. S'assurer que la fonction get_active_products existe
-- Amélioration: supporte les deux formats de produits (direct array ou nested valeur)
CREATE OR REPLACE FUNCTION get_active_products(service_data JSONB, p_service_id INTEGER)
RETURNS JSONB AS $$
DECLARE
    active_products JSONB := '[]'::JSONB;
    product JSONB;
    product_idx INTEGER := 0;
    is_product_active BOOLEAN;
    produits_array JSONB;
BEGIN
    -- Déterminer le tableau de produits à utiliser
    IF jsonb_typeof(service_data->'produits') = 'array' THEN
        produits_array := service_data->'produits';
    ELSIF jsonb_typeof(service_data->'produits'->'valeur') = 'array' THEN
        produits_array := service_data->'produits'->'valeur';
    ELSE
        RETURN '[]'::JSONB;
    END IF;
    
    -- Itérer sur les produits
    FOR product IN SELECT * FROM jsonb_array_elements(produits_array)
    LOOP
        -- Vérifier si le produit est actif dans products_lifecycle
        -- Si pas d'entrée dans products_lifecycle, considérer comme actif (valeur par défaut)
        SELECT COALESCE(pl.is_active, TRUE) INTO is_product_active
        FROM products_lifecycle pl
        WHERE pl.service_id = p_service_id
            AND pl.product_index = product_idx;
        
        -- Ajouter seulement si actif
        IF is_product_active THEN
            active_products := active_products || jsonb_build_array(product);
        END IF;
        
        product_idx := product_idx + 1;
    END LOOP;
    
    RETURN active_products;
END;
$$ LANGUAGE plpgsql STABLE;

-- 2. Modifier search_services_gps_final pour rechercher dans les PRODUITS actifs
CREATE OR REPLACE FUNCTION search_services_gps_final(
    search_query text,
    user_gps_zone text,
    radius_km integer DEFAULT 50,
    max_results integer DEFAULT 100
)
RETURNS TABLE(
    service_id integer,
    titre_service text,
    category text,
    gps_coords text,
    distance_km double precision,
    relevance_score double precision,
    gps_source text
) AS $$
DECLARE
    gps_parts text[];
    lat double precision;
    lng double precision;
    radius_adjusted double precision;
    produits_array JSONB;
BEGIN
    -- Ajuster le rayon
    radius_adjusted := COALESCE(calculate_intelligent_radius(radius_km::double precision), radius_km::double precision);
    
    -- Extraire les coordonnées GPS si fournies
    IF user_gps_zone IS NOT NULL AND user_gps_zone != '' AND user_gps_zone != 'null' THEN
        -- Diviser par le séparateur "|" pour gérer les zones polygonales
        gps_parts := string_to_array(user_gps_zone, '|');
        
        -- Pour l'instant, utiliser le premier point comme centre de recherche
        IF array_length(gps_parts, 1) > 0 THEN
            -- Extraire lat,lng du premier point
            lat := split_part(gps_parts[1], ',', 1)::double precision;
            lng := split_part(gps_parts[1], ',', 2)::double precision;
            
            -- Recherche avec filtrage GPS et produits actifs
            RETURN QUERY
            WITH services_with_active_products AS (
                SELECT 
                    s.id,
                    s.data,
                    s.category,
                    s.gps,
                    s.is_active,
                    COALESCE(
                        get_best_gps_for_service(s.data),
                        s.gps,
                        '0,0'
                    ) as best_gps,
                    get_active_products(s.data, s.id) as active_products
                FROM services s
                WHERE s.is_active = TRUE
                    -- Filtrer uniquement les services qui ont au moins un produit actif
                    AND jsonb_array_length(get_active_products(s.data, s.id)) > 0
            ),
            scored_products AS (
                SELECT 
                    s.id as service_id,
                    COALESCE(
                        s.data->>'titre_service', 
                        s.data->'titre_service'->>'valeur', 
                        'Sans titre'
                    ) as titre_service,
                    COALESCE(
                        s.category, 
                        s.data->>'category', 
                        s.data->'category'->>'valeur',
                        'Non catégorisé'
                    ) as category,
                    s.best_gps as gps_coords,
                    CASE 
                        WHEN s.best_gps IS NOT NULL AND s.best_gps != '0,0' THEN
                            calculate_distance_km(user_gps_zone, s.best_gps)
                        ELSE 999999.0
                    END as distance_km,
                    -- Score basé principalement sur les PRODUITS (priorité maximale)
                    (
                        -- Score pour correspondance dans les PRODUITS actifs (priorité MAX)
                        (
                            SELECT COALESCE(SUM(
                                CASE 
                                    -- PRIORITÉ MAXIMALE: nom du produit
                                    WHEN product->>'nom' ILIKE '%' || search_query || '%' THEN 20.0
                                    WHEN product->>'name' ILIKE '%' || search_query || '%' THEN 20.0
                                    WHEN product->>'titre' ILIKE '%' || search_query || '%' THEN 18.0
                                    -- TRÈS IMPORTANT: catégorie du produit
                                    WHEN product->>'categorie' ILIKE '%' || search_query || '%' THEN 15.0
                                    WHEN product->>'categorieQuincaillerie' ILIKE '%' || search_query || '%' THEN 15.0
                                    WHEN product->>'categorieElectromenager' ILIKE '%' || search_query || '%' THEN 15.0
                                    -- IMPORTANT: description du produit
                                    WHEN product->>'description' ILIKE '%' || search_query || '%' THEN 12.0
                                    -- Autres champs produit
                                    WHEN product->>'type' ILIKE '%' || search_query || '%' THEN 10.0
                                    WHEN product->>'marque' ILIKE '%' || search_query || '%' THEN 10.0
                                    WHEN product->>'modele' ILIKE '%' || search_query || '%' THEN 8.0
                                    WHEN product->>'matiere' ILIKE '%' || search_query || '%' THEN 8.0
                                    WHEN product->>'couleur' ILIKE '%' || search_query || '%' THEN 6.0
                                    ELSE 0.0
                                END
                            ), 0.0)
                            FROM jsonb_array_elements(s.active_products) AS product
                        ) +
                        -- Score pour correspondance dans les champs SERVICE (priorité réduite)
                        CASE 
                            WHEN s.data->>'titre_service' ILIKE '%' || search_query || '%' 
                            OR s.data->'titre_service'->>'valeur' ILIKE '%' || search_query || '%' THEN 5.0
                            ELSE 0.0
                        END +
                        CASE 
                            WHEN s.data->>'description' ILIKE '%' || search_query || '%'
                            OR s.data->'description'->>'valeur' ILIKE '%' || search_query || '%' THEN 3.0
                            ELSE 0.0
                        END +
                        CASE 
                            WHEN s.data->>'category' ILIKE '%' || search_query || '%'
                            OR s.data->'category'->>'valeur' ILIKE '%' || search_query || '%' THEN 4.0
                            ELSE 0.0
                        END
                    )::double precision as relevance_score,
                    CASE 
                        WHEN s.best_gps = get_best_gps_for_service(s.data) THEN 'produit_gps'
                        ELSE 'service_gps'
                    END as gps_source
                FROM services_with_active_products s
                WHERE 
                    -- Filtrer par distance si GPS fourni
                    CASE 
                        WHEN s.best_gps IS NOT NULL AND s.best_gps != '0,0' THEN
                            calculate_distance_km(user_gps_zone, s.best_gps) <= radius_adjusted
                        ELSE FALSE
                    END
                    -- Au moins un produit actif qui correspond à la recherche
                    AND (
                        search_query IS NULL 
                        OR search_query = ''
                        OR EXISTS (
                            SELECT 1
                            FROM jsonb_array_elements(s.active_products) AS product
                            WHERE 
                                product->>'nom' ILIKE '%' || search_query || '%'
                                OR product->>'name' ILIKE '%' || search_query || '%'
                                OR product->>'titre' ILIKE '%' || search_query || '%'
                                OR product->>'categorie' ILIKE '%' || search_query || '%'
                                OR product->>'description' ILIKE '%' || search_query || '%'
                                OR product->>'type' ILIKE '%' || search_query || '%'
                                OR product->>'marque' ILIKE '%' || search_query || '%'
                        )
                        -- OU correspondance dans les champs service (fallback)
                        OR s.data::TEXT ILIKE '%' || search_query || '%'
                    )
            )
            SELECT 
                sp.service_id,
                sp.titre_service,
                sp.category,
                sp.gps_coords,
                sp.distance_km,
                sp.relevance_score,
                sp.gps_source
            FROM scored_products sp
            WHERE sp.relevance_score > 0
            ORDER BY 
                sp.relevance_score DESC,
                sp.distance_km ASC
            LIMIT max_results;
            
            RETURN;
        END IF;
    END IF;
    
    -- Si pas de GPS, faire une recherche textuelle sur produits actifs uniquement
    RETURN QUERY
    WITH services_with_active_products AS (
        SELECT 
            s.id,
            s.data,
            s.category,
            s.gps,
            get_active_products(s.data, s.id) as active_products
        FROM services s
        WHERE s.is_active = TRUE
            AND jsonb_array_length(get_active_products(s.data, s.id)) > 0
    )
    SELECT 
        s.id as service_id,
        COALESCE(
            s.data->>'titre_service', 
            s.data->'titre_service'->>'valeur', 
            'Sans titre'
        ) as titre_service,
        COALESCE(
            s.category, 
            s.data->>'category', 
            s.data->'category'->>'valeur',
            'Non catégorisé'
        ) as category,
        COALESCE(
            get_best_gps_for_service(s.data),
            s.gps,
            '0,0'
        ) as gps_coords,
        0.0 as distance_km,
        -- Score basé principalement sur les PRODUITS
        (
            (
                SELECT COALESCE(SUM(
                    CASE 
                        WHEN product->>'nom' ILIKE '%' || search_query || '%' THEN 20.0
                        WHEN product->>'name' ILIKE '%' || search_query || '%' THEN 20.0
                        WHEN product->>'titre' ILIKE '%' || search_query || '%' THEN 18.0
                        WHEN product->>'categorie' ILIKE '%' || search_query || '%' THEN 15.0
                        WHEN product->>'description' ILIKE '%' || search_query || '%' THEN 12.0
                        WHEN product->>'type' ILIKE '%' || search_query || '%' THEN 10.0
                        WHEN product->>'marque' ILIKE '%' || search_query || '%' THEN 10.0
                        ELSE 0.0
                    END
                ), 0.0)
                FROM jsonb_array_elements(s.active_products) AS product
            ) +
            CASE 
                WHEN s.data->>'titre_service' ILIKE '%' || search_query || '%' THEN 5.0
                ELSE 0.0
            END
        )::double precision as relevance_score,
        'no_gps' as gps_source
    FROM services_with_active_products s
    WHERE 
        search_query IS NULL 
        OR search_query = ''
        OR EXISTS (
            SELECT 1
            FROM jsonb_array_elements(s.active_products) AS product
            WHERE 
                product->>'nom' ILIKE '%' || search_query || '%'
                OR product->>'name' ILIKE '%' || search_query || '%'
                OR product->>'titre' ILIKE '%' || search_query || '%'
                OR product->>'categorie' ILIKE '%' || search_query || '%'
                OR product->>'description' ILIKE '%' || search_query || '%'
        )
        OR s.data::TEXT ILIKE '%' || search_query || '%'
    ORDER BY relevance_score DESC
    LIMIT max_results;
END;
$$ LANGUAGE plpgsql STABLE;

-- Commentaires
COMMENT ON FUNCTION get_active_products IS 'Filtre et retourne uniquement les produits actifs (is_active = TRUE dans products_lifecycle). Par défaut, si pas d''entrée dans products_lifecycle, le produit est considéré comme actif.';
COMMENT ON FUNCTION search_services_gps_final IS 'Recherche dans les PRODUITS actifs (via products_lifecycle), pas dans les services. Retourne uniquement les services qui ont au moins un produit actif correspondant à la recherche.';



-- ============================================
-- Migration: 20251124001_migrate_products_to_json.sql
-- ============================================
-- Migration : Convertir les produits de format chaîne concaténée vers format JSON structuré
-- Date : 2025-11-24
-- Description : Convertit les produits stockés comme chaînes concaténées dans service.data.produits.valeur
--               vers des objets JSON structurés pour améliorer l'extraction et l'utilisation des données
-- Compatible : SQLx offline mode

-- ============================================================================
-- Fonction helper pour parser une chaîne produit
-- ============================================================================

CREATE OR REPLACE FUNCTION parse_product_string(product_string TEXT)
RETURNS JSONB
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    parts TEXT[];
    result JSONB;
    nom TEXT;
    categorie TEXT;
    description TEXT;
    prix TEXT;
    devise TEXT;
    last_numeric_index INTEGER;
    i INTEGER;
BEGIN
    -- Split par virgule
    parts := string_to_array(product_string, ',');
    
    -- Nettoyer les parties (trim)
    FOR i IN 1..array_length(parts, 1) LOOP
        parts[i] := trim(parts[i]);
    END LOOP;
    
    -- Si pas assez de parties, retourner un objet minimal
    IF array_length(parts, 1) < 2 THEN
        RETURN jsonb_build_object(
            'nom_produit', COALESCE(parts[1], 'Produit'),
            'description_produit', '',
            'prix', '0',
            'devise', 'XAF'
        );
    END IF;
    
    -- Le premier élément est toujours le nom
    nom := parts[1];
    
    -- Le deuxième élément est généralement la catégorie
    categorie := parts[2];
    
    -- Trouver le dernier élément numérique (prix)
    last_numeric_index := NULL;
    FOR i IN array_length(parts, 1) DOWNTO 1 LOOP
        IF parts[i] ~ '^\d+\.?\d*$' THEN
            last_numeric_index := i;
            EXIT;
        END IF;
    END LOOP;
    
    -- Si on a trouvé un prix
    IF last_numeric_index IS NOT NULL THEN
        prix := parts[last_numeric_index];
        
        -- La devise peut être après le prix
        IF last_numeric_index < array_length(parts, 1) THEN
            devise := parts[last_numeric_index + 1];
        ELSE
            devise := 'XAF';
        END IF;
        
        -- La description est tout ce qui est entre la catégorie et le prix
        IF last_numeric_index > 2 THEN
            description := array_to_string(parts[3:last_numeric_index-1], ', ');
        ELSIF array_length(parts, 1) >= 3 THEN
            description := parts[3];
        ELSE
            description := '';
        END IF;
    ELSE
        -- Pas de prix trouvé, tout après la catégorie est la description
        prix := '0';
        devise := 'XAF';
        IF array_length(parts, 1) >= 3 THEN
            description := array_to_string(parts[3:], ', ');
        ELSE
            description := '';
        END IF;
    END IF;
    
    -- Construire l'objet JSON
    result := jsonb_build_object(
        'nom_produit', COALESCE(nom, 'Produit'),
        'categorie_produit', COALESCE(categorie, ''),
        'description_produit', COALESCE(description, ''),
        'prix', COALESCE(prix, '0'),
        'devise', COALESCE(devise, 'XAF')
    );
    
    RETURN result;
END;
$$;

-- ============================================================================
-- Migration principale : Convertir les chaînes en objets JSON
-- ============================================================================

DO $$
DECLARE
    service_record RECORD;
    produits_array JSONB;
    new_produits_array JSONB;
    elem JSONB;
    converted_count INTEGER := 0;
    error_count INTEGER := 0;
    total_to_convert INTEGER;
BEGIN
    -- Compter les services à migrer
    SELECT COUNT(*) INTO total_to_convert
    FROM services
    WHERE jsonb_typeof(data->'produits'->'valeur') = 'array'
    AND EXISTS (
        SELECT 1
        FROM jsonb_array_elements(data->'produits'->'valeur') AS elem
        WHERE jsonb_typeof(elem) = 'string'
    );
    
    IF total_to_convert = 0 THEN
        RAISE NOTICE '✅ Aucun service à migrer (tous les produits sont déjà en format JSON)';
        RETURN;
    END IF;
    
    RAISE NOTICE '🔄 Début de la migration de % services...', total_to_convert;
    
    -- Parcourir tous les services avec produits en format chaîne
    FOR service_record IN
        SELECT id, data
        FROM services
        WHERE jsonb_typeof(data->'produits'->'valeur') = 'array'
        AND EXISTS (
            SELECT 1
            FROM jsonb_array_elements(data->'produits'->'valeur') AS elem
            WHERE jsonb_typeof(elem) = 'string'
        )
    LOOP
        BEGIN
            produits_array := service_record.data->'produits'->'valeur';
            new_produits_array := '[]'::JSONB;
            
            -- Convertir chaque élément
            FOR elem IN SELECT * FROM jsonb_array_elements(produits_array)
            LOOP
                IF jsonb_typeof(elem) = 'string' THEN
                    -- Convertir la chaîne en objet JSON
                    new_produits_array := new_produits_array || jsonb_build_array(
                        parse_product_string(elem::TEXT)
                    );
                ELSE
                    -- Garder l'objet tel quel
                    new_produits_array := new_produits_array || jsonb_build_array(elem);
                END IF;
            END LOOP;
            
            -- Mettre à jour le service
            UPDATE services
            SET data = jsonb_set(
                data,
                '{produits,valeur}',
                new_produits_array
            ),
            updated_at = NOW()
            WHERE id = service_record.id;
            
            converted_count := converted_count + 1;
            
            IF converted_count % 100 = 0 THEN
                RAISE NOTICE '   ✅ % services migrés...', converted_count;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            error_count := error_count + 1;
            RAISE WARNING '   ❌ Erreur lors de la migration du service %: %', service_record.id, SQLERRM;
        END;
    END LOOP;
    
    RAISE NOTICE '✅ Migration terminée!';
    RAISE NOTICE '   - Services migrés avec succès: %', converted_count;
    RAISE NOTICE '   - Erreurs: %', error_count;
    
    -- Vérification finale
    IF error_count > 0 THEN
        RAISE WARNING '⚠️ % erreurs rencontrées lors de la migration', error_count;
    END IF;
END $$;

-- ============================================================================
-- Nettoyage : Supprimer la fonction helper (optionnel)
-- ============================================================================

-- La fonction parse_product_string est conservée pour d'éventuelles migrations futures
-- Si vous souhaitez la supprimer, décommentez la ligne suivante :
-- DROP FUNCTION IF EXISTS parse_product_string(TEXT);



-- ============================================
-- Migration: 20251125_fix_idx_services_search_optimized.sql
-- ============================================
-- Migration pour corriger l'erreur "index row size exceeds btree maximum"
-- Date: 2025-11-25
-- Description: Supprime l'INCLUDE (data) de l'index idx_services_search_optimized
--              car la colonne data JSONB peut être trop volumineuse (limite B-tree: 2704 bytes)
--              L'index sera recréé sans INCLUDE (data), seulement avec user_id
-- Compatible: SQLx offline mode (pas de SELECT retournant des résultats)
--
-- EXPLICATION :
-- L'index avec INCLUDE (data) était conçu pour permettre des "Index-Only Scans" (très rapides),
-- mais PostgreSQL B-tree a une limite de 2704 bytes (v4) ou 8191 bytes (v5) par ligne d'index.
-- Comme data JSONB peut dépasser cette limite (ex: 7830 bytes), l'index échoue.
--
-- ALTERNATIVE (optionnelle) : Si vous voulez quand même un index covering partiel,
-- vous pouvez créer un index séparé avec seulement les champs les plus utilisés :
--   CREATE INDEX idx_services_search_covering 
--   ON services (is_active, created_at DESC) 
--   INCLUDE (user_id, (data->>'titre_service'), (data->>'category'))
--   WHERE is_active = true;
--
-- Voir backend/EXPLICATION_INDEX_INCLUDE_DATA.md pour plus de détails.

-- 1. Supprimer l'ancien index problématique
DROP INDEX IF EXISTS idx_services_search_optimized;

-- 2. Recréer l'index sans INCLUDE (data) pour éviter l'erreur de taille
--    On garde seulement user_id dans INCLUDE car c'est un INTEGER (petit, ~4 bytes)
--    Performance : Les requêtes feront un lookup vers la table pour récupérer data
--    (10-50ms au lieu de 1-5ms, mais acceptable et sans limite de taille)
CREATE INDEX IF NOT EXISTS idx_services_search_optimized 
ON services (is_active, created_at DESC) 
INCLUDE (user_id)
WHERE is_active = true;

-- 3. Commentaire pour documenter la modification
COMMENT ON INDEX idx_services_search_optimized IS 
'Index optimisé pour recherche active (sans INCLUDE data pour éviter erreur taille B-tree). 
Performance: 10-50ms par requête (acceptable). Voir EXPLICATION_INDEX_INCLUDE_DATA.md pour détails.';



