-- ============================================================================
-- TRIGGERS POUR updated_at AUTOMATIQUE
-- ============================================================================

-- Fonction générique pour updated_at
CREATE OR REPLACE FUNCTION update_specialized_service_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Triggers pour chaque table
DROP TRIGGER IF EXISTS trigger_pharmacies_updated_at ON pharmacies;
CREATE TRIGGER trigger_pharmacies_updated_at
    BEFORE UPDATE ON pharmacies
    FOR EACH ROW
    EXECUTE FUNCTION update_specialized_service_timestamp();

DROP TRIGGER IF EXISTS trigger_hopitaux_updated_at ON hopitaux_cliniques;
CREATE TRIGGER trigger_hopitaux_updated_at
    BEFORE UPDATE ON hopitaux_cliniques
    FOR EACH ROW
    EXECUTE FUNCTION update_specialized_service_timestamp();

DROP TRIGGER IF EXISTS trigger_laboratoires_updated_at ON laboratoires_imagerie;
CREATE TRIGGER trigger_laboratoires_updated_at
    BEFORE UPDATE ON laboratoires_imagerie
    FOR EACH ROW
    EXECUTE FUNCTION update_specialized_service_timestamp();

DROP TRIGGER IF EXISTS trigger_agences_updated_at ON agences_voyage;
CREATE TRIGGER trigger_agences_updated_at
    BEFORE UPDATE ON agences_voyage
    FOR EACH ROW
    EXECUTE FUNCTION update_specialized_service_timestamp();

DROP TRIGGER IF EXISTS trigger_covoiturages_updated_at ON covoiturages;
CREATE TRIGGER trigger_covoiturages_updated_at
    BEFORE UPDATE ON covoiturages
    FOR EACH ROW
    EXECUTE FUNCTION update_specialized_service_timestamp();

DROP TRIGGER IF EXISTS trigger_taxis_updated_at ON taxis_ville;
CREATE TRIGGER trigger_taxis_updated_at
    BEFORE UPDATE ON taxis_ville
    FOR EACH ROW
    EXECUTE FUNCTION update_specialized_service_timestamp();

-- ============================================================================
-- NOTES IMPORTANTES
-- ============================================================================

-- ✅ Compatible SQLx offline mode :
--    - Pas de SELECT retournant des résultats
--    - Utilisation de DO $$ blocks pour vérifications
--    - CREATE TABLE IF NOT EXISTS
--    - CREATE INDEX IF NOT EXISTS
--    - CREATE OR REPLACE FUNCTION

-- ✅ Prise en compte du moment (NOW()) :
--    - is_on_duty_now (pharmacies) : Calculé avec is_pharmacy_on_duty() et NOW()
--    - is_available_now (hôpitaux, laboratoires, taxis) : Calculé avec NOW()
--    - date_depart (covoiturages) : Filtre pour trajets disponibles maintenant/prochaines heures
--    - is_on_duty (taxis) : En service maintenant

-- ✅ Cohérence avec tables existantes :
--    - Références users(id) ON DELETE CASCADE
--    - Références services(id) ON DELETE CASCADE
--    - Format GPS : "lat,lng" (cohérent avec services.gps)
--    - Timestamps : TIMESTAMPTZ (cohérent avec services.created_at)



-- ============================================
-- Migration: 20251126_fix_search_services_gps_final_signature.sql
-- ============================================
-- Migration: Correction de la signature de search_services_gps_final
-- Date: 2025-11-26
-- Description: Corrige l'erreur "structure of query does not match function result type"
--              en garantissant que la fonction retourne exactement les colonnes attendues par le code Rust
-- Compatible: SQLx offline mode

-- 1. Supprimer toutes les versions existantes de la fonction
DROP FUNCTION IF EXISTS search_services_gps_final(text, text, integer, integer);
DROP FUNCTION IF EXISTS search_services_gps_final(text, text, integer);
DROP FUNCTION IF EXISTS search_services_gps_final(text, text);
DROP FUNCTION IF EXISTS search_services_gps_final(text);
DROP FUNCTION IF EXISTS search_services_gps_final();

-- 2. Recréer la fonction avec la signature exacte attendue par le code Rust
-- Le code Rust attend exactement ces colonnes dans cet ordre:
-- service_id, titre_service, category, gps_coords, distance_km, relevance_score, gps_source

CREATE OR REPLACE FUNCTION search_services_gps_final(
    search_query text,
    user_gps_zone text,
    radius_km integer DEFAULT 50,
    max_results integer DEFAULT 100
)
RETURNS TABLE(
    service_id integer,
    titre_service text,
    category text,
    gps_coords text,
    distance_km double precision,
    relevance_score double precision,
    gps_source text
) AS $$
DECLARE
    gps_parts text[];
    lat double precision;
    lng double precision;
    radius_adjusted double precision;
BEGIN
    -- Ajuster le rayon
    radius_adjusted := COALESCE(calculate_intelligent_radius(radius_km::double precision), radius_km::double precision);
    
    -- Extraire les coordonnées GPS si fournies
    IF user_gps_zone IS NOT NULL AND user_gps_zone != '' AND user_gps_zone != 'null' THEN
        -- Diviser par le séparateur "|" pour gérer les zones polygonales
        gps_parts := string_to_array(user_gps_zone, '|');
        
        -- Pour l'instant, utiliser le premier point comme centre de recherche
        IF array_length(gps_parts, 1) > 0 THEN
            -- Extraire lat,lng du premier point
            lat := split_part(gps_parts[1], ',', 1)::double precision;
            lng := split_part(gps_parts[1], ',', 2)::double precision;
            
            -- Recherche avec filtrage GPS et produits actifs
            RETURN QUERY
            WITH services_with_active_products AS (
                SELECT 
                    s.id,
                    s.data,
                    s.category,
                    s.gps,
                    s.is_active,
                    COALESCE(
                        get_best_gps_for_service(s.data),
                        s.gps,
                        '0,0'
                    ) as best_gps,
                    get_active_products(s.data, s.id) as active_products
                FROM services s
                WHERE s.is_active = TRUE
                    AND jsonb_array_length(get_active_products(s.data, s.id)) > 0
            ),
            scored_products AS (
                SELECT 
                    s.id as service_id,
                    COALESCE(
                        s.data->>'titre_service', 
                        s.data->'titre_service'->>'valeur', 
                        'Sans titre'
                    ) as titre_service,
                    COALESCE(
                        s.category, 
                        s.data->>'category', 
                        s.data->'category'->>'valeur',
                        'Non catégorisé'
                    ) as category,
                    s.best_gps as gps_coords,
                    CASE 
                        WHEN s.best_gps IS NOT NULL AND s.best_gps != '0,0' THEN
                            calculate_distance_km(user_gps_zone, s.best_gps)
                        ELSE 999999.0
                    END as distance_km,
                    -- Score basé principalement sur les PRODUITS
                    (
                        (
                            SELECT COALESCE(SUM(
                                CASE 
                                    WHEN product->>'nom' ILIKE '%' || search_query || '%' THEN 20.0
                                    WHEN product->>'name' ILIKE '%' || search_query || '%' THEN 20.0
                                    WHEN product->>'titre' ILIKE '%' || search_query || '%' THEN 18.0
                                    WHEN product->>'categorie' ILIKE '%' || search_query || '%' THEN 15.0
                                    WHEN product->>'description' ILIKE '%' || search_query || '%' THEN 12.0
                                    WHEN product->>'type' ILIKE '%' || search_query || '%' THEN 10.0
                                    WHEN product->>'marque' ILIKE '%' || search_query || '%' THEN 10.0
                                    ELSE 0.0
                                END
                            ), 0.0)
                            FROM jsonb_array_elements(s.active_products) AS product
                        ) +
                        CASE 
                            WHEN s.data->>'titre_service' ILIKE '%' || search_query || '%' THEN 5.0
                            ELSE 0.0
                        END
                    )::double precision as relevance_score,
                    CASE 
                        WHEN s.best_gps = get_best_gps_for_service(s.data) THEN 'produit_gps'
                        ELSE 'service_gps'
                    END as gps_source
                FROM services_with_active_products s
                WHERE 
                    CASE 
                        WHEN s.best_gps IS NOT NULL AND s.best_gps != '0,0' THEN
                            calculate_distance_km(user_gps_zone, s.best_gps) <= radius_adjusted
                        ELSE FALSE
                    END
                    AND (
                        search_query IS NULL 
                        OR search_query = ''
                        OR EXISTS (
                            SELECT 1
                            FROM jsonb_array_elements(s.active_products) AS product
                            WHERE 
                                product->>'nom' ILIKE '%' || search_query || '%'
                                OR product->>'name' ILIKE '%' || search_query || '%'
                                OR product->>'titre' ILIKE '%' || search_query || '%'
                                OR product->>'categorie' ILIKE '%' || search_query || '%'
                                OR product->>'description' ILIKE '%' || search_query || '%'
                        )
                        OR s.data::TEXT ILIKE '%' || search_query || '%'
                    )
            )
            SELECT 
                sp.service_id,
                sp.titre_service,
                sp.category,
                sp.gps_coords,
                sp.distance_km,
                sp.relevance_score,
                sp.gps_source
            FROM scored_products sp
            WHERE sp.relevance_score > 0
            ORDER BY 
                sp.relevance_score DESC,
                sp.distance_km ASC
            LIMIT max_results;
            
            RETURN;
        END IF;
    END IF;
    
    -- Si pas de GPS, faire une recherche textuelle sur produits actifs uniquement
    RETURN QUERY
    WITH services_with_active_products AS (
        SELECT 
            s.id,
            s.data,
            s.category,
            s.gps,
            get_active_products(s.data, s.id) as active_products
        FROM services s
        WHERE s.is_active = TRUE
            AND jsonb_array_length(get_active_products(s.data, s.id)) > 0
    )
    SELECT 
        s.id as service_id,
        COALESCE(
            s.data->>'titre_service', 
            s.data->'titre_service'->>'valeur', 
            'Sans titre'
        ) as titre_service,
        COALESCE(
            s.category, 
            s.data->>'category', 
            s.data->'category'->>'valeur',
            'Non catégorisé'
        ) as category,
        COALESCE(
            get_best_gps_for_service(s.data),
            s.gps,
            '0,0'
        ) as gps_coords,
        0.0 as distance_km,
        (
            (
                SELECT COALESCE(SUM(
                    CASE 
                        WHEN product->>'nom' ILIKE '%' || search_query || '%' THEN 20.0
                        WHEN product->>'name' ILIKE '%' || search_query || '%' THEN 20.0
                        WHEN product->>'titre' ILIKE '%' || search_query || '%' THEN 18.0
                        WHEN product->>'categorie' ILIKE '%' || search_query || '%' THEN 15.0
                        WHEN product->>'description' ILIKE '%' || search_query || '%' THEN 12.0
                        WHEN product->>'type' ILIKE '%' || search_query || '%' THEN 10.0
                        WHEN product->>'marque' ILIKE '%' || search_query || '%' THEN 10.0
                        ELSE 0.0
                    END
                ), 0.0)
                FROM jsonb_array_elements(s.active_products) AS product
            ) +
            CASE 
                WHEN s.data->>'titre_service' ILIKE '%' || search_query || '%' THEN 5.0
                ELSE 0.0
            END
        )::double precision as relevance_score,
        'no_gps' as gps_source
    FROM services_with_active_products s
    WHERE 
        search_query IS NULL 
        OR search_query = ''
        OR EXISTS (
            SELECT 1
            FROM jsonb_array_elements(s.active_products) AS product
            WHERE 
                product->>'nom' ILIKE '%' || search_query || '%'
                OR product->>'name' ILIKE '%' || search_query || '%'
                OR product->>'titre' ILIKE '%' || search_query || '%'
                OR product->>'categorie' ILIKE '%' || search_query || '%'
                OR product->>'description' ILIKE '%' || search_query || '%'
        )
        OR s.data::TEXT ILIKE '%' || search_query || '%'
    ORDER BY relevance_score DESC
    LIMIT max_results;
END;
$$ LANGUAGE plpgsql STABLE;

-- 3. Commentaire pour documentation
COMMENT ON FUNCTION search_services_gps_final IS 'Recherche dans les PRODUITS actifs (via products_lifecycle), pas dans les services. Retourne uniquement les services qui ont au moins un produit actif correspondant à la recherche. Signature corrigée le 2025-11-26 pour correspondre exactement au code Rust.';



-- ============================================
-- Migration: 20251126_fix_services_user_id_created_at_index.sql
-- ============================================
-- Migration pour optimiser les requêtes sur services par user_id et created_at
-- Problème: Requête lente (>1s) sur SELECT ... FROM services WHERE user_id = $1 ORDER BY created_at DESC
-- Solution: Index composite sur (user_id, created_at DESC)

CREATE INDEX IF NOT EXISTS idx_services_user_id_created_at_desc 
ON services(user_id, created_at DESC) 
WHERE is_active = TRUE;

-- Index supplémentaire pour les requêtes avec filtre is_active
CREATE INDEX IF NOT EXISTS idx_services_user_id_is_active_created_at 
ON services(user_id, is_active, created_at DESC);

COMMENT ON INDEX idx_services_user_id_created_at_desc IS 'Optimise les requêtes de liste de services par utilisateur triées par date de création';
COMMENT ON INDEX idx_services_user_id_is_active_created_at IS 'Optimise les requêtes de liste de services actifs par utilisateur';



-- ============================================
-- Migration: 20251126_optimize_search_indexes.sql
-- ============================================
-- Migration: Optimisation des index pour recherche de produits
-- Date: 2025-11-26
-- Description: Crée des index sur les colonnes fréquemment recherchées pour améliorer
--              les performances des requêtes de recherche (réduction de 2-4s à <500ms)
-- Compatible: SQLx offline mode

-- ============================================
-- 1. INDEX POUR RECHERCHE DANS SERVICES.DATA
-- ============================================

-- Index GIN pour recherche full-text dans data JSONB (titre_service, description, category)
-- Utilisé par les requêtes ILIKE sur data->>'titre_service', etc.
CREATE INDEX IF NOT EXISTS idx_services_data_search_gin 
ON services USING GIN (data jsonb_path_ops)
WHERE is_active = true;

-- Index partiel pour recherche dans titre_service (le plus fréquent)
-- Utilise une expression pour extraire directement titre_service->>'valeur'
CREATE INDEX IF NOT EXISTS idx_services_titre_service_search 
ON services ((COALESCE(data->>'titre_service', data->'titre_service'->>'valeur')))
WHERE is_active = true 
  AND (data->>'titre_service' IS NOT NULL OR data->'titre_service'->>'valeur' IS NOT NULL);

-- Index partiel pour recherche dans category
CREATE INDEX IF NOT EXISTS idx_services_category_search 
ON services ((COALESCE(category, data->>'category', data->'category'->>'valeur')))
WHERE is_active = true;

-- ============================================
-- 2. INDEX POUR RECHERCHE DANS PRODUITS (JSONB)
-- ============================================

-- Index GIN pour recherche dans les produits (array JSONB)
-- Permet des recherches rapides dans product->>'nom', product->>'categorie', etc.
-- Note: PostgreSQL supporte les index GIN sur JSONB arrays
CREATE INDEX IF NOT EXISTS idx_services_produits_gin 
ON services USING GIN ((data->'produits'))
WHERE is_active = true 
  AND (jsonb_typeof(data->'produits') = 'array' OR jsonb_typeof(data->'produits'->'valeur') = 'array');

-- ✅ CORRIGÉ: Index pour recherche spécifique dans nom_produit (le plus fréquent)
-- Note: PostgreSQL ne permet pas de sous-requête SELECT dans un index
-- On utilise un index GIN sur le champ produits directement (déjà créé ci-dessus)
-- Cet index sera utilisé pour les recherches dans les noms de produits via jsonb_path_ops

-- ============================================
-- 3. INDEX POUR AUTOCOMPLETE_CHARACTERISTICS
-- ============================================

-- Index GIN pour characteristic_vector (array TEXT)
-- Utilisé pour les recherches vectorielles dans les caractéristiques de produits
CREATE INDEX IF NOT EXISTS idx_autocomplete_characteristics_vector_gin 
ON autocomplete_characteristics USING GIN (characteristic_vector)
WHERE is_real_product = true;

-- Index GIN pour location_vector (array TEXT)
-- Utilisé pour les recherches de lieu dans les produits
CREATE INDEX IF NOT EXISTS idx_autocomplete_characteristics_location_gin 
ON autocomplete_characteristics USING GIN (location_vector)
WHERE is_real_product = true;

-- Index pour full_vector (array TEXT)
-- Utilisé pour les recherches complètes dans les vecteurs
CREATE INDEX IF NOT EXISTS idx_autocomplete_characteristics_full_vector_gin 
ON autocomplete_characteristics USING GIN (full_vector)
WHERE is_real_product = true;

-- Index composite pour recherche par service_id + identifiant_base
-- Améliore les jointures avec services
CREATE INDEX IF NOT EXISTS idx_autocomplete_service_identifiant 
ON autocomplete_characteristics (service_id, identifiant_base)
WHERE is_real_product = true;

-- ============================================
-- 4. INDEX POUR RECHERCHE GPS
-- ============================================

-- Index pour recherche GPS (si la colonne gps est utilisée pour filtrage)
-- Note: Pour les calculs de distance, PostGIS est plus efficace, mais cet index
--       peut aider pour les recherches ILIKE sur gps
CREATE INDEX IF NOT EXISTS idx_services_gps_search 
ON services (gps)
WHERE is_active = true 
  AND gps IS NOT NULL 
  AND gps != '';

-- ============================================
-- 5. INDEX POUR PRODUCTS_LIFECYCLE
-- ============================================

-- Index composite pour vérifier rapidement si un produit est actif
-- Utilisé par get_active_products() dans search_services_gps_final
CREATE INDEX IF NOT EXISTS idx_products_lifecycle_active 
ON products_lifecycle (service_id, product_index, is_active)
WHERE is_active = true;

-- ============================================
-- 6. INDEX POUR RECHERCHE FULL-TEXT (tsvector)
-- ============================================

-- Index GIN pour recherche full-text sur titre_service
-- Utilisé par ts_rank() et plainto_tsquery() dans les requêtes
CREATE INDEX IF NOT EXISTS idx_services_titre_service_fts 
ON services USING GIN (to_tsvector('french', COALESCE(data->>'titre_service', data->'titre_service'->>'valeur', '')))
WHERE is_active = true;

-- Index GIN pour recherche full-text sur description
CREATE INDEX IF NOT EXISTS idx_services_description_fts 
ON services USING GIN (to_tsvector('french', COALESCE(data->>'description', data->'description'->>'valeur', '')))
WHERE is_active = true;

-- ❌ DÉSACTIVÉ: Index GIN pour recherche full-text avec unaccent (gestion accents)
-- NOTE: Cet index ne peut pas être créé car unaccent() n'est pas marqué IMMUTABLE par défaut
-- Pour l'activer, il faudrait créer une fonction wrapper IMMUTABLE:
-- CREATE OR REPLACE FUNCTION unaccent_immutable(text) RETURNS text AS $$
--   SELECT unaccent('unaccent', $1);
-- $$ LANGUAGE sql IMMUTABLE;
-- Puis utiliser unaccent_immutable() dans l'index.
-- Pour l'instant, l'index idx_services_titre_service_fts (sans unaccent) suffit.
