-- ============================================
-- Migration: 20251127_agency_departure_schedules.sql
-- ============================================
-- Migration: Système de gestion des horaires de départ par ville/agence
-- Date: 2025-11-27
-- Description: Permet aux agences de définir les horaires de départ disponibles pour chaque trajet

-- 1. Table pour les horaires de départ par agence/ville
CREATE TABLE IF NOT EXISTS agency_departure_schedules (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    agency_user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    departure_city TEXT NOT NULL,
    arrival_city TEXT NOT NULL,
    departure_times TIME[] NOT NULL, -- ["08:00", "14:00", "20:00"] - Horaires disponibles
    day_of_week INTEGER, -- 0=Dimanche, 1=Lundi, ..., 6=Samedi (NULL = tous les jours)
    is_active BOOLEAN DEFAULT TRUE,
    notes TEXT, -- Notes optionnelles (ex: "Horaires spéciaux fêtes")
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    -- Contrainte unique : une agence ne peut avoir qu'un seul horaire par trajet/jour
    UNIQUE(agency_user_id, departure_city, arrival_city, day_of_week)
);

-- 2. Index pour performances
CREATE INDEX IF NOT EXISTS idx_agency_schedules_route ON agency_departure_schedules(departure_city, arrival_city);
CREATE INDEX IF NOT EXISTS idx_agency_schedules_agency ON agency_departure_schedules(agency_user_id);
CREATE INDEX IF NOT EXISTS idx_agency_schedules_active ON agency_departure_schedules(is_active) WHERE is_active = TRUE;
CREATE INDEX IF NOT EXISTS idx_agency_schedules_day ON agency_departure_schedules(day_of_week) WHERE day_of_week IS NOT NULL;

-- 3. Fonction pour récupérer les horaires disponibles pour un trajet
CREATE OR REPLACE FUNCTION get_available_departure_times(
    p_agency_user_id INTEGER,
    p_departure_city TEXT,
    p_arrival_city TEXT,
    p_date DATE DEFAULT NULL -- Si NULL, retourne tous les horaires (tous jours)
)
RETURNS TABLE(
    departure_time TIME,
    day_of_week INTEGER,
    is_specific_day BOOLEAN
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        unnest(ads.departure_times) as departure_time,
        ads.day_of_week,
        (ads.day_of_week IS NOT NULL) as is_specific_day
    FROM agency_departure_schedules ads
    WHERE ads.agency_user_id = p_agency_user_id
        AND ads.departure_city = p_departure_city
        AND ads.arrival_city = p_arrival_city
        AND ads.is_active = TRUE
        AND (
            -- Si jour spécifique demandé, retourner uniquement ce jour
            (p_date IS NOT NULL AND ads.day_of_week = EXTRACT(DOW FROM p_date))
            -- Si horaire pour tous les jours
            OR ads.day_of_week IS NULL
            -- Si pas de date spécifiée, retourner tous les horaires
            OR p_date IS NULL
        )
    ORDER BY ads.day_of_week NULLS FIRST, departure_time;
END;
$$ LANGUAGE plpgsql;

-- 4. Fonction pour vérifier si un horaire existe pour un trajet
CREATE OR REPLACE FUNCTION check_departure_time_exists(
    p_agency_user_id INTEGER,
    p_departure_city TEXT,
    p_arrival_city TEXT,
    p_departure_time TIME,
    p_date DATE DEFAULT NULL
)
RETURNS BOOLEAN AS $$
DECLARE
    v_exists BOOLEAN;
BEGIN
    SELECT EXISTS(
        SELECT 1
        FROM agency_departure_schedules ads
        WHERE ads.agency_user_id = p_agency_user_id
            AND ads.departure_city = p_departure_city
            AND ads.arrival_city = p_arrival_city
            AND p_departure_time = ANY(ads.departure_times)
            AND ads.is_active = TRUE
            AND (
                (p_date IS NOT NULL AND ads.day_of_week = EXTRACT(DOW FROM p_date))
                OR ads.day_of_week IS NULL
                OR p_date IS NULL
            )
    ) INTO v_exists;
    
    RETURN v_exists;
END;
$$ LANGUAGE plpgsql;

-- 5. Trigger pour mettre à jour updated_at
CREATE OR REPLACE FUNCTION update_agency_schedules_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_update_agency_schedules_updated_at
    BEFORE UPDATE ON agency_departure_schedules
    FOR EACH ROW
    EXECUTE FUNCTION update_agency_schedules_updated_at();

-- 6. Commentaires
COMMENT ON TABLE agency_departure_schedules IS 'Horaires de départ disponibles par agence, ville et trajet. Permet de définir les heures de départ pour chaque trajet.';
COMMENT ON COLUMN agency_departure_schedules.departure_times IS 'Tableau des horaires disponibles (ex: ["08:00", "14:00", "20:00"])';
COMMENT ON COLUMN agency_departure_schedules.day_of_week IS 'Jour de la semaine (0=Dimanche, 1=Lundi, ..., 6=Samedi). NULL = tous les jours';
COMMENT ON FUNCTION get_available_departure_times IS 'Retourne les horaires disponibles pour un trajet donné, optionnellement filtrés par date';
COMMENT ON FUNCTION check_departure_time_exists IS 'Vérifie si un horaire spécifique existe pour un trajet donné';



-- ============================================
-- Migration: 20251127_blood_donation_matching_system.sql
-- ============================================
-- Migration: Système Intelligent de Matching Banque de Sang
-- Date: 2025-11-27
-- Description: Tables et fonctions pour matching intelligent donneurs/demandes avec GPS temps réel
-- Note: Compatible SQLx offline mode

-- ============================================================================
-- 1. TABLE : Groupes sanguins des utilisateurs
-- ============================================================================
CREATE TABLE IF NOT EXISTS user_blood_groups (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    groupe_sanguin VARCHAR(5) NOT NULL CHECK (groupe_sanguin IN ('O+', 'O-', 'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-')),
    is_available_for_donation BOOLEAN NOT NULL DEFAULT TRUE,
    last_donation_date DATE,
    next_donation_available_date DATE, -- Calculé: last_donation_date + 8 semaines
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    CONSTRAINT unique_user_blood_group UNIQUE (user_id, groupe_sanguin)
);

CREATE INDEX IF NOT EXISTS idx_user_blood_groups_user ON user_blood_groups(user_id);
CREATE INDEX IF NOT EXISTS idx_user_blood_groups_groupe ON user_blood_groups(groupe_sanguin);
CREATE INDEX IF NOT EXISTS idx_user_blood_groups_available ON user_blood_groups(is_available_for_donation) WHERE is_available_for_donation = TRUE;
CREATE INDEX IF NOT EXISTS idx_user_blood_groups_next_donation ON user_blood_groups(next_donation_available_date) WHERE next_donation_available_date IS NOT NULL;

-- ============================================================================
-- 2. TABLE : Demandes de don de sang
-- ============================================================================
CREATE TABLE IF NOT EXISTS blood_donation_requests (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    banque_sang_id INTEGER NOT NULL REFERENCES banques_sang(id) ON DELETE CASCADE,
    service_id INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE,
    requested_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    
    -- Groupe sanguin demandé
    groupe_sanguin_requis VARCHAR(5) NOT NULL CHECK (groupe_sanguin_requis IN ('O+', 'O-', 'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-')),
    quantite_requise INTEGER NOT NULL DEFAULT 1, -- Nombre de poches
    unite VARCHAR(20) DEFAULT 'poches',
    
    -- Urgence
    is_urgent BOOLEAN NOT NULL DEFAULT FALSE,
    urgence_level VARCHAR(20) DEFAULT 'normal' CHECK (urgence_level IN ('normal', 'urgent', 'critique')),
    deadline_date DATE, -- Date limite si urgente
    
    -- Position GPS au moment de la demande (CRITIQUE: pas stockée, capturée au moment de la demande)
    request_latitude DOUBLE PRECISION,
    request_longitude DOUBLE PRECISION,
    request_location_address TEXT, -- Adresse géocodée
    
    -- Statut
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'fulfilled', 'cancelled', 'expired')),
    fulfilled_at TIMESTAMPTZ,
    cancelled_at TIMESTAMPTZ,
    cancelled_reason TEXT,
    
    -- Notes
    notes TEXT,
    patient_name TEXT, -- Nom du patient si connu
    hospital_name TEXT, -- Nom de l'hôpital si applicable
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_blood_donation_requests_banque ON blood_donation_requests(banque_sang_id);
CREATE INDEX IF NOT EXISTS idx_blood_donation_requests_groupe ON blood_donation_requests(groupe_sanguin_requis);
CREATE INDEX IF NOT EXISTS idx_blood_donation_requests_status ON blood_donation_requests(status) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_blood_donation_requests_urgent ON blood_donation_requests(is_urgent) WHERE is_urgent = TRUE;
CREATE INDEX IF NOT EXISTS idx_blood_donation_requests_created ON blood_donation_requests(created_at DESC);

-- Index pour recherche géographique (si extension PostGIS disponible)
-- CREATE INDEX IF NOT EXISTS idx_blood_donation_requests_gps ON blood_donation_requests USING GIST(ST_Point(request_longitude, request_latitude));

-- ============================================================================
-- 3. TABLE : Matches donneurs/demandes
-- ============================================================================
CREATE TABLE IF NOT EXISTS blood_donation_matches (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    request_id TEXT NOT NULL REFERENCES blood_donation_requests(id) ON DELETE CASCADE,
    donor_user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    donor_blood_group_id INTEGER NOT NULL REFERENCES user_blood_groups(id) ON DELETE CASCADE,
    
    -- Position GPS du donneur au moment du match (CRITIQUE: temps réel)
    donor_latitude DOUBLE PRECISION,
    donor_longitude DOUBLE PRECISION,
    distance_km DOUBLE PRECISION, -- Distance calculée entre demande et donneur
    
    -- Statut du match
    match_status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (match_status IN ('pending', 'notified', 'accepted', 'declined', 'completed', 'expired')),
    notified_at TIMESTAMPTZ,
    notification_sent BOOLEAN NOT NULL DEFAULT FALSE,
    accepted_at TIMESTAMPTZ,
    declined_at TIMESTAMPTZ,
    declined_reason TEXT,
    completed_at TIMESTAMPTZ,
    
    -- Score de pertinence (pour tri)
    relevance_score DOUBLE PRECISION DEFAULT 0.0, -- Basé sur distance, disponibilité, historique
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT unique_request_donor_match UNIQUE (request_id, donor_user_id)
);

CREATE INDEX IF NOT EXISTS idx_blood_donation_matches_request ON blood_donation_matches(request_id);
CREATE INDEX IF NOT EXISTS idx_blood_donation_matches_donor ON blood_donation_matches(donor_user_id);
CREATE INDEX IF NOT EXISTS idx_blood_donation_matches_status ON blood_donation_matches(match_status) WHERE match_status IN ('pending', 'notified', 'accepted');
CREATE INDEX IF NOT EXISTS idx_blood_donation_matches_relevance ON blood_donation_matches(relevance_score DESC);
CREATE INDEX IF NOT EXISTS idx_blood_donation_matches_distance ON blood_donation_matches(distance_km) WHERE distance_km IS NOT NULL;

-- ============================================================================
-- 4. FONCTION : Trouver donneurs potentiels pour une demande
-- ============================================================================
CREATE OR REPLACE FUNCTION find_potential_blood_donors(
    p_request_id TEXT,
    p_groupe_sanguin_requis VARCHAR(5),
    p_request_lat DOUBLE PRECISION,
    p_request_lng DOUBLE PRECISION,
    p_max_distance_km DOUBLE PRECISION DEFAULT 50.0,
    p_max_results INTEGER DEFAULT 20
)
RETURNS JSONB AS $$
DECLARE
    v_compatible_groups VARCHAR(5)[];
    v_donor RECORD;
    v_distance_km DOUBLE PRECISION;
    v_relevance_score DOUBLE PRECISION;
    v_results JSONB := '[]'::jsonb;
    v_count INTEGER := 0;
BEGIN
    -- Déterminer les groupes sanguins compatibles
    -- Règles de compatibilité :
    -- O- peut donner à tous
    -- O+ peut donner à O+, A+, B+, AB+
    -- A- peut donner à A-, A+, AB-, AB+
    -- A+ peut donner à A+, AB+
    -- B- peut donner à B-, B+, AB-, AB+
    -- B+ peut donner à B+, AB+
    -- AB- peut donner à AB-, AB+
    -- AB+ peut donner à AB+ uniquement
    
    v_compatible_groups := CASE p_groupe_sanguin_requis
        WHEN 'O-' THEN ARRAY['O-']::VARCHAR(5)[]
        WHEN 'O+' THEN ARRAY['O-', 'O+']::VARCHAR(5)[]
        WHEN 'A-' THEN ARRAY['O-', 'A-']::VARCHAR(5)[]
        WHEN 'A+' THEN ARRAY['O-', 'O+', 'A-', 'A+']::VARCHAR(5)[]
        WHEN 'B-' THEN ARRAY['O-', 'B-']::VARCHAR(5)[]
        WHEN 'B+' THEN ARRAY['O-', 'O+', 'B-', 'B+']::VARCHAR(5)[]
        WHEN 'AB-' THEN ARRAY['O-', 'A-', 'B-', 'AB-']::VARCHAR(5)[]
        WHEN 'AB+' THEN ARRAY['O-', 'O+', 'A-', 'A+', 'B-', 'B+', 'AB-', 'AB+']::VARCHAR(5)[]
        ELSE ARRAY[]::VARCHAR(5)[]
    END;
    
    -- Trouver les donneurs compatibles disponibles
    -- ✅ Utilisation d'une CTE pour combiner user_blood_groups et users.groupe_sanguin
    FOR v_donor IN
        WITH combined_donors AS (
            -- 1. Chercher dans user_blood_groups (priorité)
            SELECT 
                ubg.id as blood_group_id,
                ubg.user_id,
                ubg.groupe_sanguin,
                ubg.is_available_for_donation,
                ubg.next_donation_available_date,
                u.gps,
                u.nom_complet,
                u.telephone,
                u.whatsapp,
                -- Extraire latitude/longitude du GPS si disponible
                CASE 
                    WHEN u.gps IS NOT NULL AND u.gps LIKE '%,%' THEN
                        SPLIT_PART(u.gps, ',', 1)::DOUBLE PRECISION
                    ELSE NULL
                END as donor_lat,
                CASE 
                    WHEN u.gps IS NOT NULL AND u.gps LIKE '%,%' THEN
                        SPLIT_PART(u.gps, ',', 2)::DOUBLE PRECISION
                    ELSE NULL
                END as donor_lng
            FROM user_blood_groups ubg
            JOIN users u ON u.id = ubg.user_id
            WHERE ubg.groupe_sanguin = ANY(v_compatible_groups)
                AND ubg.is_available_for_donation = TRUE
                AND (ubg.next_donation_available_date IS NULL OR ubg.next_donation_available_date <= CURRENT_DATE)
                AND u.is_active = TRUE
                -- Exclure les utilisateurs déjà matchés pour cette demande
                AND NOT EXISTS (
                    SELECT 1 FROM blood_donation_matches bdm
                    WHERE bdm.request_id = p_request_id
                        AND bdm.donor_user_id = ubg.user_id
                        AND bdm.match_status IN ('pending', 'notified', 'accepted')
                )
            UNION ALL
            -- ✅ NOUVEAU: Chercher aussi dans users.groupe_sanguin si pas d'entrée dans user_blood_groups
            SELECT 
                NULL::INTEGER as blood_group_id, -- Pas d'ID car pas dans user_blood_groups
                u.id as user_id,
                u.groupe_sanguin,
                TRUE as is_available_for_donation, -- Par défaut disponible
                NULL::DATE as next_donation_available_date,
                u.gps,
                u.nom_complet,
                u.telephone,
                u.whatsapp,
                CASE 
                    WHEN u.gps IS NOT NULL AND u.gps LIKE '%,%' THEN
                        SPLIT_PART(u.gps, ',', 1)::DOUBLE PRECISION
                    ELSE NULL
                END as donor_lat,
                CASE 
                    WHEN u.gps IS NOT NULL AND u.gps LIKE '%,%' THEN
                        SPLIT_PART(u.gps, ',', 2)::DOUBLE PRECISION
                    ELSE NULL
                END as donor_lng
            FROM users u
            WHERE u.groupe_sanguin = ANY(v_compatible_groups)
                AND u.is_active = TRUE
                -- Uniquement si pas d'entrée dans user_blood_groups
                AND NOT EXISTS (
                    SELECT 1 FROM user_blood_groups ubg2
                    WHERE ubg2.user_id = u.id
                )
                -- Exclure les utilisateurs déjà matchés pour cette demande
                AND NOT EXISTS (
                    SELECT 1 FROM blood_donation_matches bdm
                    WHERE bdm.request_id = p_request_id
                        AND bdm.donor_user_id = u.id
                        AND bdm.match_status IN ('pending', 'notified', 'accepted')
                )
        )
        SELECT * FROM combined_donors
        ORDER BY 
            -- Prioriser donneurs disponibles immédiatement
            CASE WHEN combined_donors.next_donation_available_date IS NULL OR combined_donors.next_donation_available_date <= CURRENT_DATE THEN 0 ELSE 1 END,
            -- Prioriser groupes exacts (même groupe)
            CASE WHEN combined_donors.groupe_sanguin = p_groupe_sanguin_requis THEN 0 ELSE 1 END
        LIMIT p_max_results
    LOOP
        -- Calculer distance si GPS disponible
        v_distance_km := NULL;
        IF p_request_lat IS NOT NULL AND p_request_lng IS NOT NULL 
           AND v_donor.donor_lat IS NOT NULL AND v_donor.donor_lng IS NOT NULL THEN
            -- Formule Haversine simplifiée (approximation)
            v_distance_km := (
                6371.0 * acos(
                    LEAST(1.0, 
                        sin(radians(p_request_lat)) * sin(radians(v_donor.donor_lat)) +
                        cos(radians(p_request_lat)) * cos(radians(v_donor.donor_lat)) *
                        cos(radians(p_request_lng - v_donor.donor_lng))
                    )
                )
            );
        END IF;
        
        -- Filtrer par distance maximale
        IF v_distance_km IS NULL OR v_distance_km <= p_max_distance_km THEN
            -- Calculer score de pertinence
            v_relevance_score := 100.0;
            
            -- Réduire score si distance élevée
            IF v_distance_km IS NOT NULL THEN
                v_relevance_score := v_relevance_score - (v_distance_km * 0.5);
            END IF;
            
            -- Bonus si groupe exact
            IF v_donor.groupe_sanguin = p_groupe_sanguin_requis THEN
                v_relevance_score := v_relevance_score + 20.0;
            END IF;
            
            -- Bonus si disponible immédiatement
            IF v_donor.next_donation_available_date IS NULL OR v_donor.next_donation_available_date <= CURRENT_DATE THEN
                v_relevance_score := v_relevance_score + 10.0;
            END IF;
            
                    -- ✅ NOUVEAU: Si blood_group_id est NULL, essayer de créer l'entrée dans user_blood_groups
            -- Note: On ne peut pas créer dans la boucle, on retourne NULL et on créera lors de la création du match
            -- Ajouter au résultat
            v_results := v_results || jsonb_build_object(
                'blood_group_id', v_donor.blood_group_id, -- Peut être NULL si vient de users.groupe_sanguin
                'user_id', v_donor.user_id,
                'groupe_sanguin', v_donor.groupe_sanguin,
                'nom_complet', v_donor.nom_complet,
                'telephone', v_donor.telephone,
                'whatsapp', v_donor.whatsapp,
                'donor_latitude', v_donor.donor_lat,
                'donor_longitude', v_donor.donor_lng,
                'distance_km', v_distance_km,
                'relevance_score', v_relevance_score,
                'is_available_now', (v_donor.next_donation_available_date IS NULL OR v_donor.next_donation_available_date <= CURRENT_DATE)
            );
            
            v_count := v_count + 1;
        END IF;
    END LOOP;
    
    RETURN jsonb_build_object(
        'success', TRUE,
        'count', v_count,
        'donors', v_results,
        'compatible_groups', v_compatible_groups
    );
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION find_potential_blood_donors IS 'Trouve les donneurs potentiels pour une demande de sang avec matching GPS et compatibilité groupes sanguins';

-- ============================================================================
-- 5. FONCTION : Créer une demande de don et trouver les matches
-- ============================================================================
CREATE OR REPLACE FUNCTION create_blood_donation_request(
    p_banque_sang_id INTEGER,
    p_service_id INTEGER,
    p_requested_by_user_id INTEGER,
    p_groupe_sanguin_requis VARCHAR(5),
    p_quantite_requise INTEGER DEFAULT 1,
    p_unite VARCHAR(20) DEFAULT 'poches',
    p_is_urgent BOOLEAN DEFAULT FALSE,
    p_urgence_level VARCHAR(20) DEFAULT 'normal',
    p_deadline_date DATE DEFAULT NULL,
    p_request_lat DOUBLE PRECISION DEFAULT NULL,
    p_request_lng DOUBLE PRECISION DEFAULT NULL,
    p_request_location_address TEXT DEFAULT NULL,
    p_notes TEXT DEFAULT NULL,
    p_patient_name TEXT DEFAULT NULL,
    p_hospital_name TEXT DEFAULT NULL,
    p_max_distance_km DOUBLE PRECISION DEFAULT 50.0
)
RETURNS JSONB AS $$
DECLARE
    v_request_id TEXT;
    v_matches JSONB;
    v_match_count INTEGER;
    v_match_item JSONB;
    v_blood_group_id INTEGER;
    v_user_id INTEGER;
    v_groupe_sanguin VARCHAR(5);
BEGIN
    -- Créer la demande
    INSERT INTO blood_donation_requests (
        banque_sang_id,
        service_id,
        requested_by_user_id,
        groupe_sanguin_requis,
        quantite_requise,
        unite,
        is_urgent,
        urgence_level,
        deadline_date,
        request_latitude,
        request_longitude,
        request_location_address,
        notes,
        patient_name,
        hospital_name,
        status
    ) VALUES (
        p_banque_sang_id,
        p_service_id,
        p_requested_by_user_id,
        p_groupe_sanguin_requis,
        p_quantite_requise,
        p_unite,
        p_is_urgent,
        p_urgence_level,
        p_deadline_date,
        p_request_lat,
        p_request_lng,
        p_request_location_address,
        p_notes,
        p_patient_name,
        p_hospital_name,
        'active'
    ) RETURNING id INTO v_request_id;
    
    -- Trouver les donneurs potentiels
    v_matches := find_potential_blood_donors(
        v_request_id,
        p_groupe_sanguin_requis,
        p_request_lat,
        p_request_lng,
        p_max_distance_km,
        50 -- Limite de résultats pour création de matches
    );
    
    v_match_count := (v_matches->>'count')::INTEGER;
    
    -- Créer les enregistrements de match
    IF v_match_count > 0 THEN
        FOR v_match_item IN SELECT * FROM jsonb_array_elements(v_matches->'donors')
        LOOP
            v_user_id := (v_match_item->>'user_id')::INTEGER;
            v_groupe_sanguin := v_match_item->>'groupe_sanguin';
            
            -- Si blood_group_id est NULL, créer une entrée dans user_blood_groups
            IF (v_match_item->>'blood_group_id') IS NULL OR (v_match_item->>'blood_group_id') = 'null' THEN
                INSERT INTO user_blood_groups (user_id, groupe_sanguin, is_available_for_donation, created_at, updated_at)
                VALUES (v_user_id, v_groupe_sanguin, TRUE, NOW(), NOW())
                ON CONFLICT (user_id, groupe_sanguin) DO UPDATE SET updated_at = NOW()
                RETURNING id INTO v_blood_group_id;
            ELSE
                v_blood_group_id := (v_match_item->>'blood_group_id')::INTEGER;
            END IF;
            
            -- Créer le match
            INSERT INTO blood_donation_matches (
                request_id,
                donor_user_id,
                donor_blood_group_id,
                donor_latitude,
                donor_longitude,
                distance_km,
                relevance_score,
                match_status
            ) VALUES (
                v_request_id,
                v_user_id,
                v_blood_group_id,
                (v_match_item->>'donor_latitude')::DOUBLE PRECISION,
                (v_match_item->>'donor_longitude')::DOUBLE PRECISION,
                (v_match_item->>'distance_km')::DOUBLE PRECISION,
                (v_match_item->>'relevance_score')::DOUBLE PRECISION,
                'pending'
            ) ON CONFLICT (request_id, donor_user_id) DO NOTHING;
        END LOOP;
    END IF;
    
    RETURN jsonb_build_object(
        'success', TRUE,
        'request_id', v_request_id,
        'matches_found', v_match_count,
        'message', format('Demande créée avec %s donneur(s) potentiel(s)', v_match_count)
    );
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION create_blood_donation_request IS 'Crée une demande de don de sang et trouve automatiquement les donneurs compatibles';

-- ============================================================================
-- 6. FONCTION : Mettre à jour le statut d'un match (accepté/refusé)
-- ============================================================================
CREATE OR REPLACE FUNCTION update_blood_donation_match_status(
    p_match_id TEXT,
    p_new_status VARCHAR(20),
    p_declined_reason TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
    v_match RECORD;
    v_request RECORD;
BEGIN
    -- Récupérer le match
    SELECT * INTO v_match FROM blood_donation_matches WHERE id = p_match_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Match non trouvé');
    END IF;
    
    -- Mettre à jour le statut
    UPDATE blood_donation_matches
    SET 
        match_status = p_new_status,
        declined_reason = p_declined_reason,
        notified_at = CASE WHEN p_new_status = 'notified' THEN NOW() ELSE notified_at END,
        accepted_at = CASE WHEN p_new_status = 'accepted' THEN NOW() ELSE accepted_at END,
        declined_at = CASE WHEN p_new_status = 'declined' THEN NOW() ELSE declined_at END,
        completed_at = CASE WHEN p_new_status = 'completed' THEN NOW() ELSE completed_at END,
        updated_at = NOW()
    WHERE id = p_match_id;
    
    -- Si accepté, vérifier si la demande est complète
    IF p_new_status = 'accepted' THEN
        SELECT * INTO v_request FROM blood_donation_requests WHERE id = v_match.request_id;
        
        -- Compter les matches acceptés
        IF EXISTS (
            SELECT 1 FROM blood_donation_matches
            WHERE request_id = v_match.request_id
                AND match_status = 'accepted'
            GROUP BY request_id
            HAVING COUNT(*) >= v_request.quantite_requise
        ) THEN
            -- Marquer la demande comme fulfilled
            UPDATE blood_donation_requests
            SET status = 'fulfilled', fulfilled_at = NOW(), updated_at = NOW()
            WHERE id = v_match.request_id;
        END IF;
    END IF;
    
    RETURN jsonb_build_object('success', TRUE, 'match_id', p_match_id, 'new_status', p_new_status);
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION update_blood_donation_match_status IS 'Met à jour le statut d''un match donneur/demande';

-- ============================================================================
-- 7. FONCTION : Mettre à jour date de dernier don (après don effectué)
-- ============================================================================
CREATE OR REPLACE FUNCTION update_donor_last_donation(
    p_user_id INTEGER,
    p_groupe_sanguin VARCHAR(5),
    p_donation_date DATE DEFAULT CURRENT_DATE
)
RETURNS JSONB AS $$
DECLARE
    v_next_available_date DATE;
BEGIN
    -- Calculer date prochaine disponibilité (8 semaines = 56 jours)
    v_next_available_date := p_donation_date + INTERVAL '56 days';
    
    -- Mettre à jour ou créer l'enregistrement
    INSERT INTO user_blood_groups (user_id, groupe_sanguin, last_donation_date, next_donation_available_date, is_available_for_donation, updated_at)
    VALUES (p_user_id, p_groupe_sanguin, p_donation_date, v_next_available_date, FALSE, NOW())
    ON CONFLICT (user_id, groupe_sanguin)
    DO UPDATE SET
        last_donation_date = p_donation_date,
        next_donation_available_date = v_next_available_date,
        is_available_for_donation = FALSE,
        updated_at = NOW();
    
    RETURN jsonb_build_object(
        'success', TRUE,
        'next_donation_available_date', v_next_available_date,
        'message', format('Prochain don possible le %s', v_next_available_date)
    );
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION update_donor_last_donation IS 'Met à jour la date de dernier don et calcule la prochaine disponibilité (8 semaines minimum)';

-- ============================================================================
-- 8. VUE : Demandes actives avec statistiques
-- ============================================================================
CREATE OR REPLACE VIEW blood_donation_requests_active AS
SELECT 
    bdr.id,
    bdr.banque_sang_id,
    bs.nom as banque_sang_nom,
    bdr.service_id,
    bdr.requested_by_user_id,
    bdr.groupe_sanguin_requis,
    bdr.quantite_requise,
    bdr.unite,
    bdr.is_urgent,
    bdr.urgence_level,
    bdr.deadline_date,
    bdr.request_latitude,
    bdr.request_longitude,
    bdr.request_location_address,
    bdr.status,
    bdr.patient_name,
    bdr.hospital_name,
    bdr.created_at,
    COUNT(DISTINCT CASE WHEN bdm.match_status IN ('pending', 'notified', 'accepted') THEN bdm.id END) as matches_count,
    COUNT(DISTINCT CASE WHEN bdm.match_status = 'accepted' THEN bdm.id END) as accepted_matches_count,
    COUNT(DISTINCT CASE WHEN bdm.match_status = 'notified' THEN bdm.id END) as notified_matches_count
FROM blood_donation_requests bdr
JOIN banques_sang bs ON bs.id = bdr.banque_sang_id
LEFT JOIN blood_donation_matches bdm ON bdm.request_id = bdr.id
WHERE bdr.status = 'active'
GROUP BY bdr.id, bs.nom;

COMMENT ON VIEW blood_donation_requests_active IS 'Vue des demandes actives avec statistiques de matches';



-- ============================================
-- Migration: 20251127_bus_manual_seat_blocks.sql
-- ============================================
-- Migration: Gestion manuelle des places non disponibles
-- Date: 2025-11-27
-- Description: Permet aux agences de bloquer/débloquer manuellement des places
-- Note: Compatible SQLx offline mode

-- 1. Table pour les blocages manuels de places
CREATE TABLE IF NOT EXISTS bus_seat_blocks (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    product_id TEXT NOT NULL,
    seat_id VARCHAR(50) NOT NULL,
    seat_number INTEGER NOT NULL,
    
    -- Raison du blocage
    reason VARCHAR(100) NOT NULL DEFAULT 'maintenance' CHECK (reason IN ('maintenance', 'damaged', 'reserved', 'other')),
    reason_details TEXT,
    
    -- Bloqué par
    blocked_by INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    blocked_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Débloqué
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    unblocked_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
    unblocked_at TIMESTAMPTZ
    
    -- Note: Contrainte unique partielle gérée via index unique (voir après CREATE TABLE)
);

-- 2. Index pour optimiser les requêtes
CREATE INDEX IF NOT EXISTS idx_bus_seat_blocks_product ON bus_seat_blocks(product_id);
CREATE INDEX IF NOT EXISTS idx_bus_seat_blocks_active ON bus_seat_blocks(is_active) WHERE is_active = TRUE;
CREATE INDEX IF NOT EXISTS idx_bus_seat_blocks_seat ON bus_seat_blocks(seat_id);

-- 2.1. Index unique partiel : une place ne peut être bloquée qu'une fois à la fois (actif uniquement)
CREATE UNIQUE INDEX IF NOT EXISTS idx_bus_seat_blocks_unique_active 
ON bus_seat_blocks(product_id, seat_id) 
WHERE is_active = TRUE;

-- 3. Fonction pour bloquer une place manuellement
CREATE OR REPLACE FUNCTION block_bus_seat_manually(
    p_product_id TEXT,
    p_seat_id VARCHAR(50),
    p_seat_number INTEGER,
    p_blocked_by INTEGER,
    p_reason VARCHAR(100) DEFAULT 'maintenance',
    p_reason_details TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
    v_block_id TEXT;
    v_existing_block RECORD;
BEGIN
    -- Vérifier si la place est déjà bloquée
    SELECT * INTO v_existing_block
    FROM bus_seat_blocks
    WHERE product_id = p_product_id
        AND seat_id = p_seat_id
        AND is_active = TRUE;
    
    IF FOUND THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Place déjà bloquée'
        );
    END IF;
    
    -- Vérifier si la place est réservée
    IF EXISTS (
        SELECT 1 FROM bus_reservations
        WHERE product_id = p_product_id
            AND seat_id = p_seat_id
            AND status IN ('pending', 'confirmed')
    ) THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Place déjà réservée, impossible de bloquer'
        );
    END IF;
    
    -- Créer le blocage
    INSERT INTO bus_seat_blocks (
        product_id,
        seat_id,
        seat_number,
        blocked_by,
        reason,
        reason_details
    )
    VALUES (
        p_product_id,
        p_seat_id,
        p_seat_number,
        p_blocked_by,
        p_reason,
        p_reason_details
    )
    RETURNING id INTO v_block_id;
    
    RETURN jsonb_build_object(
        'success', TRUE,
        'block_id', v_block_id,
        'message', 'Place bloquée avec succès'
    );
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION block_bus_seat_manually IS 'Bloque manuellement une place de bus (maintenance, endommagée, etc.)';

-- 4. Fonction pour débloquer une place
CREATE OR REPLACE FUNCTION unblock_bus_seat_manually(
    p_product_id TEXT,
    p_seat_id VARCHAR(50),
    p_unblocked_by INTEGER
)
RETURNS JSONB AS $$
DECLARE
    v_block RECORD;
BEGIN
    -- Récupérer le blocage actif
    SELECT * INTO v_block
    FROM bus_seat_blocks
    WHERE product_id = p_product_id
        AND seat_id = p_seat_id
        AND is_active = TRUE;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Aucun blocage actif trouvé pour cette place'
        );
    END IF;
    
    -- Désactiver le blocage
    UPDATE bus_seat_blocks
    SET 
        is_active = FALSE,
        unblocked_by = p_unblocked_by,
        unblocked_at = NOW()
    WHERE id = v_block.id;
    
    RETURN jsonb_build_object(
        'success', TRUE,
        'message', 'Place débloquée avec succès'
    );
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION unblock_bus_seat_manually IS 'Débloque une place de bus précédemment bloquée';

-- 5. Fonction pour obtenir la disponibilité avec blocages
CREATE OR REPLACE FUNCTION get_bus_seat_availability_with_blocks(p_product_id TEXT)
RETURNS JSONB AS $$
DECLARE
    v_product RECORD;
    v_seat_map JSONB;
    v_reserved_seats TEXT[];
    v_blocked_seats TEXT[];
    v_available_seats JSONB;
BEGIN
    -- Récupérer le produit
    SELECT 
        p.id,
        p.name,
        p.total_seats,
        p.seat_map,
        p.bus_configuration
    INTO v_product
    FROM products p
    WHERE p.id::text = p_product_id
        AND p.type = 'ticket_voyage'
        AND p.is_active = TRUE;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Produit non trouvé');
    END IF;
    
    -- Récupérer les places réservées
    SELECT ARRAY_AGG(br.seat_id)
    INTO v_reserved_seats
    FROM bus_reservations br
    WHERE br.product_id = p_product_id
        AND br.status IN ('pending', 'confirmed')
        AND (br.expires_at IS NULL OR br.expires_at > NOW());
    
    -- Récupérer les places bloquées
    SELECT ARRAY_AGG(bsb.seat_id)
    INTO v_blocked_seats
    FROM bus_seat_blocks bsb
    WHERE bsb.product_id = p_product_id
        AND bsb.is_active = TRUE;
    
    -- Construire le seat_map avec statuts
    IF v_product.seat_map IS NULL THEN
        v_seat_map := jsonb_build_array();
    ELSE
        v_seat_map := v_product.seat_map;
    END IF;
    
    -- Mettre à jour les statuts dans le seat_map
    v_seat_map := (
        SELECT jsonb_agg(
            CASE 
                WHEN seat->>'seat_id' = ANY(v_blocked_seats) THEN
                    seat || jsonb_build_object('available', FALSE, 'status', 'blocked', 'blocked_reason', 'maintenance')
                WHEN seat->>'seat_id' = ANY(v_reserved_seats) THEN
                    seat || jsonb_build_object('available', FALSE, 'status', 'reserved')
                ELSE
                    seat || jsonb_build_object('available', TRUE, 'status', 'available')
            END
        )
        FROM jsonb_array_elements(v_seat_map) AS seat
    );
    
    v_available_seats := jsonb_build_object(
        'total_seats', v_product.total_seats,
        'reserved_count', COALESCE(array_length(v_reserved_seats, 1), 0),
        'blocked_count', COALESCE(array_length(v_blocked_seats, 1), 0),
        'available_count', GREATEST(0, 
            COALESCE(v_product.total_seats, 0) 
            - COALESCE(array_length(v_reserved_seats, 1), 0)
            - COALESCE(array_length(v_blocked_seats, 1), 0)
        ),
        'reserved_seats', COALESCE(to_jsonb(v_reserved_seats), '[]'::jsonb),
        'blocked_seats', COALESCE(to_jsonb(v_blocked_seats), '[]'::jsonb),
        'seats', v_seat_map
    );
    
    RETURN jsonb_build_object('success', TRUE, 'availability', v_available_seats);
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION get_bus_seat_availability_with_blocks IS 'Retourne la disponibilité des places en incluant les blocages manuels';

-- 6. Vue pour les blocages actifs avec détails
-- ✅ CORRIGÉ: Utilisation de LEFT JOIN pour éviter l'erreur si la table products n'existe pas
CREATE OR REPLACE VIEW bus_active_seat_blocks AS
SELECT 
    bsb.id,
    bsb.product_id,
    bsb.seat_id,
    bsb.seat_number,
    bsb.reason,
    bsb.reason_details,
    bsb.blocked_by,
    bsb.blocked_at,
    u.nom_complet as blocked_by_name,
    -- ✅ CORRIGÉ: Récupération des infos produit depuis services.data si products n'existe pas
    COALESCE(
        (SELECT data->>'name' FROM services WHERE id::text = bsb.product_id LIMIT 1),
        (SELECT data->'name'->>'valeur' FROM services WHERE id::text = bsb.product_id LIMIT 1),
        bsb.product_id
    ) as product_name,
    COALESCE(
        (SELECT data->>'numero_bus' FROM services WHERE id::text = bsb.product_id LIMIT 1),
        (SELECT data->'numero_bus'->>'valeur' FROM services WHERE id::text = bsb.product_id LIMIT 1),
        NULL
    ) as numero_bus
FROM bus_seat_blocks bsb
LEFT JOIN users u ON u.id = bsb.blocked_by
WHERE bsb.is_active = TRUE
ORDER BY bsb.blocked_at DESC;

COMMENT ON VIEW bus_active_seat_blocks IS 'Vue des blocages actifs de places avec informations détaillées';



-- ============================================
-- Migration: 20251127_bus_ticket_validation_system.sql
-- ============================================
-- Migration: Système de validation de tickets bus avec QR code
-- Date: 2025-11-27
-- Description: Table pour suivi embarquement, validation QR code, statuts
-- Note: Compatible SQLx offline mode

-- 1. Table pour le statut d'embarquement des passagers
CREATE TABLE IF NOT EXISTS bus_boarding_status (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    reservation_id TEXT NOT NULL REFERENCES bus_reservations(id) ON DELETE CASCADE,
    product_id TEXT NOT NULL,
    payment_id TEXT REFERENCES bus_ticket_payments(id) ON DELETE SET NULL,
    
    -- Statut embarquement
    boarding_status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (boarding_status IN ('pending', 'boarded', 'no_show', 'cancelled')),
    is_validated BOOLEAN NOT NULL DEFAULT FALSE,
    validated_at TIMESTAMPTZ,
    
    -- Validateur (chauffeur ou agent agence)
    validated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
    validation_method VARCHAR(20) CHECK (validation_method IN ('qr_code', 'manual', 'api')),
    
    -- Données QR code validé
    qr_code_data JSONB,
    
    -- Notes
    notes TEXT,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT unique_reservation_boarding UNIQUE (reservation_id)
);

-- 2. Index pour optimiser les requêtes
CREATE INDEX IF NOT EXISTS idx_bus_boarding_product ON bus_boarding_status(product_id);
CREATE INDEX IF NOT EXISTS idx_bus_boarding_reservation ON bus_boarding_status(reservation_id);
CREATE INDEX IF NOT EXISTS idx_bus_boarding_status ON bus_boarding_status(boarding_status);
CREATE INDEX IF NOT EXISTS idx_bus_boarding_validated ON bus_boarding_status(is_validated) WHERE is_validated = TRUE;
CREATE INDEX IF NOT EXISTS idx_bus_boarding_validated_by ON bus_boarding_status(validated_by);

-- 3. Fonction pour valider un ticket via QR code
CREATE OR REPLACE FUNCTION validate_bus_ticket(
    p_qr_code_data JSONB,
    p_validator_user_id INTEGER,
    p_product_id TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
    v_reservation_id TEXT;
    v_payment_id TEXT;
    v_product_id TEXT;
    v_reservation RECORD;
    v_payment RECORD;
    v_boarding_status RECORD;
    v_count INTEGER;
    v_is_valid BOOLEAN := FALSE;
    v_error_message TEXT;
BEGIN
    -- Extraire les données du QR code
    v_reservation_id := p_qr_code_data->>'id';
    v_payment_id := p_qr_code_data->>'payment_id';
    v_product_id := COALESCE(p_product_id, p_qr_code_data->>'product_id');
    
    IF v_reservation_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'ID réservation manquant dans QR code'
        );
    END IF;
    
    -- Vérifier que la réservation existe et est confirmée
    SELECT * INTO v_reservation
    FROM bus_reservations
    WHERE id = v_reservation_id
        AND status = 'confirmed';
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Réservation non trouvée ou non confirmée'
        );
    END IF;
    
    -- Vérifier que le produit correspond
    IF v_product_id IS NOT NULL AND v_reservation.product_id != v_product_id THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Ticket ne correspond pas à ce bus'
        );
    END IF;
    
    -- Vérifier que le paiement est complété
    IF v_payment_id IS NOT NULL THEN
        SELECT * INTO v_payment
        FROM bus_ticket_payments
        WHERE id = v_payment_id
            AND payment_status = 'completed';
        
        IF NOT FOUND THEN
            RETURN jsonb_build_object(
                'success', FALSE,
                'error', 'Paiement non trouvé ou non complété'
            );
        END IF;
    END IF;
    
    -- Vérifier si le ticket est déjà validé (par reservation_id OU payment_id)
    SELECT * INTO v_boarding_status
    FROM bus_boarding_status
    WHERE reservation_id = v_reservation_id
       OR (payment_id IS NOT NULL AND payment_id = v_payment_id AND is_validated = TRUE);
    
    IF FOUND AND v_boarding_status.is_validated = TRUE THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Ticket déjà utilisé - Ce ticket a déjà été validé et ne peut plus être utilisé',
            'already_boarded', TRUE,
            'boarded_at', v_boarding_status.validated_at,
            'validated_by_user_id', v_boarding_status.validated_by,
            'validation_method', v_boarding_status.validation_method
        );
    END IF;
    
    -- Vérification supplémentaire : s'assurer qu'aucun autre boarding_status n'existe avec le même payment_id
    IF v_payment_id IS NOT NULL THEN
        SELECT COUNT(*) INTO v_count
        FROM bus_boarding_status
        WHERE payment_id = v_payment_id AND is_validated = TRUE;
        
        IF v_count > 0 THEN
            RETURN jsonb_build_object(
                'success', FALSE,
                'error', 'Ticket déjà utilisé - Ce paiement a déjà été validé pour un autre passager',
                'already_boarded', TRUE
            );
        END IF;
    END IF;
    
    -- ⚠️ PROTECTION RACE CONDITION : Créer ou mettre à jour le statut d'embarquement
    -- La contrainte UNIQUE sur reservation_id empêche les doublons au niveau base de données
    
    IF FOUND THEN
        -- Si un boarding_status existe déjà, vérifier s'il est validé
        IF v_boarding_status.is_validated = TRUE THEN
            RETURN jsonb_build_object(
                'success', FALSE,
                'error', 'Ticket déjà utilisé - Ce ticket a déjà été validé et ne peut plus être utilisé',
                'already_boarded', TRUE,
                'boarded_at', v_boarding_status.validated_at,
                'validated_by_user_id', v_boarding_status.validated_by,
                'validation_method', v_boarding_status.validation_method
            );
        END IF;
        
        -- Si pas encore validé, mettre à jour (cas rare mais possible)
        UPDATE bus_boarding_status
        SET boarding_status = 'boarded', is_validated = TRUE, validated_at = NOW(),
            validated_by = p_validator_user_id, validation_method = 'qr_code',
            qr_code_data = p_qr_code_data, updated_at = NOW()
        WHERE reservation_id = v_reservation_id AND is_validated = FALSE
        RETURNING * INTO v_boarding_status;
        
        -- Si aucune ligne mise à jour (déjà validé entre temps), erreur
        IF NOT FOUND THEN
            SELECT * INTO v_boarding_status FROM bus_boarding_status 
            WHERE reservation_id = v_reservation_id;
            
            IF v_boarding_status.is_validated = TRUE THEN
                RETURN jsonb_build_object(
                    'success', FALSE,
                    'error', 'Ticket déjà utilisé - Ce ticket a déjà été validé et ne peut plus être utilisé',
                    'already_boarded', TRUE,
                    'boarded_at', v_boarding_status.validated_at,
                    'validated_by_user_id', v_boarding_status.validated_by,
                    'validation_method', v_boarding_status.validation_method
                );
            END IF;
        END IF;
    ELSE
        -- Créer nouveau boarding_status (avec protection UNIQUE au niveau DB)
        BEGIN
            INSERT INTO bus_boarding_status (
                reservation_id, product_id, payment_id, boarding_status, is_validated,
                validated_at, validated_by, validation_method, qr_code_data
            ) VALUES (
                v_reservation_id, v_reservation.product_id, v_payment_id, 'boarded', TRUE,
                NOW(), p_validator_user_id, 'qr_code', p_qr_code_data
            ) RETURNING * INTO v_boarding_status;
        EXCEPTION
            WHEN unique_violation THEN
                -- Si insertion échoue (doublon), récupérer l'enregistrement existant
                SELECT * INTO v_boarding_status FROM bus_boarding_status 
                WHERE reservation_id = v_reservation_id;
                
                IF v_boarding_status.is_validated = TRUE THEN
                    RETURN jsonb_build_object(
                        'success', FALSE,
                        'error', 'Ticket déjà utilisé - Ce ticket a déjà été validé et ne peut plus être utilisé',
                        'already_boarded', TRUE,
                        'boarded_at', v_boarding_status.validated_at,
                        'validated_by_user_id', v_boarding_status.validated_by,
                        'validation_method', v_boarding_status.validation_method
                    );
                END IF;
        END;
    END IF;
    
    RETURN jsonb_build_object(
        'success', TRUE,
        'reservation_id', v_reservation_id,
        'passenger_name', v_reservation.passenger_name,
        'seat_id', v_reservation.seat_id,
        'seat_number', v_reservation.seat_number,
        'validated_at', v_boarding_status.validated_at,
        'message', 'Ticket validé avec succès'
    );
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION validate_bus_ticket IS 'Valide un ticket bus via QR code et enregistre l''embarquement';

-- 4. Fonction pour obtenir le résumé d'embarquement d'un bus
CREATE OR REPLACE FUNCTION get_bus_boarding_summary(p_product_id TEXT)
RETURNS JSONB AS $$
DECLARE
    v_total_reservations INTEGER := 0;
    v_boarded_passengers INTEGER := 0;
    v_pending_passengers INTEGER := 0;
    v_no_show_passengers INTEGER := 0;
BEGIN
    -- Compter total réservations confirmées
    SELECT COUNT(*) INTO v_total_reservations
    FROM bus_reservations
    WHERE product_id = p_product_id
        AND status = 'confirmed';
    
    -- Compter passagers embarqués
    SELECT COUNT(*) INTO v_boarded_passengers
    FROM bus_boarding_status
    WHERE product_id = p_product_id
        AND boarding_status = 'boarded'
        AND is_validated = TRUE;
    
    -- Compter en attente
    SELECT COUNT(*) INTO v_pending_passengers
    FROM bus_reservations br
    WHERE br.product_id = p_product_id
        AND br.status = 'confirmed'
        AND NOT EXISTS (
            SELECT 1 FROM bus_boarding_status bbs
            WHERE bbs.reservation_id = br.id
            AND bbs.is_validated = TRUE
        );
    
    -- Compter no-show (après heure départ + 15 min)
    SELECT COUNT(*) INTO v_no_show_passengers
    FROM bus_reservations br
    JOIN products p ON p.id::text = br.product_id
    WHERE br.product_id = p_product_id
        AND br.status = 'confirmed'
        AND (p.metadata->>'departure_date' || ' ' || p.metadata->>'departure_time')::TIMESTAMP + INTERVAL '15 minutes' < NOW()
        AND NOT EXISTS (
            SELECT 1 FROM bus_boarding_status bbs
            WHERE bbs.reservation_id = br.id
            AND bbs.is_validated = TRUE
        );
    
    RETURN jsonb_build_object(
        'total_reservations', v_total_reservations,
        'boarded_passengers', v_boarded_passengers,
        'pending_passengers', v_pending_passengers,
        'no_show_passengers', v_no_show_passengers,
        'completion_percentage', CASE 
            WHEN v_total_reservations > 0 THEN 
                ROUND((v_boarded_passengers::FLOAT / v_total_reservations::FLOAT) * 100, 2)
            ELSE 0
        END,
        'is_complete', (v_boarded_passengers = v_total_reservations AND v_total_reservations > 0)
    );
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION get_bus_boarding_summary IS 'Retourne le résumé d''embarquement pour un bus (total, embarqués, en attente, no-show)';

-- 5. Vue pour liste des passagers avec statut embarquement
CREATE OR REPLACE VIEW bus_passengers_with_boarding AS
SELECT 
    br.id as reservation_id,
    br.product_id,
    br.user_id,
    br.seat_id,
    br.seat_number,
    br.passenger_name,
    br.status as reservation_status,
    btp.id as payment_id,
    btp.total_amount,
    bbs.id as boarding_status_id,
    bbs.boarding_status,
    bbs.is_validated,
    bbs.validated_at,
    bbs.validated_by,
    bbs.validation_method,
    u.nom_complet as validator_name,
    CASE 
        WHEN bbs.is_validated = TRUE THEN 'boarded'
        WHEN bbs.boarding_status = 'no_show' THEN 'no_show'
        WHEN bbs.boarding_status = 'cancelled' THEN 'cancelled'
        ELSE 'pending'
    END as display_status
FROM bus_reservations br
LEFT JOIN bus_ticket_payments btp ON btp.id = ANY(
    SELECT unnest(btp2.reservation_ids) FROM bus_ticket_payments btp2 
    WHERE br.id = ANY(btp2.reservation_ids)
    LIMIT 1
)
LEFT JOIN bus_boarding_status bbs ON bbs.reservation_id = br.id
LEFT JOIN users u ON u.id = bbs.validated_by
WHERE br.status = 'confirmed';

COMMENT ON VIEW bus_passengers_with_boarding IS 'Vue unifiée des passagers avec leur statut d''embarquement';



