-- ============================================
-- Migration: Créer table pour banques de sang (service spécialisé isolé)
-- Date: 2025-11-27
-- Description: Table dédiée pour banques de sang avec gestion des groupes sanguins et stocks
--              Détection intelligente pour recherche spécialisée
-- Note: Compatible avec SQLx offline mode

-- ============================================================================
-- BANQUE DE SANG 🩸
-- ============================================================================

-- Table banques_sang
CREATE TABLE IF NOT EXISTS banques_sang (
    id SERIAL PRIMARY KEY,
    service_id INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    
    -- Lien avec établissement (optionnel, peut être indépendant)
    hopital_id INTEGER REFERENCES hopitaux_cliniques(id) ON DELETE SET NULL,
    
    -- Informations de base
    nom VARCHAR(255) NOT NULL,
    adresse TEXT,
    quartier VARCHAR(255),
    ville VARCHAR(255),
    gps VARCHAR(255), -- Format: "lat,lng"
    
    -- Groupes sanguins disponibles avec stocks
    stocks_groupes_sanguins JSONB NOT NULL DEFAULT '{}',
    -- Format: {
    --   "O+": {"quantite": 50, "unite": "poches", "derniere_maj": "2025-11-27T10:00:00Z"},
    --   "O-": {"quantite": 30, "unite": "poches", "derniere_maj": "2025-11-27T09:00:00Z"},
    --   "A+": {...}, "A-": {...}, "B+": {...}, "B-": {...}, "AB+": {...}, "AB-": {...}
    -- }
    
    -- Services
    accepte_dons BOOLEAN DEFAULT TRUE,
    accepte_demandes BOOLEAN DEFAULT TRUE,
    urgence_24h BOOLEAN DEFAULT FALSE,
    
    -- Planification
    planning_hebdomadaire JSONB,
    -- Format: {
    --   "lundi": {"ouvert": true, "debut": "08:00", "fin": "17:00", "permanent": false},
    --   ...
    -- }
    horaires_dons TIME[], -- ["08:00", "17:00"] - Horaires pour les dons
    
    -- Contact
    telephone VARCHAR(50),
    telephone_urgence VARCHAR(50),
    whatsapp VARCHAR(50),
    email VARCHAR(255),
    
    -- Statut
    is_active BOOLEAN DEFAULT TRUE,
    is_available_now BOOLEAN DEFAULT FALSE, -- Calculé automatiquement avec NOW()
    
    -- Métadonnées
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    CONSTRAINT unique_banque_service UNIQUE(service_id)
);

-- Index pour banques_sang
CREATE INDEX IF NOT EXISTS idx_banques_sang_user_id ON banques_sang(user_id);
CREATE INDEX IF NOT EXISTS idx_banques_sang_service_id ON banques_sang(service_id);
CREATE INDEX IF NOT EXISTS idx_banques_sang_hopital_id ON banques_sang(hopital_id);
CREATE INDEX IF NOT EXISTS idx_banques_sang_is_active ON banques_sang(is_active);
CREATE INDEX IF NOT EXISTS idx_banques_sang_is_available ON banques_sang(is_available_now) WHERE is_available_now = TRUE;
CREATE INDEX IF NOT EXISTS idx_banques_sang_urgence_24h ON banques_sang(urgence_24h) WHERE urgence_24h = TRUE;
CREATE INDEX IF NOT EXISTS idx_banques_sang_accepte_dons ON banques_sang(accepte_dons) WHERE accepte_dons = TRUE;
CREATE INDEX IF NOT EXISTS idx_banques_sang_accepte_demandes ON banques_sang(accepte_demandes) WHERE accepte_demandes = TRUE;
CREATE INDEX IF NOT EXISTS idx_banques_sang_stocks_gin ON banques_sang USING GIN(stocks_groupes_sanguins);
CREATE INDEX IF NOT EXISTS idx_banques_sang_planning_gin ON banques_sang USING GIN(planning_hebdomadaire);
CREATE INDEX IF NOT EXISTS idx_banques_sang_ville ON banques_sang(ville);
CREATE INDEX IF NOT EXISTS idx_banques_sang_quartier ON banques_sang(quartier);

-- Index GPS (GIST pour recherche géographique)
-- Note: Utilisation d'une fonction IMMUTABLE pour éviter l'erreur dans l'index
CREATE OR REPLACE FUNCTION parse_gps_to_point(gps_text TEXT)
RETURNS geography AS $$
BEGIN
    IF gps_text IS NULL OR gps_text = '' THEN
        RETURN NULL;
    END IF;
    RETURN ST_SetSRID(ST_MakePoint(
        SPLIT_PART(gps_text, ',', 2)::DOUBLE PRECISION,
        SPLIT_PART(gps_text, ',', 1)::DOUBLE PRECISION
    ), 4326)::geography;
EXCEPTION
    WHEN OTHERS THEN
        RETURN NULL;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE INDEX IF NOT EXISTS idx_banques_sang_gps ON banques_sang USING GIST(
    parse_gps_to_point(gps)
) WHERE gps IS NOT NULL AND gps != '';

-- Trigger pour updated_at
CREATE TRIGGER update_banques_sang_updated_at 
    BEFORE UPDATE ON banques_sang 
    FOR EACH ROW 
    EXECUTE FUNCTION update_timestamp();

-- Commentaires
COMMENT ON TABLE banques_sang IS 'Banques de sang avec gestion des groupes sanguins, stocks et disponibilité en temps réel';
COMMENT ON COLUMN banques_sang.hopital_id IS 'Lien optionnel avec un établissement de santé (peut être indépendant)';
COMMENT ON COLUMN banques_sang.stocks_groupes_sanguins IS 'Stocks par groupe sanguin avec quantités et dates de mise à jour (JSONB)';
COMMENT ON COLUMN banques_sang.is_available_now IS 'Calculé automatiquement avec planning_hebdomadaire et NOW()';
COMMENT ON COLUMN banques_sang.horaires_dons IS 'Horaires spécifiques pour les dons de sang (peut différer des horaires généraux)';

-- ============================================================================
-- SUPPRESSION banque_sang de hopitaux_cliniques
-- ============================================================================

-- Supprimer la colonne banque_sang de hopitaux_cliniques
-- (Si un hôpital a une banque de sang, il doit créer un service spécialisé dédié)
ALTER TABLE hopitaux_cliniques DROP COLUMN IF EXISTS banque_sang;



-- ============================================
-- Migration: 20251127_create_token_consumption_and_purchase_history.sql
-- ============================================
-- Migration pour créer les tables token_consumption_logs et purchase_history
-- Ces tables sont utilisées pour suivre la consommation de tokens et l'historique des paiements

-- Table token_consumption_logs : Historique des consommations de tokens
CREATE TABLE IF NOT EXISTS token_consumption_logs (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    service_name TEXT,
    amount_consumed BIGINT NOT NULL DEFAULT 0,
    description TEXT,
    metadata JSONB
);

-- Index pour améliorer les performances des requêtes
CREATE INDEX IF NOT EXISTS idx_token_consumption_logs_user_id ON token_consumption_logs(user_id);
CREATE INDEX IF NOT EXISTS idx_token_consumption_logs_created_at ON token_consumption_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_token_consumption_logs_user_created ON token_consumption_logs(user_id, created_at DESC);

-- Table purchase_history : Historique des achats/recharges de tokens
CREATE TABLE IF NOT EXISTS purchase_history (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    amount_paid BIGINT NOT NULL DEFAULT 0,
    tokens_received BIGINT NOT NULL DEFAULT 0,
    payment_method TEXT,
    status TEXT NOT NULL DEFAULT 'pending',
    transaction_id TEXT,
    metadata JSONB
);

-- Index pour améliorer les performances des requêtes
CREATE INDEX IF NOT EXISTS idx_purchase_history_user_id ON purchase_history(user_id);
CREATE INDEX IF NOT EXISTS idx_purchase_history_created_at ON purchase_history(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_purchase_history_user_created ON purchase_history(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_purchase_history_status ON purchase_history(status);
CREATE INDEX IF NOT EXISTS idx_purchase_history_transaction_id ON purchase_history(transaction_id) WHERE transaction_id IS NOT NULL;

-- Commentaires pour documentation
COMMENT ON TABLE token_consumption_logs IS 'Historique des consommations de tokens par utilisateur';
COMMENT ON COLUMN token_consumption_logs.service_name IS 'Nom du service qui a consommé les tokens';
COMMENT ON COLUMN token_consumption_logs.amount_consumed IS 'Nombre de tokens consommés';
COMMENT ON COLUMN token_consumption_logs.metadata IS 'Métadonnées supplémentaires (JSON)';

COMMENT ON TABLE purchase_history IS 'Historique des achats et recharges de tokens';
COMMENT ON COLUMN purchase_history.amount_paid IS 'Montant payé en FCFA';
COMMENT ON COLUMN purchase_history.tokens_received IS 'Nombre de tokens reçus';
COMMENT ON COLUMN purchase_history.payment_method IS 'Méthode de paiement (mobile_money, credit_card, etc.)';
COMMENT ON COLUMN purchase_history.status IS 'Statut de la transaction (pending, completed, failed, cancelled)';
COMMENT ON COLUMN purchase_history.transaction_id IS 'ID de transaction unique';
COMMENT ON COLUMN purchase_history.metadata IS 'Métadonnées supplémentaires (JSON)';



-- ============================================
-- Migration: 20251127_improve_return_trip_matching_with_time.sql
-- ============================================
-- Migration: Amélioration du matching retour avec prise en compte de l'heure
-- Date: 2025-11-27
-- Description: Modifie la fonction match_return_trip_requests pour inclure le matching par heure de retour

-- ✅ CORRIGÉ: DROP la fonction avant de la recréer si le type de retour change
DROP FUNCTION IF EXISTS match_return_trip_requests(TEXT);

-- Fonction améliorée pour matcher automatiquement les demandes de retour avec prise en compte de l'heure
CREATE OR REPLACE FUNCTION match_return_trip_requests(p_product_id TEXT)
RETURNS TABLE(
    request_id TEXT,
    user_id INTEGER,
    passenger_names TEXT[],
    number_of_seats INTEGER,
    preferred_return_time TEXT
) AS $$
BEGIN
    -- Trouver les demandes de retour correspondantes
    -- Quand un nouveau bus est créé, on check s'il match des demandes
    RETURN QUERY
    SELECT 
        rtr.id as request_id,
        rtr.user_id,
        rtr.passenger_names,
        rtr.number_of_seats,
        rtr.preferred_return_time
    FROM return_trip_requests rtr
    JOIN products p ON p.id::text = p_product_id
    JOIN services s ON s.id = p.service_id
    LEFT JOIN bus_ticket_payments btp_outbound ON btp_outbound.id = rtr.outbound_payment_id
    WHERE rtr.status = 'pending'
        -- ✅ CRITIQUE: Match agence (le bus retour doit appartenir à la même agence que le bus aller)
        AND (
            -- Si outbound_payment_id existe, vérifier que l'agence du bus retour = agence du bus aller
            rtr.outbound_payment_id IS NULL
            OR btp_outbound.agency_user_id = s.user_id
        )
        -- Match route (inverse du voyage)
        AND rtr.return_from = p.depart
        AND rtr.return_to = p.destination
        -- Match date (avec flexibilité)
        AND p.date_depart BETWEEN 
            (rtr.preferred_return_date::date - INTERVAL '1 day' * rtr.date_flexibility_days)
            AND (rtr.preferred_return_date::date + INTERVAL '1 day' * rtr.date_flexibility_days)
        -- ✅ NOUVEAU: Match heure (si spécifiée, avec tolérance ±1h)
        AND (
            -- Si aucune heure préférée n'est spécifiée, on accepte tous les horaires
            rtr.preferred_return_time IS NULL 
            -- Si le bus n'a pas d'heure dans metadata, on accepte
            OR p.metadata->>'departure_time' IS NULL
            -- Sinon, on vérifie que l'heure du bus est dans la tolérance (±1h)
            OR ABS(
                EXTRACT(EPOCH FROM (
                    (p.metadata->>'departure_time')::TIME - rtr.preferred_return_time::TIME
                ))
            ) / 3600 <= 1  -- Tolérance de 1 heure (3600 secondes)
        )
        -- Vérifier qu'il y a assez de places
        AND p.total_seats >= rtr.number_of_seats;
END;
$$ LANGUAGE plpgsql;

-- Commentaire
COMMENT ON FUNCTION match_return_trip_requests IS 'Match les demandes de retour avec les nouveaux bus créés. Prend en compte la route, la date (avec flexibilité) et l''heure (tolérance ±1h)';



