    IF NOT EXISTS (
        SELECT 1 FROM pg_indexes 
        WHERE tablename = 'services' 
        AND indexname = 'idx_services_category_tsvector'
    ) THEN
        CREATE INDEX idx_services_category_tsvector 
        ON services USING GIN (
            to_tsvector('french', 
