                END
            ))
        ) WHERE is_active = true;
        RAISE NOTICE 'Index idx_services_products_tsvector créé';
    ELSE
        RAISE NOTICE 'Index idx_services_products_tsvector existe déjà, ignoré';
    END IF;
END $$;

