                    COALESCE((
                        SELECT MAX(
                            CASE 
                                WHEN LOWER(extract_all_product_text(product)) = LOWER(search_query) THEN 25.0
                                WHEN LOWER(extract_all_product_text(product)) LIKE LOWER(search_query) || '%' THEN 18.0
                                WHEN LOWER(COALESCE(product->>'nom', '')) = LOWER(search_query) THEN 20.0
                                WHEN product->>'nom' ILIKE '%' || search_query || '%' THEN 12.0
                                WHEN product->>'categorie' ILIKE '%' || search_query || '%' THEN 10.0
                                WHEN product->>'description' ILIKE '%' || search_query || '%' THEN 8.0
                                WHEN extract_all_product_text(product) ILIKE '%' || search_query || '%' THEN 6.0
                                ELSE 0.0
                            END
                        )
                        FROM jsonb_array_elements(ape.products_array) AS product
                        WHERE (
                            extract_all_product_text(product) ILIKE '%' || search_query || '%'
                            OR product->>'nom' ILIKE '%' || search_query || '%'
                            OR product->>'categorie' ILIKE '%' || search_query || '%'
                            OR product->>'description' ILIKE '%' || search_query || '%'
                        )
                    ), 0.0),
                    -- Score basé sur correspondance dans champs service (pour services sans produits)
                    CASE 
                        WHEN COALESCE(ape.service_data->>'titre_service', ape.service_data->'titre_service'->>'valeur', '') ILIKE '%' || search_query || '%' THEN 10.0
                        WHEN COALESCE(ape.service_data->>'description', ape.service_data->'description'->>'valeur', '') ILIKE '%' || search_query || '%' THEN 5.0
                        WHEN COALESCE(ape.service_data->>'category', ape.service_data->'category'->>'valeur', ape.category, '') ILIKE '%' || search_query || '%' THEN 8.0
                        ELSE 0.0
                    END
                )::DOUBLE PRECISION as relevance_score
            FROM all_products_extracted ape
            WHERE (
                -- ✅ Recherche dans les PRODUITS (GÉNÉRIQUE - tous champs)
                EXISTS (
                    SELECT 1 
                    FROM jsonb_array_elements(ape.products_array) AS product
                    WHERE (
                        extract_all_product_text(product) ILIKE '%' || search_query || '%'
                        OR product->>'nom' ILIKE '%' || search_query || '%'
                        OR product->>'categorie' ILIKE '%' || search_query || '%'
                        OR product->>'description' ILIKE '%' || search_query || '%'
                    )
                )
                -- ✅ OU recherche dans les champs service (pour services sans produits)
                OR COALESCE(ape.service_data->>'titre_service', ape.service_data->'titre_service'->>'valeur', '') ILIKE '%' || search_query || '%'
                OR COALESCE(ape.service_data->>'description', ape.service_data->'description'->>'valeur', '') ILIKE '%' || search_query || '%'
                OR COALESCE(ape.service_data->>'category', ape.service_data->'category'->>'valeur', ape.category, '') ILIKE '%' || search_query || '%'
            )
        )
        SELECT 
            pm.service_id::INTEGER,
            COALESCE(
                pm.service_data->>'titre_service',
                pm.service_data->'titre_service'->>'valeur',
                pm.service_data->>'titre',
                'Sans titre'
            )::TEXT as titre_service,
            COALESCE(
                pm.service_data->>'category',
                pm.service_data->'category'->>'valeur',
                pm.category,
                'Non catégorisé'
            )::TEXT as category,
            COALESCE(
                pm.gps,
                pm.service_data->>'gps_fixe',
                pm.service_data->'gps_fixe'->>'valeur',
                ''
            )::TEXT as gps_coords,
            CASE 
                WHEN pm.gps IS NOT NULL AND pm.gps != '' AND position(',' in pm.gps) > 0 THEN
                    calculate_gps_distance_km(
                        lat, lng,
                        split_part(pm.gps, ',', 1)::DOUBLE PRECISION,
                        split_part(pm.gps, ',', 2)::DOUBLE PRECISION
                    )
                WHEN pm.service_data->>'gps_fixe' IS NOT NULL AND position(',' in (pm.service_data->>'gps_fixe')) > 0 THEN
                    calculate_gps_distance_km(
                        lat, lng,
                        split_part(pm.service_data->>'gps_fixe', ',', 1)::DOUBLE PRECISION,
                        split_part(pm.service_data->>'gps_fixe', ',', 2)::DOUBLE PRECISION
                    )
                ELSE NULL
            END::DOUBLE PRECISION as distance_km,
            pm.relevance_score,
            CASE 
                WHEN pm.gps IS NOT NULL AND pm.gps != '' THEN 'gps_column'::TEXT
                WHEN pm.service_data->>'gps_fixe' IS NOT NULL THEN 'gps_fixe'::TEXT
                ELSE 'no_gps'::TEXT
            END as gps_source
        FROM products_matched pm
        WHERE pm.relevance_score > 0
        AND (
            -- Filtre par distance GPS
            CASE 
                WHEN pm.gps IS NOT NULL AND position(',' in pm.gps) > 0 THEN
                    calculate_gps_distance_km(
                        lat, lng,
                        split_part(pm.gps, ',', 1)::DOUBLE PRECISION,
                        split_part(pm.gps, ',', 2)::DOUBLE PRECISION
                    ) <= radius_adjusted
                WHEN pm.service_data->>'gps_fixe' IS NOT NULL AND position(',' in (pm.service_data->>'gps_fixe')) > 0 THEN
                    calculate_gps_distance_km(
                        lat, lng,
                        split_part(pm.service_data->>'gps_fixe', ',', 1)::DOUBLE PRECISION,
                        split_part(pm.service_data->>'gps_fixe', ',', 2)::DOUBLE PRECISION
                    ) <= radius_adjusted
                ELSE false
            END
        )
        ORDER BY pm.relevance_score DESC, distance_km ASC NULLS LAST
        LIMIT max_results;
        
        RETURN;
    END IF;
    
    -- Fallback si pas de GPS : recherche sans GPS (même logique mais sans filtrage distance)
    RETURN QUERY
    WITH all_products_extracted AS (
        SELECT 
            s.id as service_id,
            s.data as service_data,
            s.created_at,
            s.user_id,
            s.gps,
            s.category,
            CASE 
                WHEN jsonb_typeof(s.data->'produits') = 'array' 
                THEN s.data->'produits'
                WHEN jsonb_typeof(s.data->'produits'->'valeur') = 'array'
                THEN s.data->'produits'->'valeur'
                ELSE '[]'::jsonb
            END as products_array
        FROM services s
        WHERE s.is_active = true
    ),
    products_matched AS (
        SELECT DISTINCT
            ape.service_id,
            ape.service_data,
            ape.created_at,
            ape.user_id,
            ape.gps,
            ape.category,
            GREATEST(
                COALESCE((
                    SELECT MAX(
                        CASE 
                            WHEN LOWER(extract_all_product_text(product)) = LOWER(search_query) THEN 25.0
                            WHEN LOWER(extract_all_product_text(product)) LIKE LOWER(search_query) || '%' THEN 18.0
                            WHEN LOWER(COALESCE(product->>'nom', '')) = LOWER(search_query) THEN 20.0
                            WHEN product->>'nom' ILIKE '%' || search_query || '%' THEN 12.0
                            WHEN product->>'categorie' ILIKE '%' || search_query || '%' THEN 10.0
                            WHEN product->>'description' ILIKE '%' || search_query || '%' THEN 8.0
                            WHEN extract_all_product_text(product) ILIKE '%' || search_query || '%' THEN 6.0
                            ELSE 0.0
                        END
                    )
                    FROM jsonb_array_elements(ape.products_array) AS product
                    WHERE (
                        extract_all_product_text(product) ILIKE '%' || search_query || '%'
                        OR product->>'nom' ILIKE '%' || search_query || '%'
                        OR product->>'categorie' ILIKE '%' || search_query || '%'
                        OR product->>'description' ILIKE '%' || search_query || '%'
                    )
                ), 0.0),
                CASE 
                    WHEN COALESCE(ape.service_data->>'titre_service', ape.service_data->'titre_service'->>'valeur', '') ILIKE '%' || search_query || '%' THEN 10.0
                    WHEN COALESCE(ape.service_data->>'description', ape.service_data->'description'->>'valeur', '') ILIKE '%' || search_query || '%' THEN 5.0
                    WHEN COALESCE(ape.service_data->>'category', ape.service_data->'category'->>'valeur', ape.category, '') ILIKE '%' || search_query || '%' THEN 8.0
                    ELSE 0.0
                END
            )::DOUBLE PRECISION as relevance_score
        FROM all_products_extracted ape
        WHERE (
            EXISTS (
                SELECT 1 
                FROM jsonb_array_elements(ape.products_array) AS product
                WHERE (
                    extract_all_product_text(product) ILIKE '%' || search_query || '%'
                    OR product->>'nom' ILIKE '%' || search_query || '%'
                    OR product->>'categorie' ILIKE '%' || search_query || '%'
                    OR product->>'description' ILIKE '%' || search_query || '%'
                )
            )
            OR COALESCE(ape.service_data->>'titre_service', ape.service_data->'titre_service'->>'valeur', '') ILIKE '%' || search_query || '%'
            OR COALESCE(ape.service_data->>'description', ape.service_data->'description'->>'valeur', '') ILIKE '%' || search_query || '%'
            OR COALESCE(ape.service_data->>'category', ape.service_data->'category'->>'valeur', ape.category, '') ILIKE '%' || search_query || '%'
        )
    )
    SELECT 
        pm.service_id::INTEGER,
        COALESCE(
            pm.service_data->>'titre_service',
            pm.service_data->'titre_service'->>'valeur',
            pm.service_data->>'titre',
            'Sans titre'
        )::TEXT as titre_service,
        COALESCE(
            pm.service_data->>'category',
            pm.service_data->'category'->>'valeur',
            pm.category,
            'Non catégorisé'
        )::TEXT as category,
        COALESCE(
            pm.gps,
            pm.service_data->>'gps_fixe',
            pm.service_data->'gps_fixe'->>'valeur',
            ''
        )::TEXT as gps_coords,
        0.0::DOUBLE PRECISION as distance_km,
        pm.relevance_score,
        CASE 
            WHEN pm.gps IS NOT NULL AND pm.gps != '' THEN 'gps_column'::TEXT
            WHEN pm.service_data->>'gps_fixe' IS NOT NULL THEN 'gps_fixe'::TEXT
            ELSE 'no_gps'::TEXT
        END as gps_source
    FROM products_matched pm
    WHERE pm.relevance_score > 0
    ORDER BY pm.relevance_score DESC, pm.created_at DESC
    LIMIT max_results;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION search_services_gps_final(TEXT, TEXT, INTEGER, INTEGER) IS 
'Recherche de services avec filtrage GPS et recherche dans les produits (GÉNÉRIQUE). Extrait TOUS les produits AVANT de filtrer, utilise extract_all_product_text() pour rechercher dans TOUS les champs du produit. Retourne exactement 7 colonnes: service_id, titre_service, category, gps_coords, distance_km, relevance_score, gps_source';



-- ============================================
-- Migration: 20251130_001_FIX_SEARCH_GPS_FINAL_SIGNATURE.sql
-- ============================================
-- Migration: FIX DÉFINITIF - Signature search_services_gps_final
-- Date: 2025-11-30
-- Description: Fixe définitivement la signature de search_services_gps_final
--              pour correspondre exactement à ce que le code Rust attend
--              (user_gps_zone avec DEFAULT NULL)
--              + Optimisation : Ordre COALESCE aligné avec les index
-- 
-- ⚠️ IMPORTANT: Cette migration doit être la dernière à modifier cette fonction
-- ⚠️ Les migrations futures NE DOIVENT PAS modifier search_services_gps_final
--    sauf pour corriger des bugs de logique interne

-- 1. SUPPRIMER TOUTES LES VERSIONS EXISTANTES
-- ============================================================
DROP FUNCTION IF EXISTS search_services_gps_final(text, text, integer, integer);
DROP FUNCTION IF EXISTS search_services_gps_final(text, text, integer);
DROP FUNCTION IF EXISTS search_services_gps_final(text, text);
DROP FUNCTION IF EXISTS search_services_gps_final(text);
DROP FUNCTION IF EXISTS search_services_gps_final();

-- 2. CRÉER LA FONCTION AVEC LA SIGNATURE CORRECTE
-- ============================================================
-- Le code Rust appelle: search_services_gps_final($1, $2, $3, $4)
-- Où $2 (gps_zone) peut être NULL
-- DONC: user_gps_zone DOIT avoir DEFAULT NULL

CREATE OR REPLACE FUNCTION search_services_gps_final(
    search_query text,
    user_gps_zone text DEFAULT NULL,  -- ✅ OBLIGATOIRE: DEFAULT NULL pour compatibilité Rust
    search_radius_km integer DEFAULT 50,
    max_results integer DEFAULT 20
)
RETURNS TABLE(
    service_id integer,
    titre_service text,
    category text,
    gps_coords text,
    distance_km double precision,
    relevance_score double precision,
    gps_source text
) 
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    gps_parts text[];
    lat double precision;
    lng double precision;
    radius_adjusted double precision;
BEGIN
    -- Ajuster le rayon (utiliser fonction helper si elle existe, sinon valeur directe)
    BEGIN
        radius_adjusted := COALESCE(calculate_intelligent_radius(search_radius_km::double precision), search_radius_km::double precision);
    EXCEPTION WHEN OTHERS THEN
        radius_adjusted := search_radius_km::double precision;
    END;

    -- CAS 1: Recherche AVEC zone GPS
    IF user_gps_zone IS NOT NULL AND user_gps_zone != '' AND user_gps_zone != 'null' THEN
        -- Extraire les coordonnées GPS
        gps_parts := string_to_array(user_gps_zone, '|');
        
        IF array_length(gps_parts, 1) > 0 THEN
            BEGIN
                lat := split_part(gps_parts[1], ',', 1)::double precision;
                lng := split_part(gps_parts[1], ',', 2)::double precision;
            EXCEPTION WHEN OTHERS THEN
                -- Si parsing échoue, faire recherche sans GPS
                lat := NULL;
                lng := NULL;
            END;

            IF lat IS NOT NULL AND lng IS NOT NULL THEN
                -- Recherche avec GPS - version simplifiée utilisant les index existants
                RETURN QUERY
                SELECT DISTINCT ON (s.id)
                    s.id::integer AS service_id,
                    COALESCE(s.data->'titre_service'->>'valeur', s.data->>'titre_service', '')::text AS titre_service,
                    COALESCE(s.category, s.data->'category'->>'valeur', '')::text AS category,
                    COALESCE(s.gps, '')::text AS gps_coords,
                    CASE 
                        WHEN s.gps IS NOT NULL AND s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$' THEN
                            (
                                6371 * acos(
                                    GREATEST(-1.0, LEAST(1.0,
                                        cos(radians(lat)) * 
                                        cos(radians(split_part(s.gps, ',', 1)::double precision)) *
                                        cos(radians(split_part(s.gps, ',', 2)::double precision) - radians(lng)) +
                                        sin(radians(lat)) *
                                        sin(radians(split_part(s.gps, ',', 1)::double precision))
                                    ))
                                )
                            )
                        ELSE NULL
                    END AS distance_km,
                    -- ✅ Ordre COALESCE aligné avec les index
                    GREATEST(
                        ts_rank(to_tsvector('french', COALESCE(s.data->>'titre_service', s.data->'titre_service'->>'valeur', '')), plainto_tsquery('french', search_query)) * 10.0,
                        ts_rank(to_tsvector('french', COALESCE(s.data->>'description', s.data->'description'->>'valeur', '')), plainto_tsquery('french', search_query)) * 5.0,
                        0.0
                    )::double precision AS relevance_score,
                    (CASE 
                        WHEN s.gps IS NOT NULL AND s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$' THEN 'service_gps'
                        ELSE 'no_gps'
                    END)::text AS gps_source
                FROM services s
                WHERE s.is_active = true
                AND (
                    -- ✅ Ordre COALESCE aligné avec les index existants (idx_services_titre_service_fts, idx_services_description_fts)
                    to_tsvector('french', COALESCE(s.data->>'titre_service', s.data->'titre_service'->>'valeur', '')) @@ plainto_tsquery('french', search_query)
                    OR to_tsvector('french', COALESCE(s.data->>'description', s.data->'description'->>'valeur', '')) @@ plainto_tsquery('french', search_query)
                )
                AND (
                    s.gps IS NULL OR
                    (
                        s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$' AND
                        (
                            6371 * acos(
                                GREATEST(-1.0, LEAST(1.0,
                                    cos(radians(lat)) * 
                                    cos(radians(split_part(s.gps, ',', 1)::double precision)) *
                                    cos(radians(split_part(s.gps, ',', 2)::double precision) - radians(lng)) +
                                    sin(radians(lat)) *
                                    sin(radians(split_part(s.gps, ',', 1)::double precision))
                                ))
                            )
                        ) <= radius_adjusted
                    )
                )
                ORDER BY s.id, relevance_score DESC
                LIMIT max_results;
                
                RETURN;
            END IF;
        END IF;
    END IF;

    -- CAS 2: Recherche SANS GPS (recherche textuelle pure)
    RETURN QUERY
    SELECT DISTINCT ON (s.id)
        s.id::integer AS service_id,
        COALESCE(s.data->'titre_service'->>'valeur', s.data->>'titre_service', '')::text AS titre_service,
        COALESCE(s.category, s.data->'category'->>'valeur', '')::text AS category,
        COALESCE(s.gps, '')::text AS gps_coords,
        NULL::double precision AS distance_km,
        -- ✅ Ordre COALESCE aligné avec les index
        GREATEST(
            ts_rank(to_tsvector('french', COALESCE(s.data->>'titre_service', s.data->'titre_service'->>'valeur', '')), plainto_tsquery('french', search_query)) * 10.0,
            ts_rank(to_tsvector('french', COALESCE(s.data->>'description', s.data->'description'->>'valeur', '')), plainto_tsquery('french', search_query)) * 5.0,
            0.0
        )::double precision AS relevance_score,
        ('text_search')::text AS gps_source
    FROM services s
    WHERE s.is_active = true
    AND (
        -- ✅ Ordre COALESCE aligné avec les index existants
        to_tsvector('french', COALESCE(s.data->>'titre_service', s.data->'titre_service'->>'valeur', '')) @@ plainto_tsquery('french', search_query)
        OR to_tsvector('french', COALESCE(s.data->>'description', s.data->'description'->>'valeur', '')) @@ plainto_tsquery('french', search_query)
    )
    ORDER BY s.id, relevance_score DESC
    LIMIT max_results;
END;
$$;

-- 3. FONCTION HELPER (crée seulement si elle n'existe pas déjà)
-- ============================================================
CREATE OR REPLACE FUNCTION calculate_intelligent_radius(requested_radius double precision)
RETURNS double precision
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
    RETURN COALESCE(requested_radius, 50.0);
END;
$$;

