-- ============================================
-- Migration: 20251201_add_missing_product_descriptions.sql
-- ============================================
-- Migration pour ajouter les descriptions manquantes dans services.data->'produits'
-- Date: 2025-12-01
-- Description: Extrait les descriptions depuis autocomplete_characteristics.full_vector
--              et les ajoute dans services.data->'produits'->valeur[0]->description

-- Fonction pour extraire la description depuis full_vector
-- La description est souvent le 3ème élément (après nom et catégorie) ou un élément long (> 50 caractères)
CREATE OR REPLACE FUNCTION extract_description_from_full_vector(full_vector TEXT[])
RETURNS TEXT AS $$
DECLARE
    desc_candidate TEXT;
BEGIN
    -- Chercher un élément long (> 50 caractères) après les 2 premiers (nom et catégorie)
    FOR desc_candidate IN 
        SELECT unnest(full_vector[3:]) -- À partir du 3ème élément
    LOOP
        IF LENGTH(desc_candidate) > 50 THEN
            RETURN desc_candidate;
        END IF;
    END LOOP;
    
    -- Si pas trouvé, prendre le 3ème élément s'il existe
    IF array_length(full_vector, 1) >= 3 THEN
        RETURN full_vector[3];
    END IF;
    
    RETURN NULL;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- Script de mise à jour
DO $$
DECLARE
    service_record RECORD;
    product_record RECORD;
    description_text TEXT;
    updated_count INTEGER := 0;
    service_data JSONB;
    produits_obj JSONB;
    valeur_array JSONB;
    first_product JSONB;
BEGIN
    RAISE NOTICE 'Début migration: Ajout descriptions manquantes dans services.data->produits';
    
    -- Parcourir tous les services actifs avec des produits
    FOR service_record IN
        SELECT 
            s.id as service_id,
            s.data as service_data
        FROM services s
        WHERE s.is_active = true
        AND s.data->'produits' IS NOT NULL
        AND jsonb_typeof(s.data->'produits') = 'object'
        AND s.data->'produits'->>'type_donnee' = 'listeproduit'
        AND s.data->'produits'->'valeur' IS NOT NULL
        AND jsonb_array_length(s.data->'produits'->'valeur') > 0
    LOOP
        service_data := service_record.service_data;
        produits_obj := service_data->'produits';
        valeur_array := produits_obj->'valeur';
        
        -- Vérifier le premier produit
        IF jsonb_array_length(valeur_array) > 0 THEN
            first_product := valeur_array->0;
            
            -- Vérifier si description manquante
            IF (first_product->>'description' IS NULL OR first_product->>'description' = '')
               AND (first_product->>'description_produit' IS NULL OR first_product->>'description_produit' = '') THEN
                
                -- Chercher la description dans autocomplete_characteristics.full_vector
                SELECT extract_description_from_full_vector(ac.full_vector)
                INTO description_text
                FROM autocomplete_characteristics ac
                WHERE ac.service_id = service_record.service_id
                AND ac.is_real_product = TRUE
                AND ac.identifiant_base = 'produits'
                AND ac.full_vector IS NOT NULL
                AND array_length(ac.full_vector, 1) >= 3
                ORDER BY ac.usage_count DESC NULLS LAST
                LIMIT 1;
                
                -- Si description trouvée, mettre à jour
                IF description_text IS NOT NULL AND LENGTH(description_text) > 10 THEN
                    -- Mettre à jour le premier produit
                    first_product := jsonb_set(
                        first_product,
                        '{description}',
                        to_jsonb(description_text)
                    );
                    
                    -- Mettre à jour valeur_array
                    valeur_array := jsonb_set(
                        valeur_array,
                        '{0}',
                        first_product
                    );
                    
                    -- Mettre à jour produits_obj
                    produits_obj := jsonb_set(
                        produits_obj,
                        '{valeur}',
                        valeur_array
                    );
                    
                    -- Mettre à jour service_data
                    service_data := jsonb_set(
                        service_data,
                        '{produits}',
                        produits_obj
                    );
                    
                    -- Sauvegarder dans la base
                    UPDATE services
                    SET data = service_data,
                        updated_at = NOW()
                    WHERE id = service_record.service_id;
                    
                    updated_count := updated_count + 1;
                    
                    IF updated_count % 100 = 0 THEN
                        RAISE NOTICE 'Services mis à jour: %', updated_count;
                    END IF;
                END IF;
            END IF;
        END IF;
    END LOOP;
    
    RAISE NOTICE 'Migration terminée: % services mis à jour avec description', updated_count;
END $$;

-- Nettoyer la fonction temporaire
DROP FUNCTION IF EXISTS extract_description_from_full_vector(TEXT[]);

-- Vérification
SELECT 
    COUNT(*) as total_services_avec_produits,
    COUNT(*) FILTER (
        WHERE data->'produits'->'valeur'->0->>'description' IS NOT NULL 
        AND data->'produits'->'valeur'->0->>'description' != ''
    ) as services_avec_description
FROM services
WHERE is_active = true
AND data->'produits' IS NOT NULL
AND jsonb_typeof(data->'produits') = 'object'
AND data->'produits'->>'type_donnee' = 'listeproduit'
AND jsonb_array_length(data->'produits'->'valeur') > 0;



-- ============================================
-- Migration: 20251201_fix_product_lifecycle_sync_trigger.sql
-- ============================================
-- Migration: Correction du trigger de synchronisation products_lifecycle
-- Date: 2025-12-01
-- Description: Corrige le trigger pour gérer les deux formats de stockage des produits
--              (array direct et array dans objet avec type_donnee)

-- 1. Corriger la fonction de synchronisation pour gérer les deux formats
CREATE OR REPLACE FUNCTION sync_product_on_service_update()
RETURNS TRIGGER AS $$
DECLARE
    product_record JSONB;
    product_idx INTEGER;
    produits_array JSONB;
BEGIN
    -- ✅ Détecter le format 1 : array direct (data->'produits' = array)
    IF jsonb_typeof(NEW.data->'produits') = 'array' THEN
        produits_array := NEW.data->'produits';
    -- ✅ Détecter le format 2 : array dans objet avec type_donnee (data->'produits'->'valeur' = array)
    ELSIF jsonb_typeof(NEW.data->'produits') = 'object' 
        AND jsonb_typeof(NEW.data->'produits'->'valeur') = 'array' THEN
        produits_array := NEW.data->'produits'->'valeur';
    ELSE
        -- Aucun produit à synchroniser
        RETURN NEW;
    END IF;
    
    -- Synchroniser tous les produits
    product_idx := 0;
    FOR product_record IN 
        SELECT * FROM jsonb_array_elements(produits_array)
    LOOP
        INSERT INTO products_lifecycle (
            service_id,
            product_index,
            product_nom,
            product_type,
            is_active,
            auto_deactivate_at
        ) VALUES (
            NEW.id,
            product_idx,
            COALESCE(
                product_record->>'nom', 
                product_record->>'name', 
                'Produit'
            ),
            COALESCE(product_record->>'type', 'autre'),
            TRUE,
            NOW() + INTERVAL '30 days'
        )
        ON CONFLICT (service_id, product_index) 
        DO UPDATE SET
            product_nom = EXCLUDED.product_nom,
            product_type = EXCLUDED.product_type,
            updated_at = NOW();
        
        product_idx := product_idx + 1;
    END LOOP;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 2. Corriger le trigger pour détecter les deux formats
DROP TRIGGER IF EXISTS trigger_sync_products ON services;
CREATE TRIGGER trigger_sync_products
    AFTER INSERT OR UPDATE ON services
    FOR EACH ROW
    WHEN (
        -- Format 1 : array direct
        jsonb_typeof(NEW.data->'produits') = 'array'
        OR 
        -- Format 2 : array dans objet
        (
            jsonb_typeof(NEW.data->'produits') = 'object' 
            AND jsonb_typeof(NEW.data->'produits'->'valeur') = 'array'
        )
    )
    EXECUTE FUNCTION sync_product_on_service_update();

-- 3. Corriger la fonction sync_products_to_lifecycle() pour gérer les deux formats
CREATE OR REPLACE FUNCTION sync_products_to_lifecycle()
RETURNS void AS $$
DECLARE
    service_record RECORD;
    product_record JSONB;
    product_idx INTEGER;
    produits_array JSONB;
BEGIN
    -- Itérer sur tous les services actifs avec des produits
    FOR service_record IN 
        SELECT id, data 
        FROM services 
        WHERE is_active = TRUE 
        AND (
            jsonb_typeof(data->'produits') = 'array'
            OR (
                jsonb_typeof(data->'produits') = 'object' 
                AND jsonb_typeof(data->'produits'->'valeur') = 'array'
            )
        )
    LOOP
        -- Détecter le format
        IF jsonb_typeof(service_record.data->'produits') = 'array' THEN
            produits_array := service_record.data->'produits';
        ELSIF jsonb_typeof(service_record.data->'produits') = 'object' 
            AND jsonb_typeof(service_record.data->'produits'->'valeur') = 'array' THEN
            produits_array := service_record.data->'produits'->'valeur';
        ELSE
            CONTINUE;
        END IF;
        
        product_idx := 0;
        
        -- Itérer sur chaque produit du service
        FOR product_record IN 
            SELECT * FROM jsonb_array_elements(produits_array)
        LOOP
            -- Insérer ou mettre à jour dans products_lifecycle
            INSERT INTO products_lifecycle (
                service_id,
                product_index,
                product_nom,
                product_type,
                is_active,
                created_at,
                auto_deactivate_at
            ) VALUES (
                service_record.id,
                product_idx,
                COALESCE(
                    product_record->>'nom', 
                    product_record->>'name', 
                    'Produit'
                ),
                COALESCE(product_record->>'type', 'autre'),
                TRUE,
                NOW(),
                NOW() + INTERVAL '30 days'
            )
            ON CONFLICT (service_id, product_index) 
            DO UPDATE SET
                product_nom = EXCLUDED.product_nom,
                product_type = EXCLUDED.product_type,
                updated_at = NOW();
            
            product_idx := product_idx + 1;
        END LOOP;
    END LOOP;
    
    RAISE NOTICE 'Synchronisation des produits terminée';
END;
$$ LANGUAGE plpgsql;

-- 4. Fonction pour synchroniser les produits manquants (services existants)
DROP FUNCTION IF EXISTS sync_missing_products();
CREATE FUNCTION sync_missing_products()
RETURNS TABLE(
    svc_id INTEGER,
    products_synced INTEGER
) AS $$
DECLARE
    service_record RECORD;
    product_record JSONB;
    product_idx INTEGER;
    produits_array JSONB;
    synced_count INTEGER;
BEGIN
    FOR service_record IN 
        SELECT id, data 
        FROM services 
        WHERE is_active = TRUE
    LOOP
        synced_count := 0;
        
        -- Détecter le format
        IF jsonb_typeof(service_record.data->'produits') = 'array' THEN
            produits_array := service_record.data->'produits';
        ELSIF jsonb_typeof(service_record.data->'produits') = 'object' 
            AND jsonb_typeof(service_record.data->'produits'->'valeur') = 'array' THEN
            produits_array := service_record.data->'produits'->'valeur';
        ELSE
            CONTINUE;
        END IF;
        
        -- Synchroniser chaque produit
        product_idx := 0;
        FOR product_record IN 
            SELECT * FROM jsonb_array_elements(produits_array)
        LOOP
            INSERT INTO products_lifecycle (
                service_id,
                product_index,
                product_nom,
                product_type,
                is_active,
                auto_deactivate_at
            ) VALUES (
                service_record.id,
                product_idx,
                COALESCE(
                    product_record->>'nom', 
                    product_record->>'name', 
                    'Produit'
                ),
                COALESCE(product_record->>'type', 'autre'),
                TRUE,
                NOW() + INTERVAL '30 days'
            )
            ON CONFLICT (service_id, product_index) 
            DO UPDATE SET
                product_nom = EXCLUDED.product_nom,
                product_type = EXCLUDED.product_type,
                updated_at = NOW();
            
            synced_count := synced_count + 1;
            product_idx := product_idx + 1;
        END LOOP;
        
        IF synced_count > 0 THEN
            svc_id := service_record.id;
            products_synced := synced_count;
            RETURN NEXT;
        END IF;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

-- 5. Exécuter la synchronisation des produits manquants
-- Note: Cette opération peut prendre du temps selon le nombre de services
DO $$
DECLARE
    result RECORD;
    total_services INTEGER := 0;
    total_products INTEGER := 0;
BEGIN
    RAISE NOTICE 'Début de la synchronisation des produits manquants...';
    
    FOR result IN 
        SELECT svc_id, products_synced FROM sync_missing_products()
    LOOP
        total_services := total_services + 1;
        total_products := total_products + result.products_synced;
    END LOOP;
    
    RAISE NOTICE 'Synchronisation terminée: % services, % produits synchronisés', 
        total_services, total_products;
END $$;

-- 6. Statistiques après synchronisation
SELECT 
    COUNT(DISTINCT service_id) as services_avec_produits,
    COUNT(*) as total_produits,
    SUM(CASE WHEN is_active THEN 1 ELSE 0 END) as produits_actifs,
    SUM(CASE WHEN NOT is_active THEN 1 ELSE 0 END) as produits_inactifs
FROM products_lifecycle;

