-- ✅ CORRIGÉ 2026-01-29: Vérifier et créer le type ENUM si nécessaire
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'delivery_engine_type') THEN
        CREATE TYPE delivery_engine_type AS ENUM (
            'moto',
            'scooter',
            'voiture',
