-- ✅ Créer la table videos si elle n'existe pas
CREATE TABLE IF NOT EXISTS videos (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    content_id TEXT NOT NULL UNIQUE,
    service_id INTEGER REFERENCES services(id) ON DELETE CASCADE,
    titre TEXT NOT NULL,
    description TEXT,
    video_url TEXT NOT NULL,
    thumbnail TEXT,
    hashtags TEXT[] DEFAULT ARRAY[]::TEXT[],
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    is_sponsored BOOLEAN NOT NULL DEFAULT FALSE,
    studio_session_id TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    -- Métadonnées vidéo
    duration_ms INTEGER,
    video_format TEXT,
    video_source TEXT,
    -- Embedding vectoriel pour ML (stocké en TEXT, pgvector non utilisé)
    embedding TEXT, -- JSON array ou base64 pour stockage temporaire
    -- Statistiques
    view_count INTEGER DEFAULT 0,
    like_count INTEGER DEFAULT 0,
    save_count INTEGER DEFAULT 0,
    share_count INTEGER DEFAULT 0
);

-- Index pour performance
CREATE INDEX IF NOT EXISTS idx_videos_service_id ON videos(service_id) WHERE service_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_videos_content_id ON videos(content_id);
CREATE INDEX IF NOT EXISTS idx_videos_is_active ON videos(is_active) WHERE is_active = TRUE;
CREATE INDEX IF NOT EXISTS idx_videos_created_at ON videos(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_videos_studio_session_id ON videos(studio_session_id) WHERE studio_session_id IS NOT NULL;

-- Index GIN pour hashtags (recherche rapide)
CREATE INDEX IF NOT EXISTS idx_videos_hashtags_gin ON videos USING GIN(hashtags);

-- Index pour recherche full-text sur titre et description
CREATE INDEX IF NOT EXISTS idx_videos_title_fulltext 
    ON videos USING GIN(to_tsvector('french', COALESCE(titre, '')));
CREATE INDEX IF NOT EXISTS idx_videos_description_fulltext 
    ON videos USING GIN(to_tsvector('french', COALESCE(description, '')));

-- Index pour embedding (stocké en TEXT, pas de pgvector)
CREATE INDEX IF NOT EXISTS idx_videos_embedding ON videos(embedding) WHERE embedding IS NOT NULL;

-- Trigger pour updated_at
CREATE OR REPLACE FUNCTION set_videos_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_videos_updated_at ON videos;
CREATE TRIGGER trg_videos_updated_at
    BEFORE UPDATE ON videos
    FOR EACH ROW
    EXECUTE FUNCTION set_videos_updated_at();

-- ✅ Fonction pour extraire automatiquement les hashtags depuis titre/description
CREATE OR REPLACE FUNCTION extract_hashtags_from_text(input_text TEXT)
RETURNS TEXT[] AS $$
DECLARE
    hashtags TEXT[];
BEGIN
    -- Extraire tous les mots commençant par # (hashtags)
    SELECT array_agg(DISTINCT LOWER(SUBSTRING(match, 2)))
    INTO hashtags
    FROM regexp_split_to_table(input_text, '\s+') AS match
    WHERE match ~ '^#[a-zA-Z0-9_]+$';
    
    RETURN COALESCE(hashtags, ARRAY[]::TEXT[]);
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- ✅ Trigger pour extraire automatiquement les hashtags
CREATE OR REPLACE FUNCTION auto_extract_video_hashtags()
RETURNS TRIGGER AS $$
BEGIN
    -- Extraire hashtags depuis titre et description
    NEW.hashtags = array_cat(
        COALESCE(NEW.hashtags, ARRAY[]::TEXT[]),
        extract_hashtags_from_text(COALESCE(NEW.titre, '') || ' ' || COALESCE(NEW.description, ''))
    );
    
    -- Supprimer doublons
    NEW.hashtags = array(SELECT DISTINCT unnest(NEW.hashtags));
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_auto_extract_video_hashtags ON videos;
CREATE TRIGGER trg_auto_extract_video_hashtags
    BEFORE INSERT OR UPDATE OF titre, description ON videos
    FOR EACH ROW
    EXECUTE FUNCTION auto_extract_video_hashtags();

-- ✅ Vue pour statistiques hashtags (pour tendances)
CREATE OR REPLACE VIEW hashtag_stats AS
SELECT 
    tag,
    COUNT(DISTINCT v.id) as video_count,
    SUM(v.view_count) as total_views,
    SUM(v.like_count) as total_likes,
    SUM(v.save_count) as total_saves,
    (
        SUM(v.like_count * 2 + v.save_count * 1.5 + v.view_count * 0.1) 
        / GREATEST(EXTRACT(EPOCH FROM (NOW() - MIN(v.created_at))) / 3600, 1)
    ) as trend_score,
    MAX(v.created_at) as last_video_at
FROM videos v
CROSS JOIN LATERAL unnest(v.hashtags) tag
WHERE v.is_active = TRUE
GROUP BY tag;

-- Index sur la vue (via table matérielle optionnelle)
-- CREATE MATERIALIZED VIEW hashtag_stats_materialized AS SELECT * FROM hashtag_stats;
-- CREATE UNIQUE INDEX ON hashtag_stats_materialized(tag);

COMMENT ON TABLE videos IS 'Table pour stocker les vidéos du feed avec hashtags et embeddings pour ML';
COMMENT ON COLUMN videos.hashtags IS 'Array de hashtags extraits automatiquement ou ajoutés manuellement';
COMMENT ON COLUMN videos.embedding IS 'Vecteur d''embedding pour recommandations ML (stocké en TEXT, JSON array ou base64)';
COMMENT ON COLUMN videos.studio_session_id IS 'ID de session studio pour chaînage vidéos';



-- ============================================
-- Migration: 20251203_enhance_recommendations_algorithm.sql
-- ============================================
-- Migration: Amélioration algorithme de recommandations avec signaux enrichis
-- Date: 2025-12-03
-- Description: Ajoute colonnes pour temps de visionnage, préférences utilisateur, et signaux contextuels

-- ✅ 1. Ajouter colonnes à content_engagement pour tracking temps de visionnage
ALTER TABLE content_engagement 
ADD COLUMN IF NOT EXISTS watch_duration_ms INTEGER,
ADD COLUMN IF NOT EXISTS video_duration_ms INTEGER,
ADD COLUMN IF NOT EXISTS completion_rate REAL,
ADD COLUMN IF NOT EXISTS device_type VARCHAR(50),
ADD COLUMN IF NOT EXISTS location_gps VARCHAR(255),
ADD COLUMN IF NOT EXISTS shared BOOLEAN DEFAULT FALSE;

-- Index pour performance sur temps de visionnage
CREATE INDEX IF NOT EXISTS idx_content_engagement_watch_duration 
ON content_engagement(user_id, completion_rate) 
WHERE completion_rate > 0.5;

CREATE INDEX IF NOT EXISTS idx_content_engagement_user_liked 
ON content_engagement(user_id, liked) 
WHERE liked = TRUE;

CREATE INDEX IF NOT EXISTS idx_content_engagement_user_saved 
ON content_engagement(user_id, saved) 
WHERE saved = TRUE;

-- ✅ 2. Créer table user_preferences pour stocker préférences utilisateur
CREATE TABLE IF NOT EXISTS user_preferences (
    user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    preferred_categories TEXT[] DEFAULT ARRAY[]::TEXT[],
    preferred_hashtags TEXT[] DEFAULT ARRAY[]::TEXT[],
    preferred_creators INTEGER[] DEFAULT ARRAY[]::INTEGER[],
    preferred_video_length_min INTEGER DEFAULT 0,
    preferred_video_length_max INTEGER DEFAULT 600000, -- 10 minutes max par défaut
    avg_watch_duration_ms INTEGER DEFAULT 0,
    most_active_hour INTEGER, -- Heure de la journée la plus active (0-23)
    most_active_day INTEGER,   -- Jour de la semaine le plus actif (0-6, dimanche=0)
    last_updated TIMESTAMPTZ DEFAULT NOW()
);

-- Index pour user_preferences
CREATE INDEX IF NOT EXISTS idx_user_preferences_categories 
ON user_preferences USING GIN(preferred_categories);

CREATE INDEX IF NOT EXISTS idx_user_preferences_hashtags 
ON user_preferences USING GIN(preferred_hashtags);

-- ✅ 3. Fonction pour calculer/mettre à jour préférences utilisateur
CREATE OR REPLACE FUNCTION update_user_preferences(p_user_id INTEGER)
RETURNS VOID AS $$
DECLARE
    v_categories TEXT[];
    v_hashtags TEXT[];
    v_creators INTEGER[];
    v_avg_watch_duration INTEGER;
    v_most_active_hour INTEGER;
    v_most_active_day INTEGER;
BEGIN
    -- Calculer catégories préférées (depuis services likés)
    SELECT array_agg(DISTINCT s.category)
    INTO v_categories
    FROM content_engagement ce
    JOIN media m ON m.id::text = ce.content_id OR 'media_' || m.service_id || '_' || m.id = ce.content_id
    JOIN services s ON s.id = m.service_id
    WHERE ce.user_id = p_user_id
      AND ce.liked = TRUE
      AND ce.created_at > NOW() - INTERVAL '90 days'
      AND s.category IS NOT NULL;
    
    -- Calculer hashtags préférés (depuis vidéos likées)
    SELECT array_agg(DISTINCT tag)
    INTO v_hashtags
    FROM content_engagement ce
    JOIN media m ON m.id::text = ce.content_id OR 'media_' || m.service_id || '_' || m.id = ce.content_id
    CROSS JOIN LATERAL unnest(COALESCE(m.ai_tags, ARRAY[]::TEXT[])) tag
    WHERE ce.user_id = p_user_id
      AND ce.liked = TRUE
      AND ce.created_at > NOW() - INTERVAL '90 days';
    
    -- Calculer créateurs préférés (depuis services likés)
    SELECT array_agg(DISTINCT s.user_id)
    INTO v_creators
    FROM content_engagement ce
    JOIN media m ON m.id::text = ce.content_id OR 'media_' || m.service_id || '_' || m.id = ce.content_id
    JOIN services s ON s.id = m.service_id
    WHERE ce.user_id = p_user_id
      AND ce.liked = TRUE
      AND ce.created_at > NOW() - INTERVAL '90 days';
    
    -- Calculer durée moyenne de visionnage
    SELECT COALESCE(AVG(watch_duration_ms), 0)::INTEGER
    INTO v_avg_watch_duration
    FROM content_engagement
    WHERE user_id = p_user_id
      AND watch_duration_ms IS NOT NULL
      AND created_at > NOW() - INTERVAL '30 days';
    
    -- Calculer heure la plus active
    SELECT EXTRACT(HOUR FROM created_at)::INTEGER
    INTO v_most_active_hour
    FROM content_engagement
    WHERE user_id = p_user_id
      AND created_at > NOW() - INTERVAL '30 days'
    GROUP BY EXTRACT(HOUR FROM created_at)
    ORDER BY COUNT(*) DESC
    LIMIT 1;
    
    -- Calculer jour le plus actif
    SELECT EXTRACT(DOW FROM created_at)::INTEGER
    INTO v_most_active_day
    FROM content_engagement
    WHERE user_id = p_user_id
      AND created_at > NOW() - INTERVAL '30 days'
    GROUP BY EXTRACT(DOW FROM created_at)
    ORDER BY COUNT(*) DESC
    LIMIT 1;
    
    -- Insérer ou mettre à jour préférences
    INSERT INTO user_preferences (
        user_id, 
        preferred_categories, 
        preferred_hashtags, 
        preferred_creators,
        avg_watch_duration_ms,
        most_active_hour,
        most_active_day,
        last_updated
    )
    VALUES (
        p_user_id,
        COALESCE(v_categories, ARRAY[]::TEXT[]),
        COALESCE(v_hashtags, ARRAY[]::TEXT[]),
        COALESCE(v_creators, ARRAY[]::INTEGER[]),
        COALESCE(v_avg_watch_duration, 0),
        v_most_active_hour,
        v_most_active_day,
        NOW()
    )
    ON CONFLICT (user_id) DO UPDATE SET
        preferred_categories = EXCLUDED.preferred_categories,
        preferred_hashtags = EXCLUDED.preferred_hashtags,
        preferred_creators = EXCLUDED.preferred_creators,
        avg_watch_duration_ms = EXCLUDED.avg_watch_duration_ms,
        most_active_hour = EXCLUDED.most_active_hour,
        most_active_day = EXCLUDED.most_active_day,
        last_updated = NOW();
END;
$$ LANGUAGE plpgsql;

-- ✅ 4. Trigger pour mettre à jour completion_rate automatiquement
CREATE OR REPLACE FUNCTION calculate_completion_rate()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.watch_duration_ms IS NOT NULL AND NEW.video_duration_ms IS NOT NULL AND NEW.video_duration_ms > 0 THEN
        NEW.completion_rate = LEAST(
            (NEW.watch_duration_ms::REAL / NEW.video_duration_ms::REAL),
            1.0
        );
    ELSE
        NEW.completion_rate = 0.0;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_calculate_completion_rate ON content_engagement;
CREATE TRIGGER trg_calculate_completion_rate
    BEFORE INSERT OR UPDATE OF watch_duration_ms, video_duration_ms ON content_engagement
    FOR EACH ROW
    EXECUTE FUNCTION calculate_completion_rate();

-- ✅ 5. Vue pour statistiques vidéo enrichies (pour scoring)
CREATE OR REPLACE VIEW video_engagement_stats AS
SELECT 
    content_id,
    COUNT(*) as total_views,
    SUM(CASE WHEN liked = TRUE THEN 1 ELSE 0 END) as total_likes,
    SUM(CASE WHEN saved = TRUE THEN 1 ELSE 0 END) as total_saves,
    SUM(CASE WHEN shared = TRUE THEN 1 ELSE 0 END) as total_shares,
    AVG(completion_rate) as avg_completion_rate,
    AVG(watch_duration_ms) as avg_watch_duration_ms,
    MAX(created_at) as last_engagement_at
FROM content_engagement
WHERE created_at > NOW() - INTERVAL '30 days'
GROUP BY content_id;

-- Commentaires
COMMENT ON TABLE user_preferences IS 'Préférences utilisateur calculées depuis historique d''engagement';
COMMENT ON COLUMN content_engagement.watch_duration_ms IS 'Durée de visionnage en millisecondes';
COMMENT ON COLUMN content_engagement.completion_rate IS 'Taux de complétion (0.0 à 1.0)';
COMMENT ON COLUMN user_preferences.preferred_categories IS 'Catégories préférées calculées depuis historique';
COMMENT ON COLUMN user_preferences.avg_watch_duration_ms IS 'Durée moyenne de visionnage de l''utilisateur';



-- ============================================
-- Migration: 20251203_optimize_hashtags_scalability.sql
-- ============================================
-- ✅ 2025-12-03: Optimisations de scalabilité pour hashtags
-- Support de millions d'interactions simultanées

-- =====================================================
-- 1. INDEX OPTIMISÉS POUR HASHTAGS
-- =====================================================

-- Index composite pour recherche hashtags avec tri
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_videos_hashtags_active_created 
ON videos (is_active, created_at DESC) 
WHERE is_active = TRUE AND array_length(hashtags, 1) > 0;

-- Index pour recherche hashtag spécifique (performance)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_videos_hashtag_lookup
ON videos USING GIN (hashtags)
WHERE is_active = TRUE;

-- Index pour statistiques hashtags (vue hashtag_stats)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_hashtag_stats_trend_score
ON videos (created_at DESC, like_count DESC, save_count DESC)
WHERE is_active = TRUE AND array_length(hashtags, 1) > 0;

-- =====================================================
-- 2. OPTIMISATION VUE hashtag_stats
-- =====================================================

-- Vue matérialisée pour statistiques hashtags (recharge toutes les 5 minutes)
CREATE MATERIALIZED VIEW IF NOT EXISTS hashtag_stats_materialized AS
SELECT 
    tag,
    COUNT(DISTINCT v.id) as video_count,
    SUM(v.view_count) as total_views,
    SUM(v.like_count) as total_likes,
    SUM(v.save_count) as total_saves,
    (
        SUM(v.like_count * 2 + v.save_count * 1.5 + v.view_count * 0.1) 
        / GREATEST(EXTRACT(EPOCH FROM (NOW() - MIN(v.created_at))) / 3600, 1)
    ) as trend_score,
    MAX(v.created_at) as last_video_at
FROM videos v
CROSS JOIN LATERAL unnest(v.hashtags) tag
WHERE v.is_active = TRUE
GROUP BY tag;

-- Index unique sur la vue matérialisée
CREATE UNIQUE INDEX IF NOT EXISTS idx_hashtag_stats_materialized_tag 
ON hashtag_stats_materialized(tag);

-- Index pour tri par trend_score
CREATE INDEX IF NOT EXISTS idx_hashtag_stats_materialized_trend 
ON hashtag_stats_materialized(trend_score DESC);

-- Index pour tri par video_count
CREATE INDEX IF NOT EXISTS idx_hashtag_stats_materialized_count 
ON hashtag_stats_materialized(video_count DESC);

-- Fonction pour rafraîchir la vue matérialisée
CREATE OR REPLACE FUNCTION refresh_hashtag_stats()
RETURNS void AS $$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY hashtag_stats_materialized;
END;
$$ LANGUAGE plpgsql;

-- =====================================================
-- 3. INDEX POUR PAGINATION CURSOR-BASED (OPTIONNEL)
-- =====================================================

-- Index pour pagination cursor-based par created_at
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_videos_hashtag_cursor_created
ON videos (created_at DESC, id)
WHERE is_active = TRUE AND array_length(hashtags, 1) > 0;

-- Index pour pagination cursor-based par engagement
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_videos_hashtag_cursor_engagement
ON videos ((like_count * 2 + save_count * 1.5 + view_count * 0.1) DESC, id)
WHERE is_active = TRUE AND array_length(hashtags, 1) > 0;

-- =====================================================
-- 4. OPTIMISATION REQUÊTES HASHTAGS
-- =====================================================

-- Fonction optimisée pour recherche hashtags avec cache
CREATE OR REPLACE FUNCTION search_hashtags_optimized(
    search_query TEXT DEFAULT '',
    max_results INTEGER DEFAULT 50,
    trending_only BOOLEAN DEFAULT FALSE
)
RETURNS TABLE (
    tag TEXT,
    video_count BIGINT,
    view_count BIGINT,
    like_count BIGINT,
    trend_score NUMERIC,
    is_trending BOOLEAN
) AS $$
BEGIN
    IF trending_only THEN
        RETURN QUERY
        SELECT 
            hs.tag,
            hs.video_count,
            hs.total_views as view_count,
            hs.total_likes as like_count,
            hs.trend_score,
            (hs.trend_score > 10.0) as is_trending
        FROM hashtag_stats_materialized hs
        WHERE hs.video_count >= 3
        ORDER BY hs.trend_score DESC
        LIMIT max_results;
    ELSIF search_query != '' THEN
        RETURN QUERY
        SELECT 
            hs.tag,
            hs.video_count,
            hs.total_views as view_count,
            hs.total_likes as like_count,
            hs.trend_score,
            (hs.trend_score > 10.0) as is_trending
        FROM hashtag_stats_materialized hs
        WHERE LOWER(hs.tag) LIKE '%' || LOWER(search_query) || '%'
        ORDER BY hs.video_count DESC, hs.trend_score DESC
        LIMIT max_results;
    ELSE
        RETURN QUERY
        SELECT 
            hs.tag,
            hs.video_count,
            hs.total_views as view_count,
            hs.total_likes as like_count,
            hs.trend_score,
            (hs.trend_score > 10.0) as is_trending
        FROM hashtag_stats_materialized hs
        ORDER BY hs.video_count DESC
        LIMIT max_results;
    END IF;
END;
$$ LANGUAGE plpgsql STABLE;

-- Fonction optimisée pour vidéos par hashtag avec pagination
CREATE OR REPLACE FUNCTION get_videos_by_hashtag_optimized(
    hashtag_param TEXT,
    sort_mode TEXT DEFAULT 'recent',
    result_limit INTEGER DEFAULT 50,
    result_offset INTEGER DEFAULT 0
)
RETURNS TABLE (
    id TEXT,
    content_id TEXT,
    titre TEXT,
    video_url TEXT,
    thumbnail TEXT,
    service_id INTEGER,
    likes BIGINT,
    saves BIGINT,
    views BIGINT,
    created_at TIMESTAMPTZ,
    hashtags TEXT[]
) AS $$
BEGIN
    IF sort_mode = 'popular' THEN
        RETURN QUERY
        SELECT 
            v.id,
            v.content_id,
            v.titre,
            v.video_url,
            v.thumbnail,
            v.service_id,
            v.like_count::BIGINT as likes,
            v.save_count::BIGINT as saves,
            v.view_count::BIGINT as views,
            v.created_at,
            v.hashtags
        FROM videos v
        WHERE v.is_active = TRUE
        AND EXISTS (
            SELECT 1 FROM unnest(v.hashtags) tag WHERE LOWER(tag) = LOWER(hashtag_param)
        )
        ORDER BY (v.like_count * 2 + v.save_count * 1.5 + v.view_count * 0.1) DESC, v.created_at DESC
        LIMIT result_limit OFFSET result_offset;
    ELSIF sort_mode = 'trending' THEN
        RETURN QUERY
        SELECT 
            v.id,
            v.content_id,
            v.titre,
            v.video_url,
            v.thumbnail,
            v.service_id,
            v.like_count::BIGINT as likes,
            v.save_count::BIGINT as saves,
            v.view_count::BIGINT as views,
            v.created_at,
            v.hashtags
        FROM videos v
        WHERE v.is_active = TRUE
        AND EXISTS (
            SELECT 1 FROM unnest(v.hashtags) tag WHERE LOWER(tag) = LOWER(hashtag_param)
        )
        AND v.created_at > NOW() - INTERVAL '7 days'
        ORDER BY (v.like_count * 2 + v.save_count * 1.5) / GREATEST(EXTRACT(EPOCH FROM (NOW() - v.created_at)) / 3600, 1) DESC, v.created_at DESC
        LIMIT result_limit OFFSET result_offset;
    ELSE -- 'recent'
        RETURN QUERY
        SELECT 
            v.id,
            v.content_id,
            v.titre,
            v.video_url,
            v.thumbnail,
            v.service_id,
            v.like_count::BIGINT as likes,
            v.save_count::BIGINT as saves,
            v.view_count::BIGINT as views,
            v.created_at,
            v.hashtags
        FROM videos v
        WHERE v.is_active = TRUE
        AND EXISTS (
            SELECT 1 FROM unnest(v.hashtags) tag WHERE LOWER(tag) = LOWER(hashtag_param)
        )
        ORDER BY v.created_at DESC
        LIMIT result_limit OFFSET result_offset;
    END IF;
END;
$$ LANGUAGE plpgsql STABLE;

-- =====================================================
-- 5. TRIGGER POUR MAINTENIR STATISTIQUES À JOUR
-- =====================================================

-- Fonction pour mettre à jour les statistiques après modification vidéo
CREATE OR REPLACE FUNCTION update_hashtag_stats_on_video_change()
RETURNS TRIGGER AS $$
BEGIN
    -- Rafraîchir la vue matérialisée de manière asynchrone (via job)
    -- Pour l'instant, on laisse le refresh manuel ou via cron
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger pour rafraîchir stats après update engagement
-- Note: On évite de rafraîchir à chaque update pour performance
-- Le refresh se fait via job périodique (toutes les 5 minutes)

COMMENT ON MATERIALIZED VIEW hashtag_stats_materialized IS 'Vue matérialisée pour statistiques hashtags - Rafraîchir toutes les 5 minutes pour performance';
COMMENT ON FUNCTION search_hashtags_optimized IS 'Recherche optimisée hashtags avec cache via vue matérialisée';
COMMENT ON FUNCTION get_videos_by_hashtag_optimized IS 'Récupération optimisée vidéos par hashtag avec pagination';



