-- ✅ Migration : Tables pour fonctionnalités sociales vidéo
-- Date: 2025-12-07
-- Description: Crée les tables pour duets, remixes, stitches et réactions vidéo

-- 1. Table duets (duos vidéo)
CREATE TABLE IF NOT EXISTS duets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    original_video_id UUID NOT NULL,
    duet_video_url TEXT NOT NULL,
    creator_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_duets_original_video ON duets(original_video_id);
CREATE INDEX IF NOT EXISTS idx_duets_creator ON duets(creator_id);
CREATE INDEX IF NOT EXISTS idx_duets_created_at ON duets(created_at);

-- 2. Table remixes (remix vidéo)
CREATE TABLE IF NOT EXISTS remixes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    original_video_id UUID NOT NULL,
    remix_video_url TEXT NOT NULL,
    remix_type TEXT NOT NULL CHECK (remix_type IN ('speed', 'filter', 'effect', 'music', 'other')),
    effects TEXT,
    creator_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    metadata JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_remixes_original_video ON remixes(original_video_id);
CREATE INDEX IF NOT EXISTS idx_remixes_creator ON remixes(creator_id);
CREATE INDEX IF NOT EXISTS idx_remixes_type ON remixes(remix_type);
CREATE INDEX IF NOT EXISTS idx_remixes_created_at ON remixes(created_at);

-- 3. Table stitches (montage vidéo)
CREATE TABLE IF NOT EXISTS stitches (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    original_video_id UUID NOT NULL,
    stitched_video_url TEXT NOT NULL,
    start_time DOUBLE PRECISION NOT NULL,
    end_time DOUBLE PRECISION NOT NULL,
    creator_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    metadata JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_stitches_original_video ON stitches(original_video_id);
CREATE INDEX IF NOT EXISTS idx_stitches_creator ON stitches(creator_id);
CREATE INDEX IF NOT EXISTS idx_stitches_created_at ON stitches(created_at);

-- 4. Table video_reactions (réactions vidéo)
CREATE TABLE IF NOT EXISTS video_reactions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    video_id UUID NOT NULL,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    type_reaction TEXT NOT NULL CHECK (type_reaction IN ('like', 'love', 'laugh', 'wow', 'sad', 'angry')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(video_id, user_id, type_reaction)
);

CREATE INDEX IF NOT EXISTS idx_video_reactions_video ON video_reactions(video_id);
CREATE INDEX IF NOT EXISTS idx_video_reactions_user ON video_reactions(user_id);
CREATE INDEX IF NOT EXISTS idx_video_reactions_type ON video_reactions(type_reaction);
CREATE INDEX IF NOT EXISTS idx_video_reactions_created_at ON video_reactions(created_at);

-- Commentaires
COMMENT ON TABLE duets IS 'Duos vidéo - utilisateurs créent des vidéos côte à côte';
COMMENT ON TABLE remixes IS 'Remix vidéo - modifications créatives de vidéos originales';
COMMENT ON TABLE stitches IS 'Montages vidéo - extraits de vidéos originales';
COMMENT ON TABLE video_reactions IS 'Réactions émotionnelles aux vidéos';



-- ============================================
-- Migration: 20251209_fix_materialized_views_unique_indexes.sql
-- ============================================
-- ✅ CORRECTION 2025-12-09: Ajouter index uniques requis pour REFRESH MATERIALIZED VIEW CONCURRENTLY
-- Problème: Les vues matérialisées ne peuvent pas être rafraîchies en mode concurrent sans index unique
-- Solution: Ajouter des index uniques sur les vues matérialisées
-- Compatible: SQLx offline mode (utilise sqlx::query() non typé)

-- =====================================================
-- 1. services_search_cache
-- =====================================================

-- Vérifier si la vue existe et ajouter l'index unique si nécessaire
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_matviews WHERE matviewname = 'services_search_cache') THEN
        -- Vérifier si l'index unique existe déjà
        IF NOT EXISTS (
            SELECT 1 FROM pg_indexes 
            WHERE tablename = 'services_search_cache' 
            AND indexname = 'idx_services_search_cache_id_unique'
        ) THEN
            CREATE UNIQUE INDEX idx_services_search_cache_id_unique
            ON services_search_cache (id);
            RAISE NOTICE 'Index unique créé sur services_search_cache';
        ELSE
            RAISE NOTICE 'Index unique déjà présent sur services_search_cache';
        END IF;
    ELSE
        RAISE NOTICE 'Vue services_search_cache n''existe pas encore';
    END IF;
END $$;

-- =====================================================
-- 2. active_products_cache
-- =====================================================

-- Vérifier si la vue existe et recréer avec cache_id si nécessaire
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_matviews WHERE matviewname = 'active_products_cache') THEN
        -- Vérifier si la colonne cache_id existe
        IF NOT EXISTS (
            SELECT 1 FROM information_schema.columns 
            WHERE table_name = 'active_products_cache' 
            AND column_name = 'cache_id'
        ) THEN
            -- Recréer la vue avec cache_id
            DROP MATERIALIZED VIEW IF EXISTS active_products_cache CASCADE;
            
            CREATE MATERIALIZED VIEW active_products_cache AS
            SELECT 
                (s.id::bigint * 1000000 + jsonb_array_elements.pos) as cache_id,
                s.id as service_id,
                s.user_id,
                s.category,
                s.gps,
                jsonb_array_elements.product,
                s.created_at
            FROM services s
            CROSS JOIN LATERAL jsonb_array_elements(
                CASE 
                    WHEN jsonb_typeof(s.data->'produits') = 'array' 
                    THEN s.data->'produits'
                    WHEN jsonb_typeof(s.data->'produits'->'valeur') = 'array'
                    THEN s.data->'produits'->'valeur'
                    ELSE '[]'::jsonb
                END
            ) WITH ORDINALITY AS jsonb_array_elements(product, pos)
            WHERE s.is_active = TRUE
            AND (
                jsonb_typeof(s.data->'produits') = 'array' OR
                jsonb_typeof(s.data->'produits'->'valeur') = 'array'
            );
            
            -- Recréer les index
            CREATE UNIQUE INDEX idx_active_products_cache_id_unique
            ON active_products_cache (cache_id);
            
            CREATE INDEX IF NOT EXISTS idx_active_products_service_category
            ON active_products_cache (service_id, category);
            
            CREATE INDEX IF NOT EXISTS idx_active_products_product_name
            ON active_products_cache USING GIN (
                to_tsvector('french', 
                    COALESCE(product->>'name', '') || ' ' ||
                    COALESCE(product->>'description', '')
                )
            );
            
            RAISE NOTICE 'Vue active_products_cache recréée avec cache_id';
        ELSE
            -- La colonne existe déjà, juste créer l'index unique si nécessaire
            IF NOT EXISTS (
                SELECT 1 FROM pg_indexes 
                WHERE tablename = 'active_products_cache' 
                AND indexname = 'idx_active_products_cache_id_unique'
            ) THEN
                CREATE UNIQUE INDEX idx_active_products_cache_id_unique
                ON active_products_cache (cache_id);
                RAISE NOTICE 'Index unique créé sur active_products_cache';
            ELSE
                RAISE NOTICE 'Index unique déjà présent sur active_products_cache';
            END IF;
        END IF;
    ELSE
        RAISE NOTICE 'Vue active_products_cache n''existe pas encore';
    END IF;
END $$;

-- =====================================================
-- 3. global_promo_catalog_cache (vérifier si index unique existe)
-- =====================================================

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_matviews WHERE matviewname = 'global_promo_catalog_cache') THEN
        -- Vérifier si l'index unique existe déjà
        IF NOT EXISTS (
            SELECT 1 FROM pg_indexes 
            WHERE tablename = 'global_promo_catalog_cache' 
            AND indexname = 'idx_global_promo_catalog_cache_entry_id'
        ) THEN
            -- Créer l'index unique si la colonne entry_id existe
            IF EXISTS (
                SELECT 1 FROM information_schema.columns 
                WHERE table_name = 'global_promo_catalog_cache' 
                AND column_name = 'entry_id'
            ) THEN
                CREATE UNIQUE INDEX idx_global_promo_catalog_cache_entry_id
                ON global_promo_catalog_cache(entry_id);
                RAISE NOTICE 'Index unique créé sur global_promo_catalog_cache';
            ELSE
                RAISE NOTICE 'Colonne entry_id manquante dans global_promo_catalog_cache';
            END IF;
        ELSE
            RAISE NOTICE 'Index unique déjà présent sur global_promo_catalog_cache';
        END IF;
    ELSE
        RAISE NOTICE 'Vue global_promo_catalog_cache n''existe pas encore';
    END IF;
END $$;



-- ============================================
-- Migration: 20251209_optimize_slow_queries_indexes.sql
-- ============================================
-- ✅ CORRECTION 2025-12-09: Optimisation des requêtes lentes identifiées dans les logs
-- Problèmes: Requêtes >1s sur pharmacies et delivery_matching_queue
-- Compatible: SQLx offline mode (utilise sqlx::query() non typé)

-- =====================================================
-- 1. Optimisation requête pharmacies is_on_duty_now
-- =====================================================

-- Index composite pour la requête: WHERE is_active = TRUE AND is_on_duty_now = TRUE ORDER BY nom ASC
CREATE INDEX IF NOT EXISTS idx_pharmacies_active_on_duty_nom
ON pharmacies(is_active, is_on_duty_now, nom)
WHERE is_active = TRUE AND is_on_duty_now = TRUE;

-- =====================================================
-- 2. Optimisation requête delivery_matching_queue
-- =====================================================

-- Index composite pour la requête: 
-- WHERE status IN ('queued', 'searching') AND next_attempt_at <= NOW()
-- ORDER BY priority ASC, next_attempt_at ASC
CREATE INDEX IF NOT EXISTS idx_delivery_matching_queue_status_priority_next_attempt
ON delivery_matching_queue(status, priority, next_attempt_at)
WHERE status IN ('queued', 'searching');

-- Index partiel pour next_attempt_at (sans NOW() car non IMMUTABLE)
-- ✅ CORRIGÉ: Retirer NOW() du prédicat - la condition sera gérée dans les requêtes SQL
CREATE INDEX IF NOT EXISTS idx_delivery_matching_queue_next_attempt_pending
ON delivery_matching_queue(next_attempt_at)
WHERE status IN ('queued', 'searching') AND next_attempt_at IS NOT NULL;

-- =====================================================
-- 3. Notes
-- =====================================================

-- Ces index permettront d'optimiser les requêtes fréquentes :
-- 1. pharmacies: SELECT * FROM pharmacies WHERE is_active = TRUE AND is_on_duty_now = TRUE ORDER BY nom ASC
-- 2. delivery_matching_queue: SELECT ... WHERE status IN ('queued', 'searching') AND next_attempt_at <= NOW() ORDER BY priority ASC, next_attempt_at ASC



-- ============================================
-- Migration: 20251210_fix_u_client_name_error.sql
-- ============================================
-- Migration pour vérifier et corriger l'erreur "column u_client.name does not exist"
-- Date: 2025-12-10
-- Description: Vérifie toutes les vues et fonctions PostgreSQL qui référencent u_client.name
--              et les corrige pour utiliser u_client.nom_complet à la place

-- =====================================================
-- 1. VÉRIFIER LES VUES QUI UTILISENT u_client.name
-- =====================================================

-- Rechercher toutes les vues qui contiennent "u_client.name"
DO $$
DECLARE
    view_record RECORD;
    view_definition TEXT;
BEGIN
    FOR view_record IN 
        SELECT schemaname, viewname, definition
        FROM pg_views
        WHERE definition ILIKE '%u_client.name%'
           OR definition ILIKE '%u_client%name%'
    LOOP
        RAISE NOTICE 'Vue trouvée avec u_client.name: %.%', view_record.schemaname, view_record.viewname;
        RAISE NOTICE 'Définition: %', view_record.definition;
    END LOOP;
END $$;

-- =====================================================
-- 2. VÉRIFIER LES FONCTIONS QUI UTILISENT u_client.name
-- =====================================================

-- Rechercher toutes les fonctions qui contiennent "u_client.name"
DO $$
DECLARE
    func_record RECORD;
    func_definition TEXT;
BEGIN
    FOR func_record IN 
        SELECT 
            n.nspname as schema_name, 
            p.proname as function_name,
            pg_get_functiondef(p.oid) as definition
        FROM pg_proc p
        JOIN pg_namespace n ON p.pronamespace = n.oid
        WHERE pg_get_functiondef(p.oid) ILIKE '%u_client.name%'
           OR pg_get_functiondef(p.oid) ILIKE '%u_client%name%'
    LOOP
        BEGIN
            RAISE NOTICE 'Fonction trouvée avec u_client.name: %.%', func_record.schema_name, func_record.function_name;
        EXCEPTION
            WHEN OTHERS THEN
                -- Ignorer les erreurs de formatage
                NULL;
        END;
    END LOOP;
END $$;

-- =====================================================
-- 3. VÉRIFIER LES VUES MATÉRIALISÉES
-- =====================================================

-- Rechercher toutes les vues matérialisées qui contiennent "u_client.name"
DO $$
DECLARE
    matview_record RECORD;
BEGIN
    FOR matview_record IN 
        SELECT schemaname, matviewname, definition
        FROM pg_matviews
        WHERE definition ILIKE '%u_client.name%'
           OR definition ILIKE '%u_client%name%'
    LOOP
        RAISE NOTICE 'Vue matérialisée trouvée avec u_client.name: %.%', matview_record.schemaname, matview_record.matviewname;
    END LOOP;
END $$;

-- =====================================================
-- 4. CORRIGER LES VUES/FONCTIONS TROUVÉES (si nécessaire)
-- =====================================================

-- Note: Les corrections spécifiques seront ajoutées ici si des vues/fonctions sont trouvées
-- Pour l'instant, cette migration sert uniquement à diagnostiquer le problème

-- =====================================================
-- 5. VÉRIFIER QUE LA COLONNE nom_complet EXISTE DANS users
-- =====================================================

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 
        FROM information_schema.columns 
        WHERE table_schema = 'public' 
          AND table_name = 'users' 
          AND column_name = 'nom_complet'
    ) THEN
        RAISE EXCEPTION 'La colonne nom_complet n''existe pas dans la table users';
    ELSE
        RAISE NOTICE '✅ La colonne nom_complet existe dans la table users';
    END IF;
END $$;

-- =====================================================
-- 6. VÉRIFIER QUE LA COLONNE name N'EXISTE PAS DANS users
-- =====================================================

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 
        FROM information_schema.columns 
        WHERE table_schema = 'public' 
          AND table_name = 'users' 
          AND column_name = 'name'
    ) THEN
        RAISE WARNING 'La colonne name existe dans la table users (devrait être nom_complet)';
    ELSE
        RAISE NOTICE '✅ La colonne name n''existe pas dans la table users (comme attendu)';
    END IF;
END $$;

