-- Migration: 20251211_fix_user_stats_errors.sql
-- ============================================
-- Migration pour corriger les erreurs de base de données liées aux statistiques utilisateur
-- Erreurs corrigées :
-- 1. ERROR: relation "mv_user_stats" does not exist
-- 2. ERROR: function get_user_stats(integer) does not exist
-- 3. ERROR: column "u.id" must appear in the GROUP BY clause

-- ✅ 1. Créer la vue matérialisée mv_user_stats
-- Cette vue est basée sur la requête dans db_optimizer.rs::get_user_stats_cached
DROP MATERIALIZED VIEW IF EXISTS mv_user_stats CASCADE;

CREATE MATERIALIZED VIEW mv_user_stats AS
SELECT 
    u.id,
    u.tokens_balance,
    COUNT(s.id) as services_count,
    COUNT(CASE WHEN s.is_active THEN 1 END) as active_services_count,
    NULL::BIGINT as reviews_count,
    NULL::DOUBLE PRECISION as avg_rating
FROM users u
LEFT JOIN services s ON u.id = s.user_id
GROUP BY u.id, u.tokens_balance;

-- Index pour améliorer les performances
CREATE UNIQUE INDEX IF NOT EXISTS idx_mv_user_stats_id ON mv_user_stats(id);

-- ✅ 2. Créer la fonction get_user_stats
-- Cette fonction peut utiliser la vue matérialisée ou la requête directe
CREATE OR REPLACE FUNCTION get_user_stats(user_id_param INTEGER)
RETURNS TABLE (
    id INTEGER,
    tokens_balance BIGINT,
    services_count BIGINT,
    active_services_count BIGINT,
    reviews_count BIGINT,
    avg_rating DOUBLE PRECISION
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        u.id,
        u.tokens_balance,
        COUNT(s.id)::BIGINT as services_count,
        COUNT(CASE WHEN s.is_active THEN 1 END)::BIGINT as active_services_count,
        NULL::BIGINT as reviews_count,
        NULL::DOUBLE PRECISION as avg_rating
    FROM users u
    LEFT JOIN services s ON u.id = s.user_id
    WHERE u.id = user_id_param
    GROUP BY u.id, u.tokens_balance;
END;
$$ LANGUAGE plpgsql;

-- ✅ 3. Fonction pour rafraîchir la vue matérialisée
CREATE OR REPLACE FUNCTION refresh_user_stats()
RETURNS void AS $$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_user_stats;
END;
$$ LANGUAGE plpgsql;

-- ✅ 4. Commentaires pour documentation
COMMENT ON MATERIALIZED VIEW mv_user_stats IS 'Vue matérialisée pour les statistiques utilisateur (services, tokens, etc.)';
COMMENT ON FUNCTION get_user_stats(INTEGER) IS 'Fonction pour récupérer les statistiques d''un utilisateur spécifique';
COMMENT ON FUNCTION refresh_user_stats() IS 'Fonction pour rafraîchir la vue matérialisée mv_user_stats';

-- ✅ 5. Rafraîchir la vue matérialisée initialement
REFRESH MATERIALIZED VIEW mv_user_stats;

-- ✅ 6. Note sur l'erreur GROUP BY
-- L'erreur "column u.id must appear in the GROUP BY clause" peut provenir de :
-- - Une migration SQL non exécutée correctement
-- - Une requête générée dynamiquement
-- - Une fonction/vue qui n'a pas été mise à jour
-- Si cette erreur persiste, vérifier les logs pour identifier la requête spécifique
-- et s'assurer que toutes les colonnes non-agrégées dans le SELECT sont dans le GROUP BY



-- ============================================
-- Migration: 20251212_optimize_delivery_matching_queue_index.sql
-- ============================================
-- Migration pour optimiser la requête sur delivery_matching_queue
-- Date: 2025-12-12
-- Problème: Requête lente (1-1.4s) sur delivery_matching_queue
-- Solution: Créer un index composite optimisé pour la requête exacte

-- ✅ Index composite optimisé pour la requête:
-- SELECT ... FROM delivery_matching_queue
-- WHERE status IN ('queued', 'searching')
--   AND next_attempt_at <= NOW()
-- ORDER BY priority ASC, next_attempt_at ASC
-- LIMIT $1

-- Supprimer les anciens index non optimaux s'ils existent
DROP INDEX IF EXISTS idx_delivery_matching_queue_status_next_attempt_old;

-- ✅ NOUVEAU: Index composite couvrant tous les critères de la requête
-- L'ordre des colonnes est optimisé pour la requête:
-- 1. status (filtre WHERE)
-- 2. next_attempt_at (filtre WHERE + ORDER BY)
-- 3. priority (ORDER BY)
CREATE INDEX IF NOT EXISTS idx_delivery_matching_queue_optimized
ON delivery_matching_queue (status, next_attempt_at, priority)
WHERE status IN ('queued', 'searching');

-- ✅ Index partiel supplémentaire pour les requêtes avec next_attempt_at <= NOW()
-- NOTE: NOW() n'est pas IMMUTABLE, donc on ne peut pas l'utiliser dans un index partiel
-- On crée un index simple qui sera utilisé par PostgreSQL avec le filtre WHERE dans la requête
CREATE INDEX IF NOT EXISTS idx_delivery_matching_queue_priority_next_attempt
ON delivery_matching_queue (priority, next_attempt_at)
WHERE status IN ('queued', 'searching');

-- Commentaire
COMMENT ON INDEX idx_delivery_matching_queue_optimized IS 
'Index composite optimisé pour la requête de sélection des jobs de matching prêts à être traités';

COMMENT ON INDEX idx_delivery_matching_queue_priority_next_attempt IS 
'Index partiel pour les jobs en attente (status IN queued/searching) - optimise ORDER BY priority, next_attempt_at';



-- ============================================
-- Migration: 20251216_optimize_product_creation_performance.sql
-- ============================================
-- ✅ CORRECTION 2025-12-16: Optimisation des performances lors de la création de produits
-- Problèmes identifiés:
-- 1. Requête get_services_for_prestataire prend 1+ seconde (même avec index)
-- 2. Refresh de vue matérialisée prend 5-10 secondes
-- 3. Fonction refresh_services_search_optimized() prend 10.8 secondes

-- =====================================================
-- 1. Vérifier et créer index composite pour services
-- =====================================================

-- Index composite pour optimiser get_services_for_prestataire
-- La requête: SELECT id, data, is_active, created_at FROM services WHERE user_id = $1 ORDER BY created_at DESC
CREATE INDEX IF NOT EXISTS idx_services_user_id_created_at_desc_optimized_v2
ON services (user_id, created_at DESC)
WHERE is_active = TRUE;

-- Index partiel pour services actifs par utilisateur (optimise encore plus)
CREATE INDEX IF NOT EXISTS idx_services_user_id_active_created_at_desc
ON services (user_id, created_at DESC)
WHERE is_active = TRUE;

-- =====================================================
-- 2. Optimiser la vue matérialisée services_search_optimized
-- =====================================================

-- ✅ OPTIMISÉ: Utiliser autocomplete_characteristics au lieu de extract_all_product_text()
-- Le problème: extract_all_product_text() est récursif et très lent (10+ secondes)
-- Solution: Utiliser autocomplete_characteristics.full_vector qui est déjà indexé

-- D'abord, créer une version optimisée de la vue
DROP MATERIALIZED VIEW IF EXISTS services_search_optimized_v2 CASCADE;

CREATE MATERIALIZED VIEW services_search_optimized_v2 AS
SELECT 
    s.id as service_id,
    s.user_id,
    s.data,
    s.is_active,
    s.category,
    s.gps,
    s.created_at,
    -- Pré-calculer le tsvector pour recherche full-text (rapide)
    to_tsvector('french', 
        COALESCE(s.data->'titre_service'->>'valeur', '') || ' ' ||
        COALESCE(s.data->'description'->>'valeur', '') || ' ' ||
        COALESCE(s.category, '')
    ) as search_vector,
    -- ✅ OPTIMISÉ: Utiliser autocomplete_characteristics.full_vector au lieu de extract_all_product_text()
    -- C'est 10-20x plus rapide car full_vector est déjà indexé avec GIN
    COALESCE((
        SELECT string_agg(unnest_val, ' ')
        FROM (
            SELECT DISTINCT unnest_val
            FROM autocomplete_characteristics ac
            CROSS JOIN LATERAL unnest(ac.full_vector) AS unnest_val
            WHERE ac.service_id = s.id
            AND ac.identifiant_base = 'produits'
            AND ac.is_real_product = TRUE
        ) AS product_terms
    ), '') as products_text,
    -- ✅ OPTIMISÉ: Pré-calculer le tsvector produits depuis autocomplete_characteristics
    to_tsvector('french', 
        COALESCE((
            SELECT string_agg(unnest_val, ' ')
            FROM (
                SELECT DISTINCT unnest_val
                FROM autocomplete_characteristics ac
                CROSS JOIN LATERAL unnest(ac.full_vector) AS unnest_val
                WHERE ac.service_id = s.id
                AND ac.identifiant_base = 'produits'
                AND ac.is_real_product = TRUE
            ) AS product_terms
        ), '')
    ) as products_vector
FROM services s
WHERE s.is_active = TRUE;

-- Index GIN sur tsvector (ultra-rapide)
CREATE INDEX IF NOT EXISTS idx_services_search_optimized_v2_vector
ON services_search_optimized_v2 USING GIN (search_vector);

CREATE INDEX IF NOT EXISTS idx_services_search_optimized_v2_products_vector
ON services_search_optimized_v2 USING GIN (products_vector);

-- Index composite pour filtres fréquents
CREATE INDEX IF NOT EXISTS idx_services_search_optimized_v2_category_active
ON services_search_optimized_v2 (category, is_active, created_at DESC)
WHERE is_active = TRUE;

-- ✅ CRITIQUE: Index unique pour permettre REFRESH CONCURRENTLY
CREATE UNIQUE INDEX IF NOT EXISTS idx_services_search_optimized_v2_unique
ON services_search_optimized_v2 (service_id);

-- =====================================================
-- 3. Fonction de refresh optimisée
-- =====================================================

-- ✅ OPTIMISÉ: Fonction de refresh qui utilise la nouvelle vue optimisée
CREATE OR REPLACE FUNCTION refresh_services_search_optimized()
RETURNS void AS $$
BEGIN
    -- ✅ OPTIMISÉ: Utiliser la vue v2 si elle existe, sinon utiliser l'ancienne
    IF EXISTS (SELECT 1 FROM pg_matviews WHERE matviewname = 'services_search_optimized_v2') THEN
        -- ✅ CORRECTION 2026-02-02: Créer l'index unique si nécessaire AVANT le refresh
        -- Le problème: REFRESH CONCURRENTLY nécessite un index unique sans clause WHERE
        IF NOT EXISTS (
            SELECT 1 FROM pg_indexes 
            WHERE tablename = 'services_search_optimized_v2' 
            AND indexname = 'idx_services_search_optimized_v2_unique'
        ) THEN
            -- Créer l'index unique requis pour REFRESH CONCURRENTLY
            CREATE UNIQUE INDEX IF NOT EXISTS idx_services_search_optimized_v2_unique
            ON services_search_optimized_v2 (service_id);
        END IF;
        
        REFRESH MATERIALIZED VIEW CONCURRENTLY services_search_optimized_v2;
    ELSIF EXISTS (SELECT 1 FROM pg_matviews WHERE matviewname = 'services_search_optimized') THEN
        REFRESH MATERIALIZED VIEW CONCURRENTLY services_search_optimized;
    END IF;
END;
$$ LANGUAGE plpgsql;

-- =====================================================
-- 4. Analyser les tables pour optimiser les plans d'exécution
-- =====================================================

ANALYZE services;
ANALYZE autocomplete_characteristics;

-- =====================================================
-- 5. Commentaires
-- =====================================================

COMMENT ON INDEX idx_services_user_id_created_at_desc_optimized_v2 IS 
'Index composite optimisé pour get_services_for_prestataire - accélère la requête WHERE user_id = $1 ORDER BY created_at DESC';

COMMENT ON MATERIALIZED VIEW services_search_optimized_v2 IS 
'Vue matérialisée optimisée utilisant autocomplete_characteristics au lieu de extract_all_product_text() - 10-20x plus rapide';








