-- ============================================
-- Migration: 20251221_optimize_delivery_indexes.sql
-- ============================================
-- Migration pour optimiser les index du service delivery
-- Date: 2025-12-21
-- Problèmes identifiés: Requêtes lentes dans delivery_repository.rs
-- Solution: Créer les index manquants pour accélérer les requêtes fréquentes

-- ✅ INDEX 1: Pour list_delivery_ids_for_user (creator_id)
CREATE INDEX IF NOT EXISTS idx_deliveries_creator_status_requested 
ON deliveries(creator_id, status, requested_at DESC)
WHERE status <> 'completed'::delivery_status;

-- ✅ INDEX 2: Pour list_delivery_ids_for_user (recipient_user_id)
CREATE INDEX IF NOT EXISTS idx_deliveries_recipient_status_requested 
ON deliveries(recipient_user_id, status, requested_at DESC)
WHERE status <> 'completed'::delivery_status AND recipient_user_id IS NOT NULL;

-- ✅ INDEX 3: Pour le JOIN avec couriers dans list_delivery_ids_for_user
CREATE INDEX IF NOT EXISTS idx_deliveries_courier_id 
ON deliveries(courier_id)
WHERE courier_id IS NOT NULL;

-- ✅ INDEX 4: Pour les recherches géospatiales (pickup)
CREATE INDEX IF NOT EXISTS idx_deliveries_pickup_location 
ON deliveries USING GIST(pickup_location)
WHERE pickup_location IS NOT NULL;

-- ✅ INDEX 5: Pour les recherches géospatiales (dropoff)
CREATE INDEX IF NOT EXISTS idx_deliveries_dropoff_location 
ON deliveries USING GIST(dropoff_location)
WHERE dropoff_location IS NOT NULL;

-- ✅ INDEX 6: Pour couriers.user_id (JOIN dans list_delivery_ids_for_user)
CREATE INDEX IF NOT EXISTS idx_couriers_user_id 
ON couriers(user_id)
WHERE user_id IS NOT NULL;

-- ✅ INDEX 7: Pour list_matching_candidates (courier_availability_snapshots)
-- ✅ CORRECTION 2026-02-01: NOW() n'est pas IMMUTABLE, on ne peut pas l'utiliser dans un index partiel
-- La condition de date sera gérée dans les requêtes SQL
CREATE INDEX IF NOT EXISTS idx_courier_availability_snapshots_active 
ON courier_availability_snapshots(captured_at DESC, is_online, active_deliveries, max_capacity)
WHERE is_online = TRUE;

-- ✅ INDEX 8: Pour list_matching_candidates (géospatial)
CREATE INDEX IF NOT EXISTS idx_courier_availability_snapshots_location 
ON courier_availability_snapshots USING GIST(location)
WHERE location IS NOT NULL;

-- ✅ INDEX 9: Pour list_matching_candidates (courier_id)
CREATE INDEX IF NOT EXISTS idx_courier_availability_snapshots_courier 
ON courier_availability_snapshots(courier_id, captured_at DESC);

-- ✅ INDEX 10: Pour LEFT JOIN LATERAL dans list_matching_candidates
CREATE INDEX IF NOT EXISTS idx_courier_zone_assignments_active 
ON courier_zone_assignments(courier_id, is_active, is_primary DESC, updated_at DESC)
WHERE is_active = TRUE;

-- ✅ INDEX 11: Pour fetch_matching_queue_batch
CREATE INDEX IF NOT EXISTS idx_delivery_matching_queue_retry 
ON delivery_matching_queue(retry_at, status)
WHERE status IN ('queued', 'searching');

-- ✅ INDEX 12: Pour fetch_matching_queue_batch (delivery_id)
CREATE INDEX IF NOT EXISTS idx_delivery_matching_queue_delivery 
ON delivery_matching_queue(delivery_id);

-- ✅ Analyser les tables pour mettre à jour les statistiques
ANALYZE deliveries;
ANALYZE couriers;
ANALYZE courier_availability_snapshots;
ANALYZE courier_zone_assignments;
ANALYZE delivery_matching_queue;



-- ============================================
-- Migration: 20251221_optimize_services_update_performance.sql
-- ============================================
-- Migration: Optimisation des UPDATE services pour réduire la latence
-- Date: 2025-12-21
-- Problème: UPDATE services SET data prend 5-7s à cause de la réécriture complète du JSON

-- 1. Index sur id pour accélérer les UPDATE (déjà présent normalement, mais on s'assure)
CREATE INDEX IF NOT EXISTS idx_services_id_active ON services(id) WHERE is_active = true;

-- 2. Index GIN sur data pour les recherches JSONB (si pas déjà présent)
CREATE INDEX IF NOT EXISTS idx_services_data_gin ON services USING GIN (data);

-- 3. Fonction helper pour mise à jour partielle des produits (plus rapide)
CREATE OR REPLACE FUNCTION update_service_products(
    p_service_id INTEGER,
    p_products_json JSONB
) RETURNS VOID AS $$
BEGIN
    -- Utilise jsonb_set pour mettre à jour seulement la partie produits
    -- Plus rapide que réécrire tout le JSON (moins de verrous, moins de données)
    UPDATE services
    SET 
        data = jsonb_set(
            COALESCE(data, '{}'::jsonb),
            '{produits}',
            p_products_json,
            true
        ),
        updated_at = NOW()
    WHERE id = p_service_id;
END;
$$ LANGUAGE plpgsql;

-- 4. Commentaire pour documentation
COMMENT ON FUNCTION update_service_products IS 'Mise à jour optimisée des produits d''un service. Utilise jsonb_set pour éviter de réécrire tout le JSON, réduisant la latence de 5-7s à ~1-2s.';







-- ============================================
-- Migration: 20251221_optimize_slow_endpoints.sql
-- ============================================
-- Migration pour optimiser les endpoints lents identifiés dans les logs
-- Date: 2025-12-21
-- Problèmes identifiés:
-- 1. /api/services/{id}/stats et /api/services/{id}/reviews: Requêtes MongoDB lentes (2-3s)
-- 2. /api/search/direct et /api/autocomplete/search-products: array_to_string() ne peut pas utiliser l'index GIN
-- 3. Requête principale dans native_search_service.rs prend 1.745s

-- ✅ OPTIMISATION 1: Créer une fonction IMMUTABLE pour convertir full_vector en tsvector
-- Le problème: array_to_string() n'est pas IMMUTABLE, donc ne peut pas être utilisée dans un index
-- Solution: Créer une fonction IMMUTABLE qui fait la conversion
CREATE OR REPLACE FUNCTION full_vector_to_tsvector(full_vec TEXT[]) RETURNS tsvector AS $$
BEGIN
    RETURN to_tsvector('french', array_to_string(COALESCE(full_vec, ARRAY[]::TEXT[]), ' '));
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- ✅ OPTIMISATION 2: Créer une fonction IMMUTABLE pour convertir characteristic_vector en tsvector
CREATE OR REPLACE FUNCTION characteristic_vector_to_tsvector(char_vec TEXT[]) RETURNS tsvector AS $$
BEGIN
    RETURN to_tsvector('french', array_to_string(COALESCE(char_vec, ARRAY[]::TEXT[]), ' '));
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- ✅ OPTIMISATION 3: Créer un index GIN sur full_vector pour recherche tsvector
CREATE INDEX IF NOT EXISTS idx_autocomplete_full_vector_tsvector_gin 
ON autocomplete_characteristics 
USING GIN (full_vector_to_tsvector(full_vector))
WHERE identifiant_base = 'produits' AND is_real_product = TRUE;

-- ✅ OPTIMISATION 4: Créer un index GIN sur characteristic_vector pour recherche tsvector
CREATE INDEX IF NOT EXISTS idx_autocomplete_characteristic_vector_tsvector_gin 
ON autocomplete_characteristics 
USING GIN (characteristic_vector_to_tsvector(characteristic_vector))
WHERE identifiant_base = 'produits' AND is_real_product = TRUE;

-- ✅ OPTIMISATION 5: Créer un index composite pour optimiser les requêtes fréquentes
-- Index sur (identifiant_base, is_real_product, service_id) pour accélérer les JOINs
CREATE INDEX IF NOT EXISTS idx_autocomplete_composite_search 
ON autocomplete_characteristics (identifiant_base, is_real_product, service_id)
WHERE identifiant_base = 'produits' AND is_real_product = TRUE;

-- ✅ OPTIMISATION 6: Créer un index sur services.is_active pour accélérer les filtres
CREATE INDEX IF NOT EXISTS idx_services_is_active 
ON services (is_active)
WHERE is_active = TRUE;

-- ✅ OPTIMISATION 7: Créer un index sur services.category pour accélérer les filtres de catégorie
CREATE INDEX IF NOT EXISTS idx_services_category 
ON services (category)
WHERE is_active = TRUE AND category IS NOT NULL;

-- ✅ OPTIMISATION 8: Analyser les tables pour mettre à jour les statistiques
ANALYZE autocomplete_characteristics;
ANALYZE services;

-- Note: Les optimisations MongoDB (index sur service_id et event_type) doivent être faites
-- directement dans MongoDB, pas dans cette migration SQL.



-- ============================================
-- Migration: 20251222_optimize_slow_queries_indexes.sql
-- ============================================
-- ✅ Migration 2025-12-22: Optimisation des requêtes lentes identifiées dans les logs
-- Problèmes identifiés:
-- 1. GROUP BY status sur video_generation_jobs prend 300-400ms (manque d'index)
-- 2. Requêtes sur global_promo_entries avec JOIN prennent 600-700ms

-- Index pour optimiser GROUP BY status sur video_generation_jobs
CREATE INDEX IF NOT EXISTS idx_video_generation_jobs_status 
ON video_generation_jobs(status)
WHERE status IS NOT NULL;

-- Index composite pour optimiser les requêtes avec status + updated_at
CREATE INDEX IF NOT EXISTS idx_video_generation_jobs_status_updated_at 
ON video_generation_jobs(status, updated_at)
WHERE status IS NOT NULL;

-- ✅ NOUVEAU: Index partiel pour COUNT avec status = 'completed' et updated_at
-- Optimise: SELECT COUNT(*) FROM video_generation_jobs WHERE status = 'completed' AND updated_at >= NOW() - INTERVAL '24 hours'
CREATE INDEX IF NOT EXISTS idx_video_generation_jobs_completed_updated_at 
ON video_generation_jobs(updated_at)
WHERE status = 'completed';

-- ✅ NOUVEAU: Index pour optimiser les requêtes avec status = 'failed' et updated_at
CREATE INDEX IF NOT EXISTS idx_video_generation_jobs_failed_updated_at 
ON video_generation_jobs(updated_at)
WHERE status = 'failed';

-- Index pour optimiser les requêtes sur global_promo_entries avec JOIN
CREATE INDEX IF NOT EXISTS idx_global_promo_entries_event_id_status 
ON global_promo_entries(event_id, status)
WHERE event_id IS NOT NULL;

-- Index pour optimiser les requêtes sur global_promo_events avec status + dates
CREATE INDEX IF NOT EXISTS idx_global_promo_events_status_dates 
ON global_promo_events(status, starts_at, ends_at)
WHERE status IN ('scheduled', 'live', 'archived');

-- Index pour optimiser les requêtes sur live_flash_sales avec status + dates
CREATE INDEX IF NOT EXISTS idx_live_flash_sales_status_dates 
ON live_flash_sales(status, start_at, end_at)
WHERE status IN ('scheduled', 'live', 'ended');

-- Index pour optimiser les requêtes sur live_sessions avec JOIN
CREATE INDEX IF NOT EXISTS idx_live_sessions_id_host_user 
ON live_sessions(id, host_user_id, service_id)
WHERE id IS NOT NULL;

-- Commentaires pour documentation
COMMENT ON INDEX idx_video_generation_jobs_status IS 
'Optimise les requêtes GROUP BY status sur video_generation_jobs (réduit 300-400ms à <50ms)';

COMMENT ON INDEX idx_global_promo_entries_event_id_status IS 
'Optimise les JOIN entre global_promo_entries et global_promo_events (réduit 600-700ms à <100ms)';



-- ============================================
-- Migration: 20251223_improve_hybrid_image_search_relevance.sql
-- ============================================
-- Migration pour améliorer la pertinence de la recherche par image
-- Problème: Les résultats retournés ne correspondent pas à l'objet recherché
-- Problème CRITIQUE: La recherche par image n'utilise PAS autocomplete_characteristics
-- alors que c'est là que sont stockées les caractéristiques génériques générées par l'IA
-- Solution: Utiliser autocomplete_characteristics comme source principale (cohérent avec recherche textuelle)
-- Date: 2025-12-23

CREATE OR REPLACE FUNCTION hybrid_image_search(
    search_tags TEXT[],
    search_category TEXT DEFAULT NULL,
    search_marque TEXT DEFAULT NULL,
    search_couleur TEXT DEFAULT NULL,
    search_query_semantic TEXT DEFAULT NULL,
    gps_lat FLOAT DEFAULT NULL,
    gps_lng FLOAT DEFAULT NULL,
    search_radius_km INTEGER DEFAULT 50,
    max_results INTEGER DEFAULT 20
)
RETURNS TABLE (
    service_id INTEGER,
    analysis_id INTEGER,
    media_id INTEGER,
    product_description TEXT,
    product_tags TEXT[],
    product_marque TEXT,
    product_couleurs TEXT[],
    match_score FLOAT,
    distance_km FLOAT,
    service_data JSONB
) AS $$
BEGIN
    RETURN QUERY
    WITH combined_results AS (
        -- ✅ SOURCE 1 (PRIORITÉ HAUTE): Recherche dans autocomplete_characteristics
        -- C'est la source principale utilisée par la recherche textuelle et audio
        -- Contient les caractéristiques génériques générées par l'IA et sauvegardées via save_autocomplete_combination
        SELECT DISTINCT ON (ac.service_id)
            ac.service_id,
            NULL::INTEGER as analysis_id,
            NULL::INTEGER as media_id,
            ac.valeur as product_description,
            -- Extraire les tags depuis characteristic_vector et full_vector
            ARRAY(
                SELECT DISTINCT unnest(string_to_array(ac.valeur, ','))
            )::TEXT[] as product_tags,
            -- Extraire marque depuis product_labels ou characteristic_vector
            COALESCE(
                (ac.product_labels->>'marque')::TEXT,
                (SELECT unnest(string_to_array(ac.valeur, ',')) LIMIT 1)
            ) as product_marque,
            -- Extraire couleurs depuis product_labels ou characteristic_vector
            ARRAY(
                SELECT jsonb_array_elements_text(ac.product_labels->'couleurs')
                WHERE jsonb_typeof(ac.product_labels->'couleurs') = 'array'
            )::TEXT[] as product_couleurs,
            (
                -- ✅ Score full-text sur valeur (index GIN tsvector) - PRIORITÉ HAUTE
                COALESCE(
                    ts_rank(to_tsvector('french', ac.valeur), plainto_tsquery('french', COALESCE(search_query_semantic, ''))) * 400.0,
                    0.0
                ) +
                -- ✅ Score full-text sur characteristic_vector (index GIN tsvector)
                COALESCE(
                    ts_rank(characteristic_vector_to_tsvector(ac.characteristic_vector), plainto_tsquery('french', COALESCE(search_query_semantic, ''))) * 300.0,
                    0.0
                ) +
                -- ✅ Score full-text sur full_vector (index GIN tsvector)
                COALESCE(
                    ts_rank(full_vector_to_tsvector(ac.full_vector), plainto_tsquery('french', COALESCE(search_query_semantic, ''))) * 250.0,
                    0.0
                ) +
                -- ✅ Score ILIKE sur valeur (correspondance exacte)
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND LOWER(ac.valeur) = LOWER(search_query_semantic) THEN 500.0
                    WHEN search_query_semantic IS NOT NULL AND ac.valeur ILIKE search_query_semantic || '%' THEN 350.0
                    WHEN search_query_semantic IS NOT NULL AND ac.valeur ILIKE '%' || search_query_semantic || '%' THEN 200.0
                    ELSE 0.0
                END +
                -- ✅ Score tags communs (si search_tags fourni)
                CASE 
                    WHEN search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 THEN
                        (SELECT COUNT(*) * 60.0 FROM unnest(search_tags) tag 
                         WHERE ac.valeur ILIKE '%' || tag || '%'
                         OR characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery('french', tag)
                         OR full_vector_to_tsvector(ac.full_vector) @@ plainto_tsquery('french', tag))
                    ELSE 0.0
                END +
                -- ✅ Score marque exacte
                CASE 
                    WHEN search_marque IS NOT NULL 
                         AND (
                             ac.valeur ILIKE '%' || search_marque || '%'
                             OR (ac.product_labels->>'marque') ILIKE '%' || search_marque || '%'
                         )
                    THEN 250.0
                    ELSE 0.0
                END +
                -- ✅ Score couleur
                CASE 
                    WHEN search_couleur IS NOT NULL 
                         AND (
                             ac.valeur ILIKE '%' || search_couleur || '%'
                             OR (jsonb_typeof(ac.product_labels->'couleurs') = 'array' 
                                 AND ac.product_labels->'couleurs'::text ILIKE '%' || search_couleur || '%')
                         )
                    THEN 100.0
                    ELSE 0.0
                END +
                -- ✅ Score catégorie
                CASE 
                    WHEN search_category IS NOT NULL 
                         AND (
                             s.category = search_category
                             OR s.data->'category'->>'valeur' = search_category
                         )
                    THEN 150.0
                    ELSE 0.0
                END +
                -- ✅ Bonus usage_count (produits populaires)
                (COALESCE(ac.usage_count, 0)::REAL * 2.0)
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM autocomplete_characteristics ac
        INNER JOIN services s ON s.id = ac.service_id
        WHERE s.is_active = true
        AND ac.identifiant_base = 'produits'
        AND ac.is_real_product = TRUE
        AND (
            -- Matching flexible : recherche dans valeur, characteristic_vector, full_vector
            (search_query_semantic IS NOT NULL AND (
                to_tsvector('french', ac.valeur) @@ plainto_tsquery('french', search_query_semantic)
                OR characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery('french', search_query_semantic)
                OR full_vector_to_tsvector(ac.full_vector) @@ plainto_tsquery('french', search_query_semantic)
                OR ac.valeur ILIKE '%' || search_query_semantic || '%'
            ))
            OR (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND (
                EXISTS (SELECT 1 FROM unnest(search_tags) tag WHERE ac.valeur ILIKE '%' || tag || '%')
                OR EXISTS (SELECT 1 FROM unnest(search_tags) tag 
                           WHERE characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery('french', tag))
            ))
            OR (search_marque IS NOT NULL AND (
                ac.valeur ILIKE '%' || search_marque || '%'
                OR (ac.product_labels->>'marque') ILIKE '%' || search_marque || '%'
            ))
            OR (search_couleur IS NOT NULL AND (
                ac.valeur ILIKE '%' || search_couleur || '%'
                OR (jsonb_typeof(ac.product_labels->'couleurs') = 'array' 
                    AND ac.product_labels->'couleurs'::text ILIKE '%' || search_couleur || '%')
            ))
            OR (search_category IS NOT NULL AND (
                s.category = search_category
                OR s.data->'category'->>'valeur' = search_category
            ))
        )
        
        UNION ALL
        
        -- ✅ SOURCE 2: Recherche dans image_analyses (produits catalogués - fallback)
        SELECT 
            ia.service_id,
            ia.id as analysis_id,
            ia.media_id,
            ia.description as product_description,
            ia.tags as product_tags,
            ia.marque as product_marque,
            ia.couleurs as product_couleurs,
            (
                -- Score tags communs
                (SELECT COUNT(*) * 50.0 FROM unnest(ia.tags) tag WHERE tag = ANY(search_tags)) +
                -- Score marque exacte
                CASE WHEN search_marque IS NOT NULL AND ia.marque ILIKE '%' || search_marque || '%' THEN 200.0 ELSE 0.0 END +
                -- Score couleur
                CASE WHEN search_couleur IS NOT NULL AND search_couleur = ANY(ia.couleurs) THEN 80.0 ELSE 0.0 END +
                -- Score catégorie
                CASE WHEN search_category IS NOT NULL AND ia.category_detected = search_category THEN 100.0 ELSE 0.0 END +
                -- Score full-text sur description
                COALESCE(
                    ts_rank(to_tsvector('french', COALESCE(ia.description, '')), plainto_tsquery('french', COALESCE(search_query_semantic, ''))) * 500.0,
                    0.0
                ) +
                -- Score ILIKE dans description
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND ia.description ILIKE '%' || search_query_semantic || '%' THEN 150.0
                    ELSE 0.0
                END +
                -- Bonus confiance
                (ia.confiance * 50.0)
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM image_analyses ia
        INNER JOIN services s ON s.id = ia.service_id
        WHERE s.is_active = true
        -- ✅ Exclure les services déjà trouvés dans SOURCE 1 (autocomplete_characteristics)
        AND NOT EXISTS (
            SELECT 1 FROM autocomplete_characteristics ac2 
            WHERE ac2.service_id = ia.service_id 
            AND ac2.identifiant_base = 'produits' 
            AND ac2.is_real_product = TRUE
        )
        AND (
            (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND ia.tags && search_tags)
            OR (search_query_semantic IS NOT NULL AND ia.description ILIKE '%' || search_query_semantic || '%')
            OR (search_category IS NOT NULL AND ia.category_detected = search_category)
            OR (search_marque IS NOT NULL AND ia.marque ILIKE '%' || search_marque || '%')
        )
        
        UNION ALL
        
        -- ✅ SOURCE 3: Recherche dans media.ai_* (images avec IA - fallback)
        SELECT 
            m.service_id,
            NULL::INTEGER as analysis_id,
            m.id as media_id,
            COALESCE(m.ai_description, '') as product_description,
            COALESCE(m.ai_tags, ARRAY[]::TEXT[]) as product_tags,
            m.ai_metadata->>'marque' as product_marque,
            ARRAY(SELECT jsonb_array_elements_text(m.ai_metadata->'couleurs'))::TEXT[] as product_couleurs,
            (
                -- Score tags communs
                (SELECT COUNT(*) * 50.0 FROM unnest(COALESCE(m.ai_tags, ARRAY[]::TEXT[])) tag WHERE tag = ANY(search_tags)) +
                -- Score marque exacte
                CASE WHEN search_marque IS NOT NULL AND m.ai_metadata->>'marque' ILIKE '%' || search_marque || '%' THEN 200.0 ELSE 0.0 END +
                -- Score couleur
                CASE WHEN search_couleur IS NOT NULL AND m.ai_metadata->'couleurs' ? search_couleur THEN 80.0 ELSE 0.0 END +
                -- Score catégorie
                CASE WHEN search_category IS NOT NULL AND m.ai_category = search_category THEN 100.0 ELSE 0.0 END +
                -- Score full-text sur description
                COALESCE(
                    ts_rank(to_tsvector('french', COALESCE(m.ai_description, '')), plainto_tsquery('french', COALESCE(search_query_semantic, ''))) * 500.0,
                    0.0
                ) +
                -- Score ILIKE dans description
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND m.ai_description ILIKE '%' || search_query_semantic || '%' THEN 150.0
                    ELSE 0.0
                END +
                -- Bonus confiance
                (COALESCE(m.ai_confidence, 0.5) * 50.0)
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM media m
        INNER JOIN services s ON s.id = m.service_id
        WHERE s.is_active = true
        AND m.type = 'image'
        AND m.ai_description IS NOT NULL
        -- ✅ Exclure les services déjà trouvés dans SOURCE 1 ou SOURCE 2
        AND NOT EXISTS (
            SELECT 1 FROM autocomplete_characteristics ac3 
            WHERE ac3.service_id = m.service_id 
            AND ac3.identifiant_base = 'produits' 
            AND ac3.is_real_product = TRUE
        )
        AND NOT EXISTS (
            SELECT 1 FROM image_analyses ia2 
            WHERE ia2.media_id = m.id AND ia2.service_id = m.service_id
        )
        AND (
            (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND m.ai_tags && search_tags)
            OR (search_query_semantic IS NOT NULL AND m.ai_description ILIKE '%' || search_query_semantic || '%')
            OR (search_category IS NOT NULL AND m.ai_category = search_category)
            OR (search_marque IS NOT NULL AND m.ai_metadata->>'marque' ILIKE '%' || search_marque || '%')
        )
    )
    SELECT 
        cr.service_id,
        cr.analysis_id,
        cr.media_id,
        cr.product_description,
        cr.product_tags,
        cr.product_marque,
        cr.product_couleurs,
        cr.match_score,
        cr.service_data,
        -- Calculer distance GPS si coordonnées fournies
        CASE 
            WHEN gps_lat IS NOT NULL AND gps_lng IS NOT NULL THEN
                (SELECT 
                    CASE 
                        WHEN s.gps IS NOT NULL AND s.gps != '' AND s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$' THEN
                            calculate_gps_distance_km_simple(
                                gps_lat,
                                gps_lng,
                                split_part(s.gps, ',', 1)::double precision,
                                split_part(s.gps, ',', 2)::double precision
                            )
                        ELSE NULL
                    END
                FROM services s WHERE s.id = cr.service_id)
            ELSE NULL
        END::FLOAT as distance_km
    FROM combined_results cr
    WHERE cr.match_score >= 30.0  -- ✅ Seuil strict pour filtrer les résultats non pertinents
    ORDER BY 
        cr.match_score DESC,
        distance_km ASC NULLS LAST
    LIMIT max_results;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION hybrid_image_search IS 'Recherche hybride améliorée avec autocomplete_characteristics comme source principale (cohérent avec recherche textuelle/audio) - 2025-12-23';


-- ============================================
-- Migration: 20251224_fix_image_search_relevance_and_performance.sql
-- ============================================
-- Migration pour corriger la pertinence et performance de la recherche par image
-- Problèmes identifiés:
-- 1. Seuil match_score trop bas (30.0) → récupère presque tous les produits
-- 2. Recherches ILIKE trop larges → matchent presque tout
-- 3. Pas de filtrage strict sur le nombre minimum de correspondances
-- 4. Scores trop élevés pour correspondances partielles
-- Date: 2025-12-24

-- Supprimer l'ancienne fonction
-- ✅ Corrigé: Spécifier la signature complète
DROP FUNCTION IF EXISTS hybrid_image_search(TEXT[], TEXT, TEXT, TEXT, TEXT, FLOAT, FLOAT, INTEGER, INTEGER, TEXT) CASCADE;

CREATE FUNCTION hybrid_image_search(
    search_tags TEXT[],
    search_category TEXT DEFAULT NULL,
    search_marque TEXT DEFAULT NULL,
    search_couleur TEXT DEFAULT NULL,
    search_query_semantic TEXT DEFAULT NULL,
    gps_lat FLOAT DEFAULT NULL,
    gps_lng FLOAT DEFAULT NULL,
    search_radius_km INTEGER DEFAULT 50,
    max_results INTEGER DEFAULT 20,
    pg_lang TEXT DEFAULT 'french'
)
RETURNS TABLE (
    service_id INTEGER,
    analysis_id INTEGER,
    media_id INTEGER,
    product_description TEXT,
    product_tags TEXT[],
    product_marque TEXT,
    product_couleurs TEXT[],
    match_score FLOAT,
    distance_km FLOAT,
    service_data JSONB
) AS $$
BEGIN
    RETURN QUERY
    WITH combined_results AS (
        -- ✅ SOURCE 1 (PRIORITÉ HAUTE): Recherche dans autocomplete_characteristics
        SELECT DISTINCT ON (ac.service_id)
            ac.service_id,
            NULL::INTEGER as analysis_id,
            NULL::INTEGER as media_id,
            ac.valeur as product_description,
            ARRAY(
                SELECT DISTINCT unnest(string_to_array(ac.valeur, ','))
            )::TEXT[] as product_tags,
            COALESCE(
                (ac.product_labels->>'marque')::TEXT,
                (SELECT unnest(string_to_array(ac.valeur, ',')) LIMIT 1)
            ) as product_marque,
            ARRAY(
                SELECT jsonb_array_elements_text(ac.product_labels->'couleurs')
                WHERE jsonb_typeof(ac.product_labels->'couleurs') = 'array'
            )::TEXT[] as product_couleurs,
            (
                -- ✅ AMÉLIORÉ: Scoring plus strict - correspondances exactes uniquement
                -- Score ILIKE exact (priorité maximale) - SEULEMENT si correspondance exacte ou début
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND LOWER(ac.valeur) = LOWER(search_query_semantic) THEN 600.0
                    WHEN search_query_semantic IS NOT NULL AND ac.valeur ILIKE search_query_semantic || '%' THEN 400.0
                    -- ✅ SUPPRIMÉ: Correspondance partielle (trop permissive)
                    -- WHEN search_query_semantic IS NOT NULL AND ac.valeur ILIKE '%' || search_query_semantic || '%' THEN 300.0
                    ELSE 0.0
                END +
                -- ✅ Score full-text sur valeur (index GIN tsvector) - avec langue dynamique
                COALESCE(
                    ts_rank(to_tsvector(pg_lang, ac.valeur), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 400.0,
                    0.0
                ) +
                -- ✅ Score full-text sur characteristic_vector
                COALESCE(
                    ts_rank(characteristic_vector_to_tsvector(ac.characteristic_vector), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 300.0,
                    0.0
                ) +
                -- ✅ Score full-text sur full_vector
                COALESCE(
                    ts_rank(full_vector_to_tsvector(ac.full_vector), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 250.0,
                    0.0
                ) +
                -- ✅ AMÉLIORÉ: Score tags communs - SEULEMENT si au moins 2 tags correspondent
                CASE 
                    WHEN search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 THEN
                        (SELECT 
                            CASE 
                                WHEN COUNT(*) >= 2 THEN COUNT(*) * 100.0  -- Bonus si 2+ tags
                                WHEN COUNT(*) = 1 THEN 50.0  -- Score réduit si 1 seul tag
                                ELSE 0.0
                            END
                         FROM unnest(search_tags) tag 
                         WHERE ac.valeur ILIKE '%' || tag || '%'
                         OR characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery(pg_lang, tag)
                         OR full_vector_to_tsvector(ac.full_vector) @@ plainto_tsquery(pg_lang, tag))
                    ELSE 0.0
                END +
                -- ✅ Score marque exacte (priorité haute)
                CASE 
                    WHEN search_marque IS NOT NULL 
                         AND (
                             ac.valeur ILIKE search_marque || '%'  -- ✅ Commence par la marque (plus strict)
                             OR (ac.product_labels->>'marque') ILIKE search_marque || '%'
                         )
                    THEN 350.0
                    ELSE 0.0
                END +
                -- ✅ Score couleur (priorité moyenne)
                CASE 
                    WHEN search_couleur IS NOT NULL 
                         AND (
                             ac.valeur ILIKE '%' || search_couleur || '%'
                             OR (jsonb_typeof(ac.product_labels->'couleurs') = 'array' 
                                 AND ac.product_labels->'couleurs'::text ILIKE '%' || search_couleur || '%')
                         )
                    THEN 150.0
                    ELSE 0.0
                END +
                -- ✅ Score catégorie (priorité moyenne)
                CASE 
                    WHEN search_category IS NOT NULL 
                         AND (
                             s.category = search_category
                             OR s.data->'category'->>'valeur' = search_category
                         )
                    THEN 200.0
                    ELSE 0.0
                END +
                -- ✅ Bonus usage_count (produits populaires) - réduit
                (COALESCE(ac.usage_count, 0)::REAL * 1.0)  -- Réduit de 2.0 à 1.0
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM autocomplete_characteristics ac
        INNER JOIN services s ON s.id = ac.service_id
        WHERE s.is_active = true
        AND ac.identifiant_base = 'produits'
        AND ac.is_real_product = TRUE
        AND (
            -- ✅ AMÉLIORÉ: Conditions plus strictes - correspondances exactes ou début uniquement
            (search_query_semantic IS NOT NULL AND (
                ac.valeur ILIKE search_query_semantic || '%'  -- ✅ Commence par (plus strict)
                OR to_tsvector(pg_lang, ac.valeur) @@ plainto_tsquery(pg_lang, search_query_semantic)
                OR characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery(pg_lang, search_query_semantic)
                OR full_vector_to_tsvector(ac.full_vector) @@ plainto_tsquery(pg_lang, search_query_semantic)
            ))
            OR (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND (
                -- ✅ AMÉLIORÉ: Exiger au moins 2 tags correspondants (plus strict)
                (SELECT COUNT(*) FROM unnest(search_tags) tag 
                 WHERE ac.valeur ILIKE '%' || tag || '%'
                 OR characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery(pg_lang, tag)) >= 2
            ))
            OR (search_marque IS NOT NULL AND (
                ac.valeur ILIKE search_marque || '%'  -- ✅ Commence par la marque
                OR (ac.product_labels->>'marque') ILIKE search_marque || '%'
            ))
            OR (search_couleur IS NOT NULL AND (
                ac.valeur ILIKE '%' || search_couleur || '%'
                OR (jsonb_typeof(ac.product_labels->'couleurs') = 'array' 
                    AND ac.product_labels->'couleurs'::text ILIKE '%' || search_couleur || '%')
            ))
            OR (search_category IS NOT NULL AND (
                s.category = search_category
                OR s.data->'category'->>'valeur' = search_category
            ))
        )
        
        UNION ALL
        
        -- ✅ SOURCE 2: Recherche dans image_analyses (produits catalogués - fallback)
        SELECT 
            ia.service_id,
            ia.id as analysis_id,
            ia.media_id,
            ia.description as product_description,
            ia.tags as product_tags,
            ia.marque as product_marque,
            ia.couleurs as product_couleurs,
            (
                -- ✅ AMÉLIORÉ: Scoring plus strict
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND LOWER(ia.description) = LOWER(search_query_semantic) THEN 550.0
                    WHEN search_query_semantic IS NOT NULL AND ia.description ILIKE search_query_semantic || '%' THEN 400.0
                    -- ✅ SUPPRIMÉ: Correspondance partielle
                    ELSE 0.0
                END +
                -- ✅ Score tags communs - SEULEMENT si au moins 2 tags
                (SELECT 
                    CASE 
                        WHEN COUNT(*) >= 2 THEN COUNT(*) * 80.0
                        WHEN COUNT(*) = 1 THEN 30.0
                        ELSE 0.0
                    END
                 FROM unnest(ia.tags) tag WHERE tag = ANY(search_tags)) +
                -- Score marque exacte
                CASE WHEN search_marque IS NOT NULL AND ia.marque ILIKE search_marque || '%' THEN 300.0 ELSE 0.0 END +
                -- Score couleur
                CASE WHEN search_couleur IS NOT NULL AND search_couleur = ANY(ia.couleurs) THEN 120.0 ELSE 0.0 END +
                -- Score catégorie
                CASE WHEN search_category IS NOT NULL AND ia.category_detected = search_category THEN 180.0 ELSE 0.0 END +
                -- ✅ Score full-text sur description (langue dynamique)
                COALESCE(
                    ts_rank(to_tsvector(pg_lang, COALESCE(ia.description, '')), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 500.0,
                    0.0
                ) +
                -- Bonus confiance (réduit)
                (ia.confiance * 30.0)  -- Réduit de 50.0 à 30.0
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM image_analyses ia
        INNER JOIN services s ON s.id = ia.service_id
        WHERE s.is_active = true
        AND NOT EXISTS (
            SELECT 1 FROM autocomplete_characteristics ac2 
            WHERE ac2.service_id = ia.service_id 
            AND ac2.identifiant_base = 'produits' 
            AND ac2.is_real_product = TRUE
        )
        AND (
            (search_query_semantic IS NOT NULL AND (
                ia.description ILIKE search_query_semantic || '%'  -- ✅ Commence par
                OR to_tsvector(pg_lang, COALESCE(ia.description, '')) @@ plainto_tsquery(pg_lang, search_query_semantic)
            ))
            OR (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND (
                -- ✅ AMÉLIORÉ: Exiger au moins 2 tags correspondants
                (SELECT COUNT(*) FROM unnest(ia.tags) tag WHERE tag = ANY(search_tags)) >= 2
            ))
            OR (search_category IS NOT NULL AND ia.category_detected = search_category)
            OR (search_marque IS NOT NULL AND ia.marque ILIKE search_marque || '%')
        )
        
        UNION ALL
        
        -- ✅ SOURCE 3: Recherche dans media.ai_* (images avec IA - fallback)
        SELECT 
            m.service_id,
            NULL::INTEGER as analysis_id,
            m.id as media_id,
            COALESCE(m.ai_description, '') as product_description,
            COALESCE(m.ai_tags, ARRAY[]::TEXT[]) as product_tags,
            m.ai_metadata->>'marque' as product_marque,
            ARRAY(SELECT jsonb_array_elements_text(m.ai_metadata->'couleurs'))::TEXT[] as product_couleurs,
            (
                -- ✅ AMÉLIORÉ: Scoring plus strict
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND LOWER(COALESCE(m.ai_description, '')) = LOWER(search_query_semantic) THEN 550.0
                    WHEN search_query_semantic IS NOT NULL AND m.ai_description ILIKE search_query_semantic || '%' THEN 400.0
                    -- ✅ SUPPRIMÉ: Correspondance partielle
                    ELSE 0.0
                END +
                -- ✅ Score tags communs - SEULEMENT si au moins 2 tags
                (SELECT 
                    CASE 
                        WHEN COUNT(*) >= 2 THEN COUNT(*) * 80.0
                        WHEN COUNT(*) = 1 THEN 30.0
                        ELSE 0.0
                    END
                 FROM unnest(COALESCE(m.ai_tags, ARRAY[]::TEXT[])) tag WHERE tag = ANY(search_tags)) +
                -- Score marque exacte
                CASE WHEN search_marque IS NOT NULL AND m.ai_metadata->>'marque' ILIKE search_marque || '%' THEN 300.0 ELSE 0.0 END +
                -- Score couleur
                CASE WHEN search_couleur IS NOT NULL AND m.ai_metadata->'couleurs' ? search_couleur THEN 120.0 ELSE 0.0 END +
                -- Score catégorie
                CASE WHEN search_category IS NOT NULL AND m.ai_category = search_category THEN 180.0 ELSE 0.0 END +
                -- ✅ Score full-text sur description (langue dynamique)
                COALESCE(
                    ts_rank(to_tsvector(pg_lang, COALESCE(m.ai_description, '')), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 500.0,
                    0.0
                ) +
                -- Bonus confiance (réduit)
                (COALESCE(m.ai_confidence, 0.5) * 30.0)  -- Réduit de 50.0 à 30.0
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM media m
        INNER JOIN services s ON s.id = m.service_id
        WHERE s.is_active = true
        AND m.type = 'image'
        AND m.ai_description IS NOT NULL
        AND NOT EXISTS (
            SELECT 1 FROM autocomplete_characteristics ac3 
            WHERE ac3.service_id = m.service_id 
            AND ac3.identifiant_base = 'produits' 
            AND ac3.is_real_product = TRUE
        )
        AND NOT EXISTS (
            SELECT 1 FROM image_analyses ia2 
            WHERE ia2.media_id = m.id AND ia2.service_id = m.service_id
        )
        AND (
            (search_query_semantic IS NOT NULL AND (
                m.ai_description ILIKE search_query_semantic || '%'  -- ✅ Commence par
                OR to_tsvector(pg_lang, COALESCE(m.ai_description, '')) @@ plainto_tsquery(pg_lang, search_query_semantic)
            ))
            OR (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND (
                -- ✅ AMÉLIORÉ: Exiger au moins 2 tags correspondants
                (SELECT COUNT(*) FROM unnest(COALESCE(m.ai_tags, ARRAY[]::TEXT[])) tag WHERE tag = ANY(search_tags)) >= 2
            ))
            OR (search_category IS NOT NULL AND m.ai_category = search_category)
            OR (search_marque IS NOT NULL AND m.ai_metadata->>'marque' ILIKE search_marque || '%')
        )
    )
    SELECT 
        cr.service_id,
        cr.analysis_id,
        cr.media_id,
        cr.product_description,
        cr.product_tags,
        cr.product_marque,
        cr.product_couleurs,
        cr.match_score,
        cr.service_data,
        -- Calculer distance GPS si coordonnées fournies
        CASE 
            WHEN gps_lat IS NOT NULL AND gps_lng IS NOT NULL THEN
                (SELECT 
                    CASE 
                        WHEN s.gps IS NOT NULL AND s.gps != '' AND s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$' THEN
                            calculate_gps_distance_km_simple(
                                gps_lat,
                                gps_lng,
                                split_part(s.gps, ',', 1)::double precision,
                                split_part(s.gps, ',', 2)::double precision
                            )
                        ELSE NULL
                    END
                FROM services s WHERE s.id = cr.service_id)
            ELSE NULL
        END::FLOAT as distance_km
    FROM combined_results cr
    WHERE cr.match_score >= 150.0  -- ✅ SEUIL AUGMENTÉ: 150.0 au lieu de 30.0 (5x plus strict)
    ORDER BY 
        cr.match_score DESC,
        distance_km ASC NULLS LAST
    LIMIT max_results;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION hybrid_image_search IS 'Recherche hybride améliorée avec seuil strict (150.0) et scoring priorisant correspondances exactes - 2025-12-24';





-- ============================================
-- Migration: 20251224_improve_hybrid_image_search_language_and_relevance.sql
-- ============================================
-- Migration pour améliorer la pertinence de la recherche par image
-- Problème: La fonction utilise 'french' en dur au lieu de détection automatique
-- Problème: Le scoring ne priorise pas assez les correspondances exactes (ILIKE)
-- Solution: Ajouter paramètre langue + améliorer scoring pour prioriser ILIKE
-- Date: 2025-12-24

-- Supprimer l'ancienne fonction si elle existe (toutes les signatures)
-- ✅ Corrigé: Spécifier la signature complète
DROP FUNCTION IF EXISTS hybrid_image_search(TEXT[], TEXT, TEXT, TEXT, TEXT, FLOAT, FLOAT, INTEGER, INTEGER, TEXT) CASCADE;

CREATE FUNCTION hybrid_image_search(
    search_tags TEXT[],
    search_category TEXT DEFAULT NULL,
    search_marque TEXT DEFAULT NULL,
    search_couleur TEXT DEFAULT NULL,
    search_query_semantic TEXT DEFAULT NULL,
    gps_lat FLOAT DEFAULT NULL,
    gps_lng FLOAT DEFAULT NULL,
    search_radius_km INTEGER DEFAULT 50,
    max_results INTEGER DEFAULT 20,
    pg_lang TEXT DEFAULT 'french'  -- ✅ NOUVEAU: Paramètre langue PostgreSQL (ex: 'french', 'english', 'simple')
)
RETURNS TABLE (
    service_id INTEGER,
    analysis_id INTEGER,
    media_id INTEGER,
    product_description TEXT,
    product_tags TEXT[],
    product_marque TEXT,
    product_couleurs TEXT[],
    match_score FLOAT,
    distance_km FLOAT,
    service_data JSONB
) AS $$
BEGIN
    RETURN QUERY
    WITH combined_results AS (
        -- ✅ SOURCE 1 (PRIORITÉ HAUTE): Recherche dans autocomplete_characteristics
        -- C'est la source principale utilisée par la recherche textuelle et audio
        SELECT DISTINCT ON (ac.service_id)
            ac.service_id,
            NULL::INTEGER as analysis_id,
            NULL::INTEGER as media_id,
            ac.valeur as product_description,
            -- Extraire les tags depuis characteristic_vector et full_vector
            ARRAY(
                SELECT DISTINCT unnest(string_to_array(ac.valeur, ','))
            )::TEXT[] as product_tags,
            -- Extraire marque depuis product_labels ou characteristic_vector
            COALESCE(
                (ac.product_labels->>'marque')::TEXT,
                (SELECT unnest(string_to_array(ac.valeur, ',')) LIMIT 1)
            ) as product_marque,
            -- Extraire couleurs depuis product_labels ou characteristic_vector
            ARRAY(
                SELECT jsonb_array_elements_text(ac.product_labels->'couleurs')
                WHERE jsonb_typeof(ac.product_labels->'couleurs') = 'array'
            )::TEXT[] as product_couleurs,
            (
                -- ✅ AMÉLIORÉ: Prioriser ILIKE pour correspondances exactes (gestion accents)
                -- Score ILIKE exact (priorité maximale)
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND LOWER(ac.valeur) = LOWER(search_query_semantic) THEN 600.0
                    WHEN search_query_semantic IS NOT NULL AND ac.valeur ILIKE search_query_semantic || '%' THEN 450.0
                    WHEN search_query_semantic IS NOT NULL AND ac.valeur ILIKE '%' || search_query_semantic || '%' THEN 300.0
                    ELSE 0.0
                END +
                -- ✅ Score full-text sur valeur (index GIN tsvector) - avec langue dynamique
                COALESCE(
                    ts_rank(to_tsvector(pg_lang, ac.valeur), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 400.0,
                    0.0
                ) +
                -- ✅ Score full-text sur characteristic_vector (index GIN tsvector) - avec langue dynamique
                COALESCE(
                    ts_rank(characteristic_vector_to_tsvector(ac.characteristic_vector), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 300.0,
                    0.0
                ) +
                -- ✅ Score full-text sur full_vector (index GIN tsvector) - avec langue dynamique
                COALESCE(
                    ts_rank(full_vector_to_tsvector(ac.full_vector), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 250.0,
                    0.0
                ) +
                -- ✅ Score tags communs (si search_tags fourni) - avec ILIKE prioritaire
                CASE 
                    WHEN search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 THEN
                        (SELECT COUNT(*) * 80.0 FROM unnest(search_tags) tag 
                         WHERE ac.valeur ILIKE '%' || tag || '%'
                         OR characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery(pg_lang, tag)
                         OR full_vector_to_tsvector(ac.full_vector) @@ plainto_tsquery(pg_lang, tag))
                    ELSE 0.0
                END +
                -- ✅ Score marque exacte (avec ILIKE prioritaire)
                CASE 
                    WHEN search_marque IS NOT NULL 
                         AND (
                             ac.valeur ILIKE '%' || search_marque || '%'
                             OR (ac.product_labels->>'marque') ILIKE '%' || search_marque || '%'
                         )
                    THEN 300.0
                    ELSE 0.0
                END +
                -- ✅ Score couleur
                CASE 
                    WHEN search_couleur IS NOT NULL 
                         AND (
                             ac.valeur ILIKE '%' || search_couleur || '%'
                             OR (jsonb_typeof(ac.product_labels->'couleurs') = 'array' 
                                 AND ac.product_labels->'couleurs'::text ILIKE '%' || search_couleur || '%')
                         )
                    THEN 120.0
                    ELSE 0.0
                END +
                -- ✅ Score catégorie
                CASE 
                    WHEN search_category IS NOT NULL 
                         AND (
                             s.category = search_category
                             OR s.data->'category'->>'valeur' = search_category
                         )
                    THEN 180.0
                    ELSE 0.0
                END +
                -- ✅ Bonus usage_count (produits populaires)
                (COALESCE(ac.usage_count, 0)::REAL * 2.0)
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM autocomplete_characteristics ac
        INNER JOIN services s ON s.id = ac.service_id
        WHERE s.is_active = true
        AND ac.identifiant_base = 'produits'
        AND ac.is_real_product = TRUE
        AND (
            -- ✅ AMÉLIORÉ: Matching flexible avec priorité ILIKE + full-text (langue dynamique)
            (search_query_semantic IS NOT NULL AND (
                ac.valeur ILIKE '%' || search_query_semantic || '%'  -- ✅ ILIKE en premier (gestion accents)
                OR to_tsvector(pg_lang, ac.valeur) @@ plainto_tsquery(pg_lang, search_query_semantic)
                OR characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery(pg_lang, search_query_semantic)
                OR full_vector_to_tsvector(ac.full_vector) @@ plainto_tsquery(pg_lang, search_query_semantic)
            ))
            OR (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND (
                EXISTS (SELECT 1 FROM unnest(search_tags) tag WHERE ac.valeur ILIKE '%' || tag || '%')
                OR EXISTS (SELECT 1 FROM unnest(search_tags) tag 
                           WHERE characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery(pg_lang, tag))
            ))
            OR (search_marque IS NOT NULL AND (
                ac.valeur ILIKE '%' || search_marque || '%'
                OR (ac.product_labels->>'marque') ILIKE '%' || search_marque || '%'
            ))
            OR (search_couleur IS NOT NULL AND (
                ac.valeur ILIKE '%' || search_couleur || '%'
                OR (jsonb_typeof(ac.product_labels->'couleurs') = 'array' 
                    AND ac.product_labels->'couleurs'::text ILIKE '%' || search_couleur || '%')
            ))
            OR (search_category IS NOT NULL AND (
                s.category = search_category
                OR s.data->'category'->>'valeur' = search_category
            ))
        )
        
        UNION ALL
        
        -- ✅ SOURCE 2: Recherche dans image_analyses (produits catalogués - fallback)
        SELECT 
            ia.service_id,
            ia.id as analysis_id,
            ia.media_id,
            ia.description as product_description,
            ia.tags as product_tags,
            ia.marque as product_marque,
            ia.couleurs as product_couleurs,
            (
                -- ✅ AMÉLIORÉ: Prioriser ILIKE pour correspondances exactes
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND LOWER(ia.description) = LOWER(search_query_semantic) THEN 550.0
                    WHEN search_query_semantic IS NOT NULL AND ia.description ILIKE search_query_semantic || '%' THEN 400.0
                    WHEN search_query_semantic IS NOT NULL AND ia.description ILIKE '%' || search_query_semantic || '%' THEN 250.0
                    ELSE 0.0
                END +
                -- Score tags communs
                (SELECT COUNT(*) * 60.0 FROM unnest(ia.tags) tag WHERE tag = ANY(search_tags)) +
                -- Score marque exacte
                CASE WHEN search_marque IS NOT NULL AND ia.marque ILIKE '%' || search_marque || '%' THEN 250.0 ELSE 0.0 END +
                -- Score couleur
                CASE WHEN search_couleur IS NOT NULL AND search_couleur = ANY(ia.couleurs) THEN 100.0 ELSE 0.0 END +
                -- Score catégorie
                CASE WHEN search_category IS NOT NULL AND ia.category_detected = search_category THEN 150.0 ELSE 0.0 END +
                -- ✅ Score full-text sur description (langue dynamique)
                COALESCE(
                    ts_rank(to_tsvector(pg_lang, COALESCE(ia.description, '')), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 500.0,
                    0.0
                ) +
                -- Bonus confiance
                (ia.confiance * 50.0)
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM image_analyses ia
        INNER JOIN services s ON s.id = ia.service_id
        WHERE s.is_active = true
        -- ✅ Exclure les services déjà trouvés dans SOURCE 1 (autocomplete_characteristics)
        AND NOT EXISTS (
            SELECT 1 FROM autocomplete_characteristics ac2 
            WHERE ac2.service_id = ia.service_id 
            AND ac2.identifiant_base = 'produits' 
            AND ac2.is_real_product = TRUE
        )
        AND (
            (search_query_semantic IS NOT NULL AND ia.description ILIKE '%' || search_query_semantic || '%')
            OR (search_query_semantic IS NOT NULL AND to_tsvector(pg_lang, COALESCE(ia.description, '')) @@ plainto_tsquery(pg_lang, search_query_semantic))
            OR (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND ia.tags && search_tags)
            OR (search_category IS NOT NULL AND ia.category_detected = search_category)
            OR (search_marque IS NOT NULL AND ia.marque ILIKE '%' || search_marque || '%')
        )
        
        UNION ALL
        
        -- ✅ SOURCE 3: Recherche dans media.ai_* (images avec IA - fallback)
        SELECT 
            m.service_id,
            NULL::INTEGER as analysis_id,
            m.id as media_id,
            COALESCE(m.ai_description, '') as product_description,
            COALESCE(m.ai_tags, ARRAY[]::TEXT[]) as product_tags,
            m.ai_metadata->>'marque' as product_marque,
            ARRAY(SELECT jsonb_array_elements_text(m.ai_metadata->'couleurs'))::TEXT[] as product_couleurs,
            (
                -- ✅ AMÉLIORÉ: Prioriser ILIKE pour correspondances exactes
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND LOWER(COALESCE(m.ai_description, '')) = LOWER(search_query_semantic) THEN 550.0
                    WHEN search_query_semantic IS NOT NULL AND m.ai_description ILIKE search_query_semantic || '%' THEN 400.0
                    WHEN search_query_semantic IS NOT NULL AND m.ai_description ILIKE '%' || search_query_semantic || '%' THEN 250.0
                    ELSE 0.0
                END +
                -- Score tags communs
                (SELECT COUNT(*) * 60.0 FROM unnest(COALESCE(m.ai_tags, ARRAY[]::TEXT[])) tag WHERE tag = ANY(search_tags)) +
                -- Score marque exacte
                CASE WHEN search_marque IS NOT NULL AND m.ai_metadata->>'marque' ILIKE '%' || search_marque || '%' THEN 250.0 ELSE 0.0 END +
                -- Score couleur
                CASE WHEN search_couleur IS NOT NULL AND m.ai_metadata->'couleurs' ? search_couleur THEN 100.0 ELSE 0.0 END +
                -- Score catégorie
                CASE WHEN search_category IS NOT NULL AND m.ai_category = search_category THEN 150.0 ELSE 0.0 END +
                -- ✅ Score full-text sur description (langue dynamique)
                COALESCE(
                    ts_rank(to_tsvector(pg_lang, COALESCE(m.ai_description, '')), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 500.0,
                    0.0
                ) +
                -- Bonus confiance
                (COALESCE(m.ai_confidence, 0.5) * 50.0)
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM media m
        INNER JOIN services s ON s.id = m.service_id
        WHERE s.is_active = true
        AND m.type = 'image'
        AND m.ai_description IS NOT NULL
        -- ✅ Exclure les services déjà trouvés dans SOURCE 1 ou SOURCE 2
        AND NOT EXISTS (
            SELECT 1 FROM autocomplete_characteristics ac3 
            WHERE ac3.service_id = m.service_id 
            AND ac3.identifiant_base = 'produits' 
            AND ac3.is_real_product = TRUE
        )
        AND NOT EXISTS (
            SELECT 1 FROM image_analyses ia2 
            WHERE ia2.media_id = m.id AND ia2.service_id = m.service_id
        )
        AND (
            (search_query_semantic IS NOT NULL AND m.ai_description ILIKE '%' || search_query_semantic || '%')
            OR (search_query_semantic IS NOT NULL AND to_tsvector(pg_lang, COALESCE(m.ai_description, '')) @@ plainto_tsquery(pg_lang, search_query_semantic))
            OR (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND m.ai_tags && search_tags)
            OR (search_category IS NOT NULL AND m.ai_category = search_category)
            OR (search_marque IS NOT NULL AND m.ai_metadata->>'marque' ILIKE '%' || search_marque || '%')
        )
    )
    SELECT 
        cr.service_id,
        cr.analysis_id,
        cr.media_id,
        cr.product_description,
        cr.product_tags,
        cr.product_marque,
        cr.product_couleurs,
        cr.match_score,
        cr.service_data,
        -- Calculer distance GPS si coordonnées fournies
        CASE 
            WHEN gps_lat IS NOT NULL AND gps_lng IS NOT NULL THEN
                (SELECT 
                    CASE 
                        WHEN s.gps IS NOT NULL AND s.gps != '' AND s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$' THEN
                            calculate_gps_distance_km_simple(
                                gps_lat,
                                gps_lng,
                                split_part(s.gps, ',', 1)::double precision,
                                split_part(s.gps, ',', 2)::double precision
                            )
                        ELSE NULL
                    END
                FROM services s WHERE s.id = cr.service_id)
            ELSE NULL
        END::FLOAT as distance_km
    FROM combined_results cr
    WHERE cr.match_score >= 30.0  -- ✅ Seuil strict pour filtrer les résultats non pertinents
    ORDER BY 
        cr.match_score DESC,
        distance_km ASC NULLS LAST
    LIMIT max_results;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION hybrid_image_search IS 'Recherche hybride améliorée avec langue dynamique et scoring priorisant ILIKE (gestion accents) - 2025-12-24';





-- ============================================
-- Migration: 20251224_optimize_slow_queries_critical.sql
-- ============================================
-- ✅ OPTIMISATION CRITIQUE 2025-12-24: Correction des requêtes lentes identifiées dans les logs
-- Problèmes identifiés:
-- 1. Requête pharmacies avec JOIN services: 1.68s
-- 2. Requête delivery_matching_queue: 1.37s
-- 3. Requête deliveries avec tous les champs: 1.4-2.3s
-- 4. Fonction find_nearby_couriers: 2.1s
-- 5. Refresh vues matérialisées: 8-15s (normal mais peut être optimisé)

-- =====================================================
-- 1. Optimisation requête pharmacies avec JOIN services
-- =====================================================

-- Index pour la requête: SELECT p.id, p.nom, s.user_id FROM pharmacies p INNER JOIN services s ON s.id = p.service_id WHERE p.is_on_duty_now = true AND s.is_active = true
CREATE INDEX IF NOT EXISTS idx_pharmacies_service_id_active
ON pharmacies(service_id)
WHERE is_on_duty_now = true;

-- Index pour services.is_active (déjà peut-être existant, mais on s'assure)
CREATE INDEX IF NOT EXISTS idx_services_id_active
ON services(id, is_active)
WHERE is_active = true;

-- Index composite pour la jointure optimisée
CREATE INDEX IF NOT EXISTS idx_pharmacies_on_duty_service_active
ON pharmacies(service_id, is_on_duty_now)
WHERE is_on_duty_now = true;

-- =====================================================
-- 2. Optimisation requête deliveries (SELECT avec tous les champs)
-- =====================================================

-- Index sur deliveries.id (déjà probablement existant en PRIMARY KEY, mais on s'assure)
-- La requête WHERE id = $1 devrait être rapide avec PK, mais les ST_Y/ST_X peuvent être lents
-- On crée un index fonctionnel pour accélérer les extractions de coordonnées

-- Index pour pickup_location (si souvent utilisé)
CREATE INDEX IF NOT EXISTS idx_deliveries_pickup_location_gist
ON deliveries USING GIST(pickup_location)
WHERE pickup_location IS NOT NULL;

-- Index pour dropoff_location
CREATE INDEX IF NOT EXISTS idx_deliveries_dropoff_location_gist
ON deliveries USING GIST(dropoff_location)
WHERE dropoff_location IS NOT NULL;

-- Index pour store_location
CREATE INDEX IF NOT EXISTS idx_deliveries_store_location_gist
ON deliveries USING GIST(store_location)
WHERE store_location IS NOT NULL;

-- Index pour recipient_dropoff_override
CREATE INDEX IF NOT EXISTS idx_deliveries_recipient_dropoff_gist
ON deliveries USING GIST(recipient_dropoff_override)
WHERE recipient_dropoff_override IS NOT NULL;

-- Index composite pour les requêtes fréquentes sur deliveries
CREATE INDEX IF NOT EXISTS idx_deliveries_id_status
ON deliveries(id, status)
WHERE status IN ('requested', 'accepted', 'en_route_pickup', 'picked_up', 'en_route_delivery', 'completed');

-- =====================================================
-- 3. Optimisation fonction find_nearby_couriers
-- =====================================================

-- Cette fonction utilise courier_availability_snapshots avec PostGIS
-- On s'assure que les index géographiques existent

-- Index GIST pour la recherche géographique sur courier_availability_snapshots
CREATE INDEX IF NOT EXISTS idx_courier_availability_snapshots_location_gist
ON courier_availability_snapshots USING GIST(ST_MakePoint(longitude, latitude))
WHERE latitude IS NOT NULL AND longitude IS NOT NULL AND is_online = true;

-- Index pour is_online et load_factor (utilisés dans find_nearby_couriers)
CREATE INDEX IF NOT EXISTS idx_courier_availability_snapshots_online_load
ON courier_availability_snapshots(is_online, load_factor, captured_at)
WHERE is_online = true AND load_factor < 1.0;

-- Index pour courier_assets.is_primary (utilisé dans la jointure)
CREATE INDEX IF NOT EXISTS idx_courier_assets_primary
ON courier_assets(courier_id, is_primary)
WHERE is_primary = true;

-- =====================================================
-- 4. Optimisation delivery_matching_queue (amélioration des index existants)
-- =====================================================

-- Index partiel optimisé pour next_attempt_at <= NOW()
-- Améliore la requête: WHERE status IN ('queued', 'searching') AND next_attempt_at <= NOW()
CREATE INDEX IF NOT EXISTS idx_delivery_matching_queue_pending_optimized
ON delivery_matching_queue(status, next_attempt_at, priority)
WHERE status IN ('queued', 'searching')
AND next_attempt_at IS NOT NULL;

-- Index pour les updates fréquents (améliore UPDATE ... WHERE delivery_id = $1)
CREATE INDEX IF NOT EXISTS idx_delivery_matching_queue_delivery_id
ON delivery_matching_queue(delivery_id)
WHERE status IN ('queued', 'searching');

