-- 7. Analyser les tables pour mettre à jour les statistiques
-- =====================================================
ANALYZE services;
ANALYZE autocomplete_characteristics;

-- =====================================================
-- 8. Vérification finale
-- =====================================================
DO $$
DECLARE
    idx_count INTEGER;
BEGIN
    -- Compter les index tsvector sur services
    SELECT COUNT(*) INTO idx_count
    FROM pg_indexes
    WHERE tablename = 'services'
    AND indexdef LIKE '%to_tsvector%';
    
    RAISE NOTICE '📊 Index tsvector sur services: %', idx_count;
    
    -- Compter les index tsvector sur autocomplete_characteristics
    SELECT COUNT(*) INTO idx_count
    FROM pg_indexes
    WHERE tablename = 'autocomplete_characteristics'
    AND indexdef LIKE '%to_tsvector%';
    
    RAISE NOTICE '📊 Index tsvector sur autocomplete_characteristics: %', idx_count;
    
    RAISE NOTICE '✅ Migration terminée - Tous les index nécessaires sont en place';
END $$;




-- ============================================
-- Migration: 20251227_fix_image_search_strict_matching.sql
-- ============================================
-- Migration pour corriger la pertinence de la recherche par image
-- Problèmes identifiés:
-- 1. Conditions WHERE trop permissives avec OR → matchent même avec un seul critère faible
-- 2. Scoring trop généreux → correspondance catégorie seule (200.0) dépasse seuil 150.0
-- 3. Pas de validation que les critères principaux (tags/query) sont remplis
-- 4. ⚠️ NOUVEAU 2025-12-27: Produits génériques (services, prestations) n'ont pas de marque/couleur
--    → La recherche par image doit fonctionner même sans marque/couleur
-- Solution: 
-- - Exiger correspondance sur tags OU query semantic + scoring plus strict
-- - Adapter pour produits génériques: 1 tag suffit (au lieu de 2), marque/couleur optionnels
-- Date: 2025-12-27

-- ✅ Corrigé: Spécifier la signature complète pour éviter "function name is not unique"
DROP FUNCTION IF EXISTS hybrid_image_search(TEXT[], TEXT, TEXT, TEXT, TEXT, FLOAT, FLOAT, INTEGER, INTEGER, TEXT) CASCADE;

CREATE FUNCTION hybrid_image_search(
    search_tags TEXT[],
    search_category TEXT DEFAULT NULL,
    search_marque TEXT DEFAULT NULL,
    search_couleur TEXT DEFAULT NULL,
    search_query_semantic TEXT DEFAULT NULL,
    gps_lat FLOAT DEFAULT NULL,
    gps_lng FLOAT DEFAULT NULL,
    search_radius_km INTEGER DEFAULT 50,
    max_results INTEGER DEFAULT 20,
    pg_lang TEXT DEFAULT 'french'
)
RETURNS TABLE (
    service_id INTEGER,
    analysis_id INTEGER,
    media_id INTEGER,
    product_description TEXT,
    product_tags TEXT[],
    product_marque TEXT,
    product_couleurs TEXT[],
    match_score FLOAT,
    distance_km FLOAT,
    service_data JSONB
) AS $$
BEGIN
    RETURN QUERY
    WITH combined_results AS (
        -- ✅ SOURCE 1 (PRIORITÉ HAUTE): Recherche dans autocomplete_characteristics
        SELECT DISTINCT ON (ac.service_id)
            ac.service_id,
            NULL::INTEGER as analysis_id,
            NULL::INTEGER as media_id,
            ac.valeur as product_description,
            ARRAY(
                SELECT DISTINCT unnest(string_to_array(ac.valeur, ','))
            )::TEXT[] as product_tags,
            COALESCE(
                (ac.product_labels->>'marque')::TEXT,
                (SELECT unnest(string_to_array(ac.valeur, ',')) LIMIT 1)
            ) as product_marque,
            ARRAY(
                SELECT jsonb_array_elements_text(ac.product_labels->'couleurs')
                WHERE jsonb_typeof(ac.product_labels->'couleurs') = 'array'
            )::TEXT[] as product_couleurs,
            (
                -- ✅ CRITIQUE: Scoring basé sur correspondances RÉELLES uniquement
                -- Score ILIKE exact (priorité maximale) - SEULEMENT si correspondance exacte ou début
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND LOWER(ac.valeur) = LOWER(search_query_semantic) THEN 600.0
                    WHEN search_query_semantic IS NOT NULL AND ac.valeur ILIKE search_query_semantic || '%' THEN 400.0
                    ELSE 0.0
                END +
                -- ✅ Score full-text sur valeur (index GIN tsvector) - avec langue dynamique
                COALESCE(
                    ts_rank(to_tsvector(pg_lang, ac.valeur), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 400.0,
                    0.0
                ) +
                -- ✅ Score full-text sur characteristic_vector
                COALESCE(
                    ts_rank(characteristic_vector_to_tsvector(ac.characteristic_vector), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 300.0,
                    0.0
                ) +
                -- ✅ Score full-text sur full_vector
                COALESCE(
                    ts_rank(full_vector_to_tsvector(ac.full_vector), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 250.0,
                    0.0
                ) +
                -- ✅ AMÉLIORÉ 2025-12-27: Score tags communs - 1 tag suffit pour produits génériques
                CASE 
                    WHEN search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 THEN
                        (SELECT 
                            CASE 
                                WHEN COUNT(*) >= 2 THEN COUNT(*) * 120.0  -- Bonus si 2+ tags
                                WHEN COUNT(*) = 1 THEN 60.0  -- Augmenté de 40.0 à 60.0 pour produits génériques
                                ELSE 0.0
                            END
                         FROM unnest(search_tags) tag 
                         WHERE ac.valeur ILIKE '%' || tag || '%'
                         OR characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery(pg_lang, tag)
                         OR full_vector_to_tsvector(ac.full_vector) @@ plainto_tsquery(pg_lang, tag))
                    ELSE 0.0
                END +
                -- ✅ Score marque exacte (priorité haute) - SEULEMENT si commence par
                CASE 
                    WHEN search_marque IS NOT NULL 
                         AND (
                             ac.valeur ILIKE search_marque || '%'
                             OR (ac.product_labels->>'marque') ILIKE search_marque || '%'
                         )
                    THEN 300.0
                    ELSE 0.0
                END +
                -- ✅ Score couleur (priorité moyenne) - réduit
                CASE 
                    WHEN search_couleur IS NOT NULL 
                         AND (
                             ac.valeur ILIKE '%' || search_couleur || '%'
                             OR (jsonb_typeof(ac.product_labels->'couleurs') = 'array' 
                                 AND ac.product_labels->'couleurs'::text ILIKE '%' || search_couleur || '%')
                         )
                    THEN 100.0  -- Réduit de 150.0 à 100.0
                    ELSE 0.0
                END +
                -- ✅ CRITIQUE: Score catégorie - SEULEMENT comme bonus, pas comme critère principal
                CASE 
                    WHEN search_category IS NOT NULL 
                         AND (
                             s.category = search_category
                             OR s.data->'category'->>'valeur' = search_category
                         )
                    THEN 50.0  -- Réduit de 200.0 à 50.0 (bonus seulement, pas critère principal)
                    ELSE 0.0
                END +
                -- ✅ Bonus usage_count (produits populaires) - réduit
                (COALESCE(ac.usage_count, 0)::REAL * 0.5)  -- Réduit de 1.0 à 0.5
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM autocomplete_characteristics ac
        INNER JOIN services s ON s.id = ac.service_id
        WHERE s.is_active = true
        AND ac.identifiant_base = 'produits'
        AND ac.is_real_product = TRUE
        AND (
            -- ✅ CRITIQUE 2025-12-27: Adapter pour produits génériques (sans marque/couleur)
            -- Les produits génériques (services, prestations) n'ont pas de marque/couleur
            -- Il faut permettre matching sur query semantic OU tags même sans marque/couleur
            (
                -- Option 1: Correspondance sur query semantic (description) - PRIORITAIRE pour produits génériques
                (search_query_semantic IS NOT NULL AND search_query_semantic != '' AND (
                    ac.valeur ILIKE search_query_semantic || '%'
                    OR to_tsvector(pg_lang, ac.valeur) @@ plainto_tsquery(pg_lang, search_query_semantic)
                    OR characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery(pg_lang, search_query_semantic)
                    OR full_vector_to_tsvector(ac.full_vector) @@ plainto_tsquery(pg_lang, search_query_semantic)
                ))
                -- Option 2: Correspondance sur au moins 1 tag (réduit de 2 à 1 pour produits génériques)
                -- ✅ AMÉLIORÉ: 1 tag suffit si le produit est générique (pas de marque/couleur)
                OR (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND (
                    (SELECT COUNT(*) FROM unnest(search_tags) tag 
                     WHERE ac.valeur ILIKE '%' || tag || '%'
                     OR characteristic_vector_to_tsvector(ac.characteristic_vector) @@ plainto_tsquery(pg_lang, tag)
                     OR full_vector_to_tsvector(ac.full_vector) @@ plainto_tsquery(pg_lang, tag)) >= 1
                ))
                -- Option 3: Correspondance marque exacte (SEULEMENT si marque fournie - produits spécifiques)
                -- ✅ AMÉLIORÉ: Ne pas exiger marque pour produits génériques
                OR (search_marque IS NOT NULL AND search_marque != '' AND (
                    ac.valeur ILIKE search_marque || '%'
                    OR (ac.product_labels->>'marque') ILIKE search_marque || '%'
                ))
            )
            -- ✅ Les critères secondaires (couleur, catégorie) sont des filtres additionnels, pas des critères principaux
            -- ✅ AMÉLIORÉ: Ne pas exclure les produits génériques qui n'ont pas de couleur
            AND (search_couleur IS NULL OR search_couleur = '' OR (
                ac.valeur ILIKE '%' || search_couleur || '%'
                OR (jsonb_typeof(ac.product_labels->'couleurs') = 'array' 
                    AND ac.product_labels->'couleurs'::text ILIKE '%' || search_couleur || '%')
            ))
            AND (search_category IS NULL OR search_category = '' OR (
                s.category = search_category
                OR s.data->'category'->>'valeur' = search_category
            ))
        )
        
        UNION ALL
        
        -- ✅ SOURCE 2: Recherche dans image_analyses (produits catalogués - fallback)
        SELECT 
            ia.service_id,
            ia.id as analysis_id,
            ia.media_id,
            ia.description as product_description,
            ia.tags as product_tags,
            ia.marque as product_marque,
            ia.couleurs as product_couleurs,
            (
                -- ✅ AMÉLIORÉ: Scoring plus strict
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND LOWER(ia.description) = LOWER(search_query_semantic) THEN 550.0
                    WHEN search_query_semantic IS NOT NULL AND ia.description ILIKE search_query_semantic || '%' THEN 400.0
                    ELSE 0.0
                END +
                -- ✅ Score tags communs - SEULEMENT si au moins 2 tags
                (SELECT 
                    CASE 
                        WHEN COUNT(*) >= 2 THEN COUNT(*) * 100.0  -- Augmenté de 80.0
                        WHEN COUNT(*) = 1 THEN 30.0
                        ELSE 0.0
                    END
                 FROM unnest(ia.tags) tag WHERE tag = ANY(search_tags)) +
                -- Score marque exacte
                CASE WHEN search_marque IS NOT NULL AND ia.marque ILIKE search_marque || '%' THEN 300.0 ELSE 0.0 END +
                -- Score couleur
                CASE WHEN search_couleur IS NOT NULL AND search_couleur = ANY(ia.couleurs) THEN 100.0 ELSE 0.0 END +
                -- ✅ Score catégorie - bonus seulement
                CASE WHEN search_category IS NOT NULL AND ia.category_detected = search_category THEN 50.0 ELSE 0.0 END +
                -- ✅ Score full-text sur description (langue dynamique)
                COALESCE(
                    ts_rank(to_tsvector(pg_lang, COALESCE(ia.description, '')), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 500.0,
                    0.0
                ) +
                -- Bonus confiance (réduit)
                (ia.confiance * 20.0)  -- Réduit de 30.0 à 20.0
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM image_analyses ia
        INNER JOIN services s ON s.id = ia.service_id
        WHERE s.is_active = true
        AND NOT EXISTS (
            SELECT 1 FROM autocomplete_characteristics ac2 
            WHERE ac2.service_id = ia.service_id 
            AND ac2.identifiant_base = 'produits' 
            AND ac2.is_real_product = TRUE
        )
        AND (
            -- ✅ CRITIQUE 2025-12-27: Adapter pour produits génériques (sans marque/couleur)
            (
                -- Option 1: Correspondance sur query semantic (description) - PRIORITAIRE pour produits génériques
                (search_query_semantic IS NOT NULL AND search_query_semantic != '' AND (
                    ia.description ILIKE search_query_semantic || '%'
                    OR to_tsvector(pg_lang, COALESCE(ia.description, '')) @@ plainto_tsquery(pg_lang, search_query_semantic)
                ))
                -- Option 2: Correspondance sur au moins 1 tag (réduit de 2 à 1 pour produits génériques)
                OR (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND (
                    (SELECT COUNT(*) FROM unnest(ia.tags) tag WHERE tag = ANY(search_tags)) >= 1
                ))
                -- Option 3: Correspondance marque exacte (SEULEMENT si marque fournie - produits spécifiques)
                OR (search_marque IS NOT NULL AND search_marque != '' AND ia.marque ILIKE search_marque || '%')
            )
            -- ✅ Les critères secondaires (couleur, catégorie) sont des filtres additionnels, pas des critères principaux
            AND (search_couleur IS NULL OR search_couleur = '' OR search_couleur = ANY(ia.couleurs))
            AND (search_category IS NULL OR search_category = '' OR ia.category_detected = search_category)
        )
        
        UNION ALL
        
        -- ✅ SOURCE 3: Recherche dans media.ai_* (images avec IA - fallback)
        SELECT 
            m.service_id,
            NULL::INTEGER as analysis_id,
            m.id as media_id,
            COALESCE(m.ai_description, '') as product_description,
            COALESCE(m.ai_tags, ARRAY[]::TEXT[]) as product_tags,
            m.ai_metadata->>'marque' as product_marque,
            ARRAY(SELECT jsonb_array_elements_text(m.ai_metadata->'couleurs'))::TEXT[] as product_couleurs,
            (
                -- ✅ AMÉLIORÉ: Scoring plus strict
                CASE 
                    WHEN search_query_semantic IS NOT NULL AND LOWER(COALESCE(m.ai_description, '')) = LOWER(search_query_semantic) THEN 550.0
                    WHEN search_query_semantic IS NOT NULL AND m.ai_description ILIKE search_query_semantic || '%' THEN 400.0
                    ELSE 0.0
                END +
                -- ✅ Score tags communs - AMÉLIORÉ: 1 tag suffit pour produits génériques
                (SELECT 
                    CASE 
                        WHEN COUNT(*) >= 2 THEN COUNT(*) * 100.0
                        WHEN COUNT(*) = 1 THEN 50.0  -- Augmenté de 30.0 à 50.0 pour produits génériques
                        ELSE 0.0
                    END
                 FROM unnest(COALESCE(m.ai_tags, ARRAY[]::TEXT[])) tag WHERE tag = ANY(search_tags)) +
                -- Score marque exacte
                CASE WHEN search_marque IS NOT NULL AND m.ai_metadata->>'marque' ILIKE search_marque || '%' THEN 300.0 ELSE 0.0 END +
                -- Score couleur
                CASE WHEN search_couleur IS NOT NULL AND m.ai_metadata->'couleurs' ? search_couleur THEN 100.0 ELSE 0.0 END +
                -- ✅ Score catégorie - bonus seulement
                CASE WHEN search_category IS NOT NULL AND m.ai_category = search_category THEN 50.0 ELSE 0.0 END +
                -- ✅ Score full-text sur description (langue dynamique)
                COALESCE(
                    ts_rank(to_tsvector(pg_lang, COALESCE(m.ai_description, '')), plainto_tsquery(pg_lang, COALESCE(search_query_semantic, ''))) * 500.0,
                    0.0
                ) +
                -- Bonus confiance (réduit)
                (COALESCE(m.ai_confidence, 0.5) * 20.0)  -- Réduit de 30.0 à 20.0
            )::FLOAT as match_score,
            NULL::FLOAT as distance_km,
            s.data as service_data
        FROM media m
        INNER JOIN services s ON s.id = m.service_id
        WHERE s.is_active = true
        AND m.type = 'image'
        AND m.ai_description IS NOT NULL
        AND NOT EXISTS (
            SELECT 1 FROM autocomplete_characteristics ac3 
            WHERE ac3.service_id = m.service_id 
            AND ac3.identifiant_base = 'produits' 
            AND ac3.is_real_product = TRUE
        )
        AND NOT EXISTS (
            SELECT 1 FROM image_analyses ia2 
            WHERE ia2.media_id = m.id AND ia2.service_id = m.service_id
        )
        AND (
            -- ✅ CRITIQUE: Même logique - exiger correspondance sur tags OU query semantic
            (
                (search_query_semantic IS NOT NULL AND search_query_semantic != '' AND (
                    m.ai_description ILIKE search_query_semantic || '%'
                    OR to_tsvector(pg_lang, COALESCE(m.ai_description, '')) @@ plainto_tsquery(pg_lang, search_query_semantic)
                ))
                -- Option 2: Correspondance sur au moins 1 tag (réduit de 2 à 1 pour produits génériques)
                OR (search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 AND (
                    (SELECT COUNT(*) FROM unnest(COALESCE(m.ai_tags, ARRAY[]::TEXT[])) tag WHERE tag = ANY(search_tags)) >= 1
                ))
                OR (search_marque IS NOT NULL AND search_marque != '' AND m.ai_metadata->>'marque' ILIKE search_marque || '%')
            )
            AND (search_couleur IS NULL OR search_couleur = '' OR m.ai_metadata->'couleurs' ? search_couleur)
            AND (search_category IS NULL OR search_category = '' OR m.ai_category = search_category)
        )
    )
    SELECT 
        cr.service_id,
        cr.analysis_id,
        cr.media_id,
        cr.product_description,
        cr.product_tags,
        cr.product_marque,
        cr.product_couleurs,
        cr.match_score,
        cr.service_data,
        -- Calculer distance GPS si coordonnées fournies
        CASE 
            WHEN gps_lat IS NOT NULL AND gps_lng IS NOT NULL THEN
                (SELECT 
                    CASE 
                        WHEN s.gps IS NOT NULL AND s.gps != '' AND s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$' THEN
                            calculate_gps_distance_km_simple(
                                gps_lat,
                                gps_lng,
                                split_part(s.gps, ',', 1)::double precision,
                                split_part(s.gps, ',', 2)::double precision
                            )
                        ELSE NULL
                    END
                FROM services s WHERE s.id = cr.service_id)
            ELSE NULL
        END::FLOAT as distance_km
    FROM combined_results cr
    WHERE cr.match_score >= 200.0  -- ✅ SEUIL AUGMENTÉ: 200.0 au lieu de 150.0 (plus strict)
    ORDER BY 
        cr.match_score DESC,
        distance_km ASC NULLS LAST
    LIMIT max_results;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION hybrid_image_search IS 'Recherche hybride avec matching strict: exige correspondance sur tags OU query semantic (catégorie seule insuffisante) - seuil 200.0 - 2025-12-27';



-- ============================================
-- Migration: 20251227_optimize_add_product_performance.sql
-- ============================================
-- Migration: Optimisation critique de l'ajout de produit pour éviter erreurs 500
-- Date: 2025-12-27
-- Problème: UPDATE services prend 7-12s, causant des timeouts et erreurs 500
-- Solution: Fonction PostgreSQL optimisée qui insère directement dans le tableau sans réécrire tout le JSONB

-- Fonction optimisée pour ajouter un produit directement au tableau produits.valeur
-- Utilise une seule requête UPDATE atomique, évitant les lectures multiples
CREATE OR REPLACE FUNCTION add_product_to_service_jsonb(
    p_service_id INTEGER,
    p_product_json JSONB
) RETURNS INTEGER AS $$
DECLARE
    v_product_index INTEGER;
BEGIN
    -- Calculer l'index AVANT l'UPDATE (0-based)
    SELECT COALESCE(jsonb_array_length(data->'produits'->'valeur'), 0)
    INTO v_product_index
    FROM services
    WHERE id = p_service_id;
    
    -- UPDATE atomique qui gère tous les cas en une seule opération
    UPDATE services
    SET 
        data = CASE
            -- Si produits.valeur existe déjà, ajouter au tableau avec ||
            WHEN data->'produits'->'valeur' IS NOT NULL THEN
                jsonb_set(
                    data,
                    '{produits,valeur}',
                    (data->'produits'->'valeur') || jsonb_build_array(p_product_json),
                    true
                )
            -- Si produits existe mais pas valeur, créer valeur
            WHEN data->'produits' IS NOT NULL THEN
                jsonb_set(
                    data,
                    '{produits,valeur}',
                    jsonb_build_array(p_product_json),
                    true
                )
            -- Si produits n'existe pas, créer toute la structure
            ELSE
                COALESCE(data, '{}'::jsonb) || jsonb_build_object(
                    'produits',
                    jsonb_build_object(
                        'type_donnee', 'autocomplete',
                        'valeur', jsonb_build_array(p_product_json),
                        'separateur', ',',
                        'sous_caracteristiques', '{}'::jsonb,
                        'filtrable', true,
                        'origine_champs', 'formulaire'
                    )
                )
        END,
        updated_at = NOW()
    WHERE id = p_service_id;
    
    -- Retourner l'index du produit (0-based)
    RETURN v_product_index;
END;
$$ LANGUAGE plpgsql;

-- Commentaire pour documentation
COMMENT ON FUNCTION add_product_to_service_jsonb IS 'Fonction optimisée pour ajouter un produit au service. Utilise une seule requête UPDATE atomique qui évite les lectures multiples et réduit les verrous, améliorant significativement les performances.';

