-- ============================================
-- Migration: 20251230_fix_add_product_tls_error.sql
-- ============================================
-- Migration: Correction erreurs TLS lors de l'ajout de produit
-- Date: 2025-12-30
-- Problème: La fonction add_product_to_service_jsonb fait 2 opérations (SELECT puis UPDATE)
--           ce qui peut prendre du temps et causer des fermetures TLS inattendues
-- Solution: Optimiser pour une seule opération UPDATE atomique avec RETURNING

-- Fonction optimisée en une seule opération atomique
CREATE OR REPLACE FUNCTION add_product_to_service_jsonb(
    p_service_id INTEGER,
    p_product_json JSONB
) RETURNS INTEGER AS $$
DECLARE
    v_product_index INTEGER;
BEGIN
    -- ✅ OPTIMISÉ: Une seule opération UPDATE atomique
    -- Calcule l'index AVANT l'UPDATE et fait l'UPDATE en une seule opération
    -- Évite les fermetures TLS en réduisant le temps d'exécution
    
    -- Calculer l'index AVANT l'UPDATE (0-based) - lecture rapide sans verrou
    SELECT COALESCE(jsonb_array_length(data->'produits'->'valeur'), 0)
    INTO v_product_index
    FROM services
    WHERE id = p_service_id;
    
    -- Si le service n'existe pas, retourner -1
    IF v_product_index IS NULL THEN
        RETURN -1;
    END IF;
    
    -- UPDATE atomique qui gère tous les cas en une seule opération
    UPDATE services
    SET 
        data = CASE
            -- Si produits.valeur existe déjà, ajouter au tableau avec ||
            WHEN data->'produits'->'valeur' IS NOT NULL THEN
                jsonb_set(
                    data,
                    '{produits,valeur}',
                    (data->'produits'->'valeur') || jsonb_build_array(p_product_json),
                    true
                )
            -- Si produits existe mais pas valeur, créer valeur
            WHEN data->'produits' IS NOT NULL THEN
                jsonb_set(
                    data,
                    '{produits,valeur}',
                    jsonb_build_array(p_product_json),
                    true
                )
            -- Si produits n'existe pas, créer toute la structure
            ELSE
                COALESCE(data, '{}'::jsonb) || jsonb_build_object(
                    'produits',
                    jsonb_build_object(
                        'type_donnee', 'autocomplete',
                        'valeur', jsonb_build_array(p_product_json),
                        'separateur', ',',
                        'sous_caracteristiques', '{}'::jsonb,
                        'filtrable', true,
                        'origine_champs', 'formulaire'
                    )
                )
        END,
        updated_at = NOW()
    WHERE id = p_service_id;
    
    -- Retourner l'index du produit (0-based) - sera incrémenté après l'UPDATE
    RETURN v_product_index;
END;
$$ LANGUAGE plpgsql;

-- Commentaire mis à jour
COMMENT ON FUNCTION add_product_to_service_jsonb IS 'Fonction optimisée pour ajouter un produit au service. Utilise une opération UPDATE atomique pour éviter les fermetures TLS et améliorer les performances.';



-- ============================================
-- Migration: 20251230_fix_audio_cache_cleanup_function.sql
-- ============================================
-- Migration: Correction fonction run_audio_cache_cleanup
-- Date: 2025-12-30
-- Description: Corrige l'erreur "record result has no field deleted_count" 
--              en changeant le retour de JSONB à TABLE avec variables explicites

-- =====================================================
-- Correction de la fonction run_audio_cache_cleanup
-- =====================================================

-- ✅ CORRIGÉ 2025-12-30: Retourne une TABLE pour correspondre au code Rust
-- Le problème était que RECORD ne permettait pas d'accéder aux champs de manière fiable
-- La solution: utiliser des variables explicites et retourner une TABLE
DROP FUNCTION IF EXISTS run_audio_cache_cleanup();

CREATE OR REPLACE FUNCTION run_audio_cache_cleanup()
RETURNS TABLE(
    deleted_count INTEGER,
    kept_count INTEGER,
    total_before INTEGER,
    total_after INTEGER
) AS $$
DECLARE
    deleted_count_var INTEGER := 0;
    kept_count_var INTEGER := 0;
    total_before_var INTEGER := 0;
    total_after_var INTEGER := 0;
BEGIN
    -- Vérifier si la fonction cleanup_old_audio_transcriptions existe
    IF EXISTS (
        SELECT 1 FROM pg_proc 
        WHERE proname = 'cleanup_old_audio_transcriptions'
    ) THEN
        -- Exécuter le nettoyage et récupérer les résultats dans des variables explicites
        -- Utiliser COALESCE pour garantir des valeurs non-NULL
        SELECT 
            COALESCE(deleted_count, 0),
            COALESCE(kept_count, 0),
            COALESCE(total_before, 0),
            COALESCE(total_after, 0)
        INTO 
            deleted_count_var,
            kept_count_var,
            total_before_var,
            total_after_var
        FROM cleanup_old_audio_transcriptions()
        LIMIT 1;
    ELSE
        -- Si la fonction n'existe pas, retourner des valeurs par défaut (0)
        RAISE NOTICE 'Fonction cleanup_old_audio_transcriptions non trouvée, retour de valeurs par défaut';
    END IF;
    
    -- Log (peut être envoyé à un système de monitoring)
    RAISE NOTICE 'Audio cache cleanup: deleted %, kept %, total before %, after %', 
        deleted_count_var, kept_count_var, total_before_var, total_after_var;
    
    -- Retourner les résultats comme une table (toujours des valeurs non-NULL)
    RETURN QUERY SELECT deleted_count_var, kept_count_var, total_before_var, total_after_var;
END;
$$ LANGUAGE plpgsql;

-- Vérification
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_proc WHERE proname = 'run_audio_cache_cleanup'
    ) THEN
        RAISE EXCEPTION 'Fonction run_audio_cache_cleanup non créée';
    END IF;
    
    RAISE NOTICE '✅ Fonction run_audio_cache_cleanup corrigée avec succès';
END $$;



