-- Migration: 20251231_fix_audio_cache_cleanup_null_handling.sql
-- ============================================
-- Migration: Correction gestion NULL dans run_audio_cache_cleanup
-- Date: 2025-12-31
-- Description: Corrige l'erreur UnexpectedNullError en gérant les valeurs NULL
--              et en vérifiant l'existence de cleanup_old_audio_transcriptions

-- =====================================================
-- Correction de la fonction run_audio_cache_cleanup pour gérer les NULL
-- =====================================================

CREATE OR REPLACE FUNCTION run_audio_cache_cleanup()
RETURNS TABLE(
    deleted_count INTEGER,
    kept_count INTEGER,
    total_before INTEGER,
    total_after INTEGER
) AS $$
DECLARE
    deleted_count_var INTEGER := 0;
    kept_count_var INTEGER := 0;
    total_before_var INTEGER := 0;
    total_after_var INTEGER := 0;
BEGIN
    -- Vérifier si la fonction cleanup_old_audio_transcriptions existe
    IF EXISTS (
        SELECT 1 FROM pg_proc 
        WHERE proname = 'cleanup_old_audio_transcriptions'
    ) THEN
        -- Exécuter le nettoyage et récupérer les résultats dans des variables explicites
        -- Utiliser COALESCE pour garantir des valeurs non-NULL
        SELECT 
            COALESCE(deleted_count, 0),
            COALESCE(kept_count, 0),
            COALESCE(total_before, 0),
            COALESCE(total_after, 0)
        INTO 
            deleted_count_var,
            kept_count_var,
            total_before_var,
            total_after_var
        FROM cleanup_old_audio_transcriptions()
        LIMIT 1;
    ELSE
        -- Si la fonction n'existe pas, retourner des valeurs par défaut (0)
        RAISE NOTICE 'Fonction cleanup_old_audio_transcriptions non trouvée, retour de valeurs par défaut';
    END IF;
    
    -- Log (peut être envoyé à un système de monitoring)
    RAISE NOTICE 'Audio cache cleanup: deleted %, kept %, total before %, after %', 
        deleted_count_var, kept_count_var, total_before_var, total_after_var;
    
    -- Retourner les résultats comme une table (toujours des valeurs non-NULL)
    RETURN QUERY SELECT deleted_count_var, kept_count_var, total_before_var, total_after_var;
END;
$$ LANGUAGE plpgsql;

-- Vérification
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_proc WHERE proname = 'run_audio_cache_cleanup'
    ) THEN
        RAISE EXCEPTION 'Fonction run_audio_cache_cleanup non créée';
    END IF;
    
    RAISE NOTICE '✅ Fonction run_audio_cache_cleanup corrigée avec gestion NULL';
END $$;




-- ============================================
-- Migration: 20251231_fix_product_creation_deadlock.sql
-- ============================================
-- Migration: Correction blocages (deadlock) dans add_product_to_service_jsonb_v2
-- Date: 2025-12-31
-- Problème: FOR UPDATE peut causer des blocages si plusieurs requêtes arrivent en même temps
-- Solution: Utiliser FOR UPDATE NOWAIT pour éviter les blocages longs, avec retry côté application

-- ============================================================================
-- 1. FONCTION OPTIMISÉE: Utilise FOR UPDATE NOWAIT pour éviter les blocages
-- ============================================================================
CREATE OR REPLACE FUNCTION add_product_to_service_jsonb_v2(
    p_service_id INTEGER,
    p_product_json JSONB
) RETURNS TABLE(
    product_index INTEGER,
    produits_data JSONB,
    lieu_data JSONB
) AS $$
DECLARE
    v_product_index INTEGER;
    v_produits_data JSONB;
    v_lieu_data JSONB;
    v_lock_acquired BOOLEAN := FALSE;
BEGIN
    -- ✅ CORRIGÉ 2025-12-31: Utiliser FOR UPDATE NOWAIT pour éviter les blocages
    -- Si le verrou ne peut pas être acquis immédiatement, retourner une erreur
    -- L'application fera un retry avec backoff
    BEGIN
        SELECT COALESCE(jsonb_array_length(data->'produits'->'valeur'), 0)
        INTO v_product_index
        FROM services
        WHERE id = p_service_id
        FOR UPDATE NOWAIT;  -- ✅ NOUVEAU: NOWAIT évite les blocages longs
        
        v_lock_acquired := TRUE;
    EXCEPTION
        WHEN lock_not_available THEN
            -- Le service est verrouillé par une autre transaction
            -- Retourner une erreur que l'application peut gérer avec un retry
            RAISE EXCEPTION 'Service % est actuellement verrouillé par une autre transaction. Veuillez réessayer dans quelques instants.', p_service_id;
    END;
    
    -- Si le service n'existe pas, retourner vide
    IF v_product_index IS NULL THEN
        RETURN;
    END IF;
    
    -- ✅ OPTIMISÉ: UPDATE atomique qui retourne les données nécessaires
    UPDATE services
    SET 
        data = CASE
            -- Si produits.valeur existe déjà, ajouter au tableau
            WHEN data->'produits'->'valeur' IS NOT NULL THEN
                jsonb_set(
                    data,
                    '{produits,valeur}',
                    (data->'produits'->'valeur') || jsonb_build_array(p_product_json),
                    true
                )
            -- Si produits existe mais pas valeur, créer valeur
            WHEN data->'produits' IS NOT NULL THEN
                jsonb_set(
                    data,
                    '{produits,valeur}',
                    jsonb_build_array(p_product_json),
                    true
                )
            -- Si produits n'existe pas, créer toute la structure
            ELSE
                COALESCE(data, '{}'::jsonb) || jsonb_build_object(
                    'produits',
                    jsonb_build_object(
                        'type_donnee', 'autocomplete',
                        'valeur', jsonb_build_array(p_product_json),
                        'separateur', ',',
                        'sous_caracteristiques', '{}'::jsonb,
                        'filtrable', true,
                        'origine_champs', 'formulaire'
                    )
                )
        END,
        updated_at = NOW()
    WHERE id = p_service_id
    RETURNING 
        data->'produits' as produits_data,
        data->'lieu_produit' as lieu_data
    INTO v_produits_data, v_lieu_data;
    
    -- Si aucun service n'a été mis à jour, retourner vide
    IF NOT FOUND THEN
        RETURN;
    END IF;
    
    -- Retourner les résultats
    product_index := v_product_index;
    produits_data := v_produits_data;
    lieu_data := v_lieu_data;
    
    RETURN NEXT;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION add_product_to_service_jsonb_v2 IS 'Fonction optimisée qui utilise FOR UPDATE NOWAIT pour éviter les blocages. Si le service est verrouillé, retourne une erreur que l''application peut gérer avec un retry.';

-- ============================================================================
-- 2. VÉRIFICATION
-- ============================================================================
DO $$
BEGIN
    -- Vérifier que la fonction existe
    IF NOT EXISTS (
        SELECT 1 FROM pg_proc 
        WHERE proname = 'add_product_to_service_jsonb_v2'
    ) THEN
        RAISE EXCEPTION 'Fonction add_product_to_service_jsonb_v2 n''existe pas';
    END IF;
    
    RAISE NOTICE '✅ Migration terminée avec succès';
END $$;




-- ============================================
-- Migration: 20251231_fix_product_creation_issues.sql
-- ============================================
-- Migration: Correction définitive des problèmes de création de produit
-- Date: 2025-12-31
-- Problèmes corrigés:
-- 1. Fonction add_product_to_service_jsonb trop lente (3+ secondes) causant erreurs TLS
-- 2. Contrainte UNIQUE manquante pour autocomplete_characteristics
-- 3. Amélioration gestion erreurs TLS avec retry

-- ============================================================================
-- 1. OPTIMISATION CRITIQUE: add_product_to_service_jsonb
-- ============================================================================
-- Problème: La fonction fait un SELECT puis un UPDATE, causant des latences de 3+ secondes
-- Solution: Calculer l'index AVANT l'UPDATE, puis UPDATE atomique en une seule opération
CREATE OR REPLACE FUNCTION add_product_to_service_jsonb(
    p_service_id INTEGER,
    p_product_json JSONB
) RETURNS INTEGER AS $$
DECLARE
    v_product_index INTEGER;
    v_updated_data JSONB;
BEGIN
    -- ✅ OPTIMISÉ: Calculer l'index AVANT l'UPDATE (lecture rapide sans verrou)
    -- Cette lecture est très rapide (<10ms) car elle ne modifie rien
    SELECT COALESCE(jsonb_array_length(data->'produits'->'valeur'), 0)
    INTO v_product_index
    FROM services
    WHERE id = p_service_id
    FOR UPDATE;  -- Verrouiller la ligne pour éviter les race conditions
    
    -- Si le service n'existe pas, retourner -1
    IF v_product_index IS NULL THEN
        RETURN -1;
    END IF;
    
    -- ✅ OPTIMISÉ: UPDATE atomique en une seule opération
    -- Le verrou FOR UPDATE garantit qu'on a l'index correct
    UPDATE services
    SET 
        data = CASE
            -- Si produits.valeur existe déjà, ajouter au tableau avec ||
            WHEN data->'produits'->'valeur' IS NOT NULL THEN
                jsonb_set(
                    data,
                    '{produits,valeur}',
                    (data->'produits'->'valeur') || jsonb_build_array(p_product_json),
                    true
                )
            -- Si produits existe mais pas valeur, créer valeur
            WHEN data->'produits' IS NOT NULL THEN
                jsonb_set(
                    data,
                    '{produits,valeur}',
                    jsonb_build_array(p_product_json),
                    true
                )
            -- Si produits n'existe pas, créer toute la structure
            ELSE
                COALESCE(data, '{}'::jsonb) || jsonb_build_object(
                    'produits',
                    jsonb_build_object(
                        'type_donnee', 'autocomplete',
                        'valeur', jsonb_build_array(p_product_json),
                        'separateur', ',',
                        'sous_caracteristiques', '{}'::jsonb,
                        'filtrable', true,
                        'origine_champs', 'formulaire'
                    )
                )
        END,
        updated_at = NOW()
    WHERE id = p_service_id;
    
    -- Si aucun service n'a été mis à jour, retourner -1
    IF NOT FOUND THEN
        RETURN -1;
    END IF;
    
    -- Retourner l'index du produit (0-based) - sera le nouvel index après ajout
    RETURN v_product_index;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION add_product_to_service_jsonb IS 'Fonction optimisée pour ajouter un produit au service. Utilise une seule opération UPDATE atomique avec RETURNING pour éviter les fermetures TLS et améliorer les performances (<100ms au lieu de 3+ secondes).';

-- ============================================================================
-- 2. CORRECTION: Contrainte UNIQUE pour autocomplete_characteristics
-- ============================================================================
-- Problème: Erreur "there is no unique or exclusion constraint matching the ON CONFLICT specification"
-- Solution: Nettoyer les doublons puis créer la contrainte UNIQUE si elle n'existe pas

-- Vérifier si la contrainte existe déjà
DO $$
BEGIN
    -- Vérifier si la table existe
    IF EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' 
        AND table_name = 'autocomplete_characteristics'
    ) THEN
        -- Vérifier si la contrainte unique existe
        IF NOT EXISTS (
            SELECT 1 FROM information_schema.table_constraints
            WHERE constraint_name = 'unique_autocomplete_characteristic'
            AND table_name = 'autocomplete_characteristics'
            AND constraint_type = 'UNIQUE'
        ) THEN
            -- ✅ CRITIQUE: Nettoyer les doublons AVANT de créer la contrainte UNIQUE
            -- Garder seulement le premier enregistrement (celui avec le plus petit id)
            DELETE FROM autocomplete_characteristics ac1
            WHERE EXISTS (
                SELECT 1 FROM autocomplete_characteristics ac2
                WHERE ac2.identifiant_base = ac1.identifiant_base
                AND ac2.sous_caracteristique = ac1.sous_caracteristique
                AND ac2.valeur = ac1.valeur
                AND ac2.id < ac1.id
            );
            
            RAISE NOTICE 'Doublons nettoyés dans autocomplete_characteristics';
            
            -- Créer la contrainte UNIQUE
            ALTER TABLE autocomplete_characteristics
            ADD CONSTRAINT unique_autocomplete_characteristic 
            UNIQUE (identifiant_base, sous_caracteristique, valeur);
            
            RAISE NOTICE 'Contrainte UNIQUE unique_autocomplete_characteristic créée';
        ELSE
            RAISE NOTICE 'Contrainte UNIQUE unique_autocomplete_characteristic existe déjà';
        END IF;
    ELSE
        RAISE NOTICE 'Table autocomplete_characteristics n''existe pas encore';
    END IF;
END $$;

-- ============================================================================
-- 3. AMÉLIORATION: Fonction upsert_autocomplete_characteristic
-- ============================================================================
-- S'assurer que la fonction utilise bien la contrainte UNIQUE
CREATE OR REPLACE FUNCTION upsert_autocomplete_characteristic(
    p_identifiant_base VARCHAR(255),
    p_sous_caracteristique VARCHAR(255),
    p_valeur VARCHAR(500),
    p_origine_champs VARCHAR(50) DEFAULT 'ia',
    p_user_id INTEGER DEFAULT NULL,
    p_service_id INTEGER DEFAULT NULL
)
RETURNS INTEGER AS $$
DECLARE
    v_id INTEGER;
BEGIN
    -- Essayer d'insérer avec ON CONFLICT
    INSERT INTO autocomplete_characteristics (
        identifiant_base,
        sous_caracteristique,
        valeur,
        origine_champs,
        user_id,
        service_id,
        usage_count
    )
    VALUES (
        p_identifiant_base,
        p_sous_caracteristique,
        p_valeur,
        p_origine_champs,
        p_user_id,
        p_service_id,
        1
    )
    ON CONFLICT (identifiant_base, sous_caracteristique, valeur)
    DO UPDATE SET
        usage_count = autocomplete_characteristics.usage_count + 1,
        updated_at = NOW(),
        -- Mettre à jour user_id et service_id si fournis (pour tracking)
        user_id = COALESCE(EXCLUDED.user_id, autocomplete_characteristics.user_id),
        service_id = COALESCE(EXCLUDED.service_id, autocomplete_characteristics.service_id);
    
    -- Récupérer l'ID directement avec RETURNING (plus efficace)
    SELECT id INTO v_id
    FROM autocomplete_characteristics
    WHERE identifiant_base = p_identifiant_base
    AND sous_caracteristique = p_sous_caracteristique
    AND valeur = p_valeur;
    
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION upsert_autocomplete_characteristic IS 'Insère ou met à jour une caractéristique autocomplete avec incrément du compteur d''usage. Utilise la contrainte UNIQUE (identifiant_base, sous_caracteristique, valeur).';

