-- ============================================
-- ============================================
-- PHASE 2 : Correction des références media -> service_products
-- ============================================
-- Date: 2026-01-03
-- Objectif: Corriger les product_id dans media pour référencer service_products.id
-- ============================================

\echo '🔧 Correction des références media -> service_products...'

-- ============================================
-- ÉTAPE 1 : Analyser l'état actuel
-- ============================================
\echo '📊 Étape 1 : Analyse de l''état actuel...'

SELECT 
    'Total médias avec produits' as metric,
    COUNT(*)::BIGINT as count
FROM media
WHERE service_id IN (SELECT DISTINCT service_id FROM service_products)
AND (product_id IS NOT NULL OR product_index IS NOT NULL)

UNION ALL

SELECT 
    'Médias avec product_id (TEXT)' as metric,
    COUNT(*)::BIGINT as count
FROM media
WHERE service_id IN (SELECT DISTINCT service_id FROM service_products)
AND product_id IS NOT NULL

UNION ALL

SELECT 
    'Médias avec product_index (INTEGER)' as metric,
    COUNT(*)::BIGINT as count
FROM media
WHERE service_id IN (SELECT DISTINCT service_id FROM service_products)
AND product_index IS NOT NULL

UNION ALL

SELECT 
    'Médias pouvant être corrigés (via product_index)' as metric,
    COUNT(*)::BIGINT as count
FROM media m
INNER JOIN service_products sp ON sp.service_id = m.service_id AND sp.product_index = m.product_index
WHERE m.service_id IN (SELECT DISTINCT service_id FROM service_products)
AND m.product_index IS NOT NULL;

-- ============================================
-- ÉTAPE 2 : Corriger les product_id via product_index
-- ============================================
\echo '🔧 Étape 2 : Correction des product_id via product_index...'

-- Mettre à jour les product_id en utilisant product_index pour trouver le bon service_products.id
UPDATE media m
SET product_id = sp.id::TEXT
FROM service_products sp
WHERE m.service_id = sp.service_id
AND m.product_index = sp.product_index
AND m.service_id IN (SELECT DISTINCT service_id FROM service_products)
AND (
    -- Cas 1: product_id est NULL mais product_index existe
    (m.product_id IS NULL AND m.product_index IS NOT NULL)
    OR
    -- Cas 2: product_id ne correspond à aucun id valide dans service_products
    (m.product_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM service_products sp2 
        WHERE sp2.id::TEXT = m.product_id
    ))
    OR
    -- Cas 3: product_id est un format ancien (prod_0, 120_1, etc.)
    (m.product_id IS NOT NULL AND (
        m.product_id LIKE 'prod_%' 
        OR m.product_id LIKE '%_%' 
        OR NOT (m.product_id ~ '^\d+$')
    ))
);

-- Afficher le nombre de product_id corrigés
SELECT 
    COUNT(*) as product_id_corriges
FROM media m
INNER JOIN service_products sp ON sp.id::TEXT = m.product_id
WHERE m.service_id IN (SELECT DISTINCT service_id FROM service_products)
AND m.product_id IS NOT NULL;

-- ============================================
-- ÉTAPE 3 : Vérification post-correction
-- ============================================
\echo '✅ Étape 3 : Vérification post-correction...'

-- Statistiques après correction
SELECT 
    'Médias avec product_id valide' as metric,
    COUNT(*)::BIGINT as count
FROM media m
INNER JOIN service_products sp ON sp.id::TEXT = m.product_id
WHERE m.service_id IN (SELECT DISTINCT service_id FROM service_products)
AND m.product_id IS NOT NULL

UNION ALL

SELECT 
    'Médias avec product_id invalide' as metric,
    COUNT(*)::BIGINT as count
FROM media m
WHERE m.service_id IN (SELECT DISTINCT service_id FROM service_products)
AND m.product_id IS NOT NULL
AND NOT EXISTS (
    SELECT 1 FROM service_products sp 
    WHERE sp.id::TEXT = m.product_id
)

UNION ALL

SELECT 
    'Médias avec product_index mais sans product_id' as metric,
    COUNT(*)::BIGINT as count
FROM media m
WHERE m.service_id IN (SELECT DISTINCT service_id FROM service_products)
AND m.product_index IS NOT NULL
AND m.product_id IS NULL;

-- Détails des médias corrigés
SELECT 
    m.id as media_id,
    m.service_id,
    m.product_id as product_id_apres,
    m.product_index,
    sp.id as service_product_id,
    sp.product_name,
    CASE 
        WHEN m.product_id = sp.id::TEXT THEN '✅ OK'
        ELSE '❌ INVALIDE'
    END as status
FROM media m
LEFT JOIN service_products sp ON sp.id::TEXT = m.product_id
WHERE m.service_id IN (SELECT DISTINCT service_id FROM service_products)
AND (m.product_id IS NOT NULL OR m.product_index IS NOT NULL)
ORDER BY m.service_id, m.product_index
LIMIT 20;

\echo '✅ Correction des références media terminée !'



-- ============================================
-- Migration: 20260103_phase2_migrate_existing_products.sql
-- ============================================
-- ============================================
-- PHASE 2 : Migration des produits existants
-- ============================================
-- Date: 2026-01-03
-- Objectif: Migrer les produits existants depuis JSONB vers service_products
-- et corriger les product_id dans autocomplete_characteristics
-- ============================================

\echo '🚀 Début Phase 2 : Migration des produits existants...'

-- ============================================
-- ÉTAPE 1 : Migrer les produits depuis JSONB vers service_products
-- ============================================
\echo '📦 Étape 1 : Migration des produits depuis JSONB...'

-- Utiliser une approche avec INSERT ... SELECT pour éviter les problèmes de boucle
INSERT INTO service_products (
    service_id,
    product_index,
    product_data,
    is_active,
    created_at,
    updated_at
)
SELECT 
    s.id as service_id,
    (prod.ordinality - 1)::INTEGER as product_index,
    (prod.value - 'images' - 'videos' - 'audios' - 'documents')::JSONB as product_data,
    COALESCE(
        ((prod.value - 'images' - 'videos' - 'audios' - 'documents')->>'is_active')::boolean,
        true
    ) as is_active,
    NOW() as created_at,
    NOW() as updated_at
FROM services s
CROSS JOIN LATERAL jsonb_array_elements(s.data->'produits'->'valeur') 
    WITH ORDINALITY AS prod(value, ordinality)
WHERE s.is_active = true
AND s.data->'produits'->'valeur' IS NOT NULL
AND jsonb_typeof(s.data->'produits'->'valeur') = 'array'
AND jsonb_array_length(s.data->'produits'->'valeur') > 0
AND NOT EXISTS (
    -- Ne pas migrer si des produits existent déjà pour ce service
    SELECT 1 FROM service_products sp 
    WHERE sp.service_id = s.id
)
ON CONFLICT (service_id, product_index) 
DO UPDATE SET 
    product_data = EXCLUDED.product_data,
    updated_at = NOW();

-- Afficher le nombre de produits migrés
SELECT 
    COUNT(*) as produits_migres,
    COUNT(DISTINCT service_id) as services_migres
FROM service_products
WHERE created_at > NOW() - INTERVAL '1 minute';

-- ============================================
-- ÉTAPE 2 : Corriger les product_id dans autocomplete_characteristics
-- ============================================
\echo '🔧 Étape 2 : Correction des product_id dans autocomplete_characteristics...'

-- Mettre à jour autocomplete_characteristics avec les nouveaux product_id
-- Les anciens product_id référencent probablement des index (0, 1, 2...) au lieu des vrais id
UPDATE autocomplete_characteristics ac
SET 
    product_id = sp.id::TEXT,
    updated_at = NOW()
FROM service_products sp
WHERE ac.service_id = sp.service_id
AND ac.is_real_product = TRUE
AND ac.identifiant_base = 'produits'
AND ac.product_id IS NOT NULL
AND (
    -- Cas 1: product_id est un nombre qui correspond à un product_index
    (ac.product_id ~ '^\d+$' AND ac.product_id::INTEGER = sp.product_index)
    OR
    -- Cas 2: product_id ne correspond à aucun id valide dans service_products
    NOT EXISTS (
        SELECT 1 FROM service_products sp2 
        WHERE sp2.id::TEXT = ac.product_id
    )
);

-- Afficher le nombre de product_id corrigés
SELECT 
    COUNT(*) as product_id_corriges
FROM autocomplete_characteristics ac
INNER JOIN service_products sp ON sp.id::TEXT = ac.product_id
WHERE ac.is_real_product = TRUE
AND ac.identifiant_base = 'produits'
AND ac.updated_at > NOW() - INTERVAL '1 minute';

-- ============================================
-- ÉTAPE 3 : Vérification post-migration
-- ============================================
\echo '✅ Étape 3 : Vérification post-migration...'

-- Statistiques après migration
SELECT 
    'Produits migrés dans service_products' as metric,
    COUNT(*)::BIGINT as count
FROM service_products
WHERE is_active = true

UNION ALL

SELECT 
    'Services avec produits migrés' as metric,
    COUNT(DISTINCT service_id)::BIGINT as count
FROM service_products
WHERE is_active = true

UNION ALL

SELECT 
    'product_id valides dans autocomplete_characteristics' as metric,
    COUNT(DISTINCT ac.product_id)::BIGINT as count
FROM autocomplete_characteristics ac
INNER JOIN service_products sp ON sp.id::TEXT = ac.product_id
WHERE ac.is_real_product = TRUE
AND ac.identifiant_base = 'produits';

\echo '✅ Phase 2 terminée !'


-- ============================================
-- Migration: 20260104_001_create_delivery_partners.sql
-- ============================================
-- ✅ NOUVEAU 2026-01-04: Création de la table delivery_partners pour gérer les partenaires de livraison
-- Cette table permet aux administrateurs de créer et gérer des partenaires de logistique
-- qui seront associés aux coursiers lors de leur enregistrement

-- ✅ NOUVEAU 2026-01-04: Créer le type ENUM pour les types de partenaires
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'delivery_partner_type') THEN
        CREATE TYPE delivery_partner_type AS ENUM (
            'Livraison',
            'pharmacie',
            'hopital',
            'laboratoire',
            'agence de voyage',
            'demenagement',
            'transport'
        );
    END IF;
END
$$;

CREATE TABLE IF NOT EXISTS delivery_partners (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL UNIQUE,
    description TEXT,
    partner_type delivery_partner_type NOT NULL DEFAULT 'Livraison',
    contact_email VARCHAR(255),
    contact_phone VARCHAR(50),
    address TEXT,
    city VARCHAR(100),
    country VARCHAR(100),
    website VARCHAR(255),
    logo_url TEXT,
    is_active BOOLEAN DEFAULT TRUE,
    created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Index pour recherche rapide
CREATE INDEX IF NOT EXISTS idx_delivery_partners_name ON delivery_partners(name);
CREATE INDEX IF NOT EXISTS idx_delivery_partners_active ON delivery_partners(is_active);
CREATE INDEX IF NOT EXISTS idx_delivery_partners_created_by ON delivery_partners(created_by);
CREATE INDEX IF NOT EXISTS idx_delivery_partners_type ON delivery_partners(partner_type);

-- ✅ NOUVEAU 2026-01-04: Ajouter partner_id à courier_applications
ALTER TABLE courier_applications 
ADD COLUMN IF NOT EXISTS partner_id INTEGER REFERENCES delivery_partners(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_courier_applications_partner ON courier_applications(partner_id);

-- ✅ NOUVEAU 2026-01-04: Ajouter vehicle_image_url à courier_assets
ALTER TABLE courier_assets 
ADD COLUMN IF NOT EXISTS vehicle_image_url TEXT;

-- Commentaires pour documentation
COMMENT ON TABLE delivery_partners IS 'Partenaires de livraison (gestionnaires de logistique) qui peuvent être associés aux coursiers';
COMMENT ON COLUMN delivery_partners.partner_type IS 'Type de partenaire: Livraison, pharmacie, hopital, laboratoire, agence de voyage, demenagement, transport';
COMMENT ON COLUMN courier_applications.partner_id IS 'Référence au partenaire de livraison auquel appartient le coursier';
COMMENT ON COLUMN courier_assets.vehicle_image_url IS 'URL de l\'image du moyen de transport du coursier';



-- ============================================
-- Migration: 20260104_apply_delivery_partners_migrations.sql
-- ============================================
-- ✅ NOUVEAU 2026-01-04: Migration complète pour delivery_partners
-- Ce script applique toutes les migrations nécessaires pour les partenaires de livraison

-- 1. Créer l'enum delivery_partner_type avec 'livraison' en minuscule
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'delivery_partner_type') THEN
        CREATE TYPE delivery_partner_type AS ENUM (
            'livraison',
            'livraison_courses_marche',
            'pharmacie',
            'hopital',
            'laboratoire',
            'agence de voyage',
            'demenagement',
            'transport',
            'assureur',
            'supermarche',
            'telecom',
            'chauffeur'
        );
    END IF;
END
$$;

-- 2. Ajouter 'livraison' à l'enum si n'existe pas (pour les bases existantes)
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_enum 
        WHERE enumlabel = 'livraison' AND enumtypid = 'delivery_partner_type'::regtype
    ) THEN
        ALTER TYPE delivery_partner_type ADD VALUE 'livraison';
    END IF;
END
$$;

-- 3. Ajouter les nouveaux types de partenaires à l'enum
DO $$
BEGIN
    -- Ajouter 'assureur' si n'existe pas
    IF NOT EXISTS (
        SELECT 1 FROM pg_enum 
        WHERE enumlabel = 'assureur' AND enumtypid = 'delivery_partner_type'::regtype
    ) THEN
        ALTER TYPE delivery_partner_type ADD VALUE 'assureur';
    END IF;
    
    -- Ajouter 'supermarche' si n'existe pas
    IF NOT EXISTS (
        SELECT 1 FROM pg_enum 
        WHERE enumlabel = 'supermarche' AND enumtypid = 'delivery_partner_type'::regtype
    ) THEN
        ALTER TYPE delivery_partner_type ADD VALUE 'supermarche';
    END IF;
    
    -- Ajouter 'telecom' si n'existe pas
    IF NOT EXISTS (
        SELECT 1 FROM pg_enum 
        WHERE enumlabel = 'telecom' AND enumtypid = 'delivery_partner_type'::regtype
    ) THEN
        ALTER TYPE delivery_partner_type ADD VALUE 'telecom';
    END IF;
    
    -- ✅ NOUVEAU: Ajouter 'livraison_courses_marche' si n'existe pas (pour coursiers spécialisés en courses au marché)
    IF NOT EXISTS (
        SELECT 1 FROM pg_enum 
        WHERE enumlabel = 'livraison_courses_marche' AND enumtypid = 'delivery_partner_type'::regtype
    ) THEN
        ALTER TYPE delivery_partner_type ADD VALUE 'livraison_courses_marche';
    END IF;
    
    -- ✅ NOUVEAU: Ajouter 'chauffeur' si n'existe pas (pour chauffeurs taxi/covoiturage)
    IF NOT EXISTS (
        SELECT 1 FROM pg_enum 
        WHERE enumlabel = 'chauffeur' AND enumtypid = 'delivery_partner_type'::regtype
    ) THEN
        ALTER TYPE delivery_partner_type ADD VALUE 'chauffeur';
    END IF;
END
$$;

-- 4. Créer la table delivery_partners si elle n'existe pas
CREATE TABLE IF NOT EXISTS delivery_partners (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    partner_type delivery_partner_type NOT NULL DEFAULT 'livraison',
    contact_email VARCHAR(255),
    contact_phone VARCHAR(50),
    address TEXT,
    city VARCHAR(100),
    country VARCHAR(100) NOT NULL DEFAULT 'Non spécifié', -- ✅ NOUVEAU 2026-01-04: Pays obligatoire
    continent VARCHAR(50), -- ✅ NOUVEAU 2026-01-04: Continent optionnel
    website VARCHAR(255),
    logo_url TEXT,
    -- ✅ NOUVEAU 2026-01-04: Localisation intelligente du partenaire
    location_latitude DOUBLE PRECISION,
    location_longitude DOUBLE PRECISION,
    location_address TEXT,
    is_active BOOLEAN DEFAULT TRUE,
    created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. Modifier la contrainte UNIQUE pour permettre le même nom dans différents pays
DO $$
BEGIN
    -- Supprimer l'ancienne contrainte UNIQUE sur name si elle existe
    IF EXISTS (
        SELECT 1 FROM pg_constraint 
        WHERE conname = 'delivery_partners_name_key' 
        AND conrelid = 'delivery_partners'::regclass
    ) THEN
        ALTER TABLE delivery_partners DROP CONSTRAINT delivery_partners_name_key;
    END IF;
    
    -- Ajouter la nouvelle contrainte UNIQUE sur (name, country) si elle n'existe pas
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint 
        WHERE conname = 'delivery_partners_name_country_key' 
        AND conrelid = 'delivery_partners'::regclass
    ) THEN
        ALTER TABLE delivery_partners ADD CONSTRAINT delivery_partners_name_country_key UNIQUE (name, country);
    END IF;
END
$$;

-- 6. Ajouter la colonne country si elle n'existe pas et la rendre NOT NULL
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'delivery_partners' AND column_name = 'country'
    ) THEN
        ALTER TABLE delivery_partners ADD COLUMN country VARCHAR(100) DEFAULT 'Non spécifié';
    END IF;
    
    -- Mettre à jour les valeurs NULL avec une valeur par défaut
    UPDATE delivery_partners SET country = 'Non spécifié' WHERE country IS NULL;
    
    -- Rendre country NOT NULL si ce n'est pas déjà le cas
    IF EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'delivery_partners' 
        AND column_name = 'country' 
        AND is_nullable = 'YES'
    ) THEN
        ALTER TABLE delivery_partners ALTER COLUMN country SET NOT NULL;
    END IF;
END
$$;

-- 7. Ajouter la colonne continent si elle n'existe pas
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'delivery_partners' AND column_name = 'continent'
    ) THEN
        ALTER TABLE delivery_partners ADD COLUMN continent VARCHAR(50);
    END IF;
END
$$;

-- 8. Ajouter les colonnes de localisation si elles n'existent pas
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'delivery_partners' AND column_name = 'location_latitude'
    ) THEN
        ALTER TABLE delivery_partners 
        ADD COLUMN location_latitude DOUBLE PRECISION,
        ADD COLUMN location_longitude DOUBLE PRECISION,
        ADD COLUMN location_address TEXT;
    END IF;
END
$$;

-- 9. Ajouter la colonne partner_type si elle n'existe pas
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'delivery_partners' AND column_name = 'partner_type'
    ) THEN
        ALTER TABLE delivery_partners 
        ADD COLUMN partner_type delivery_partner_type NOT NULL DEFAULT 'livraison';
    END IF;
END
$$;

-- 10. Mettre à jour 'Livraison' en 'livraison' dans les données existantes
UPDATE delivery_partners 
SET partner_type = 'livraison'::delivery_partner_type 
WHERE partner_type::text = 'Livraison';

-- 11. Créer les index
CREATE INDEX IF NOT EXISTS idx_delivery_partners_name ON delivery_partners(name);
CREATE INDEX IF NOT EXISTS idx_delivery_partners_active ON delivery_partners(is_active);
CREATE INDEX IF NOT EXISTS idx_delivery_partners_created_by ON delivery_partners(created_by);
CREATE INDEX IF NOT EXISTS idx_delivery_partners_type ON delivery_partners(partner_type);
CREATE INDEX IF NOT EXISTS idx_delivery_partners_country ON delivery_partners(country);
CREATE INDEX IF NOT EXISTS idx_delivery_partners_continent ON delivery_partners(continent);

-- 12. Ajouter partner_id à courier_applications si n'existe pas
ALTER TABLE courier_applications 
ADD COLUMN IF NOT EXISTS partner_id INTEGER REFERENCES delivery_partners(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_courier_applications_partner ON courier_applications(partner_id);

-- 13. Ajouter vehicle_image_url à courier_assets si n'existe pas
ALTER TABLE courier_assets 
ADD COLUMN IF NOT EXISTS vehicle_image_url TEXT;

-- 14. Ajouter la contrainte CHECK sur users.role pour inclure 'partenaire' et 'super_admin'
DO $$
DECLARE
    constraint_def TEXT;
    constraint_exists BOOLEAN;
BEGIN
    -- Vérifier si la contrainte existe déjà
    SELECT EXISTS (
        SELECT 1 FROM pg_constraint 
        WHERE conname = 'users_role_check' 
        AND conrelid = 'users'::regclass
    ) INTO constraint_exists;
    
    IF constraint_exists THEN
        -- Récupérer la définition actuelle de la contrainte
        SELECT pg_get_constraintdef(oid) INTO constraint_def
        FROM pg_constraint
        WHERE conname = 'users_role_check' 
        AND conrelid = 'users'::regclass;
        
        -- Si la contrainte ne contient pas 'super_admin', on la recrée
        IF constraint_def NOT LIKE '%super_admin%' THEN
            ALTER TABLE users DROP CONSTRAINT users_role_check;
            ALTER TABLE users ADD CONSTRAINT users_role_check 
            CHECK (role IN ('user', 'admin', 'super_admin', 'partenaire'));
            RAISE NOTICE 'Contrainte users_role_check mise a jour avec super_admin';
        ELSE
            RAISE NOTICE 'Contrainte users_role_check deja a jour avec super_admin';
        END IF;
    ELSE
        -- La contrainte n'existe pas, on la crée avec tous les rôles
        ALTER TABLE users ADD CONSTRAINT users_role_check 
        CHECK (role IN ('user', 'admin', 'super_admin', 'partenaire'));
        RAISE NOTICE 'Contrainte users_role_check creee avec super_admin et partenaire';
    END IF;
EXCEPTION
    WHEN duplicate_object THEN 
        RAISE NOTICE 'Contrainte users_role_check deja presente';
    WHEN OTHERS THEN
        RAISE NOTICE 'Erreur lors de la mise a jour de la contrainte: %', SQLERRM;
END
$$;

-- ✅ Migration terminée
SELECT '✅ Migrations delivery_partners appliquées avec succès' AS status;




-- ============================================
-- Migration: 20260111_optimize_delivery_queries_additional.sql
-- ============================================
-- ✅ OPTIMISATION ADDITIONNELLE 2026-01-11: Correction des requêtes lentes identifiées dans les warnings
-- Problèmes identifiés:
-- 1. SELECT deliveries avec ST_Y/ST_X: 1.1-1.5s (get_delivery_summary)
-- 2. find_nearby_couriers: 1.14s
-- 3. UPDATE delivery_matching_queue: 1.09s
-- 4. SELECT 1 (healthcheck): 1+ seconde (indique latence réseau ou charge DB)

-- =====================================================
-- 1. Optimisation requête get_delivery_summary
-- =====================================================

-- Index GIST pour return_pickup_location (manquant)
CREATE INDEX IF NOT EXISTS idx_deliveries_return_pickup_location_gist
ON deliveries USING GIST(return_pickup_location)
WHERE return_pickup_location IS NOT NULL;

-- Index GIST pour return_dropoff_location (manquant)
CREATE INDEX IF NOT EXISTS idx_deliveries_return_dropoff_location_gist
ON deliveries USING GIST(return_dropoff_location)
WHERE return_dropoff_location IS NOT NULL;

-- Index composite pour is_round_trip (utilisé dans la requête)
CREATE INDEX IF NOT EXISTS idx_deliveries_round_trip
ON deliveries(id, is_round_trip)
WHERE is_round_trip = true;

-- =====================================================
-- 2. Optimisation find_nearby_couriers (amélioration)
-- =====================================================

-- Index pour captured_at récent (utilisé dans find_nearby_couriers)
-- Améliore la requête WHERE captured_at >= NOW() - INTERVAL '1 hour'
CREATE INDEX IF NOT EXISTS idx_courier_availability_snapshots_recent
ON courier_availability_snapshots(captured_at DESC, is_online, load_factor)
WHERE is_online = true AND load_factor < 1.0;

-- Index composite pour user_id et courier_id (utilisé dans jointure)
CREATE INDEX IF NOT EXISTS idx_courier_availability_snapshots_user_courier
ON courier_availability_snapshots(user_id, courier_id)
WHERE is_online = true;

-- =====================================================
-- 3. Optimisation UPDATE delivery_matching_queue
-- =====================================================

-- Index pour WHERE delivery_id = $1 dans UPDATE (amélioration)
CREATE INDEX IF NOT EXISTS idx_delivery_matching_queue_delivery_id_status
ON delivery_matching_queue(delivery_id, status);

-- Index pour next_attempt_at (utilisé dans WHERE clauses)
CREATE INDEX IF NOT EXISTS idx_delivery_matching_queue_next_attempt
ON delivery_matching_queue(next_attempt_at)
WHERE next_attempt_at IS NOT NULL;

-- =====================================================
-- 4. Optimisation requêtes fréquentes sur deliveries
-- =====================================================

-- Index pour creator_id (utilisé dans plusieurs requêtes)
CREATE INDEX IF NOT EXISTS idx_deliveries_creator_id
ON deliveries(creator_id, status, requested_at DESC);

-- Index pour courier_id (utilisé dans plusieurs requêtes)
CREATE INDEX IF NOT EXISTS idx_deliveries_courier_id
ON deliveries(courier_id, status, requested_at DESC);

-- Index pour recipient_user_id (utilisé dans requêtes récipient)
CREATE INDEX IF NOT EXISTS idx_deliveries_recipient_user_id
ON deliveries(recipient_user_id, status)
WHERE recipient_user_id IS NOT NULL;

-- Index pour tracking_token (utilisé dans requêtes de suivi)
CREATE INDEX IF NOT EXISTS idx_deliveries_tracking_token
ON deliveries(tracking_token)
WHERE tracking_token IS NOT NULL;

-- Index pour recipient_tracking_token
CREATE INDEX IF NOT EXISTS idx_deliveries_recipient_tracking_token
ON deliveries(recipient_tracking_token)
WHERE recipient_tracking_token IS NOT NULL;

-- =====================================================
-- 5. ANALYZE pour mettre à jour les statistiques
-- =====================================================

-- Analyser les tables pour que PostgreSQL utilise les nouveaux index
ANALYZE deliveries;
