-- ============================================
-- Migration: 20260113_optimize_vector_matching_vectorial.sql
-- ============================================
-- Migration: Optimisation Matching Vectoriel avec Test Vectoriel (équivalent %in% R)
-- Date: 2026-01-13
-- Description: Remplace l'itération séquentielle par un test vectoriel unique (comme %in% en R)

-- =====================================================
-- Fonction de Matching Vectoriel Optimisée (Vectorielle)
-- =====================================================

CREATE OR REPLACE FUNCTION calculate_vector_match_score_optimized(
    product_vector_normalized TEXT[],
    search_keywords_normalized TEXT[]
)
RETURNS REAL AS $$
    -- ✅ TEST VECTORIEL UNIQUE (équivalent à %in% en R) : Pas d'itération séquentielle
    -- Utilise l'intersection d'arrays pour compter les matches en une seule opération
    SELECT COALESCE(
        GREATEST(
            -- Score exact (100%) : Test vectoriel avec intersection
            -- Équivalent R: sum(search_keywords %in% product_vector) / length(search_keywords) * 100
            (
                SELECT array_length(
                    ARRAY(
                        SELECT unnest(search_keywords_normalized)
                        INTERSECT
                        SELECT unnest(product_vector_normalized)
                    ),
                    1
                )::REAL
            ) / NULLIF(array_length(search_keywords_normalized, 1), 0)::REAL * 100.0,
            
            -- Score partiel (70%) : Mots tronqués (LIKE) - toujours nécessaire pour variations
            -- Mais optimisé avec EXISTS au lieu de boucle
            (
                SELECT COUNT(*)::REAL
                FROM unnest(search_keywords_normalized) AS keyword
                WHERE EXISTS (
                    SELECT 1
                    FROM unnest(product_vector_normalized) AS elem
                    WHERE elem LIKE keyword || '%' OR keyword LIKE elem || '%'
                )
            ) / NULLIF(array_length(search_keywords_normalized, 1), 0)::REAL * 70.0,
            
            -- Score fuzzy (40%) : Fautes de frappe (similarity) - toujours nécessaire
            (
                SELECT COUNT(*)::REAL
                FROM unnest(search_keywords_normalized) AS keyword
                WHERE EXISTS (
                    SELECT 1
                    FROM unnest(product_vector_normalized) AS elem
                    WHERE similarity(keyword, elem) > 0.3
                )
            ) / NULLIF(array_length(search_keywords_normalized, 1), 0)::REAL * 40.0
        ),
        0.0
    );
$$ LANGUAGE sql IMMUTABLE;

COMMENT ON FUNCTION calculate_vector_match_score_optimized IS 
'Calcule le score de matching vectoriel avec test vectoriel unique (équivalent %in% en R). 
Utilise l''intersection d''arrays pour compter les matches en une seule opération vectorielle.';

-- =====================================================
-- Vérification
-- =====================================================

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_proc WHERE proname = 'calculate_vector_match_score_optimized'
    ) THEN
        RAISE EXCEPTION 'Fonction calculate_vector_match_score_optimized non créée';
    END IF;
    
    RAISE NOTICE '✅ Migration optimisation matching vectoriel vectoriel appliquée avec succès';
END $$;




-- ============================================
-- Migration: 20260114_create_negotiated_prices_table.sql
-- ============================================
-- Migration pour créer la table negotiated_prices
-- Date: 2026-01-14
-- Description: Table pour gérer les prix négociés entre prestataire et client

CREATE TABLE IF NOT EXISTS negotiated_prices (
    id SERIAL PRIMARY KEY,
    conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
    service_id INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE,
    product_index INTEGER,
    merchant_user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    client_user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    original_price_cents BIGINT NOT NULL,
    negotiated_price_cents BIGINT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted', 'rejected', 'expired', 'cancelled')),
    expires_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    accepted_at TIMESTAMP WITH TIME ZONE,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    metadata JSONB DEFAULT '{}'::jsonb
);

-- Index pour améliorer les performances
CREATE INDEX IF NOT EXISTS idx_negotiated_prices_conversation_id ON negotiated_prices(conversation_id);
CREATE INDEX IF NOT EXISTS idx_negotiated_prices_service_id ON negotiated_prices(service_id);
CREATE INDEX IF NOT EXISTS idx_negotiated_prices_client_user_id ON negotiated_prices(client_user_id);
CREATE INDEX IF NOT EXISTS idx_negotiated_prices_merchant_user_id ON negotiated_prices(merchant_user_id);
CREATE INDEX IF NOT EXISTS idx_negotiated_prices_status ON negotiated_prices(status);
CREATE INDEX IF NOT EXISTS idx_negotiated_prices_expires_at ON negotiated_prices(expires_at);

-- Index composite pour requêtes courantes
CREATE INDEX IF NOT EXISTS idx_negotiated_prices_lookup 
ON negotiated_prices(conversation_id, service_id, product_index, client_user_id, status);

-- Contrainte UNIQUE pour éviter les doublons (une seule offre en attente par conversation/service/produit/client)
-- Note: Les offres précédentes sont annulées avant de créer une nouvelle offre
CREATE UNIQUE INDEX IF NOT EXISTS idx_negotiated_prices_unique_pending
ON negotiated_prices(conversation_id, service_id, COALESCE(product_index, -1), client_user_id)
WHERE status = 'pending';

-- Commentaires
COMMENT ON TABLE negotiated_prices IS 'Offres de prix négociés entre prestataire et client';
COMMENT ON COLUMN negotiated_prices.status IS 'pending: en attente, accepted: acceptée, rejected: rejetée, expired: expirée, cancelled: annulée';
COMMENT ON COLUMN negotiated_prices.product_index IS 'Index du produit dans le service (NULL pour le service entier)';



-- ============================================
-- Migration: 20260114_fix_image_search_to_tsvector_error.sql
-- ============================================
-- Migration: Correction erreur to_tsvector avec langue dynamique
-- Date: 2026-01-14
-- Description: Corrige l'erreur "function to_tsvector(text, text) does not exist" 
--              en convertissant correctement le paramètre TEXT en regconfig

-- =====================================================
-- 1. Fonction Helper pour Convertir Langue TEXT -> regconfig
-- =====================================================

CREATE OR REPLACE FUNCTION get_text_search_config(lang_text TEXT)
RETURNS regconfig AS $$
BEGIN
    -- Convertir le texte de langue en regconfig valide
    -- Valeurs supportées: french, english, spanish, portuguese, arabic
    CASE 
        WHEN lang_text ILIKE 'french' OR lang_text ILIKE 'français' OR lang_text ILIKE 'fr' THEN
            RETURN 'french'::regconfig;
        WHEN lang_text ILIKE 'english' OR lang_text ILIKE 'anglais' OR lang_text ILIKE 'en' THEN
            RETURN 'english'::regconfig;
        WHEN lang_text ILIKE 'spanish' OR lang_text ILIKE 'espagnol' OR lang_text ILIKE 'es' THEN
            RETURN 'spanish'::regconfig;
        WHEN lang_text ILIKE 'portuguese' OR lang_text ILIKE 'portugais' OR lang_text ILIKE 'pt' THEN
            RETURN 'portuguese'::regconfig;
        WHEN lang_text ILIKE 'arabic' OR lang_text ILIKE 'arabe' OR lang_text ILIKE 'ar' THEN
            RETURN 'arabic'::regconfig;
        ELSE
            -- Français par défaut si langue non reconnue
            RETURN 'french'::regconfig;
    END CASE;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

COMMENT ON FUNCTION get_text_search_config IS 'Convertit un texte de langue en regconfig PostgreSQL valide pour to_tsvector';

-- =====================================================
-- 2. Correction de la Fonction search_images_by_ai_analysis
-- =====================================================

CREATE OR REPLACE FUNCTION search_images_by_ai_analysis(
    search_query TEXT,
    search_tags TEXT[],
    search_category TEXT DEFAULT NULL,
    search_marque TEXT DEFAULT NULL,
    search_couleur TEXT DEFAULT NULL,
    gps_lat FLOAT DEFAULT NULL,
    gps_lng FLOAT DEFAULT NULL,
    search_radius_km INTEGER DEFAULT 50,
    max_results INTEGER DEFAULT 20,
    detected_lang TEXT DEFAULT 'french'  -- Langue dynamique
)
RETURNS TABLE (
    service_id INTEGER,
    media_id INTEGER,
    media_path TEXT,
    product_name TEXT,
    ai_description TEXT,
    ai_tags TEXT[],
    match_score FLOAT,
    distance_km FLOAT,
    service_data JSONB
) AS $$
DECLARE
    normalized_search_query TEXT;
    normalized_search_tags TEXT[];
    normalized_search_marque TEXT;
    normalized_search_couleur TEXT;
    lang_config regconfig;  -- ✅ CORRIGÉ: Variable regconfig au lieu de TEXT
BEGIN
    -- ✅ CORRIGÉ: Convertir la langue TEXT en regconfig
    lang_config := get_text_search_config(detected_lang);
    
    -- Normaliser les paramètres de recherche
    normalized_search_query := normalize_text(search_query);
    normalized_search_tags := normalize_word_array(search_tags);
    normalized_search_marque := CASE WHEN search_marque IS NOT NULL THEN normalize_text(search_marque) ELSE NULL END;
    normalized_search_couleur := CASE WHEN search_couleur IS NOT NULL THEN normalize_text(search_couleur) ELSE NULL END;

    RETURN QUERY
    WITH ranked_results AS (
        SELECT 
            s.id as service_id,
            m.id as media_id,
            m.path as media_path,
            COALESCE(
                product->>'nom',
                product->>'name',
                product->>'titre',
                'Produit'
            ) as product_name,
            m.ai_description,
            m.ai_tags,
            (
                -- ✅ CORRIGÉ: Utiliser lang_config (regconfig) au lieu de detected_lang (TEXT)
                COALESCE(
                    ts_rank(
                        to_tsvector(lang_config, COALESCE(m.normalized_ai_description, '')),
                        plainto_tsquery(lang_config, normalized_search_query)
                    ) * 50.0,
                    0.0
                ) +
                
                -- Matching vectoriel optimisé avec similarité (exact + partiel + fuzzy)
                COALESCE(
                    calculate_vector_match_score_optimized(
                        m.normalized_ai_tags,
                        normalized_search_tags
                    ) * 30.0,  -- Multiplicateur pour tags
                    0.0
                ) +
                
                -- Matching partiel sur description normalisée (mots tronqués)
                CASE 
                    WHEN normalized_search_query != '' 
                         AND m.normalized_ai_description LIKE '%' || normalized_search_query || '%'
                    THEN 35.0
                    ELSE 0.0
                END +
                
                -- Bonus tags communs avec normalisation
                (SELECT COUNT(*) * 20.0 
                 FROM unnest(COALESCE(m.normalized_ai_tags, ARRAY[]::TEXT[])) tag 
                 WHERE tag = ANY(normalized_search_tags)) +
                
                -- Bonus marque exacte avec normalisation
                CASE 
                    WHEN normalized_search_marque IS NOT NULL 
                         AND normalize_text(COALESCE(m.ai_metadata->>'marque', '')) = normalized_search_marque
                    THEN 100.0 
                    ELSE 0.0 
                END +
                
                -- Bonus couleur avec normalisation
                CASE 
                    WHEN normalized_search_couleur IS NOT NULL 
                         AND EXISTS (
                             SELECT 1 
                             FROM jsonb_array_elements_text(COALESCE(m.ai_metadata->'couleurs', '[]'::jsonb)) AS couleur
                             WHERE normalize_text(couleur) = normalized_search_couleur
                         )
                    THEN 30.0 
                    ELSE 0.0 
                END +
                
                -- Bonus catégorie identique
                CASE 
                    WHEN search_category IS NOT NULL 
                         AND m.ai_category = search_category 
                    THEN 40.0 
                    ELSE 0.0 
                END +
                
                -- Bonus confidence élevée
                (COALESCE(m.ai_confidence, 0.5) * 20.0)
                
            )::FLOAT as match_score,
            
            -- Calcul distance GPS si coordonnées fournies
            CASE 
                WHEN gps_lat IS NOT NULL AND gps_lng IS NOT NULL 
                     AND s.gps IS NOT NULL AND s.gps != '' 
                     AND s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$'
                THEN
                    ST_Distance(
                        ST_Point(gps_lng, gps_lat)::geography,
                        ST_Point(
                            COALESCE(CAST(SPLIT_PART(s.gps, ',', 2) AS FLOAT), 0.0),
                            COALESCE(CAST(SPLIT_PART(s.gps, ',', 1) AS FLOAT), 0.0)
                        )::geography
                    ) / 1000.0  -- Convertir en km
                ELSE NULL
            END as distance_km,
            
            s.data as service_data,
            product
        FROM services s
        INNER JOIN media m ON m.service_id = s.id
        CROSS JOIN LATERAL jsonb_array_elements(
            CASE 
                WHEN jsonb_typeof(s.data->'produits') = 'array' 
                THEN s.data->'produits'
                ELSE '[]'::jsonb
            END
        ) AS product
        WHERE s.is_active = true
        AND m.type = 'image'
        AND m.ai_description IS NOT NULL
        AND (
            -- ✅ CORRIGÉ: Utiliser lang_config (regconfig) au lieu de detected_lang (TEXT)
            to_tsvector(lang_config, COALESCE(m.normalized_ai_description, '')) @@ plainto_tsquery(lang_config, normalized_search_query)
            OR m.normalized_ai_tags && normalized_search_tags  -- Overlap sur tags normalisés
            OR calculate_vector_match_score_optimized(m.normalized_ai_tags, normalized_search_tags) > 0.0  -- Matching vectoriel optimisé
            OR (normalized_search_query != '' AND m.normalized_ai_description LIKE '%' || normalized_search_query || '%')  -- Matching partiel
            OR (search_category IS NOT NULL AND m.ai_category = search_category)
        )
        -- Filtre GPS si coordonnées fournies
        AND (
            gps_lat IS NULL 
            OR gps_lng IS NULL
            OR search_radius_km IS NULL
            OR s.gps IS NULL
            OR s.gps = ''
            OR s.gps !~ '^-?\d+\.?\d*,-?\d+\.?\d*$'
            OR ST_Distance(
                ST_Point(gps_lng, gps_lat)::geography,
                ST_Point(
                    COALESCE(CAST(SPLIT_PART(s.gps, ',', 2) AS FLOAT), 0.0),
                    COALESCE(CAST(SPLIT_PART(s.gps, ',', 1) AS FLOAT), 0.0)
                )::geography
            ) / 1000.0 <= search_radius_km
        )
    )
    SELECT 
        ranked_results.service_id,
        ranked_results.media_id,
        ranked_results.media_path,
        ranked_results.product_name,
        ranked_results.ai_description,
        ranked_results.ai_tags,
        ranked_results.match_score,
        ranked_results.distance_km,
        ranked_results.service_data
    FROM ranked_results
    WHERE ranked_results.match_score > 0.0  -- ✅ AMÉLIORÉ: Filtrer les résultats avec score > 0
    ORDER BY 
        ranked_results.match_score DESC,
        ranked_results.distance_km ASC NULLS LAST
    LIMIT max_results;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION search_images_by_ai_analysis IS 'Recherche intelligente d''images par analyse IA avec matching vectoriel optimisé, gestion accents, matching partiel/fuzzy, et langue dynamique (CORRIGÉ: conversion TEXT->regconfig)';

-- =====================================================
-- 3. Vérification
-- =====================================================

DO $$
BEGIN
    -- Vérifier que la fonction helper existe
    IF NOT EXISTS (
        SELECT 1 FROM pg_proc 
        WHERE proname = 'get_text_search_config'
    ) THEN
        RAISE EXCEPTION 'Fonction get_text_search_config non créée';
    END IF;
    
    -- Vérifier que la fonction principale existe
    IF NOT EXISTS (
        SELECT 1 FROM pg_proc 
        WHERE proname = 'search_images_by_ai_analysis'
    ) THEN
        RAISE EXCEPTION 'Fonction search_images_by_ai_analysis non créée';
    END IF;
    
    RAISE NOTICE '✅ Migration correction to_tsvector appliquée avec succès';
END $$;








-- ============================================
-- Migration: 20260114_optimize_delivery_queries_performance.sql
-- ============================================
-- ✅ Migration pour optimiser les requêtes deliveries lentes
-- Problème: Requêtes SELECT deliveries avec ST_Y/ST_X prennent 1.0s-1.9s
-- Solution: Ajouter colonnes calculées pour éviter les calculs géographiques à chaque requête

-- 1. Ajouter colonnes calculées pour éviter ST_Y/ST_X à chaque requête
ALTER TABLE deliveries 
ADD COLUMN IF NOT EXISTS pickup_lat FLOAT,
ADD COLUMN IF NOT EXISTS pickup_lng FLOAT,
ADD COLUMN IF NOT EXISTS dropoff_lat FLOAT,
ADD COLUMN IF NOT EXISTS dropoff_lng FLOAT,
ADD COLUMN IF NOT EXISTS store_lat FLOAT,
ADD COLUMN IF NOT EXISTS store_lng FLOAT;

-- 2. Créer trigger pour mettre à jour automatiquement les coordonnées
CREATE OR REPLACE FUNCTION update_delivery_coordinates()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.pickup_location IS NOT NULL THEN
        NEW.pickup_lat := ST_Y(NEW.pickup_location::geometry);
        NEW.pickup_lng := ST_X(NEW.pickup_location::geometry);
    ELSE
        NEW.pickup_lat := NULL;
        NEW.pickup_lng := NULL;
    END IF;
    
    IF NEW.dropoff_location IS NOT NULL THEN
        NEW.dropoff_lat := ST_Y(NEW.dropoff_location::geometry);
        NEW.dropoff_lng := ST_X(NEW.dropoff_location::geometry);
    ELSE
        NEW.dropoff_lat := NULL;
        NEW.dropoff_lng := NULL;
    END IF;
    
    IF NEW.store_location IS NOT NULL THEN
        NEW.store_lat := ST_Y(NEW.store_location::geometry);
        NEW.store_lng := ST_X(NEW.store_location::geometry);
    ELSE
        NEW.store_lat := NULL;
        NEW.store_lng := NULL;
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 3. Créer le trigger (DROP IF EXISTS pour éviter erreur si existe déjà)
DROP TRIGGER IF EXISTS delivery_coordinates_trigger ON deliveries;
CREATE TRIGGER delivery_coordinates_trigger
BEFORE INSERT OR UPDATE OF pickup_location, dropoff_location, store_location
ON deliveries
FOR EACH ROW
EXECUTE FUNCTION update_delivery_coordinates();

-- 4. Mettre à jour les enregistrements existants
UPDATE deliveries 
SET 
    pickup_lat = CASE WHEN pickup_location IS NOT NULL THEN ST_Y(pickup_location::geometry) ELSE NULL END,
    pickup_lng = CASE WHEN pickup_location IS NOT NULL THEN ST_X(pickup_location::geometry) ELSE NULL END,
    dropoff_lat = CASE WHEN dropoff_location IS NOT NULL THEN ST_Y(dropoff_location::geometry) ELSE NULL END,
    dropoff_lng = CASE WHEN dropoff_location IS NOT NULL THEN ST_X(dropoff_location::geometry) ELSE NULL END,
    store_lat = CASE WHEN store_location IS NOT NULL THEN ST_Y(store_location::geometry) ELSE NULL END,
    store_lng = CASE WHEN store_location IS NOT NULL THEN ST_X(store_location::geometry) ELSE NULL END
WHERE pickup_lat IS NULL OR pickup_lng IS NULL OR dropoff_lat IS NULL OR dropoff_lng IS NULL;

-- 5. Index pour delivery_matching_queue (optimiser UPDATE)
CREATE INDEX IF NOT EXISTS idx_delivery_matching_queue_delivery_id 
ON delivery_matching_queue(delivery_id);

-- 6. Index spatial pour courier_availability_snapshots (optimiser ST_Distance)
CREATE INDEX IF NOT EXISTS idx_courier_availability_location_gist 
ON courier_availability_snapshots USING GIST(location);

-- 7. Index composite pour optimiser les recherches de coursiers disponibles
CREATE INDEX IF NOT EXISTS idx_courier_availability_online_captured 
ON courier_availability_snapshots(is_online, captured_at) 
WHERE is_online = TRUE;

-- 8. Index pour optimiser les requêtes deliveries par ID (déjà présent mais on s'assure)
CREATE INDEX IF NOT EXISTS idx_deliveries_id ON deliveries(id);

-- 9. Index pour optimiser les requêtes deliveries par statut et updated_at
CREATE INDEX IF NOT EXISTS idx_deliveries_status_updated_at 
ON deliveries(status, updated_at) 
WHERE status NOT IN ('delivered', 'cancelled', 'completed');

-- 10. Optimiser idle_in_transaction_session_timeout (via SET dans la connexion, pas dans migration)
-- Cette configuration sera faite dans le code Rust

COMMENT ON COLUMN deliveries.pickup_lat IS 'Latitude calculée depuis pickup_location (évite ST_Y à chaque requête)';
COMMENT ON COLUMN deliveries.pickup_lng IS 'Longitude calculée depuis pickup_location (évite ST_X à chaque requête)';
COMMENT ON COLUMN deliveries.dropoff_lat IS 'Latitude calculée depuis dropoff_location (évite ST_Y à chaque requête)';
COMMENT ON COLUMN deliveries.dropoff_lng IS 'Longitude calculée depuis dropoff_location (évite ST_X à chaque requête)';
COMMENT ON COLUMN deliveries.store_lat IS 'Latitude calculée depuis store_location (évite ST_Y à chaque requête)';
COMMENT ON COLUMN deliveries.store_lng IS 'Longitude calculée depuis store_location (évite ST_X à chaque requête)';








-- ============================================
-- Migration: 20260114_optimize_search_performance.sql
-- ============================================
-- Migration: Optimisation des performances de recherche
-- Date: 2026-01-14
-- Problèmes corrigés:
--   1. Requête publicites lente (1.136s) - manque d'index
--   2. UPDATE delivery_matching_queue lent (1.288s) - manque d'index
--   3. SELECT delivery_parcels avec sous-requête lente (436-765ms) - besoin d'index

-- 1. Index pour publicites (requête dans publicite_search_service.rs)
-- Optimise: SELECT ... FROM publicites WHERE status = 'active' AND date_fin > NOW() AND date_debut <= NOW()
-- Note: On ne peut pas utiliser NOW() dans WHERE d'un index partiel (pas IMMUTABLE)
-- L'index sera efficace même sans la condition date_fin > NOW() car PostgreSQL peut utiliser l'index pour filtrer
CREATE INDEX IF NOT EXISTS idx_publicites_active_filter 
ON publicites(date_fin DESC, date_debut DESC) 
WHERE status = 'active';

-- Index complémentaire pour status seul (si pas déjà existant)
CREATE INDEX IF NOT EXISTS idx_publicites_status 
ON publicites(status) 
WHERE status = 'active';

-- 2. Index pour delivery_matching_queue (UPDATE dans delivery_repository.rs)
-- Optimise: UPDATE delivery_matching_queue ... WHERE delivery_id = $1
CREATE INDEX IF NOT EXISTS idx_delivery_matching_queue_delivery_id 
ON delivery_matching_queue(delivery_id);

-- 3. Index pour deliveries.parcel_id (optimise JOIN dans delivery_service.rs)
-- Optimise: SELECT dp.constraints FROM delivery_parcels dp INNER JOIN deliveries d ON d.parcel_id = dp.id WHERE d.id = $1
CREATE INDEX IF NOT EXISTS idx_deliveries_parcel_id 
ON deliveries(parcel_id);

-- Index complémentaire pour delivery_parcels.id (si pas déjà PRIMARY KEY)
-- Note: Si id est PRIMARY KEY, cet index n'est pas nécessaire mais ne fait pas de mal
CREATE INDEX IF NOT EXISTS idx_delivery_parcels_id 
ON delivery_parcels(id);

-- 4. Index pour service_products.service_id (si pas déjà existant)
-- Optimise: SELECT ... FROM service_products WHERE service_id = $1 AND is_active = TRUE
CREATE INDEX IF NOT EXISTS idx_service_products_service_id_active 
ON service_products(service_id, is_active) 
WHERE is_active = TRUE;

-- Vérification des index créés
DO $$
BEGIN
    RAISE NOTICE '✅ Migration 20260114_optimize_search_performance appliquée avec succès';
    RAISE NOTICE 'Index créés:';
    RAISE NOTICE '  - idx_publicites_active_filter';
    RAISE NOTICE '  - idx_publicites_status';
    RAISE NOTICE '  - idx_delivery_matching_queue_delivery_id';
    RAISE NOTICE '  - idx_deliveries_parcel_id';
    RAISE NOTICE '  - idx_delivery_parcels_id';
    RAISE NOTICE '  - idx_service_products_service_id_active';
END $$;



-- ============================================
-- Migration: 20260115_fix_image_search_empty_results.sql
-- ============================================
-- Migration: Correction recherche image - Gestion images non analysées
-- Date: 2026-01-15
-- Description: Améliore la fonction search_images_by_ai_analysis pour gérer les cas où
--              les images n'ont pas été analysées par l'IA (description générique, tags vides)

-- =====================================================
-- 1. Amélioration de la Fonction search_images_by_ai_analysis
-- =====================================================

CREATE OR REPLACE FUNCTION search_images_by_ai_analysis(
    search_query TEXT,
    search_tags TEXT[],
    search_category TEXT DEFAULT NULL,
    search_marque TEXT DEFAULT NULL,
    search_couleur TEXT DEFAULT NULL,
    gps_lat FLOAT DEFAULT NULL,
    gps_lng FLOAT DEFAULT NULL,
    search_radius_km INTEGER DEFAULT 50,
    max_results INTEGER DEFAULT 20,
    detected_lang TEXT DEFAULT 'french'
)
RETURNS TABLE (
    service_id INTEGER,
    media_id INTEGER,
    media_path TEXT,
    product_name TEXT,
    ai_description TEXT,
    ai_tags TEXT[],
    match_score FLOAT,
    distance_km FLOAT,
    service_data JSONB
) AS $$
DECLARE
    normalized_search_query TEXT;
    normalized_search_tags TEXT[];
    normalized_search_marque TEXT;
    normalized_search_couleur TEXT;
    lang_config regconfig;
    is_generic_description BOOLEAN;
BEGIN
    -- Convertir la langue TEXT en regconfig
    lang_config := get_text_search_config(detected_lang);
    
    -- Normaliser les paramètres de recherche
    normalized_search_query := normalize_text(search_query);
    normalized_search_tags := normalize_word_array(search_tags);
    normalized_search_marque := CASE WHEN search_marque IS NOT NULL THEN normalize_text(search_marque) ELSE NULL END;
    normalized_search_couleur := CASE WHEN search_couleur IS NOT NULL THEN normalize_text(search_couleur) ELSE NULL END;
    
    -- Détecter si la description est générique (non analysée)
    is_generic_description := normalized_search_query ILIKE '%image générée automatiquement%' 
                            OR normalized_search_query ILIKE '%générée automatiquement%';

    RETURN QUERY
    WITH ranked_results AS (
        SELECT 
            s.id as service_id,
            m.id as media_id,
            m.path as media_path,
            COALESCE(
                product->>'nom',
                product->>'name',
                product->>'titre',
                'Produit'
            ) as product_name,
            m.ai_description,
            m.ai_tags,
            (
                -- ✅ AMÉLIORÉ: Score Full-Text avec gestion des descriptions génériques
                CASE 
                    -- Si description générique, utiliser recherche sur nom de produit
                    WHEN m.normalized_ai_description ILIKE '%image générée automatiquement%' 
                         OR m.normalized_ai_description ILIKE '%générée automatiquement%'
                    THEN 
                        -- Recherche sur nom de produit à la place
                        CASE 
                            WHEN normalized_search_query != '' 
                                 AND (
                                     COALESCE(product->>'nom', '') ILIKE '%' || normalized_search_query || '%'
                                     OR COALESCE(product->>'name', '') ILIKE '%' || normalized_search_query || '%'
                                     OR COALESCE(product->>'titre', '') ILIKE '%' || normalized_search_query || '%'
                                 )
                            THEN 40.0  -- Score pour match sur nom de produit
                            ELSE 0.0
                        END
                    ELSE
                        -- Recherche normale sur description IA
                        COALESCE(
                            ts_rank(
                                to_tsvector(lang_config, COALESCE(m.normalized_ai_description, '')),
                                plainto_tsquery(lang_config, normalized_search_query)
                            ) * 50.0,
                            0.0
                        )
                END +
                
                -- Matching vectoriel optimisé avec similarité (exact + partiel + fuzzy)
                COALESCE(
                    calculate_vector_match_score_optimized(
                        m.normalized_ai_tags,
                        normalized_search_tags
                    ) * 30.0,
                    0.0
                ) +
                
                -- ✅ AMÉLIORÉ: Matching partiel sur description normalisée OU nom de produit
                CASE 
                    WHEN normalized_search_query != '' THEN
                        CASE 
                            -- Si description générique, chercher dans nom de produit
                            WHEN m.normalized_ai_description ILIKE '%image générée automatiquement%' 
                                 OR m.normalized_ai_description ILIKE '%générée automatiquement%'
                            THEN
                                CASE 
                                    WHEN COALESCE(product->>'nom', '') ILIKE '%' || normalized_search_query || '%'
                                         OR COALESCE(product->>'name', '') ILIKE '%' || normalized_search_query || '%'
                                         OR COALESCE(product->>'titre', '') ILIKE '%' || normalized_search_query || '%'
                                    THEN 35.0
                                    ELSE 0.0
                                END
                            -- Sinon, chercher dans description normalisée
                            WHEN m.normalized_ai_description LIKE '%' || normalized_search_query || '%'
                            THEN 35.0
                            ELSE 0.0
                        END
                    ELSE 0.0
                END +
                
                -- Bonus tags communs avec normalisation
                (SELECT COUNT(*) * 20.0 
                 FROM unnest(COALESCE(m.normalized_ai_tags, ARRAY[]::TEXT[])) tag 
                 WHERE tag = ANY(normalized_search_tags)) +
                
                -- ✅ AMÉLIORÉ: Bonus marque exacte avec normalisation (chercher aussi dans nom produit)
                CASE 
                    WHEN normalized_search_marque IS NOT NULL THEN
                        CASE 
                            WHEN normalize_text(COALESCE(m.ai_metadata->>'marque', '')) = normalized_search_marque
                                 OR COALESCE(product->>'marque', '') ILIKE '%' || normalized_search_marque || '%'
                                 OR COALESCE(product->>'brand', '') ILIKE '%' || normalized_search_marque || '%'
                            THEN 100.0 
                            ELSE 0.0 
                        END
                    ELSE 0.0
                END +
                
                -- Bonus couleur avec normalisation
                CASE 
                    WHEN normalized_search_couleur IS NOT NULL 
                         AND EXISTS (
                             SELECT 1 
                             FROM jsonb_array_elements_text(COALESCE(m.ai_metadata->'couleurs', '[]'::jsonb)) AS couleur
                             WHERE normalize_text(couleur) = normalized_search_couleur
                         )
                    THEN 30.0 
                    ELSE 0.0
                END +
                
                -- ✅ AMÉLIORÉ: Bonus catégorie identique (chercher aussi dans données service)
                CASE 
                    WHEN search_category IS NOT NULL THEN
                        CASE 
                            WHEN m.ai_category = search_category 
                                 OR COALESCE(product->>'categorie', '') ILIKE '%' || search_category || '%'
                                 OR COALESCE(product->>'category', '') ILIKE '%' || search_category || '%'
                                 OR COALESCE(s.data->>'categorie', '') ILIKE '%' || search_category || '%'
                            THEN 40.0 
                            ELSE 0.0
                        END
                    ELSE 0.0
                END +
                
                -- Bonus confidence élevée (minimum 10 points même si NULL)
                (COALESCE(m.ai_confidence, 0.5) * 20.0)
                
            )::FLOAT as match_score,
            
            -- Calcul distance GPS si coordonnées fournies
            CASE 
                WHEN gps_lat IS NOT NULL AND gps_lng IS NOT NULL 
                     AND s.gps IS NOT NULL AND s.gps != '' 
                     AND s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$'
                THEN
                    ST_Distance(
                        ST_Point(gps_lng, gps_lat)::geography,
                        ST_Point(
                            COALESCE(CAST(SPLIT_PART(s.gps, ',', 2) AS FLOAT), 0.0),
                            COALESCE(CAST(SPLIT_PART(s.gps, ',', 1) AS FLOAT), 0.0)
                        )::geography
                    ) / 1000.0  -- Convertir en km
                ELSE NULL
            END as distance_km,
            
            s.data as service_data,
            product
        FROM services s
        INNER JOIN media m ON m.service_id = s.id
        CROSS JOIN LATERAL jsonb_array_elements(
            CASE 
                WHEN jsonb_typeof(s.data->'produits') = 'array' 
                THEN s.data->'produits'
                ELSE '[]'::jsonb
            END
        ) AS product
        WHERE s.is_active = true
        AND m.type = 'image'
        AND (
            -- ✅ AMÉLIORÉ: Conditions de recherche étendues pour gérer images non analysées
            -- 1. Recherche normale sur description IA (si analysée)
            (
                m.ai_description IS NOT NULL 
                AND m.normalized_ai_description NOT ILIKE '%image générée automatiquement%'
                AND m.normalized_ai_description NOT ILIKE '%générée automatiquement%'
                AND (
                    to_tsvector(lang_config, COALESCE(m.normalized_ai_description, '')) @@ plainto_tsquery(lang_config, normalized_search_query)
                    OR m.normalized_ai_tags && normalized_search_tags
                    OR calculate_vector_match_score_optimized(m.normalized_ai_tags, normalized_search_tags) > 0.0
                    OR (normalized_search_query != '' AND m.normalized_ai_description LIKE '%' || normalized_search_query || '%')
                )
            )
            -- 2. Recherche sur nom de produit (si description générique)
            OR (
                (
                    m.ai_description IS NULL
                    OR m.normalized_ai_description ILIKE '%image générée automatiquement%'
                    OR m.normalized_ai_description ILIKE '%générée automatiquement%'
                )
                AND normalized_search_query != ''
                AND (
                    COALESCE(product->>'nom', '') ILIKE '%' || normalized_search_query || '%'
                    OR COALESCE(product->>'name', '') ILIKE '%' || normalized_search_query || '%'
                    OR COALESCE(product->>'titre', '') ILIKE '%' || normalized_search_query || '%'
                )
            )
            -- 3. Recherche par catégorie (même si description générique)
            OR (
                search_category IS NOT NULL 
                AND (
                    m.ai_category = search_category
                    OR COALESCE(product->>'categorie', '') ILIKE '%' || search_category || '%'
                    OR COALESCE(product->>'category', '') ILIKE '%' || search_category || '%'
                    OR COALESCE(s.data->>'categorie', '') ILIKE '%' || search_category || '%'
                )
            )
            -- 4. Recherche par marque (même si description générique)
            OR (
                normalized_search_marque IS NOT NULL
                AND (
                    normalize_text(COALESCE(m.ai_metadata->>'marque', '')) = normalized_search_marque
                    OR COALESCE(product->>'marque', '') ILIKE '%' || normalized_search_marque || '%'
                    OR COALESCE(product->>'brand', '') ILIKE '%' || normalized_search_marque || '%'
                )
            )
        )
        -- Filtre GPS si coordonnées fournies
        AND (
            gps_lat IS NULL 
            OR gps_lng IS NULL
            OR search_radius_km IS NULL
            OR s.gps IS NULL
            OR s.gps = ''
            OR s.gps !~ '^-?\d+\.?\d*,-?\d+\.?\d*$'
            OR ST_Distance(
                ST_Point(gps_lng, gps_lat)::geography,
                ST_Point(
                    COALESCE(CAST(SPLIT_PART(s.gps, ',', 2) AS FLOAT), 0.0),
                    COALESCE(CAST(SPLIT_PART(s.gps, ',', 1) AS FLOAT), 0.0)
                )::geography
            ) / 1000.0 <= search_radius_km
        )
    )
    SELECT 
        ranked_results.service_id,
        ranked_results.media_id,
        ranked_results.media_path,
        ranked_results.product_name,
        ranked_results.ai_description,
        ranked_results.ai_tags,
        ranked_results.match_score,
        ranked_results.distance_km,
        ranked_results.service_data
    FROM ranked_results
    WHERE ranked_results.match_score > 0.0  -- Filtrer les résultats avec score > 0
    ORDER BY 
        ranked_results.match_score DESC,
        ranked_results.distance_km ASC NULLS LAST
    LIMIT max_results;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION search_images_by_ai_analysis IS 'Recherche intelligente d''images par analyse IA avec gestion des images non analysées (recherche sur nom de produit si description générique)';

-- =====================================================
-- 2. Vérification
-- =====================================================

DO $$
BEGIN
    -- Vérifier que la fonction existe
    IF NOT EXISTS (
        SELECT 1 FROM pg_proc 
        WHERE proname = 'search_images_by_ai_analysis'
    ) THEN
        RAISE EXCEPTION 'Fonction search_images_by_ai_analysis non créée';
    END IF;
    
    RAISE NOTICE '✅ Migration correction recherche image (gestion images non analysées) appliquée avec succès';
END $$;








-- ============================================
-- Migration: 20260115_fix_image_search_use_all_ia_keywords.sql
-- ============================================
-- Migration: Recherche image - Utiliser TOUS les mots-clés du JSON IA de manière générique
-- Date: 2026-01-15
-- Description: Extrait TOUS les mots-clés du JSON IA (description, tags, caracteristiques_cles)
--              de manière générique et fait une recherche textuelle classique dans les caractéristiques des produits

-- =====================================================
-- 1. Fonction Helper pour Extraire Tous les Mots-clés d'un JSON IA (GÉNÉRIQUE)
-- =====================================================

CREATE OR REPLACE FUNCTION extract_all_keywords_from_ia_json_generic(
    search_query TEXT,
    search_tags TEXT[],
    search_category TEXT,
    caracteristiques_cles JSONB
)
RETURNS TEXT[] AS $$
DECLARE
    all_keywords TEXT[] := ARRAY[]::TEXT[];
    keyword TEXT;
    key TEXT;
    value TEXT;
    word TEXT;
BEGIN
    -- 1. Ajouter search_query (diviser en mots individuels)
    IF search_query IS NOT NULL AND search_query != '' THEN
        SELECT array_agg(DISTINCT trim(word))
        INTO all_keywords
        FROM unnest(string_to_array(normalize_text(search_query), ' ')) AS word
        WHERE trim(word) != '' AND length(trim(word)) > 2;  -- Ignorer mots trop courts
    END IF;
    
    -- 2. Ajouter tous les tags (déjà normalisés)
    IF search_tags IS NOT NULL AND array_length(search_tags, 1) > 0 THEN
        all_keywords := all_keywords || normalize_word_array(search_tags);
    END IF;
    
    -- 3. Ajouter la catégorie
    IF search_category IS NOT NULL AND search_category != '' THEN
        all_keywords := array_append(all_keywords, normalize_text(search_category));
    END IF;
    
    -- 4. ✅ GÉNÉRIQUE: Extraire TOUTES les valeurs de caracteristiques_cles (sans présupposer de structure)
    IF caracteristiques_cles IS NOT NULL THEN
        FOR key, value IN SELECT * FROM jsonb_each_text(caracteristiques_cles)
        LOOP
            -- Ajouter la clé normalisée (ex: "marque", "couleur", "taille", etc.)
            IF key IS NOT NULL AND key != '' THEN
                all_keywords := array_append(all_keywords, normalize_text(key));
            END IF;
            
            -- Traiter la valeur (peut être string, array, ou autre)
            IF value IS NOT NULL AND value != '' THEN
                -- Vérifier si c'est un tableau JSON
                IF value LIKE '[%' THEN
                    -- C'est un tableau JSON, extraire chaque élément
                    DECLARE
                        json_array JSONB;
                        array_element TEXT;
                    BEGIN
                        BEGIN
                            json_array := value::JSONB;
                            FOR array_element IN SELECT jsonb_array_elements_text(json_array)
                            LOOP
                                IF array_element IS NOT NULL AND array_element != '' THEN
                                    -- Diviser en mots si nécessaire
                                    FOR word IN SELECT unnest(string_to_array(normalize_text(array_element), ' '))
                                    LOOP
                                        IF word IS NOT NULL AND word != '' AND length(word) > 2 THEN
                                            all_keywords := array_append(all_keywords, word);
                                        END IF;
                                    END LOOP;
                                END IF;
                            END LOOP;
                        EXCEPTION WHEN OTHERS THEN
                            -- Si erreur parsing JSON, traiter comme string simple
                            FOR word IN SELECT unnest(string_to_array(normalize_text(value), ' '))
                            LOOP
                                IF word IS NOT NULL AND word != '' AND length(word) > 2 THEN
                                    all_keywords := array_append(all_keywords, word);
                                END IF;
                            END LOOP;
                        END;
                    END;
                ELSE
                    -- Valeur simple, diviser en mots
                    FOR word IN SELECT unnest(string_to_array(normalize_text(value), ' '))
                    LOOP
                        IF word IS NOT NULL AND word != '' AND length(word) > 2 THEN
                            all_keywords := array_append(all_keywords, word);
                        END IF;
                    END LOOP;
                END IF;
            END IF;
        END LOOP;
    END IF;
    
    -- 5. Supprimer les doublons et les valeurs vides
    SELECT array_agg(DISTINCT kw)
    INTO all_keywords
    FROM unnest(all_keywords) AS kw
    WHERE kw IS NOT NULL AND kw != '' AND length(kw) > 2;
    
    RETURN COALESCE(all_keywords, ARRAY[]::TEXT[]);
END;
$$ LANGUAGE plpgsql IMMUTABLE;

COMMENT ON FUNCTION extract_all_keywords_from_ia_json_generic IS 'Extrait TOUS les mots-clés du JSON IA de manière générique (description, tags, caracteristiques_cles) sans présupposer de structure';

-- =====================================================
-- 2. Fonction de Recherche Textuelle dans Caractéristiques Produits (GÉNÉRIQUE)
-- =====================================================

CREATE OR REPLACE FUNCTION search_in_product_characteristics_generic(
    product_data JSONB,
    keywords TEXT[]
)
RETURNS BOOLEAN AS $$
DECLARE
    keyword TEXT;
    search_text TEXT := '';
    prod_key TEXT;
    prod_value TEXT;
    sc_key TEXT;
    sc_value TEXT;
    sc_element TEXT;
    json_array JSONB;
BEGIN
    -- Construire un texte de recherche depuis TOUTES les caractéristiques du produit (générique)
    
    -- 1. Extraire toutes les valeurs textuelles du produit (récursif)
    FOR prod_key, prod_value IN SELECT * FROM jsonb_each_text(product_data)
    LOOP
        IF prod_value IS NOT NULL AND prod_value != '' THEN
            -- Si c'est un tableau JSON
            IF prod_value LIKE '[%' THEN
                BEGIN
                    json_array := prod_value::JSONB;
                    FOR sc_element IN SELECT jsonb_array_elements_text(json_array)
                    LOOP
                        IF sc_element IS NOT NULL AND sc_element != '' THEN
                            search_text := search_text || ' ' || sc_element;
                        END IF;
                    END LOOP;
                EXCEPTION WHEN OTHERS THEN
                    -- Si erreur, traiter comme string simple
                    search_text := search_text || ' ' || prod_value;
                END;
            ELSE
                -- Valeur simple
                search_text := search_text || ' ' || prod_value;
            END IF;
        END IF;
    END LOOP;
    
    -- 2. Extraire récursivement depuis sous_caracteristiques (si existe)
    IF product_data ? 'sous_caracteristiques' THEN
        FOR sc_key, sc_value IN SELECT * FROM jsonb_each_text(product_data->'sous_caracteristiques')
        LOOP
            -- Ajouter la clé
            IF sc_key IS NOT NULL AND sc_key != '' THEN
                search_text := search_text || ' ' || sc_key;
            END IF;
            
            -- Ajouter la valeur (peut être string ou array)
            IF sc_value IS NOT NULL AND sc_value != '' THEN
                IF sc_value LIKE '[%' THEN
                    -- C'est un tableau JSON
                    BEGIN
                        json_array := sc_value::JSONB;
                        FOR sc_element IN SELECT jsonb_array_elements_text(json_array)
                        LOOP
                            IF sc_element IS NOT NULL AND sc_element != '' THEN
                                search_text := search_text || ' ' || sc_element;
                            END IF;
                        END LOOP;
                    EXCEPTION WHEN OTHERS THEN
                        search_text := search_text || ' ' || sc_value;
                    END;
                ELSE
                    -- Valeur simple
                    search_text := search_text || ' ' || sc_value;
                END IF;
            END IF;
        END LOOP;
    END IF;
    
    -- Normaliser le texte de recherche
    search_text := normalize_text(search_text);
    
    -- Vérifier si au moins un mot-clé est présent dans le texte
    IF keywords IS NULL OR array_length(keywords, 1) IS NULL OR array_length(keywords, 1) = 0 THEN
        RETURN FALSE;
    END IF;
    
    -- Recherche: au moins un mot-clé doit matcher
    FOREACH keyword IN ARRAY keywords
    LOOP
        IF keyword IS NOT NULL AND keyword != '' AND length(keyword) > 2 THEN
            IF search_text LIKE '%' || keyword || '%' THEN
                RETURN TRUE;
            END IF;
        END IF;
    END LOOP;
    
    RETURN FALSE;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

COMMENT ON FUNCTION search_in_product_characteristics_generic IS 'Recherche textuelle générique dans TOUTES les caractéristiques d''un produit (nom, description, sous_caracteristiques, etc.)';

-- =====================================================
-- 3. Mise à Jour de la Fonction search_images_by_ai_analysis (GÉNÉRIQUE)
-- =====================================================

CREATE OR REPLACE FUNCTION search_images_by_ai_analysis(
    search_query TEXT,
    search_tags TEXT[],
    search_category TEXT DEFAULT NULL,
    search_marque TEXT DEFAULT NULL,
    search_couleur TEXT DEFAULT NULL,
    gps_lat FLOAT DEFAULT NULL,
    gps_lng FLOAT DEFAULT NULL,
    search_radius_km INTEGER DEFAULT 50,
    max_results INTEGER DEFAULT 20,
    detected_lang TEXT DEFAULT 'french',
    search_couleurs TEXT[] DEFAULT NULL,  -- Gardé pour compatibilité mais pas utilisé directement
    caracteristiques_cles JSONB DEFAULT NULL  -- ✅ NOUVEAU: Caractéristiques clés du JSON IA (générique)
)
RETURNS TABLE (
    service_id INTEGER,
    media_id INTEGER,
    media_path TEXT,
    product_name TEXT,
    ai_description TEXT,
    ai_tags TEXT[],
    match_score FLOAT,
    distance_km FLOAT,
    service_data JSONB
) AS $$
DECLARE
    normalized_search_query TEXT;
    normalized_search_tags TEXT[];
    lang_config regconfig;
    all_keywords TEXT[];  -- ✅ Tous les mots-clés extraits du JSON IA (générique)
BEGIN
    -- Convertir la langue TEXT en regconfig
    lang_config := get_text_search_config(detected_lang);
    
    -- Normaliser les paramètres de recherche
    normalized_search_query := normalize_text(search_query);
    normalized_search_tags := normalize_word_array(search_tags);
    
    -- ✅ GÉNÉRIQUE: Extraire TOUS les mots-clés du JSON IA (sans présupposer de structure)
    all_keywords := extract_all_keywords_from_ia_json_generic(
        normalized_search_query,
        normalized_search_tags,
        COALESCE(search_category, ''),
        caracteristiques_cles
    );
    
    RETURN QUERY
    WITH ranked_results AS (
        SELECT 
            s.id as service_id,
            m.id as media_id,
            m.path as media_path,
            COALESCE(
                product->>'nom',
                product->>'name',
                product->>'titre',
                'Produit'
            ) as product_name,
            m.ai_description,
            m.ai_tags,
            (
                -- ✅ Score principal: Recherche textuelle générique dans caractéristiques produits
                CASE 
                    WHEN search_in_product_characteristics_generic(product, all_keywords) THEN 100.0
                    ELSE 0.0
                END +
                
                -- Bonus pour match exact sur nom de produit
                CASE 
                    WHEN normalized_search_query != '' AND (
                        COALESCE(product->>'nom', '') ILIKE '%' || normalized_search_query || '%'
                        OR COALESCE(product->>'name', '') ILIKE '%' || normalized_search_query || '%'
                        OR COALESCE(product->>'titre', '') ILIKE '%' || normalized_search_query || '%'
                    )
                    THEN 50.0
                    ELSE 0.0
                END +
                
                -- Bonus pour match sur catégorie
                CASE 
                    WHEN search_category IS NOT NULL AND (
                        COALESCE(product->>'categorie', '') ILIKE '%' || search_category || '%'
                        OR COALESCE(product->>'category', '') ILIKE '%' || search_category || '%'
                        OR COALESCE(s.data->>'categorie', '') ILIKE '%' || search_category || '%'
                    )
                    THEN 60.0
                    ELSE 0.0
                END +
                
                -- Bonus pour match sur description IA (si disponible et non générique)
                CASE 
                    WHEN m.normalized_ai_description IS NOT NULL 
                         AND m.normalized_ai_description NOT ILIKE '%image générée automatiquement%'
                         AND normalized_search_query != ''
                         AND m.normalized_ai_description LIKE '%' || normalized_search_query || '%'
                    THEN 30.0
                    ELSE 0.0
                END +
                
                -- Bonus tags communs
                (SELECT COUNT(*) * 15.0 
                 FROM unnest(COALESCE(m.normalized_ai_tags, ARRAY[]::TEXT[])) tag 
                 WHERE tag = ANY(normalized_search_tags)) +
                
                -- Bonus confidence
                (COALESCE(m.ai_confidence, 0.5) * 10.0)
                
            )::FLOAT as match_score,
            
            -- Calcul distance GPS si coordonnées fournies
            CASE 
                WHEN gps_lat IS NOT NULL AND gps_lng IS NOT NULL 
                     AND s.gps IS NOT NULL AND s.gps != '' 
                     AND s.gps ~ '^-?\d+\.?\d*,-?\d+\.?\d*$'
                THEN
                    ST_Distance(
                        ST_Point(gps_lng, gps_lat)::geography,
                        ST_Point(
                            COALESCE(CAST(SPLIT_PART(s.gps, ',', 2) AS FLOAT), 0.0),
                            COALESCE(CAST(SPLIT_PART(s.gps, ',', 1) AS FLOAT), 0.0)
                        )::geography
                    ) / 1000.0
                ELSE NULL
            END as distance_km,
            
            s.data as service_data,
            product
        FROM services s
        INNER JOIN media m ON m.service_id = s.id
        CROSS JOIN LATERAL jsonb_array_elements(
            CASE 
                WHEN jsonb_typeof(s.data->'produits') = 'array' 
                THEN s.data->'produits'
                ELSE '[]'::jsonb
            END
        ) AS product
        WHERE s.is_active = true
        AND m.type = 'image'
        AND (
            -- ✅ Recherche textuelle générique dans caractéristiques produits avec TOUS les mots-clés
            search_in_product_characteristics_generic(product, all_keywords)
            -- OU recherche classique sur description IA (si disponible et non générique)
            OR (
                m.ai_description IS NOT NULL 
                AND m.normalized_ai_description NOT ILIKE '%image générée automatiquement%'
                AND (
                    to_tsvector(lang_config, COALESCE(m.normalized_ai_description, '')) @@ plainto_tsquery(lang_config, normalized_search_query)
                    OR m.normalized_ai_tags && normalized_search_tags
                )
            )
        )
        -- Filtre GPS si coordonnées fournies
        AND (
            gps_lat IS NULL 
            OR gps_lng IS NULL
            OR search_radius_km IS NULL
            OR s.gps IS NULL
            OR s.gps = ''
            OR s.gps !~ '^-?\d+\.?\d*,-?\d+\.?\d*$'
            OR ST_Distance(
                ST_Point(gps_lng, gps_lat)::geography,
                ST_Point(
                    COALESCE(CAST(SPLIT_PART(s.gps, ',', 2) AS FLOAT), 0.0),
                    COALESCE(CAST(SPLIT_PART(s.gps, ',', 1) AS FLOAT), 0.0)
                )::geography
            ) / 1000.0 <= search_radius_km
        )
    )
    SELECT 
        ranked_results.service_id,
        ranked_results.media_id,
        ranked_results.media_path,
        ranked_results.product_name,
        ranked_results.ai_description,
        ranked_results.ai_tags,
        ranked_results.match_score,
        ranked_results.distance_km,
        ranked_results.service_data
    FROM ranked_results
    WHERE ranked_results.match_score > 0.0
    ORDER BY 
        ranked_results.match_score DESC,
        ranked_results.distance_km ASC NULLS LAST
    LIMIT max_results;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION search_images_by_ai_analysis IS 'Recherche intelligente d''images utilisant TOUS les mots-clés du JSON IA de manière générique pour recherche textuelle dans caractéristiques produits';

-- =====================================================
-- 4. Vérification
-- =====================================================

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_proc 
        WHERE proname = 'extract_all_keywords_from_ia_json_generic'
    ) THEN
        RAISE EXCEPTION 'Fonction extract_all_keywords_from_ia_json_generic non créée';
    END IF;
    
    IF NOT EXISTS (
        SELECT 1 FROM pg_proc 
        WHERE proname = 'search_in_product_characteristics_generic'
    ) THEN
        RAISE EXCEPTION 'Fonction search_in_product_characteristics_generic non créée';
