        WHEN 'car' THEN 4
        WHEN 'pickup' THEN 5
        WHEN 'van' THEN 6
        WHEN 'truck' THEN 7
        WHEN 'walking' THEN 8
    END as new_id,
    slug
FROM parcel_types
WHERE slug IN ('bike', 'motorcycle', 'tricycle', 'car', 'pickup', 'van', 'truck', 'walking');

-- ✅ ÉTAPE 3: Désactiver temporairement les contraintes de clé étrangère
ALTER TABLE product_delivery_config DISABLE TRIGGER ALL;
ALTER TABLE courier_assets DISABLE TRIGGER ALL;

-- ✅ ÉTAPE 4: Mettre à jour les références dans product_delivery_config
