            type_etablissement VARCHAR(50) NOT NULL, -- 'primaire', 'secondaire', 'superieur'
            niveau VARCHAR(50) NOT NULL, -- 'CP1', '6ème', 'L1', etc.
            classe VARCHAR(50), -- Pour primaire/secondaire
