            AND table_name = 'programmes_scolaires' 
            AND column_name = 'annee_scolaire'
        ) THEN
            CREATE INDEX IF NOT EXISTS idx_programmes_annee 
            ON programmes_scolaires(annee_scolaire);
        END IF;
    END IF;
END $$;

